        out = zd.parse_bilans(_imf_sdmx({'0:0:0:0:0': {0: '5000000000'}, '0:0:1:0:0': {1: '100000000'}}, ['2026-Q1', '2014-Q4'], dims))
        self.assertEqual(out['rows']['VNM']['q'], '2026-Q1'); self.assertNotIn('in_pe', out['rows']['VNM']['s'], 'seria z 2014 poza plikiem')

