class FunduszeV90(unittest.TestCase):
    """v90: fundusze ETF w USA — przepływ = zmiana liczby jednostek × NAV z plików State Street i iShares (bez klucza)."""

    XML = ('<?xml version="1.0"?><ss:Workbook xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet">'
           '<ss:Worksheet ss:Name="Holdings"><ss:Table><ss:Row><ss:Cell><ss:Data ss:Type="String">AT&T</ss:Data></ss:Cell></ss:Row></ss:Table></ss:Worksheet>'
           '<ss:Worksheet ss:Name="Historical"><ss:Table>'
           '<ss:Row><ss:Cell><ss:Data ss:Type="String">As Of</ss:Data></ss:Cell><ss:Cell><ss:Data ss:Type="String">NAV per Share</ss:Data></ss:Cell>'
           '<ss:Cell><ss:Data ss:Type="String">Ex-Dividends</ss:Data></ss:Cell><ss:Cell><ss:Data ss:Type="String">Shares Outstanding</ss:Data></ss:Cell></ss:Row>'
           '{rows}</ss:Table></ss:Worksheet></ss:Workbook>')

    @classmethod
    def xml(cls, rows):
        r = ''.join(f'<ss:Row><ss:Cell><ss:Data ss:Type="String">{d}</ss:Data></ss:Cell><ss:Cell><ss:Data ss:Type="Number">{n}</ss:Data></ss:Cell>'
                    f'<ss:Cell><ss:Data ss:Type="String">--</ss:Data></ss:Cell><ss:Cell><ss:Data ss:Type="{"Number" if s != "--" else "String"}">{s}</ss:Data></ss:Cell></ss:Row>'
                    for d, n, s in rows)
        return cls.XML.format(rows=r).encode()

    @staticmethod
    def days(n, end='2026-09-24'):
        d, out = datetime.date.fromisoformat(end), []
        while len(out) < n:
            if d.weekday() < 5:
                out.append(d)
            d -= datetime.timedelta(days=1)
        return out[::-1]

    def test_parse_ishares_and_screener(self):
        ds = self.days(25)
        rows = [(d.strftime('%b %d, %Y'), 100.0 + i, 1000000 + 1000 * i) for i, d in enumerate(ds)][::-1] + [('Jan 03, 2000', 50.0, '--')]
        h = zd.parse_ishares_hist(self.xml(rows))
        self.assertEqual(len(h), 25, 'wiersz z „--” pominięty; gołe „&” w innym arkuszu nie psuje pliku')
        self.assertEqual(h[-1], ['2026-09-24', 124.0, 1024000]); self.assertEqual(h[0][0], ds[0].isoformat())
        with self.assertRaises(RuntimeError):
            zd.parse_ishares_hist(self.xml(rows[:5]))
        j = {'239726': {'localExchangeTicker': 'IVV', 'portfolioId': 239726, 'navAmount': {'r': 770.800542}, 'navAmountAsOf': {'r': 20260924},
                        'totalNetAssetsFund': {'r': 882219760864.18}, 'totalNetAssetsFundAsOf': {'r': 20260924}},
             '239623': {'localExchangeTicker': 'EFA', 'navAmount': {'r': 90.0}, 'navAmountAsOf': {'r': 20260924},
                        'totalNetAssetsFund': {'r': 9e9}, 'totalNetAssetsFundAsOf': {'r': 20260923}},
             '1': {'localExchangeTicker': 'XYZ', 'navAmount': {'r': 1.0}, 'navAmountAsOf': {'r': 20260924}, 'totalNetAssetsFund': {'r': 1.0}, 'totalNetAssetsFundAsOf': {'r': 20260924}}}
        s = zd.parse_ishares_screener(j)
        self.assertEqual(s, {'IVV': ('239726', '2026-09-24', 770.800542, 1144550000)}, 'różne daty NAV i aktywów — bez liczby; spoza listy — pominięty; v94: pełne tysiące')

    def test_parse_ssga(self):
        rows = {1: {1: 'Fund Name:', 2: 'SPDR® Gold Shares'}, 2: {1: 'Ticker Symbol:', 2: 'GLD®'}, 4: {1: 'Date', 2: 'NAV', 3: 'Shares Outstanding', 4: 'Total Net Assets'}}
        for i, d in enumerate(self.days(25)[::-1]):
            rows[5 + i] = {1: d.strftime('%d-%b-%Y'), 2: str(390.0 - i), 3: f'{3.697E8 - i * 1e5:E}', 4: '1'}
        rows[40] = {1: 'The whole or any part of this work may not be reproduced'}
        with mock.patch.object(zd, '_xlsx_rows', return_value=rows):
            h = zd.parse_ssga_navhist(b'x', 'GLD')
            self.assertEqual((len(h), h[-1]), (25, ['2026-09-24', 390.0, 369700000]))
            with self.assertRaises(RuntimeError):
                zd.parse_ssga_navhist(b'x', 'SPY')           # inny symbol w pliku — błąd, nie cudze liczby

    def test_flows_and_groups(self):
        h = [['2026-09-21', 100.0, 1000], ['2026-09-22', 101.0, 1100], ['2026-09-23', 50.0, 2200], ['2026-09-24', 50.0, 2150]]
        self.assertEqual(zd.fund_flows(h), {'2026-09-22': 100 * 101 / 1e6, '2026-09-23': 0.0, '2026-09-24': -50 * 50 / 1e6}, 'podział 2:1 — przepływ dnia liczony po podziale (v93)')
        self.assertEqual(zd.fund_flows([['2026-09-21', 100.0, 1000], ['2026-09-22', 50.0, 1000]]), {}, 'skok NAV bez podziału — dzień pominięty')
        fu = {'SPY': {'h': [['2026-09-22', 10.0, 100], ['2026-09-23', 10.0, 110], ['2026-09-24', 10.0, 130]]},
              'IVV': {'h': [['2026-09-22', 20.0, 50], ['2026-09-23', 20.0, 60]]}}
        ds, v, aum = zd.fund_group(fu, ('SPY', 'IVV'))
        self.assertEqual((ds, aum), (['2026-09-23'], (10.0 * 130 + 20.0 * 60) / 1e6), 'do ostatniego wspólnego dnia')
        self.assertAlmostEqual(v[0], 300 / 1e6)
        fu['IVV']['h'] = [['2026-09-21', 20.0, 50], ['2026-09-23', 20.0, 60]]   # v231: +20% (ponad 1,35× w parze dni = skok, FUND_PARA_X)
        ds, v, _ = zd.fund_group(fu, ('SPY', 'IVV'))
        self.assertEqual(ds, ['2026-09-23']); self.assertAlmostEqual(v[0], 100 / 1e6 + 200 / 1e6, msg='zmiana przez dwa dni przypisana do dnia publikacji')
        self.assertEqual(zd.fund_group(fu, ('SPY', 'EEM')), ([], [], None), 'brak funduszu w grupie — brak grupy, nie część')

    def test_build_fundusze(self):
        zd.META['errors'].clear(); zd.META['notes'].clear()
        ds = self.days(260)
        hist = self.xml([(d.strftime('%b %d, %Y'), 50.0, 1000000 + 100 * i) for i, d in enumerate(ds)][::-1])
        scr = {str(i): {'localExchangeTicker': t, 'portfolioId': str(i), 'navAmount': {'r': 50.0}, 'navAmountAsOf': {'r': 20260925},
                        'totalNetAssetsFund': {'r': 50.0 * 2000000}, 'totalNetAssetsFundAsOf': {'r': 20260925}} for i, t in enumerate(zd.FUND_ISH)}
        calls = []
        def fake(url, timeout=60, headers=None):
            calls.append(url)
            if 'ssga.com' in url:
                raise urllib.error.HTTPError(url, 403, 'Forbidden', None, None)
            if 'product-screener' in url:
                return json.dumps(scr).encode()
            return hist
        now = datetime.datetime(2026, 9, 25, 22, 0, tzinfo=datetime.timezone.utc)
        with mock.patch.object(zd, 'get_bytes', side_effect=fake), mock.patch.object(zd, '_now_utc', return_value=now), \
                mock.patch.object(zd, 'FUND_SLEEP', 0), mock.patch.object(zd.time, 'sleep'):
            out = zd.build_fundusze(None)
        self.assertEqual(sum('get-fund-document' in u for u in calls), 3, 'najwyżej 3 pełne historie na przebieg')
        full = [t for t, f in out['f'].items() if len(f.get('h') or []) > 1]
        self.assertEqual(len(full), 3); self.assertEqual(out['f'][full[0]]['h'][-1], ['2026-09-25', 50.0, 2000000], 'dzień z zestawienia dopisany')
        self.assertEqual(sum(1 for f in out['f'].values() if f.get('h')), 22, 'pozostałe fundusze iShares — jeden dzień z zestawienia (bez przepływu), do uzupełnienia w kolejnych przebiegach')
        self.assertTrue(any(e.startswith('fundusze ETF: 15 problemów') for e in zd.META['errors']), 'State Street niedostępny — błąd w meta')
        prev = out; prev['f']['SPY'] = {'iss': 'ssga', 'at': (now - datetime.timedelta(hours=1)).isoformat(), 'h': [['2026-09-24', 1.0, 1]]}
        calls.clear()
        with mock.patch.object(zd, 'get_bytes', side_effect=fake), mock.patch.object(zd, '_now_utc', return_value=now), \
                mock.patch.object(zd, 'FUND_SLEEP', 0), mock.patch.object(zd.time, 'sleep'):
            out2 = zd.build_fundusze(prev)
        self.assertFalse(any('spy.xlsx' in u for u in calls), 'plik State Street młodszy niż 6 h — bez pobierania')
        self.assertEqual(sum('get-fund-document' in u for u in calls), 3, 'kolejne 3 fundusze uzupełniane')
        with mock.patch.object(zd, 'get_bytes', side_effect=RuntimeError('offline')), mock.patch.object(zd, '_now_utc', return_value=now), \
                mock.patch.object(zd, 'FUND_SLEEP', 0), mock.patch.object(zd.time, 'sleep'):
            with self.assertRaises(RuntimeError):
                zd.build_fundusze(None)

    def test_trendy_uses_funds(self):
        ds = self.days(60, '2026-09-18')
        fu = {t: {'h': [[d.isoformat(), 100.0, 1000000 + (5000 if i >= 55 else 1000) * i] for i, d in enumerate(ds)]} for t in ('SPY', 'IVV')}
        with mock.patch.object(zd, '_now_utc', return_value=datetime.datetime(2026, 9, 21, 10, 0, tzinfo=datetime.timezone.utc)):
            out = zd.build_trendy({'fundusze': {'f': fu}})
        r = {x['id']: x for x in out['f']}['fe_us']
        self.assertEqual((r['g'], r['m'], r['cur'], r['n'], r['date']), ('fe', 'flow', 'USD', 8, '2026-09-18'))
        self.assertIn(r['st'], ('in_up', 'in_rev', 'in_new'), 'większy napływ w ostatnim tygodniu')
        self.assertTrue(r['ph'] > 0 and r['du'] > 0)
        self.assertEqual([b['id'] for b in out['b']], ['fe'])


class TrendyDailyV120(unittest.TestCase):
    """v120: sygnały dzienne — jedna reguła dla wszystkich rynków, test wstecz na całej historii pliku, brak nie jest zerem, bez sieci."""

    NOW = datetime.datetime(2026, 9, 26, 10, 0, tzinfo=datetime.timezone.utc)   # sobota rano (UTC) — wiek danych
    NY = datetime.datetime(2026, 9, 26, 6, 0)                                    # sobota rano w Nowym Jorku (bez strefy, jak zegar w teście)
    STATES = ('buy', 'sell', 'obs', 'x', 'quiet', 'stale', 'short', 'nodata')

    def setUp(self):
        ps = [mock.patch.object(zd, '_now_utc', return_value=self.NOW), mock.patch.object(zd, '_ny_now', return_value=self.NY),
              mock.patch.object(zd.urllib.request, 'urlopen', side_effect=AssertionError('sieć w teście'))]
        for p in ps:
            p.start(); self.addCleanup(p.stop)
        zd.META['notes'].clear()

    @staticmethod
    def days(n, end='2026-09-25'):
        return [d.isoformat() for d in FunduszeV90.days(n, end)]

    @classmethod
    def fund(cls, n=80, end='2026-09-25', last_du=None, last_ret=0.1, iss='ishares'):
        """Historia funduszu: NAV na przemian −0,5 % / +0,5 % (ostatni dzień: last_ret %), jednostki rosną o 1200 / 800 na przemian
        (przepływ ≈ 0,1 mln, wahania poniżej progu dzięki dolnej granicy rozrzutu — zwykły dzień jest „spokojny”); ostatni dzień: zmiana
        jednostek last_du (50 000 = przepływ ≈ 5 mln, wielokrotnie ponad progiem). Seria ±stała leżałaby dokładnie na progu |z| = 1."""
        h, p, u = [], 100.0, 1000000
        for i, d in enumerate(cls.days(n, end)):
            if i:
                p = p * (1 + (last_ret if i == n - 1 else (0.5 if i % 2 else -0.5)) / 100)
                u += (1200 if i % 2 else 800) if not (i == n - 1 and last_du is not None) else last_du
            h.append([d, round(p, 6), u])
        return {'iss': iss, 'h': h}

    @classmethod
    def closes(cls, n=70, last_ret=0.1):
        """Zamknięcia rynku tylko z ceną: +0,4 %, +0,4 %, −0,8 % w kółko (ruch ceny strzela co trzeci dzień); ostatni dzień: last_ret %."""
        out, p = [], 50.0
        for i, d in enumerate(cls.days(n)):
            if i:
                p = p * (1 + (last_ret if i == n - 1 else (-0.8 if i % 3 == 0 else 0.4)) / 100)
            out.append([d, round(p, 4)])
        return out

    def test_z_window(self):
        v = [float(x) for x in range(100)]
        prev = v[10:70]
        self.assertAlmostEqual(zd._td_z(v, 70), (70 - zd._mean(prev)) / max(zd._sd(prev), 0.25 * zd._mean(prev)), places=9, msg='dokładnie 60 poprzednich')
        v[70] = 1000.0
        self.assertAlmostEqual(zd._td_z(v, 70), (1000 - zd._mean(prev)) / zd._sd(prev), places=9, msg='wartość i nie wchodzi do średniej ani rozrzutu')
        v[50] = None
        prev59 = [x for x in v[10:70] if x is not None]
        self.assertAlmostEqual(zd._td_z(v, 70), (1000 - zd._mean(prev59)) / zd._sd(prev59), places=9, msg='None pominięty, nie zero')
        self.assertIsNone(zd._td_z([1.0, 2.0] * 20 + [None] * 21 + [5.0], 61), 'tylko 39 liczb w oknie 60 — za mało')
        self.assertIsNotNone(zd._td_z([1.0, 2.0] * 20 + [None] * 20 + [5.0], 60), '40 liczb — wystarczy')
        self.assertIsNone(zd._td_z(v, 0)); self.assertIsNone(zd._td_z(v, 5)); self.assertIsNone(zd._td_z([None] * 70, 69)); self.assertIsNone(zd._td_z([], 0))
        self.assertEqual(zd._td_z([0.0] * 60 + [1.0], 60), 2.0, 'tło z samych zer, dziś napływ: „dużo większy niż zwykle” (+TD_Z2), nie brak')
        self.assertEqual(zd._td_z([0.0] * 60 + [-0.3], 60), -2.0, 'tło z samych zer, dziś odpływ: −TD_Z2')
        z0 = zd._td_z([0.0] * 60 + [0.0], 60)
        self.assertEqual(json.dumps(z0), '0.0', 'zero po samych zerach: z = 0 (spokojny dzień), nie brak i nie −0')
        self.assertEqual(zd._td_z([0.0] * 30 + [None] * 10 + [0.0] * 20 + [5.0], 60), 2.0, 'None pominięty — 50 zer wystarcza')
        self.assertIsNone(zd._td_z([0.0] * 39 + [None] * 21 + [5.0], 60), 'tylko 39 zer w oknie — za mało historii')
        self.assertIsNone(zd._td_z([0.0] * 60 + [None], 60), 'dziś brak — brak, nie zero')
        self.assertEqual(zd._td_z([7.0] * 60 + [7.0], 60), 0.0, 'stała różna od zera: dolna granica rozrzutu, z = 0')
        self.assertAlmostEqual(zd._td_z([5.0] * 60 + [-5.0], 60), -10 / (0.25 * 5), places=9, msg='stała historia: rozrzut = 1/4 typowego dnia')
        self.assertLessEqual(abs(zd._td_z([5.0] * 60 + [-5.0], 60)), 4 / zd.TD_FLOOR)
        self.assertAlmostEqual(zd._td_z([1.0] * 60 + [1.0], 60, demean=False), 1.0, places=9, msg='zwroty bez odejmowania średniej')
        self.assertAlmostEqual(zd._td_z([0.5, -0.5] * 30 + [1.0], 60, demean=False), 2.0, places=9)
        self.assertIsNone(zd._td_z([0.0] * 60 + [1.0], 60, demean=False))

    def test_split_day(self):
        h = self.fund(80)['h']
        for r in h[50:]:
            r[1], r[2] = r[1] / 2, r[2] * 2                                # podział 2:1 od wiersza 50
        rows = zd._fund_rows(h)
        self.assertEqual(len(rows), 80)
        dates, px, ret = zd._td_fund_px(rows)
        self.assertIsNone(ret[50], 'dzień podziału — zwrot to brak, nie −50 %')
        self.assertAlmostEqual(ret[49], (h[49][1] / h[48][1] - 1) * 100, places=9); self.assertAlmostEqual(ret[51], (h[51][1] / h[50][1] - 1) * 100, places=9)
        self.assertEqual(sum(1 for x in ret if x is None), 2, 'tylko pierwszy wiersz i dzień podziału')
        flow = [1.0 + 0.1 * ((-1) ** i) for i in range(80)]                # spokojne dni (1 ± 0,1: z = ±0,4 dzięki dolnej granicy rozrzutu)
        flow[49] = 50.0                                                     # sygnał w dniu 49 → wynik = zwrot dnia 50 (podział) → para pominięta
        retm = [x if i in (49, 50, 51) else None for i, x in enumerate(ret)]   # cena nie strzela (< 40 liczb), zwroty wokół podziału prawdziwe
        self.assertEqual(zd._td_pairs(dates, flow, retm, 0), [], 'para przez dzień podziału pominięta')
        flow[49], flow[48] = 1.1, 50.0
        self.assertEqual(zd._td_pairs(dates, flow, retm, 0), [(dates[48], 'f', 1, 1)], 'dzień przed: wynik = zwrot dnia 49 (+0,5 %), para jest')

    def test_pairs_outcome(self):
        ds = self.days(50)
        flow = [1.0 + 0.1 * ((-1) ** i) for i in range(50)]                # 1 ± 0,1: zwykły dzień z = ±0,4 (spokojny)
        flow[45] = 100.0
        ret = [None] * 50                                                   # cena: za mało liczb — nigdy nie strzela
        ret[46] = -1.0; ret[47] = 1.0
        self.assertEqual(zd._td_pairs(ds, flow, ret, 0), [(ds[45], 'f', 1, 0)], 'pub 0: wynik z sesji t+1 (pudło)')
        self.assertEqual(zd._td_pairs(ds, flow, ret, 1), [(ds[45], 'f', 1, 1)], 'pub 1: sygnał znany w sesji t+1, wynik z t+2 (trafienie)')
        ds3 = ds[:46] + [(datetime.date.fromisoformat(x) + datetime.timedelta(days=7)).isoformat() for x in ds[46:]]
        self.assertEqual(zd._td_pairs(ds3, flow, ret, 1), [], 'pub 1: luka 8 dni między dniem sygnału a sesją publikacji — para pominięta')
        flow[45] = -100.0
        self.assertEqual(zd._td_pairs(ds, flow, ret, 0), [(ds[45], 'f', -1, 1)], 'kierunek −1: spadek = trafienie')
        ret[46] = 0.0
        self.assertEqual(zd._td_pairs(ds, flow, ret, 0), [], 'dzień bez zmiany ceny — ani trafienie, ani pudło')
        ret[46] = -1.0
        ds2 = list(ds); ds2[46] = (datetime.date.fromisoformat(ds[45]) + datetime.timedelta(days=6)).isoformat()
        self.assertEqual(zd._td_pairs(ds2, flow, ret, 0), [], 'przerwa 6 dni — para pominięta')
        fri = self.days(46, '2026-09-18') + ['2026-09-21', '2026-09-22', '2026-09-23', '2026-09-24']
        self.assertEqual(zd._td_pairs(fri, flow, ret, 0), [(fri[45], 'f', -1, 1)], 'piątek → poniedziałek (3 dni) zostaje')
        self.assertEqual(zd._td_pairs(ds, flow, [None] * 50, 0), [], 'bez cen — bez par, nie zero')
        flow2 = [1.0 + 0.1 * ((-1) ** i) for i in range(50)]; flow2[45] = 100.0
        ret2 = [None] * 5 + [0.5 * ((-1) ** i) for i in range(40)] + [-5.0] + [None] * 4   # 40 liczb przed dniem 45; potem brak
        self.assertEqual(zd._td_pairs(ds, flow2, ret2, 0), [(ds[45], 'x', 0, None)], 'dzień sprzeczny (napływ, cena w dół): zwracany bez trafienia')

    def test_bonds(self):
        ds = [d.isoformat() for d in (datetime.date(2026, 6, 1) + datetime.timedelta(days=i) for i in range(120)) if d.weekday() < 5]
        first = next(i for i in range(60, len(ds)) if ds[i][:7] != ds[i - 1][:7])   # pierwszy wiersz miesiąca po 60 dniach
        self.assertTrue(zd._td_month_first(ds, first)); self.assertFalse(zd._td_month_first(ds, first + 1)); self.assertTrue(zd._td_month_first(ds, 0))
        flow = [1.0 + 0.1 * ((-1) ** i) for i in range(len(ds))]          # spokojne dni
        flow[first - 1] = 50.0; flow[first] = 50.0
        ret = [0.6 if i % 2 else -0.2 for i in range(len(ds))]             # cena strzela co drugi dzień — u obligacji nie wchodzi do reguły
        ret[first] = -2.0; ret[first + 1] = 2.0
        pr = zd._td_pairs(ds, flow, ret, 0, bd=True)
        self.assertEqual(pr, [(ds[first], 'f', 1, 1)], 'obligacje: wynik z pierwszej sesji miesiąca pominięty; cena nie wchodzi do reguły')
        self.assertTrue(all(p[1] == 'p' for p in zd._td_pairs(ds[:first - 1], flow[:first - 1], ret[:first - 1], 0, bd=False)), 'akcje: ta sama seria dałaby regułę p')
        self.assertEqual(zd._td_class(0.2, 3.0, bd=True), ('none', 0, 0), 'obligacje: sama cena nie daje reguły')
        self.assertEqual(zd._td_class(1.5, -3.0, bd=True), ('f', 1, 1), 'obligacje: cena nie robi też dnia sprzecznego')
        self.assertEqual(zd._td_class(2.5, 3.0, bd=True), ('f', 1, 2))
        fu = {'TLT': self.fund(80, last_du=50000, last_ret=3.0)}
        d, bd = zd.build_daily({'fundusze': {'f': fu}})
        r = d[0]
        self.assertEqual((r['id'], r['fam'], r['rule'], r['dir'], r['pub']), ('TLT', 'bd', 'f', 1, 0))
        self.assertTrue(zd._isnum(r['zp']) and r['zp'] > 1, 'zp policzone i pokazane, choć nie wchodzi do reguły')

    def test_class_table(self):
        T = {(-1.5, -1.5): ('fp', -1, 2), (-1.5, 0.0): ('f', -1, 1), (-1.5, 1.5): ('x', 0, 0),
             (0.0, -1.5): ('p', -1, 1), (0.0, 0.0): ('none', 0, 0), (0.0, 1.5): ('p', 1, 1),
             (1.5, -1.5): ('x', 0, 0), (1.5, 0.0): ('f', 1, 1), (1.5, 1.5): ('fp', 1, 2)}
        for (zf, zp), exp in T.items():
            self.assertEqual(zd._td_class(zf, zp), exp, (zf, zp))
        self.assertEqual(zd._td_class(None, None), ('none', 0, 0)); self.assertEqual(zd._td_class(None, 1.2), ('p', 1, 1)); self.assertEqual(zd._td_class(-2.0, None), ('f', -1, 2))
        self.assertEqual(zd._td_class(2.5, 1.5), ('fp', 1, 3), 'siła najwyżej 3'); self.assertEqual(zd._td_class(2.5, 2.5), ('fp', 1, 3))
        self.assertEqual(zd._td_class(0.99, 0.99), ('none', 0, 0), 'próg 1 rozrzutu'); self.assertEqual(zd._td_class(1.0, 0.0), ('f', 1, 1))
        self.assertEqual(zd._td_class(0.5, 2.0), ('p', 1, 2)); self.assertEqual(zd._td_class(-0.5, -1.0), ('p', -1, 1))

    def test_pool(self):
        def dates(n, start='2026-01-05'):
            d0, out = datetime.date.fromisoformat(start), []
            while len(out) < n:
                if d0.weekday() < 5:
                    out.append(d0.isoformat())
                d0 += datetime.timedelta(days=1)
            return out
        ds = dates(120)
        lines = {('eq', 'f'): [(d, 1 if i % 3 else 0, 'A') for i, d in enumerate(ds)] + [(d, 1 if i % 3 else 0, 'B') for i, d in enumerate(ds)]}
        with mock.patch.object(zd, 'wilson', wraps=zd.wilson) as w:
            bd = zd._td_pool(lines)
        self.assertEqual(len(bd), 7); self.assertEqual([(b['fam'], b['rule']) for b in bd], list(zd.TD_RULES))
        e = bd[0]
        self.assertEqual((e['k'], e['n'], e['days'], e['m'], e['from'], e['to'], e['need']), (160, 240, 120, 2, ds[0], ds[-1], 0), 'dwa rynki na tych samych dniach: dni < par')
        w.assert_any_call(160, 240, n_eff=120)
        self.assertEqual(e['p'], 66.7); self.assertEqual(e['ci'], list(zd.wilson(160, 240, n_eff=120))); self.assertEqual(e['vd'], 'edge')
        self.assertTrue(e['h1'] > 50 and e['h2'] > 50); self.assertEqual((e['lk'], e['ln'], e['ldays']), (0, 0, 0), 'przed wdrożeniem — licznik pusty')
        for b in bd[1:]:
            self.assertEqual((b['k'], b['n'], b['days'], b['p'], b['ci'], b['h1'], b['h2'], b['m'], b['need'], b['vd'], b['from']),
                             (0, 0, 0, None, [None, None], None, None, 0, 100, 'short', None), 'linia bez par: braki, nie zera')
        anti = zd._td_pool({('pm', 'p'): [(d, 1 if i % 3 == 0 else 0, 'SLV') for i, d in enumerate(ds)]})[5]
        self.assertEqual((anti['fam'], anti['rule'], anti['vd'], anti['p']), ('pm', 'p', 'anti', 33.3)); self.assertTrue(anti['ci'][1] < 50)
        veto = zd._td_pool({('eq', 'p'): [(d, 1 if i < 60 or i % 20 < 9 else 0, 'A') for i, d in enumerate(ds)]})[1]   # 60/60, potem 27/60
        self.assertTrue(veto['ci'][0] > 50 and veto['h1'] > 50 and veto['h2'] < 50, veto)
        self.assertEqual(veto['vd'], 'none', 'druga połowa poniżej 50 — bez przewagi mimo dolnej granicy > 50')
        none = zd._td_pool({('eq', 'fp'): [(d, i % 2, 'A') for i, d in enumerate(ds)]})[2]
        self.assertEqual((none['vd'], none['p']), ('none', 50.0))
        short = zd._td_pool({('pm', 'f'): [(d, 1, 'GLD') for d in ds[:70]]})[4]
        self.assertEqual((short['vd'], short['days'], short['need'], short['p']), ('short', 70, 30, 100.0), 'za mało dni mimo 100 % trafień')
        late = dates(30, '2026-09-28')
        oos = zd._td_pool({('eq', 'f'): [(d, 1, 'A') for d in ds] + [(d, i % 2, 'A') for i, d in enumerate(late)] + [(late[0], 1, 'B')]})[0]
        self.assertEqual((oos['lk'], oos['ln'], oos['ldays']), (16, 31, 30), 'od wdrożenia: tylko daty ≥ TD_SINCE')
        self.assertEqual(zd._td_pool({})[3]['vd'], 'short'); self.assertEqual(zd._td_pool(None)[6]['rule'], 'fp')

    def test_live_clock(self):
        sat = datetime.datetime(2026, 9, 26, 6, 0)
        self.assertTrue(zd._td_live('2026-09-25', sat), 'dane z piątku, sobota — aktualne do poniedziałku 16:15')
        self.assertEqual(zd._td_next('2026-09-25').isoformat(), '2026-09-28', 'następna sesja po piątku = poniedziałek')
        self.assertFalse(zd._td_live('2026-09-24', sat), 'dane z czwartku, sobota — sesja piątkowa minęła')
        self.assertFalse(zd._td_live('2026-09-25', datetime.datetime(2026, 9, 28, 16, 20)), 'poniedziałek 16:20 NY — nieaktualne')
        self.assertTrue(zd._td_live('2026-09-25', datetime.datetime(2026, 9, 28, 15, 0)), 'poniedziałek 15:00 NY — aktualne')
        self.assertTrue(zd._td_live('2026-09-25', datetime.datetime(2026, 9, 28, 16, 14, 59)))
        self.assertFalse(zd._td_live('2026-09-25', datetime.datetime(2026, 9, 28, 16, 15)))
        from zoneinfo import ZoneInfo
        self.assertFalse(zd._td_live('2026-09-25', datetime.datetime(2026, 9, 28, 16, 20, tzinfo=ZoneInfo('America/New_York'))), 'zegar ze strefą — to samo')
        self.assertEqual(zd._td_next('2026-09-26').isoformat(), '2026-09-28'); self.assertEqual(zd._td_next('2026-09-23').isoformat(), '2026-09-24')

    def test_country_rows(self):
        ds = self.days(80)
        ewt = self.fund(80); ewt['h'] = ewt['h'][:-1]                       # ostatni dzień przepływu bez NAV
        tw = {'d': [[d, 100.0 + 20.0 * ((-1) ** i), 0, 0, 0, 3.1 + 0.6 * ((-1) ** i), d] for i, d in enumerate(ds)], 'empty': []}   # spokojne dni
        tw['d'][-1][1] = 5000.0; tw['d'][-1][5] = 155.0
        india = {'d': [[d, 20.0 + 4.0 * ((-1) ** i), 1.0, 0, 0, 88.0] for i, d in enumerate(ds)]}
        india['d'][-1][1] = 900.0
        S = {'obce': {'tw': tw, 'in': india}, 'fundusze': {'f': {'EWT': ewt, 'INDA': self.fund(80)}}}
        d, _ = zd.build_daily(S)
        by = {r['id']: r for r in d}
        self.assertEqual(set(by), {'EWT', 'INDA', 'in_eq', 'tw'})
        t = by['tw']
        self.assertEqual((t['sym'], t['cur'], t['f'], t['fu'], t['grp'], t['iss'], t['pub'], t['date']), ('EWT', 'TWD', 5000.0, 155.0, None, None, 0, ds[-1]))
        self.assertIsNone(t['r']); self.assertIsNone(t['zp']); self.assertNotEqual(t['r'], 0)
        self.assertEqual((t['rule'], t['dir'], t['st'], t['side']), ('f', 1, 'obs', 'buy'), 'sam przepływ (cena: brak) daje regułę f')
        i = by['in_eq']
        self.assertEqual((i['sym'], i['cur'], i['f'], i['fu'], i['rule']), ('INDA', 'USD', 900.0, 900.0, 'f'), 'Indie już w USD: fu = f')
        self.assertTrue(zd._isnum(i['r']) and zd._isnum(i['zp']), 'NAV z tego dnia jest — zwrot policzony')
        d2, b2 = zd.build_daily({'obce': {'tw': tw, 'in': india}})
        self.assertEqual((d2, b2), (None, None), 'bez pliku funduszy — bez wierszy krajów (nie karta z samymi brakami); bez żadnej serii — blok niepoliczony')
        s = zd._td_series_ob({'tw': tw}, zd.TD_OB[1], {'EWT': self.fund(80)})
        self.assertEqual(len(s['dates']), 80); self.assertIsNone(s['ret'][0]); self.assertTrue(all(zd._isnum(x) for x in s['ret'][1:]))
        holes = dict(tw); holes['d'] = tw['d'][:-2] + tw['d'][-1:]         # dzień roboczy bez wiersza → kalendarz sesji: brak
        s = zd._td_series_ob({'tw': holes}, zd.TD_OB[1], {'EWT': self.fund(80)})
        self.assertEqual(len(s['dates']), 80); self.assertIsNone(s['flow'][-2]); self.assertIsNotNone(s['ret'][-2], 'NAV jest, więc zwrot jest')

    def test_build_trendy_integration(self):
        import copy
        S = TrendyV89('test_build_rows').S(); S0 = copy.deepcopy(S)
        out = zd.build_trendy(S)
        with mock.patch.object(zd, 'build_daily', return_value=([], [])):
            ref = zd.build_trendy(S)
        self.assertEqual(S, S0, 'build_trendy nie zmienia wejścia')
        for k in ('f', 'p', 'b', 'rules', 'v'):
            self.assertEqual(out[k], ref[k], f'{k}: część tygodniowa bajt w bajt jak przed łatką')
        self.assertEqual(set(out) - set(ref), set()); self.assertEqual(set(out), {'at', 'v', 'src', 'rules', 'f', 'p', 'b', 'dv', 'dsince', 'dr', 'd', 'bd'})
        self.assertEqual((out['dv'], out['dsince']), (1, '2026-09-28'))
        self.assertEqual(out['dr'], {'lb': 60, 'min': 40, 'z1': 1.0, 'z2': 2.0, 'floor': 0.25, 'gap': 4, 'neff': 100, 'pub': {'ishares': 0, 'ssga': 1},
                                     'pubsym': {'GLD': 0, 'GLDM': 0}, 'excluded': ['br', 'mx', 'th', 'in_bd', 'jp', 'tr', 'cf', 'cs', 'cr', 'ix']})
        self.assertEqual((out['d'], out['bd']), (None, None), 'bez funduszy, krajów i cen — blok niepoliczony (null), nie „zero rynków”')
        self.assertIn('"d": null, "bd": null', json.dumps(out, ensure_ascii=False))
        self.assertEqual([b['id'] for b in out['b']], ['th', 'mx', 'ob'], 'część tygodniowa nietknięta')
        px = self.closes(70)
        out = zd.build_trendy({'ceny': {'q': {'EWC': {'d': px}, 'KSA': {'d': px[:10]}}}})
        self.assertEqual([r['id'] for r in out['d']], ['EWC', 'KSA'], 'bez funduszy: tylko rynki z ceną')
        e = out['d'][0]
        self.assertEqual((e['f'], e['zf'], e['fu'], e['cur'], e['grp'], e['iss'], e['pub']), (None, None, None, None, None, None, 0), 'rynek tylko z ceną: przepływ = brak')
        self.assertTrue(zd._isnum(e['r']) and zd._isnum(e['zp'])); self.assertEqual(out['d'][1]['st'], 'short', '10 dni cen — za mało historii')
        self.assertEqual([(b['fam'], b['rule']) for b in out['bd']], list(zd.TD_RULES), 'same ceny: 7 linii, jest co liczyć')
        self.assertTrue(all(b['n'] == 0 and b['vd'] == 'short' for b in out['bd'] if b['fam'] != 'eq' or b['rule'] != 'p'))
        zd.META['notes'].clear()
        out = zd.build_trendy({'fundusze': {'f': {'IVV': self.fund(80)}}, 'ceny': {'q': {'EWC': {'d': 5}}}})
        self.assertEqual([r['id'] for r in out['d']], ['IVV'], 'zepsuta seria cen — wiersz funduszu zostaje')
        self.assertTrue(any(n.startswith('trendy dziennie EWC:') for n in zd.META['notes']), zd.META['notes'])
        zd.META['notes'].clear()
        S2 = {'fundusze': {'f': {'IVV': self.fund(80)}}}
        ok = zd.build_trendy(S2)
        self.assertEqual([r['id'] for r in ok['d']], ['IVV']); zd.META['notes'].clear()
        with mock.patch.object(zd, 'build_daily', side_effect=RuntimeError('awaria')):
            out = zd.build_trendy(S2)
        self.assertEqual((out['d'], out['bd'], out['dv']), (None, None, 1), 'awaria to nie „zero rynków”: null, strona ukrywa blok')
        self.assertIn('trendy dziennie: awaria', zd.META['notes'])
        for k in ('f', 'p', 'b', 'rules', 'v'):
            self.assertEqual(out[k], ok[k], f'{k}: część tygodniowa policzona jak zwykle')
        self.assertIsNone(zd.build_trendy(None)['d'])

    def test_constants(self):
        import inspect
        self.assertIsInstance(zd.TD_Z1, float); self.assertIsInstance(zd.TD_Z2, float); self.assertIsInstance(zd.TD_FLOOR, float)
        self.assertEqual(len(zd.TD_RULES), 7); self.assertEqual(len(set(zd.TD_RULES)), 7)
        self.assertEqual({f for f, _ in zd.TD_RULES}, {'eq', 'bd', 'pm'}); self.assertNotIn(('bd', 'p'), zd.TD_RULES); self.assertNotIn(('bd', 'fp'), zd.TD_RULES)
        src = inspect.getsource(zd._td_class) + inspect.getsource(zd._td_z) + inspect.getsource(zd._td_pairs) + inspect.getsource(zd._td_pool)
        for sym in list(zd.TD_GRP) + list(zd.TD_PX) + ['in_eq', 'tw', 'hk']:
            self.assertNotRegex(src, r"'" + sym + r"'", f'żadnych progów na rynek: {sym}')
        self.assertFalse(set(zd.TD_FAM['bd']) & set(zd.TD_FAM['pm']))
        self.assertTrue(set(zd.TD_FAM['bd']) | set(zd.TD_FAM['pm']) <= set(zd.TD_GRP), 'rodziny tylko z funduszy z TR_FE')
        self.assertEqual(len(zd.TD_GRP), 37); self.assertEqual(zd.TD_GRP['SPY'], 'fe_us'); self.assertEqual(zd.TD_GRP['SLV'], 'fe_silver')
        self.assertEqual(zd.TD_SINCE, '2026-09-28'); self.assertEqual(zd.TD_V, 1); self.assertEqual(zd.TD_PUB, {'ishares': 0, 'ssga': 1})
        self.assertEqual(zd.TD_PUB_SYM, {'GLD': 0, 'GLDM': 0}); self.assertTrue(set(zd.TD_PUB_SYM) <= set(zd.TD_GRP), 'wyjątki tylko dla funduszy z listy')
        self.assertEqual({t: zd._td_series_fund({t: self.fund(80, iss=i)}, t)['pub'] for t, i in (('GLD', 'ssga'), ('GLDM', 'ssga'), ('SPY', 'ssga'), ('BIL', 'ssga'), ('IAU', 'ishares'))},
                         {'GLD': 0, 'GLDM': 0, 'SPY': 1, 'BIL': 1, 'IAU': 0}, 'wyjątek pliku przed wydawcą; pozostałe pliki wydawcy bez zmian')
        self.assertEqual([o[0] for o in zd.TD_OB], ['in_eq', 'tw', 'hk']); self.assertEqual(len(zd.TD_PX), 9)
        self.assertNotIn('SPY', zd.TD_PX, 'SPY ma przepływy — nie jest rynkiem tylko z ceną')

    def test_rows_nulls_and_states(self):
        fu = {'IVV': self.fund(80, last_du=50000), 'SPY': self.fund(80, end='2026-09-24', iss='ssga'), 'GLD': self.fund(80, last_ret=-3.0, iss='ssga'),
              'SLV': self.fund(30), 'XLK': self.fund(80, last_du=50000, last_ret=-3.0), 'EEM': self.fund(80), 'EWT': self.fund(80, end='2026-09-24')}
        px = self.closes(70)
        tw = {'d': [[d, 100.0 + 20.0 * ((-1) ** i), 0, 0, 0, 3.1 + 0.6 * ((-1) ** i), d] for i, d in enumerate(self.days(80))], 'empty': []}
        tw['d'][-1][1] = None; tw['d'][-1][5] = None                        # ostatni dzień bez liczb (a NAV EWT z tego dnia też brak)
        d, bd = zd.build_daily({'fundusze': {'f': fu}, 'ceny': {'q': {'EWC': {'d': px}}}, 'obce': {'tw': tw}})
        by = {r['id']: r for r in d}
        self.assertEqual([r['id'] for r in d], ['SPY', 'IVV', 'XLK', 'EEM', 'EWT', 'GLD', 'SLV', 'tw', 'EWC'], 'kolejność: fundusze wg TR_FE, kraje, ceny')
        for r in d:
            self.assertIn(r['st'], self.STATES); self.assertIn(r['rule'], ('f', 'p', 'fp', 'x', 'none')); self.assertIn(r['dir'], (-1, 0, 1))
            self.assertIn(r['str'], (0, 1, 2, 3)); self.assertIn(r['vd'], ('edge', 'anti', 'none', 'short', None))
            for k in ('f', 'zf', 'fu', 'r', 'zp'):
                self.assertTrue(r[k] is None or (zd._isnum(r[k]) and not isinstance(r[k], bool)), (r['id'], k, r[k]))
            self.assertEqual(r['side'], ('buy' if r['dir'] > 0 else 'sell') if r['st'] in ('buy', 'sell', 'obs') else 'none', r['id'])
            if r['st'] in ('buy', 'sell', 'obs'):
                self.assertNotEqual(r['dir'], 0); self.assertTrue(r['live'])
            self.assertEqual(r['nx'] > r['date'], True); self.assertEqual(len(r), 24)
        self.assertEqual((by['IVV']['st'], by['IVV']['rule'], by['IVV']['side'], by['IVV']['str'], by['IVV']['vd']), ('obs', 'f', 'buy', 2, 'short'))
        self.assertEqual((by['IVV']['ik'], by['IVV']['in']), (0, 0), 'ten rynek: jeszcze bez par — zero par to prawdziwe zero')
        self.assertEqual((by['SPY']['st'], by['SPY']['pub'], by['SPY']['date'], by['SPY']['nx'], by['SPY']['live'], by['SPY']['age'], by['SPY']['side']),
                         ('stale', 1, '2026-09-24', '2026-09-25', False, 2, 'none'), 'wiersz z czwartku w sobotę — nieaktualny')
        self.assertEqual((by['GLD']['st'], by['GLD']['rule'], by['GLD']['dir'], by['GLD']['side'], by['GLD']['fam']), ('obs', 'p', -1, 'sell', 'pm'))
        self.assertEqual((by['GLD']['iss'], by['GLD']['pub']), ('ssga', 0), 'trust złota: dane dzień wcześniej niż reszta plików wydawcy')
        self.assertEqual((by['SLV']['st'], by['SLV']['zf'], by['SLV']['zp']), ('short', None, None), '30 dni — za mało historii, z = brak')
        self.assertEqual((by['XLK']['st'], by['XLK']['rule'], by['XLK']['dir'], by['XLK']['side'], by['XLK']['str']), ('x', 'x', 0, 'none', 0), 'napływ, ale cena w dół')
        self.assertEqual((by['EEM']['st'], by['EEM']['rule']), ('quiet', 'none'))
        self.assertEqual((by['tw']['st'], by['tw']['f'], by['tw']['fu'], by['tw']['zf']), ('nodata', None, None, None), 'brak liczb z tego dnia — brak, nie zero')
        self.assertEqual((by['EWC']['st'], by['EWC']['f'], by['EWC']['ik'], by['EWC']['in']), ('quiet', None, None, None))
        self.assertEqual(len(bd), 7); self.assertTrue(all(b['vd'] == 'short' for b in bd), 'krótkie serie — wszystkie linie „za mało historii”')
        self.assertEqual((bd[0]['n'], bd[0]['m'], bd[0]['p']), (0, 0, None), 'spokojne przepływy w historii — linia eq·f bez par (brak, nie zero)')
        self.assertTrue(bd[1]['n'] > 0 and bd[1]['m'] >= 1 and bd[1]['days'] < bd[1]['n'], 'eq·p: kilka funduszy na tych samych dniach — dni < par')

    def test_flat_flow_history(self):
        """Przegląd v120, uwaga 1: liczba jednostek bez zmian przez tygodnie (przepływ dokładnie 0 każdego dnia), potem tworzenie jednostek.
        Prawdziwa liczba nie może wyjść jako brak: karta nie może pisać „brak danych”, a test wstecz musi widzieć taki dzień."""
        def hist(last_du):
            h, p = [], 100.0
            for i, d in enumerate(self.days(80)):
                if i:
                    p = p * (1 + (0.1 if i == 79 else (0.5 if i % 2 else -0.5)) / 100)
                h.append([d, round(p, 6), 1000000 + (last_du if i == 79 else 0)])
            return {'iss': 'ishares', 'h': h}
        d, bd = zd.build_daily({'fundusze': {'f': {'EFA': hist(50000), 'EEM': hist(0), 'EWJ': hist(-50000)}}})
        by = {r['id']: r for r in d}
        e = by['EFA']
        self.assertTrue(e['f'] > 4.9, e['f'])
        self.assertEqual((e['zf'], e['rule'], e['dir'], e['str'], e['st'], e['side']), (2.0, 'f', 1, 2, 'obs', 'buy'), 'duży napływ po płaskim tle — sygnał „dużo większy”')
        self.assertEqual((by['EWJ']['zf'], by['EWJ']['rule'], by['EWJ']['side']), (-2.0, 'f', 'sell'), 'odpływ po płaskim tle')
        q = by['EEM']
        self.assertEqual((q['f'], q['zf'], q['rule'], q['st']), (0.0, 0.0, 'none', 'quiet'), 'zero po zerach: prawdziwe 0 i z = 0 (spokojny dzień), nie brak')
        for r in d:
            self.assertFalse(zd._isnum(r['f']) and r['zf'] is None, 'liczba przepływu przy 40+ dniach tła zawsze ma z')
        ds = self.days(50); flow = [0.0] * 50; flow[45] = 12.5
        ret = [None] * 50; ret[46] = 0.7
        self.assertEqual(zd._td_pairs(ds, flow, ret, 0), [(ds[45], 'f', 1, 1)], 'napływ po samych zerach — para f w teście wstecz')

    def test_failure_isolated(self):
        """Przegląd v120, uwaga 2: awaria jednego rynku (test wstecz albo karta) nie kasuje pozostałych; brak kart = None, nie []."""
        fu = {'IVV': self.fund(80), 'EEM': self.fund(80), 'EWJ': self.fund(80)}
        real_pairs, real_row = zd._td_pairs, zd._td_row
        calls = []

        def pairs(*a, **k):
            calls.append(1)
            if len(calls) == 1:
                raise RuntimeError('zła seria')
            return real_pairs(*a, **k)

        def row(s, *a):
            if s['id'] == 'EWJ':
                raise ValueError('zły dzień')
            return real_row(s, *a)
        with mock.patch.object(zd, '_td_pairs', side_effect=pairs), mock.patch.object(zd, '_td_row', side_effect=row):
            d, bd = zd.build_daily({'fundusze': {'f': fu}})
        self.assertEqual([r['id'] for r in d], ['EEM'], 'IVV (test wstecz) i EWJ (karta) bez kart — EEM zostaje')
        self.assertEqual(len(bd), 7)
        self.assertEqual([n for n in zd.META['notes'] if n.startswith('trendy dziennie')], ['trendy dziennie IVV: zła seria', 'trendy dziennie EWJ: zły dzień'])
        zd.META['notes'].clear()
        with mock.patch.object(zd, '_td_row', side_effect=RuntimeError('wszystko')):
            self.assertEqual(zd.build_daily({'fundusze': {'f': fu}}), (None, None), 'żadnej karty — blok niepoliczony, nie „zero rynków”')
        self.assertEqual(len(zd.META['notes']), 3)
        self.assertEqual(zd.build_daily({}), (None, None)); self.assertEqual(zd.build_daily(None), (None, None))
        self.assertEqual(zd.build_daily({'fundusze': {'f': {'IVV': {'iss': 'ishares', 'h': [['2026-09-25', 1.0, 1]]}}}}), (None, None), 'jeden wiersz — bez serii')

    def test_country_price_not_pooled(self):
        """Przegląd v120, uwaga 4: wiersz kraju ma cenę z NAV funduszu, który ma własny wiersz — jego pary „p” nie idą do linii
        zbiorczej (ten sam dzień i ta sama sesja wyniku liczyłyby się dwa razy); pary „f”/„fp” (własne wejście: przepływ zagraniczny) idą."""
        ds = self.days(80)
        india = {'d': [[x, 20.0 + 4.0 * ((-1) ** i), 1.0, 0, 0, 88.0] for i, x in enumerate(ds)]}
        fixed = [(ds[50], 'p', 1, 1), (ds[51], 'f', 1, 0), (ds[52], 'fp', -1, 1), (ds[53], 'x', 0, None)]
        with mock.patch.object(zd, '_td_pairs', return_value=fixed):
            d, bd = zd.build_daily({'obce': {'in': india}, 'fundusze': {'f': {'INDA': self.fund(80)}}})
        self.assertEqual([r['id'] for r in d], ['INDA', 'in_eq'])
        line = {(b['fam'], b['rule']): b for b in bd}
        self.assertEqual((line[('eq', 'p')]['n'], line[('eq', 'p')]['m']), (1, 1), 'eq·p: tylko para funduszu, bez duplikatu z wiersza kraju')
        self.assertEqual((line[('eq', 'f')]['n'], line[('eq', 'f')]['m'], line[('eq', 'fp')]['n'], line[('eq', 'fp')]['m']), (2, 2, 2, 2), 'f i fp z obu wierszy')
        s = zd._td_series_ob({'in': india}, zd.TD_OB[0], {'INDA': self.fund(80)})
        self.assertEqual(s['nopool'], ('p',)); self.assertNotIn('nopool', zd._td_series_fund({'INDA': self.fund(80)}, 'INDA'))
        self.assertNotIn('nopool', d[1], 'klucz wewnętrzny — nie trafia do pliku')

    def test_anti_never_flips_side(self):
        fu = {'IVV': self.fund(80, last_du=50000), 'GLD': self.fund(80, last_du=-50000, iss='ishares')}
        base = zd._td_pool({})
        for vd in ('anti', 'none', 'short', 'edge'):
            fake = [dict(b, vd=vd) for b in base]
            with mock.patch.object(zd, '_td_pool', return_value=fake):
                d, bd = zd.build_daily({'fundusze': {'f': fu}})
            by = {r['id']: r for r in d}
            exp = ('buy', 'sell') if vd == 'edge' else ('obs', 'obs')
            self.assertEqual((by['IVV']['st'], by['IVV']['side'], by['IVV']['dir'], by['IVV']['vd']), (exp[0], 'buy', 1, vd), vd)
            self.assertEqual((by['GLD']['st'], by['GLD']['side'], by['GLD']['dir'], by['GLD']['vd']), (exp[1], 'sell', -1, vd), 'anti/none/short: obserwacja po stronie kierunku, nigdy odwrotnie')
            self.assertEqual([b['vd'] for b in bd], [vd] * 7)


class TrendyDailyCrV123(unittest.TestCase):
    """v123: sygnały dzienne krypto (rodzina „cr”) — doba UTC, 7 dni w tygodniu, na razie tylko ruch ceny (reguła „p”), własna wersja
    reguły i własny licznik „od wdrożenia”. Świat (wiersze, 7 linii) i część tygodniowa bajt w bajt bez zmian. Brak nie jest zerem, bez sieci."""

    NOW = datetime.datetime(2026, 9, 26, 10, 0, tzinfo=datetime.timezone.utc)   # sobota rano (UTC)
    NY = datetime.datetime(2026, 9, 26, 6, 0)                                    # sobota rano w Nowym Jorku (bez strefy, jak w TrendyDailyV120)
    STATES = ('buy', 'sell', 'obs', 'x', 'quiet', 'stale', 'short', 'nodata')
    KEYS = {'at', 'v', 'src', 'rules', 'f', 'p', 'b', 'dv', 'dsince', 'dr', 'd', 'bd'}
    A = (0.4, 0.4, -0.8)     # zwroty w kółko: −0,8 % strzela (z ≈ −1,41), następna doba +0,4 % → pudło (kierunek −1)
    B = (0.4, -0.8, -0.1)    # −0,8 % strzela (z ≈ −1,54), następna doba −0,1 % → trafienie

    def setUp(self):
        ps = [mock.patch.object(zd, '_now_utc', return_value=self.NOW), mock.patch.object(zd, '_ny_now', return_value=self.NY),
              mock.patch.object(zd.urllib.request, 'urlopen', side_effect=AssertionError('sieć w teście'))]
        for p in ps:
            p.start(); self.addCleanup(p.stop)
        zd.META['notes'].clear()

    @staticmethod
    def cdays(n, end='2026-09-25'):
        """n kolejnych dób kalendarzowych (z sobotami i niedzielami) kończących się dobą end — nie dni sesji jak w TrendyDailyV120."""
        e = datetime.date.fromisoformat(end)
        return [(e - datetime.timedelta(days=n - 1 - i)).isoformat() for i in range(n)]

    @classmethod
    def coin(cls, n=80, end='2026-09-25', last_ret=0.1, pat=None, p0=100.0):
        """Zamknięcia jednej pary [doba, zamknięcie] jak w data/ceny-krypto.json: zwrot doby i = pat[i % 3] %, ostatnia doba: last_ret %."""
        pat = pat or cls.A
        out, p = [], p0
        for i, d in enumerate(cls.cdays(n, end)):
            if i:
                p = p * (1 + (last_ret if i == n - 1 else pat[i % 3]) / 100)
            out.append([d, round(p, 6)])
        return out

    @staticmethod
    def kc(**coins):
        """Plik cen krypto w kształcie data/ceny-krypto.json: q[SYM] = {'d': [[doba, zamknięcie]], 'vol': […]}."""
        return {'at': '2026-09-26T02:10:00+00:00', 'quote': 'USDT', 'q': {s: {'d': d, 'vol': []} for s, d in coins.items()}}

    def world(self):
        """Mały świat v120 (fundusze + rynek tylko z ceną) — do sprawdzenia, że krypto go nie rusza."""
        W = TrendyDailyV120
        return {'fundusze': {'f': {'IVV': W.fund(80, last_du=50000), 'GLD': W.fund(80, last_ret=-3.0, iss='ssga'), 'EEM': W.fund(80)}},
                'ceny': {'q': {'EWC': {'d': W.closes(70)}}}}

    @staticmethod
    def dump(x):
        return json.dumps(x, ensure_ascii=False, separators=(',', ':'))   # jak save(): te same bajty co w pliku

    # (a) seria jednej pary
    def test_series(self):
        today = datetime.date(2026, 9, 26)
        rows = self.coin(10, end='2026-09-25', last_ret=1.0)
        s = zd._td_series_cr(self.kc(BTC=rows), 'BTC', today)
        self.assertEqual(s['dates'], self.cdays(10)); self.assertIsNone(s['ret'][0])
        self.assertAlmostEqual(s['ret'][-1], (rows[-1][1] / rows[-2][1] - 1) * 100, places=9)
        self.assertEqual((s['id'], s['sym'], s['fam'], s['grp'], s['iss'], s['pub'], s['cur'], s['flow'], s['fu']), ('BTC', 'BTC', 'cr', None, None, 0, None, None, None))
        gap = rows[:5] + rows[6:]                                            # brak doby 6 (indeks 5)
        s = zd._td_series_cr(self.kc(BTC=gap), 'BTC', today)
        self.assertEqual(len(s['dates']), 9)
        self.assertIsNone(s['ret'][5], 'doba po luce: brak, nie zero i nie zwrot przez dwie doby')
        self.assertAlmostEqual(s['ret'][6], (gap[6][1] / gap[5][1] - 1) * 100, places=9, msg='następna doba po luce — zwykły zwrot')
        self.assertTrue(all(zd._isnum(x) for i, x in enumerate(s['ret']) if i not in (0, 5)))
        late = rows + [['2026-09-26', rows[-1][1] * 2], ['2026-09-27', rows[-1][1] * 3]]
        s = zd._td_series_cr(self.kc(BTC=late), 'BTC', today)
        self.assertEqual(s['dates'][-1], '2026-09-25', 'doba dzisiejsza (UTC) i późniejsze — odrzucone (niezamknięte)')
        bad = [list(r) for r in rows]
        bad[2][1] = 0; bad[3][1] = -5.0; bad[4][1] = float('nan'); bad[6][1] = '101.5'; bad[7][1] = None; bad[8][1] = True
        bad += [['2026-09-2x', 1.0], 'zły wiersz', ['2026-09-25']]
        s = zd._td_series_cr(self.kc(BTC=bad), 'BTC', today)
        self.assertEqual(s['dates'], [rows[i][0] for i in (0, 1, 5, 9)], 'zamknięcia ≤ 0, NaN, tekst, None, bool i złe wiersze odrzucone')
        self.assertEqual([x is None for x in s['ret']], [True, False, True, True], 'luki po odrzuconych wierszach = brak, nie zero')
        self.assertIsNone(zd._td_series_cr(self.kc(BTC=rows[:1]), 'BTC', today), 'jeden wiersz — bez serii')
        self.assertIsNone(zd._td_series_cr(self.kc(BTC=[]), 'BTC', today))
        self.assertIsNone(zd._td_series_cr(self.kc(BTC=rows), 'ETH', today), 'brak pary w pliku — bez serii')
        self.assertIsNone(zd._td_series_cr(None, 'BTC', today)); self.assertIsNone(zd._td_series_cr({'q': None}, 'BTC', today))
        with self.assertRaises(ValueError):
            zd._td_series_cr(self.kc(BTC=[rows[1], rows[0]] + rows[2:]), 'BTC', today)
        with self.assertRaises(ValueError):
            zd._td_series_cr(self.kc(BTC=rows[:3] + [rows[2]] + rows[3:]), 'BTC', today)   # powtórzona doba
        k0 = self.kc(BTC=[list(r) for r in rows]); k1 = json.loads(json.dumps(k0))
        zd._td_series_cr(k0, 'BTC', today); self.assertEqual(k0, k1, 'nie zmienia pliku wejściowego')
        d, bd = zd.build_daily_cr({'ceny-krypto': self.kc(BTC=[rows[1], rows[0]] + rows[2:], ETH=self.coin(80), SOL=self.coin(80))})
        self.assertEqual([r['id'] for r in d], ['ETH', 'SOL'], 'zepsuta seria BTC: bez karty; pozostałe zostają')
        self.assertEqual([n for n in zd.META['notes'] if n.startswith('trendy dziennie krypto')], ['trendy dziennie krypto BTC: daty nie rosną'])
        ds = self.cdays(50); ret = [None] + [0.5 * (-1) ** i for i in range(1, 41)] + [None] * 4 + [3.0, None, 0.5, 0.5, 0.5]
        self.assertEqual(zd._td_pairs(ds, None, ret, 0, False), [], 'sygnał tuż przed luką: bez pary (wynik = brak)')
        ret[46] = 0.5
        self.assertEqual(zd._td_pairs(ds, None, ret, 0, False), [(ds[45], 'p', 1, 1)], 'ta sama doba z wynikiem — para jest')

    # (b) zegar doby UTC
    def test_clock_utc(self):
        from zoneinfo import ZoneInfo
        utc = datetime.timezone.utc
        self.assertTrue(zd._td_live_cr('2026-09-25', datetime.datetime(2026, 9, 26, 0, 0, tzinfo=utc)), 'doba następna (sobota) trwa')
        self.assertTrue(zd._td_live_cr('2026-09-25', datetime.datetime(2026, 9, 26, 23, 59, 59, tzinfo=utc)))
        self.assertFalse(zd._td_live_cr('2026-09-25', datetime.datetime(2026, 9, 27, 0, 0, tzinfo=utc)), 'północ UTC po sobocie — nieaktualne')
        waw = ZoneInfo('Europe/Warsaw')
        self.assertTrue(zd._td_live_cr('2026-09-25', datetime.datetime(2026, 9, 27, 1, 59, 59, tzinfo=waw)), 'Warszawa 01:59:59 = 23:59:59 UTC')
        self.assertFalse(zd._td_live_cr('2026-09-25', datetime.datetime(2026, 9, 27, 2, 0, tzinfo=waw)), 'Warszawa 02:00 = 00:00 UTC')
        self.assertTrue(zd._td_live_cr('2026-09-25', datetime.datetime(2026, 9, 26, 23, 59, 59)), 'zegar bez strefy = UTC')
        self.assertFalse(zd._td_live_cr('2026-09-25', datetime.datetime(2026, 9, 27, 0, 0)))
        self.assertEqual(zd._td_next('2026-09-25').isoformat(), '2026-09-28', 'świat: następna sesja po piątku nadal poniedziałek')
        d, _ = zd.build_daily_cr({'ceny-krypto': self.kc(BTC=self.coin(80))})
        r = d[0]
        self.assertEqual((r['date'], r['nx'], r['live'], r['age']), ('2026-09-25', '2026-09-26', True, 1), 'piątek → sobota (krypto: 7 dni w tygodniu)')
        with mock.patch.object(zd, '_now_utc', return_value=datetime.datetime(2026, 9, 27, 0, 30, tzinfo=utc)):
            d, _ = zd.build_daily_cr({'ceny-krypto': self.kc(BTC=self.coin(80), ETH=self.coin(80, last_ret=3.0))})
        self.assertEqual([(r['st'], r['live'], r['age']) for r in d], [('stale', False, 2)] * 2, 'ok. 00:00–03:00 UTC: przed nowym plikiem karty uczciwie nieaktualne')
        self.assertEqual((d[1]['rule'], d[1]['dir'], d[1]['side']), ('p', 1, 'none'), 'nieaktualna: reguła policzona do opisu, bez strony')
        with mock.patch.object(zd, '_now_utc', return_value=datetime.datetime(2026, 9, 27, 3, 0, tzinfo=utc)):
            d, _ = zd.build_daily_cr({'ceny-krypto': self.kc(BTC=self.coin(81, end='2026-09-26'))})
        self.assertEqual((d[0]['date'], d[0]['nx'], d[0]['live'], d[0]['age']), ('2026-09-26', '2026-09-27', True, 1), 'sobota → niedziela')

    # (c) budowa: 2 pary × 80 dób, jedna linia z własną wersją i datą wdrożenia
    def test_build(self):
        S = {'ceny-krypto': self.kc(ETH=self.coin(80, last_ret=0.1), BTC=self.coin(80, last_ret=3.0))}
        with mock.patch.object(zd, 'wilson', wraps=zd.wilson) as w:
            d, bd = zd.build_daily_cr(S)
        self.assertEqual([r['id'] for r in d], ['BTC', 'ETH'], 'kolejność wg TR_CR_SYMS, nie wg pliku')
        world_keys = list(zd._td_row(zd._td_series_px({'q': {'EWC': {'d': TrendyDailyV120.closes(70)}}}, 'EWC'), {}, {}, self.NY, self.NOW.date()))
        for r in d:
            self.assertEqual(list(r), world_keys, 'ten sam układ pól co karty świata (24)')
            self.assertEqual((r['fam'], r['id'], r['sym'], r['grp'], r['iss'], r['pub']), ('cr', r['sym'], r['sym'], None, None, 0))
            for k in ('f', 'zf', 'fu', 'cur'):
                self.assertIsNone(r[k], (r['id'], k, 'brak przepływu = None, nigdy 0'))
            self.assertIn('"f":null,"cur":null,"fu":null,"zf":null', self.dump(r))
            self.assertIn(r['rule'], ('p', 'none')); self.assertNotEqual(r['rule'], 'x'); self.assertLessEqual(r['str'], 2); self.assertIn(r['st'], self.STATES)
            self.assertTrue(zd._isnum(r['r']) and zd._isnum(r['zp']))
        b_, e_ = d
        self.assertEqual((b_['rule'], b_['dir'], b_['str'], b_['st'], b_['side'], b_['vd']), ('p', 1, 2, 'obs', 'buy', 'short'), 'BTC +3 %: mocny ruch, szara karta (linia za krótka)')
        self.assertEqual((e_['rule'], e_['dir'], e_['str'], e_['st'], e_['side'], e_['vd'], e_['ik'], e_['in']), ('none', 0, 0, 'quiet', 'none', None, None, None))
        self.assertEqual(len(bd), 1)
        b = bd[0]
        self.assertEqual((b['fam'], b['rule'], b['v'], b['since']), ('cr', 'p', 1, '2026-09-28'))
        self.assertEqual(list(b)[-3:], ['vd', 'v', 'since'], 'v i since dopisane na końcu linii')
        sig = [x for i, x in enumerate(self.cdays(80)) if 41 <= i <= 78 and i % 3 == 2]   # −0,8 % z ≥ 40 poprzednimi zwrotami, wynik w pliku
        self.assertEqual((b['k'], b['n'], b['days'], b['m'], b['from'], b['to']), (0, 2 * len(sig), len(sig), 2, sig[0], sig[-1]), 'wspólne doby: dni < par')
        self.assertLess(b['days'], b['n']); self.assertEqual((b['p'], b['vd'], b['need']), (0.0, 'short', 100 - len(sig)), '0 trafień przy n > 0 to prawdziwe 0')
        w.assert_any_call(b['k'], b['n'], n_eff=b['days'])
        self.assertEqual(b['ci'], list(zd.wilson(b['k'], b['n'], n_eff=b['days'])))
        self.assertEqual((b_['ik'], b_['in']), (0, len(sig)), 'BTC: własne pary reguły p')
        self.assertEqual((b['lk'], b['ln'], b['ldays']), (0, 0, 0), 'przed wdrożeniem — licznik pusty')
        self.assertNotRegex(self.dump([d, bd]).lower(), r'binance|coinbase|coin ?metrics|coingecko|defillama|sosovalue', 'bez nazw dostawców')

    def test_since_counter(self):
        """Licznik „od wdrożenia” linii krypto liczy tylko doby sygnału ≥ TD_SINCE_CR — niezależnie od TD_SINCE świata."""
        with mock.patch.object(zd, '_now_utc', return_value=datetime.datetime(2026, 10, 10, 10, 0, tzinfo=datetime.timezone.utc)):
            S = {'ceny-krypto': self.kc(BTC=self.coin(80, end='2026-10-09', pat=self.A), ETH=self.coin(80, end='2026-10-09', pat=self.B))}
            d, bd = zd.build_daily_cr(S)
            with mock.patch.object(zd, 'TD_SINCE', '2020-01-01'):
                d2, bd2 = zd.build_daily_cr(S)
            with mock.patch.object(zd, 'TD_SINCE_CR', '2020-01-01'):
                d3, bd3 = zd.build_daily_cr(S)
        b = bd[0]
        pr = []
        for sym in ('BTC', 'ETH'):
            s = zd._td_series_cr(S['ceny-krypto'], sym, datetime.date(2026, 10, 10))
            pr += zd._td_pairs(s['dates'], None, s['ret'], 0, False)
        late = [(p[0], p[3]) for p in pr if p[0] >= '2026-09-28']
        self.assertEqual((b['lk'], b['ln'], b['ldays']), (sum(h for _, h in late), len(late), len({x for x, _ in late})))
        self.assertEqual((b['lk'], b['ln'], b['ldays']), (3, 7, 7), 'BTC: 4 pudła, ETH: 3 trafienia od 28.09 (różne doby)')
        self.assertLess(b['ln'], b['n']); self.assertEqual(b['n'], len(pr)); self.assertEqual(b['days'], b['n'], 'różne doby sygnałów: dni = pary')
        self.assertEqual(bd2, bd, 'podmiana TD_SINCE (świat) nie zmienia licznika krypto')
        self.assertEqual((bd3[0]['ln'], bd3[0]['lk']), (b['n'], b['k']), 'licznik krypto idzie za TD_SINCE_CR')
        self.assertEqual(bd3[0]['since'], '2020-01-01')

    # (d) build_trendy z plikiem cen krypto i bez niego
    def test_trendy_with_and_without(self):
        import copy
        S = dict(self.world(), **{'ceny-krypto': self.kc(SOL=self.coin(80, last_ret=3.0), BTC=self.coin(80))})
        S0 = copy.deepcopy(S)
        out = zd.build_trendy(S)
        ref = zd.build_trendy({k: v for k, v in S.items() if k != 'ceny-krypto'})
        self.assertEqual(S, S0, 'build_trendy nie zmienia wejścia')
        self.assertEqual(set(out), self.KEYS); self.assertEqual(set(ref), self.KEYS, 'bez nowych kluczy na górze pliku')
        for k in ('at', 'v', 'src', 'rules', 'f', 'p', 'b', 'dv', 'dsince', 'dr'):
            self.assertEqual(self.dump(out[k]), self.dump(ref[k]), f'{k}: bajt w bajt')
        n = len(ref['d'])
        self.assertEqual(n, 4); self.assertEqual(len(ref['bd']), 7)
        self.assertEqual(self.dump(out['d'][:n]), self.dump(ref['d']), 'wiersze świata bez zmian i na początku')
        self.assertEqual(self.dump(out['bd'][:7]), self.dump(ref['bd']), '7 linii świata bez zmian i na początku')
        self.assertEqual([(r['id'], r['fam']) for r in out['d'][n:]], [('BTC', 'cr'), ('SOL', 'cr')], 'dopisane tylko karty krypto, na końcu, wg TR_CR_SYMS')
        self.assertEqual([(b['fam'], b['rule'], b['v'], b['since']) for b in out['bd'][7:]], [('cr', 'p', 1, '2026-09-28')])
        self.assertFalse(any(r['fam'] == 'cr' for r in ref['d']))
        cut = dict(out, d=out['d'][:n], bd=out['bd'][:7])
        self.assertEqual(self.dump(cut), self.dump(ref), 'plik bez wpisów krypto = plik bez pliku cen krypto (bajt w bajt)')
        self.assertEqual(out['src'], ref['src']); self.assertNotIn('ceny-krypto', out['src'], 'src bez zmian (pytanie otwarte 3)')
        self.assertEqual([n_ for n_ in zd.META['notes'] if 'krypto' in n_], [])

    # (e) awarie izolowane
    def test_failures_isolated(self):
        S = dict(self.world(), **{'ceny-krypto': self.kc(BTC=self.coin(80), ETH=self.coin(80))})
        ref = zd.build_trendy({k: v for k, v in S.items() if k != 'ceny-krypto'})
        with mock.patch.object(zd, 'build_daily', side_effect=RuntimeError('awaria świata')):
            out = zd.build_trendy(S)
        self.assertEqual([(r['id'], r['fam']) for r in out['d']], [('BTC', 'cr'), ('ETH', 'cr')], 'świat padł: d = same karty krypto')
        self.assertEqual([(b['fam'], b['rule']) for b in out['bd']], [('cr', 'p')])
        self.assertIn('trendy dziennie: awaria świata', zd.META['notes']); self.assertEqual(set(out), self.KEYS)
        zd.META['notes'].clear()
        with mock.patch.object(zd, 'build_daily_cr', side_effect=RuntimeError('awaria krypto')):
            out = zd.build_trendy(S)
        self.assertEqual(self.dump(out), self.dump(ref), 'krypto padło: plik dokładnie jak bez krypto')
        self.assertEqual([n for n in zd.META['notes'] if 'krypto' in n], ['trendy dziennie krypto: awaria krypto'])
        zd.META['notes'].clear()
        with mock.patch.object(zd, 'build_daily', side_effect=RuntimeError('a')), mock.patch.object(zd, 'build_daily_cr', side_effect=RuntimeError('b')):
            out = zd.build_trendy(S)
        self.assertEqual((out['d'], out['bd']), (None, None), 'obie części padły — null/null, nie puste listy')
        zd.META['notes'].clear()
        real_pairs, real_row = zd._td_pairs, zd._td_row
        calls = []

        def pairs(*a, **k):
            calls.append(1)
            if len(calls) == 1:
                raise RuntimeError('zła seria')
            return real_pairs(*a, **k)

        def row(s, *a):
            if s['id'] == 'SOL':
                raise ValueError('zły dzień')
            return real_row(s, *a)
        with mock.patch.object(zd, '_td_pairs', side_effect=pairs), mock.patch.object(zd, '_td_row', side_effect=row):
            d, bd = zd.build_daily_cr({'ceny-krypto': self.kc(BTC=self.coin(80), ETH=self.coin(80), SOL=self.coin(80))})
        self.assertEqual([r['id'] for r in d], ['ETH'], 'BTC (test wstecz) i SOL (karta) bez kart — ETH zostaje')
        self.assertEqual(len(bd), 1)
        self.assertEqual(zd.META['notes'], ['trendy dziennie krypto BTC: zła seria', 'trendy dziennie krypto SOL: zły dzień'])
        zd.META['notes'].clear()
        with mock.patch.object(zd, '_td_row', side_effect=RuntimeError('wszystko')):
            self.assertEqual(zd.build_daily_cr({'ceny-krypto': self.kc(BTC=self.coin(80))}), (None, None), 'żadnej karty — (None, None), nie []')

    # (f) brak pliku, zły plik, za krótkie serie
    def test_absent(self):
        cases = ({}, None, {'ceny-krypto': None}, {'ceny-krypto': []}, {'ceny-krypto': {}}, {'ceny-krypto': {'q': None}},
                 {'ceny-krypto': {'q': {}}}, {'ceny-krypto': {'q': ['BTC']}}, {'ceny-krypto': {'at': 'x'}},
                 {'ceny-krypto': self.kc(BTC=self.coin(1), ETH=[], SOL=[['2026-09-26', 1.0], ['2026-09-27', 2.0]])})
        for S in cases:
            self.assertEqual(zd.build_daily_cr(S), (None, None), S)
            out = zd.build_trendy(S)
            self.assertEqual((out['d'], out['bd']), (None, None), f'bez świata i bez krypto: null/null ({S})')
        self.assertTrue(any(n.startswith('trendy dziennie krypto BTC:') for n in zd.META['notes']), 'q nie jest słownikiem — uwaga w meta, nie cisza')
        zd.META['notes'].clear()
        ref = zd.build_trendy(self.world())
        out = zd.build_trendy(dict(self.world(), **{'ceny-krypto': {'q': {}}}))
        self.assertEqual(self.dump(out), self.dump(ref), 'plik cen krypto bez par — plik trendów jak dziś')

    # (g) stałe
    def test_constants(self):
        self.assertEqual(zd.TD_VC, 1); self.assertEqual(zd.TD_SINCE_CR, '2026-09-28'); self.assertEqual(zd.TD_RULES_CR, (('cr', 'p'),))
        self.assertEqual(len(zd.TD_RULES), 7); self.assertEqual(zd.TD_V, 1); self.assertEqual(zd.TD_SINCE, '2026-09-28')
        self.assertEqual(zd.TD_EXCLUDED, ('br', 'mx', 'th', 'in_bd', 'jp', 'tr', 'cf', 'cs', 'cr', 'ix'), 'bez zmian: zestaw reguł wersji TD_V')
        self.assertEqual(zd._td_rules()['excluded'], list(zd.TD_EXCLUDED))
        self.assertEqual(zd.TR_CR_SYMS, ('BTC', 'ETH', 'XRP', 'BNB', 'SOL', 'DOGE', 'ADA', 'TRX', 'LINK', 'AVAX'), 'bez stablecoinów (cena ≈ 1 USD)')
        w = zd._td_pool({})
        self.assertEqual([(b['fam'], b['rule']) for b in w], list(zd.TD_RULES)); self.assertTrue(all('v' not in b and 'since' not in b for b in w))
        c = zd._td_pool({}, zd.TD_RULES_CR, zd.TD_SINCE_CR)
        self.assertEqual(len(c), 1)
        self.assertEqual((c[0]['fam'], c[0]['rule'], c[0]['vd'], c[0]['need'], c[0]['n'], c[0]['p'], c[0]['ci']), ('cr', 'p', 'short', 100, 0, None, [None, None]))
        with mock.patch.object(zd, 'TD_RULES', (('eq', 'f'),)):
            self.assertEqual(len(zd._td_pool({})), 1, 'domyślne rules = TD_RULES w chwili wywołania (testy z podmianą działają)')
        lines = {('cr', 'p'): [('2026-09-27', 1, 'BTC'), ('2026-09-28', 1, 'BTC'), ('2026-09-29', 0, 'ETH'), ('2026-09-29', 1, 'BTC')]}
        b = zd._td_pool(lines, zd.TD_RULES_CR, zd.TD_SINCE_CR)[0]
        self.assertEqual((b['k'], b['n'], b['days'], b['m'], b['lk'], b['ln'], b['ldays']), (3, 4, 3, 2, 2, 3, 2))
        with mock.patch.object(zd, 'TD_SINCE', '2026-01-01'):
            self.assertEqual(zd._td_pool(lines, zd.TD_RULES_CR, zd.TD_SINCE_CR)[0]['ln'], 3, 'since podane jawnie — TD_SINCE nie ma wpływu')
            self.assertEqual(zd._td_pool({('eq', 'f'): lines[('cr', 'p')]})[0]['ln'], 4, 'świat: domyślne since = TD_SINCE w chwili wywołania')
        self.assertFalse(any(b['fam'] == 'cr' for b in zd._td_pool(lines)), 'linie świata nie biorą par krypto')

    # (h) stany kart
    def test_states(self):
        utc = datetime.timezone.utc
        miss_last = self.coin(80, last_ret=3.0); miss_last[-1][1] = None                # brak zamknięcia 25.09 → karta z 24.09
        miss_prev = self.coin(80, last_ret=3.0); miss_prev[-2][1] = None                # brak zamknięcia 24.09 → zwrot 25.09 nieznany
        S = {'ceny-krypto': self.kc(BTC=miss_prev, ETH=self.coin(41, last_ret=3.0), XRP=self.coin(42, last_ret=3.0),
                                    BNB=self.coin(80, end='2026-09-24', last_ret=3.0), SOL=miss_last, DOGE=self.coin(80, last_ret=-3.0),
                                    ADA=self.coin(80, last_ret=0.8))}
        d, bd = zd.build_daily_cr(S)
        by = {r['id']: r for r in d}
        self.assertEqual(list(by), ['BTC', 'ETH', 'XRP', 'BNB', 'SOL', 'DOGE', 'ADA'])
        t = by['BTC']
        self.assertEqual((t['date'], t['st'], t['r'], t['zp'], t['rule'], t['dir'], t['side'], t['str']), ('2026-09-25', 'nodata', None, None, 'none', 0, 'none', 0),
                         'brak poprzedniego zamknięcia: zwrot doby = brak (nie 0), karta „brak danych”')
        self.assertEqual((by['ETH']['st'], by['ETH']['zp'], by['ETH']['rule']), ('short', None, 'none'), '39 wcześniejszych zwrotów — za mało historii')
        self.assertEqual((by['XRP']['st'], by['XRP']['rule'], by['XRP']['str']), ('obs', 'p', 2), '40 wcześniejszych zwrotów — wystarczy')
        s = by['BNB']
        self.assertEqual((s['st'], s['rule'], s['dir'], s['str'], s['side'], s['live'], s['nx'], s['age'], s['vd']), ('stale', 'p', 1, 2, 'none', False, '2026-09-25', 2, 'short'),
                         'dane z 24.09 w sobotę: nieaktualne, reguła nadal policzona')
        m = by['SOL']
        self.assertEqual((m['date'], m['st'], m['age']), ('2026-09-24', 'stale', 2), 'brak zamknięcia 25.09: karta z 24.09, nie zwrot 0')
        self.assertEqual((by['DOGE']['st'], by['DOGE']['side'], by['DOGE']['dir']), ('obs', 'sell', -1))
        self.assertEqual((by['ADA']['st'], by['ADA']['str'], by['ADA']['rule']), ('obs', 1, 'p'), 'ruch ≥ 1 rozrzutu, < 2 — siła 1')
        for r in d:
            self.assertEqual(r['side'], ('buy' if r['dir'] > 0 else 'sell') if r['st'] in ('buy', 'sell', 'obs') else 'none', r['id'])
            if r['st'] in ('buy', 'sell', 'obs'):
                self.assertTrue(r['live']); self.assertNotEqual(r['dir'], 0)
        base = zd._td_pool({}, zd.TD_RULES_CR, zd.TD_SINCE_CR)
        S2 = {'ceny-krypto': self.kc(BTC=self.coin(80, last_ret=3.0), ETH=self.coin(80, last_ret=-3.0))}
        for vd in ('anti', 'none', 'short', 'edge'):
            with mock.patch.object(zd, '_td_pool', return_value=[dict(b, vd=vd) for b in base]):
                d, bd = zd.build_daily_cr(S2)
            by = {r['id']: r for r in d}
            exp = ('buy', 'sell') if vd == 'edge' else ('obs', 'obs')
            self.assertEqual((by['BTC']['st'], by['BTC']['side'], by['BTC']['dir'], by['BTC']['vd']), (exp[0], 'buy', 1, vd), vd)
            self.assertEqual((by['ETH']['st'], by['ETH']['side'], by['ETH']['dir'], by['ETH']['vd']), (exp[1], 'sell', -1, vd), 'anti: obserwacja po stronie kierunku, nigdy odwrotnie')
            self.assertEqual([(b['vd'], b['v'], b['since']) for b in bd], [(vd, 1, '2026-09-28')])
        with mock.patch.object(zd, '_now_utc', return_value=datetime.datetime(2026, 9, 27, 0, 0, tzinfo=utc)):
            d, _ = zd.build_daily_cr(S2)
        self.assertEqual([r['st'] for r in d], ['stale', 'stale'], 'koniec soboty UTC — karty z piątku nieaktualne')


import math as _math_v125   # v125: deterministyczne świece i premia w zaślepkach budowniczego (moduł testów nie importował math)


class TrendyDailyCrV125(unittest.TestCase):
    """v125 (SPEC-v125, rewizja 2): sygnały dzienne krypto w wersji reguły 2 — pięć powodów (p, t, e, s, h) z pliku data/krypto-dzien.json,
    dwie linie łączone (n2, all), okno 06:00 → 06:00 UTC, granica „na czas” 05:30 UTC, ocena w próbie zakresem 99,3% ze „zwykłą dobą” i obiema
    połowami historii, dziennik kart (data/krypto-dziennik.json) z punktami kontrolnymi 100/200/400 (zakres 99,8%) i kopią w archiwum,
    budowniczy pliku dziennego (świece, premia kontraktów, archiwum pierwszej publikacji przepływów i podaży stablecoinów) z jednym limitem
    czasu, przebieg główny, archiwum i kontrola. Wersja 1 i świat bez zmian. Bez sieci (get_bytes / get_json / hl_post / urlopen zaślepione)
    i bez prawdziwego zegara (_now_utc przypięty; NOW procesu nie służy do `seen`)."""

    UTC = datetime.timezone.utc
    NOW = datetime.datetime(2026, 9, 27, 9, 0, tzinfo=datetime.timezone.utc)
    CSV0 = zd.TD_CR_CSV                                       # prawdziwa ścieżka kopii dziennika (w testach podmieniana na nieistniejącą)
    ENV_EMPTY = ('SOSOVALUE_KEY', 'COINGECKO_KEY', 'FINNHUB_KEY', 'TWELVEDATA_KEY', 'COINMARKETCAP_KEY', 'FRED_KEY', 'EIA_KEY', 'BLS_KEY',
                 'BEA_KEY', 'SITE_URL', 'CACHE_DIR')
    PROVIDERS = r'binance|coinbase|coin ?metrics|defillama|hyperliquid|sosovalue|coingecko|ishares|ssga'

    def setUp(self):
        import tempfile
        zd.META['errors'].clear(); zd.META['notes'].clear()
        self.tmp = tempfile.mkdtemp(prefix='kd-v125-')
        net = AssertionError('sieć w teście')
        ps = [mock.patch.object(zd, '_now_utc', return_value=self.NOW),
              mock.patch.object(zd.urllib.request, 'urlopen', side_effect=net),
              mock.patch.object(zd, 'get_bytes', side_effect=net), mock.patch.object(zd, 'get_json', side_effect=net),
              mock.patch.object(zd, 'hl_post', side_effect=net),
              mock.patch.object(zd, 'TD_CR_CSV', os.path.join(self.tmp, 'brak', 'krypto-dziennik.csv')),   # archiwum repozytorium nie wchodzi do testu
              mock.patch.object(zd, 'KD_HL_SLEEP', 0)]
        for p in ps:
            p.start(); self.addCleanup(p.stop)
        zd._CR_LOG[0] = zd._CR_LOG[1] = None
        self.addCleanup(zd._CR_LOG.__setitem__, slice(None), [None, None])

    # ---------------------------------------------------------------- pomocnicze
    @staticmethod
    def day(i, d0='2025-01-01'):
        return (datetime.date.fromisoformat(d0) + datetime.timedelta(days=i)).isoformat()

    @classmethod
    def at(cls, d, hh=0, mm=0):
        d = d if isinstance(d, datetime.date) else datetime.date.fromisoformat(d)
        return datetime.datetime.combine(d, datetime.time(hh, mm), cls.UTC)

    @classmethod
    def kd_synth(cls, n=200, syms=('BTC', 'SOL'), seed=7, taker=None, net=None, pub_late=(), d0='2025-01-01'):
        """Mały plik krypto-dzien (n dób od d0, 5 kolumn q, premia 24 h, przepływy BTC/ETH, podaż stablecoinów z kolumną zmiany doby).
        Losowość tylko z random() (ten sam ciąg liczb na każdej platformie i wersji Pythona) — bez funkcji biblioteki matematycznej."""
        import random
        r = random.Random(seed).random

        def nz():
            return (r() + r() + r() + r() - 2.0) * 1.7        # ≈ rozkład normalny (0, 1), sama arytmetyka
        kd = {'q': {}, 'hl': {}, 'cm': {}, 'st': {'d': []}, 'ready': True}
        for s in syms:
            c = 100.0; rows = []
            for i in range(n):
                c *= 1 + 0.02 * nz()
                qv = 1_000_000; tb = int(qv * (taker(i) if taker else 0.5 + 0.02 * nz()))
                rows.append([cls.day(i, d0), round(c, 4), qv, tb, round(c * (1 + 0.005 * nz()), 4)])
            kd['q'][s] = {'d': rows, 'seen': [cls.day(n - 1, d0), cls.day(n, d0) + 'T02:40:00Z'], 'miss': []}
            kd['hl'][s] = {'d': [[cls.day(i, d0), round(0.5 + 0.3 * nz(), 4), 24] for i in range(n)], 'seen': [cls.day(n - 1, d0), cls.day(n, d0) + 'T00:20:00Z']}
        S = 1e11; prev = None
        for i in range(n):
            S += 1e8 + 2e8 * nz()
            kd['st']['d'].append([cls.day(i, d0), int(S * 0.7), int(S * 0.3), None, None, None if prev is None else int(round(S - prev))]); prev = S
        for a in ('btc', 'eth'):
            kd['cm'][a] = {'d': [[cls.day(i, d0), 1000.0 + (net(i) if net else 100 * nz()), 1000.0,
                                  cls.day(i + 1, d0) + ('T07:00:00Z' if i in pub_late else 'T02:30:00Z'), None] for i in range(n)]}
        return kd

    @staticmethod
    def core(kd, now, log=None):
        """build_daily_cr2 bez meta i bez dziennika (jak build_daily_cr2_core sędziego) → (karty, linie, serie, pary linii, ys)."""
        today = now.date()
        series = [x for x in (zd._td_series_cr2(kd, s, today) for s in zd.TR_CR_SYMS) if x]
        lines = {k: [] for k in zd.TD_RULES_CR2}; own = {}; ys = {}
        for s in series:
            ys[s['id']] = {s['dates'][i]: y for i in range(len(s['dates'])) for y in [zd._td_win(s, i)] if y is not None}
            for d, k, v, hit in zd._td_pairs_cr2(s):
                lines[('cr', k)].append((d, hit, s['id'], v))
                if k == 'all':
                    o = own.setdefault(s['id'], [0, 0]); o[0] += hit; o[1] += 1
        bd = zd._td_pool_cr2(lines, ys, log=log, today=today)
        vd = {(b['fam'], b['rule']): b['vd'] for b in bd}
        return [zd._td_row_cr2(s, vd, own, today, now) for s in series], bd, series, lines, ys

    @classmethod
    def mk_s(cls, last=None, n=61, sym='BTC', end='2026-09-26', late=False, on=None):
        """Seria ręczna do kart: każde wejście na przemian +1 / −1 (średnia 0, rozrzut 1), ostatnia doba = last[k] (brak klucza: 0,5 —
        w zwykłym zakresie). ±10 strzela, ±3 mocno. Wejście e tylko dla par z TD_CR_FLOWS."""
        e0 = datetime.date.fromisoformat(end)
        dates = [(e0 - datetime.timedelta(days=n - 1 - i)).isoformat() for i in range(n)]
        keys = ('p', 't', 'e', 's', 'h') if sym in zd.TD_CR_FLOWS else ('p', 't', 's', 'h')
        base = [(-1.0) ** i for i in range(n - 1)]
        inp = {k: base + [(last or {}).get(k, 0.5)] for k in keys}
        onf = {k: [True] * n for k in keys if k != 'p' and k != 't'}
        for k, v in (on or {}).items():
            onf[k][-1] = v
        return {'id': sym, 'sym': sym, 'dates': dates, 'close': [100.0] * n, 'o6': [100.0] * n, 'in': inp, 'on': onf, 'late': late}

    @staticmethod
    def dump(x):
        return json.dumps(x, ensure_ascii=False, separators=(',', ':'))   # jak save(): te same bajty co w pliku

    class Zegar:
        """Umowny zegar monotoniczny do testów terminu budowniczego (testy bez zegara): stoi w miejscu, dopóki atrapa źródła nie „odczeka”
        opóźnienia odpowiedzi — sleep przesuwa go od razu, bez prawdziwego czekania. Podstawiany jako zd.time, czyli tylko w module zbieracza
        (pozostałe funkcje modułu time bez zmian; wątki biblioteki standardowej mają własny zegar), więc wynik nie zależy od szybkości ani
        obciążenia maszyny. Z KD_THREADS = 1 kolejność zapytań i wskazania zegara są za każdym razem te same."""

        def __init__(self, t0=1000.0):
            import threading as _th
            self.t = float(t0); self._lock = _th.Lock()

        def monotonic(self):
            with self._lock:
                return self.t

        def sleep(self, s):
            with self._lock:
                self.t += max(0.0, float(s))

        def __getattr__(self, name):
            import time as _t
            return getattr(_t, name)

    class Fake:
        """Źródła bez sieci (deterministyczne): plik świec doby D jest od D+1 02:10 (miesięczny — od 02:10 pierwszego dnia następnego
        miesiąca), premia kontraktów do `now` (albo do hl_until), Coin Metrics do wczoraj z czasem statusu D+1 02:30. gap = doby bez pliku
        (dziennego i w miesięcznym), no1h = doby bez dziennego pliku 1h, hl_bad = godziny z premią nie-liczbą, rewritten = doby przepisane
        później (czas statusu po 200 dniach), no_eod = doby przepływów bez znacznika końca doby, usdc_no_eod = doby USDC bez znacznika,
        st_shift = przeliczenie całej historii poziomów stablecoinów (USD), flow_shift = przeliczenie przepływów BTC/ETH (monety).
        delay(rodzaj, adres) = opóźnienie odpowiedzi w s (rodzaj 'b' świece, 'j' Coin Metrics, 'h' premia); honor = limit zapytania jak
        w urllib (odpowiedź wolniejsza niż limit → po limicie TimeoutError). tmo = [(rodzaj, limit, pozostały czas budowniczego, adres)]."""

        def __init__(self, now, month_ok=True, hl_sleep=0.0, hl_fail=(), st_shift=0.0, rewritten=(), gap=(), no1h=(), hl_until=None,
                     hl_bad=(), no_eod=(), usdc_no_eod=(), flow_shift=0.0, delay=None, honor=False):
            self.now = now; self.month_ok = month_ok; self.hl_sleep = hl_sleep; self.hl_fail = set(hl_fail); self.st_shift = st_shift
            self.rewritten = set(rewritten); self.gap = set(gap); self.no1h = set(no1h); self.hl_until = hl_until or now
            self.hl_bad = set(hl_bad); self.no_eod = set(no_eod); self.usdc_no_eod = set(usdc_no_eod)
            self.flow_shift = flow_shift; self.delay = delay; self.honor = honor
            self.bytes = []; self.json = []; self.hl = []; self.tmo = []

        def wait(self, kind, timeout, url=''):
            clock = zd.time                          # moduł time zbieracza: prawdziwy albo umowny zegar testu (Zegar) — ten sam, który czyta termin
            T = zd._KD_TERMIN[0]
            self.tmo.append((kind, timeout, None if T is None else T - clock.monotonic(), url))
            d = self.delay(kind, url) if self.delay else 0.0
            if self.honor and timeout is not None and d > timeout:
                clock.sleep(timeout); raise TimeoutError('timed out')
            if d:
                clock.sleep(d)

        @staticmethod
        def ms(dt):
            return int(dt.timestamp() * 1000)

        @staticmethod
        def at(d, hh=0, mm=0):
            return datetime.datetime.combine(d, datetime.time(hh, mm), datetime.timezone.utc)

        @staticmethod
        def close(sym, d):
            return round(100 + 10 * _math_v125.sin(d.toordinal() / 7 + len(sym)) + sum(map(ord, sym)) % 7, 4)

        def kl_rows(self, sym, days, iv):
            import io as _io, zipfile as _zf
            out = []
            for d in days:
                if iv == '1d':
                    t = self.ms(self.at(d)) * (1000 if d.year >= 2025 else 1)       # µs od 2025 r., jak w prawdziwych plikach
                    c = self.close(sym, d); qv = 1e9 + d.toordinal() % 97 * 1e6; tb = qv * (0.5 + 0.03 * _math_v125.sin(d.toordinal()))
                    out.append([t, c, c, c, c, 1, t + 1, qv, 10, 1, tb, 0])
                else:
                    for hh in (5, 6, 7):
                        t = self.ms(self.at(d, hh)) * (1000 if d.year >= 2025 else 1)
                        o = self.close(sym, d) * (1 + hh / 1000)
                        out.append([t, o, o, o, o, 1, t + 1, 1, 1, 1, 1, 0])
            b = _io.BytesIO()
            with _zf.ZipFile(b, 'w') as z:
                z.writestr('x.csv', ''.join(','.join(str(x) for x in r) + '\n' for r in out))
            return b.getvalue()

        def get_bytes(self, url, headers=None, timeout=60):
            import urllib.error as _ue
            self.bytes.append(url); self.wait('b', timeout, url)
            f = url.rsplit('/', 1)[1][:-4]                       # BTCUSDT-1d-2025-06-10 / BTCUSDT-1d-2025-05
            p, iv, per = f.split('-', 2)
            sym = p[:-4]
            nf = _ue.HTTPError(url, 404, 'nf', {}, None)
            if len(per) == 7:
                y, m = map(int, per.split('-'))
                first = datetime.date(y, m, 1); nxt = datetime.date(y + m // 12, m % 12 + 1, 1)
                if not self.month_ok or self.at(nxt, 2, 10) > self.now:
                    raise nf
                return self.kl_rows(sym, [first + datetime.timedelta(days=i) for i in range((nxt - first).days)
                                          if (first + datetime.timedelta(days=i)).isoformat() not in self.gap], iv)
            d = datetime.date.fromisoformat(per)
            if per in self.gap or self.at(d + datetime.timedelta(days=1), 2, 10) > self.now or (iv == '1h' and per in self.no1h):
                raise nf
            return self.kl_rows(sym, [d], iv)

        def hl_post(self, body, timeout=None):
            self.hl.append(body); self.wait('h', timeout, body['coin'])
            if body['coin'] in self.hl_fail:
                raise TimeoutError('timed out')
            if self.hl_sleep:
                zd.time.sleep(self.hl_sleep)
            t0 = body['startTime']; out = []
            t = (t0 // 3600000 + (1 if t0 % 3600000 else 0)) * 3600000
            while t <= self.ms(min(self.now, self.hl_until)) and len(out) < 500:
                prem = 'x' if t in self.hl_bad else '%.8f' % (0.0001 * _math_v125.sin(t / 3.6e6 / 5))
                out.append({'coin': body['coin'], 'time': t, 'premium': prem, 'fundingRate': '0.0000125'})
                t += 3600000
            return out

        def lv(self, d, a):
            base = 1.5e11 if a == 'usdt' else 7e10
            return base + 1e8 * (d.toordinal() % 400) + 3e7 * _math_v125.sin(d.toordinal()) + self.st_shift

        def get_json(self, url, headers=None, timeout=30):
            self.json.append(url); self.wait('j', timeout, url)
            start = datetime.date.fromisoformat(url.split('start_time=')[1][:10])
            y = self.now.date() - datetime.timedelta(days=1)
            rows = []; d = start
            while d <= y:
                pub = self.at(d + datetime.timedelta(days=1), 2, 30)
                if pub > self.now:
                    break
                iso = (pub if d.isoformat() not in self.rewritten else self.at(d + datetime.timedelta(days=200))).strftime('%Y-%m-%dT%H:%M:%S.000000000Z')
                if 'FlowInExNtv' in url:
                    for a in ('btc', 'eth'):
                        r = {'asset': a, 'time': d.isoformat() + 'T00:00:00.000000000Z', 'FlowInExNtv': str(1000 + d.toordinal() % 50 + self.flow_shift),
                             'FlowOutExNtv': '1000', 'FlowInExNtv-status-time': iso, 'FlowOutExNtv-status-time': iso}
                        if d.isoformat() not in self.no_eod:
                            r['AssetEODCompletionTime'] = iso
                        rows.append(r)
                else:
                    for a in ('usdt', 'usdc'):
                        r = {'asset': a, 'time': d.isoformat() + 'T00:00:00.000000000Z', 'SplyCur': str(self.lv(d, a))}
                        if not (a == 'usdc' and d.isoformat() in self.usdc_no_eod):
                            r['AssetEODCompletionTime'] = iso
                        rows.append(r)
                d += datetime.timedelta(days=1)
            return {'data': rows}

    def run_kd(self, fake, prev=None, run_t0=None):
        with mock.patch.object(zd, 'get_bytes', fake.get_bytes), mock.patch.object(zd, 'get_json', fake.get_json), \
                mock.patch.object(zd, 'hl_post', fake.hl_post), mock.patch.object(zd, '_now_utc', lambda: fake.now), \
                mock.patch.object(zd, 'KD_KEEP', 90):
            return zd.build_krypto_dzien(prev, run_t0=run_t0)

    def seeded(self, d, hh=10):
        """Pełny plik na dobę d, godz. hh (kilka przebiegów, aż ready) — okno KD_KEEP = 90 dób dla szybkości testu."""
        kd = None
        for i in range(12):
            kd = self.run_kd(self.Fake(self.at(d, hh, i)), kd)
            if kd['ready']:
                return kd
        self.fail('bez ready po 12 przebiegach: ' + json.dumps(kd['bf']))

    # ---------------------------------------------------------------- 1–2: stałe i granica czasu
    def test_constants(self):
        import inspect
        self.assertEqual(zd.TD_VC2, 2); self.assertEqual([k for _, k in zd.TD_RULES_CR2], ['p', 't', 'e', 's', 'h', 'n2', 'all'])
        self.assertEqual({f for f, _ in zd.TD_RULES_CR2}, {'cr'}); self.assertEqual(zd.TD_CR_M, 7)
        self.assertEqual(round(zd.TD_CR_ZM, 4), 2.6901); self.assertEqual(zd.TD_CR_CL, 99.3); self.assertEqual(zd.TD_CR_LOOKS, (100, 200, 400))
        self.assertEqual(round(zd.TD_CR_ZL, 4), 3.0381); self.assertEqual(zd.TD_CR_CLL, 99.8); self.assertEqual(round(zd.TD_CR_ZP, 4), 0.8416)
        self.assertEqual((zd.TD_CR_WH, zd.TD_CR_CUT, zd.TD_CR_HMIN, zd.TD_CR_Y1), (6, 330, 20, 365))
        # punkt kontrolny dopiero wtedy, gdy wynik doby jest ostateczny: świeca 06:00 doby D+2 jest ponawiana, dopóki ta doba ma < KD_GAP_H
        # godzin (do D+5 00:00) — TD_CR_SETTLE = 5 (przegląd 27.09; było 4)
        self.assertEqual(zd.TD_CR_SETTLE, 5); self.assertGreaterEqual(zd.TD_CR_SETTLE * 24, 2 * 24 + 24 + zd.KD_GAP_H)
        self.assertEqual(zd.TD_CR_IN, (('p', 1), ('t', 1), ('e', -1), ('s', 1), ('h', -1))); self.assertEqual(zd.TD_CR_FLOWS, ('BTC', 'ETH'))
        self.assertEqual(zd.TD_CR_JST, ('buy', 'sell', 'obs', 'x', 'quiet')); self.assertEqual(zd.TD_CR_DIG, {'p': 2, 't': 1, 'e': 0, 's': 0, 'h': 4})
        self.assertEqual(zd.TD_CR_CSV_COLS, ['date', 'coin', 'n', 'state', 'votes', 'saved_at', 'y', 'v', 'since'])
        self.assertEqual(self.CSV0, os.path.join(os.path.dirname(os.path.abspath(zd.__file__)), 'archiwum', 'krypto-dziennik.csv'))
        self.assertIsNotNone(zd._d(zd.TD_SINCE_CR2)); self.assertGreaterEqual(zd.TD_SINCE_CR2, '2026-09-28', 'data wdrożenia wersji 2 (ustawiana przy wydaniu)')
        self.assertFalse(hasattr(zd, 'TD_CR_LOG_KEEP'), 'wiersze dziennika nigdy nie są usuwane')
        self.assertEqual((zd.KD_KEEP, zd.KD_T, zd.KD_T_LATE, zd.KD_LATE, zd.KD_BUDGET, zd.KD_THREADS, zd.KD_TIMEOUT, zd.KD_CM_TIMEOUT), (1100, 60, 20, 480, 40, 4, 20, 30))
        self.assertEqual((zd.KD_POLL_H, zd.KD_GAP_H, zd.KD_HL_CALLS, zd.KD_CM_POLL_H, zd.KD_CM_DAYS, zd.KD_CM_DONE_M, zd.KD_LABEL), (2, 48, 20, 1, 5, 270, 'Krypto dziennie'))
        self.assertTrue(zd.KD_CM_F.startswith(zd.CM_API) and zd.KD_CM_S.startswith(zd.CM_API)); self.assertNotIn('api_key', zd.KD_CM_F + zd.KD_CM_S, 'bez klucza')
        # wersja 1 i świat bez zmian
        self.assertEqual((zd.TD_VC, zd.TD_SINCE_CR, zd.TD_RULES_CR), (1, '2026-09-28', (('cr', 'p'),)))
        self.assertEqual((zd.TD_V, zd.TD_SINCE, len(zd.TD_RULES)), (1, '2026-09-28', 7)); self.assertIn('cr', zd.TD_EXCLUDED)
        self.assertEqual([(b['fam'], b['rule']) for b in zd._td_pool({})], list(zd.TD_RULES), '_td_pool({}) nadal 7 linii świata')
        # żadnego progu ani wyjątku na parę w regułach wersji 2 (przepływy wyłącznie przez TD_CR_FLOWS)
        src = ''.join(inspect.getsource(f) for f in (zd._td_series_cr2, zd._td_votes, zd._td_win, zd._td_pairs_cr2, zd._td_vd_cr2, zd._td_stat,
                                                     zd._td_side, zd._td_y1, zd._td_pool_cr2, zd._td_row_cr2, zd._td_cr_pairs, zd._td_cr_cp,
                                                     zd._td_cr_log, zd.build_daily_cr2))
        for sym in zd.TR_CR_SYMS:
            self.assertNotRegex(src, "'" + sym + "'", sym); self.assertNotRegex(src, "'" + sym.lower() + "'", sym)

    def test_cut(self):
        self.assertEqual(zd._td_cut('2026-09-26'), '2026-09-27T05:30:00'); self.assertEqual(zd._td_cut('2026-12-31'), '2027-01-01T05:30:00')
        self.assertTrue(zd._td_early('2026-09-27T05:29:59Z', '2026-09-26')); self.assertTrue(zd._td_early('2026-09-27T05:29:59+00:00', '2026-09-26'))
        self.assertFalse(zd._td_early('2026-09-27T05:30:00+00:00', '2026-09-26'), '05:30:00 to już po czasie')
        self.assertFalse(zd._td_early(None, '2026-09-26')); self.assertFalse(zd._td_early('', '2026-09-26')); self.assertFalse(zd._td_early('2026-09-27', '2026-09-26'))
        self.assertEqual(zd._td_cal('2026-02-27', '2026-03-02'), ['2026-02-27', '2026-02-28', '2026-03-01', '2026-03-02'])

    # ---------------------------------------------------------------- 3–4: seria i „na czas”
    def test_series(self):
        import copy
        d = self.day
        kd = self.kd_synth(60, syms=('BTC', 'ETH', 'SOL')); kd0 = copy.deepcopy(kd)
        s = zd._td_series_cr2(kd, 'SOL', datetime.date(2025, 3, 30))
        self.assertEqual(kd, kd0, 'seria nie zmienia pliku')
        self.assertEqual((s['id'], s['sym'], len(s['dates']), s['dates'][0], s['dates'][-1]), ('SOL', 'SOL', 60, d(0), d(59)))
        self.assertNotIn('e', s['in'], 'przepływy tylko dla BTC i ETH'); self.assertNotIn('e', s['on'])
        self.assertIn('e', zd._td_series_cr2(kd, 'BTC', datetime.date(2025, 3, 30))['in']); self.assertIn('e', zd._td_series_cr2(kd, 'ETH', datetime.date(2025, 3, 30))['in'])
        del kd['q']['SOL']['d'][30]
        s = zd._td_series_cr2(kd, 'SOL', datetime.date(2025, 3, 30))
        i = s['dates'].index(d(30))
        self.assertEqual(len(s['dates']), 60, 'oś kalendarzowa — luka zostaje dobą z brakiem')
        for k in ('close', 'o6'):
            self.assertIsNone(s[k][i], k)
        self.assertIsNone(s['in']['p'][i]); self.assertIsNone(s['in']['p'][i + 1], 'zmiana przez lukę: brak po obu stronach, nigdy 0'); self.assertIsNone(s['in']['t'][i])
        r = kd['q']['SOL']['d'][5]; self.assertAlmostEqual(s['in']['t'][5], 100 * (2 * r[3] / r[2] - 1))
        self.assertAlmostEqual(s['in']['p'][5], (kd['q']['SOL']['d'][5][1] / kd['q']['SOL']['d'][4][1] - 1) * 100)
        self.assertAlmostEqual(s['in']['h'][5], kd['hl']['SOL']['d'][5][1] / 100)
        self.assertAlmostEqual(s['in']['s'][5], kd['st']['d'][5][5] / 1e6, msg='s = zapisana pierwsza zmiana doby')
        self.assertIsNone(s['in']['s'][0], 'pierwsza zapisana doba: zmiana nieznana'); self.assertIsNone(s['in']['p'][0])
        # t: None, gdy obrót brak / 0, obrót kupujących brak albo większy od obrotu
        q = kd['q']['SOL']['d']
        q[10][2] = None; q[11][2] = 0; q[12][3] = None; q[13][3] = q[13][2] + 1; q[14][3] = 0
        kd['hl']['SOL']['d'][15][2] = 19; kd['hl']['SOL']['d'][16][2] = 20; kd['st']['d'][17][5] = None
        s = zd._td_series_cr2(kd, 'SOL', datetime.date(2025, 3, 30))
        self.assertEqual([s['in']['t'][k] for k in (10, 11, 12, 13)], [None] * 4); self.assertEqual(s['in']['t'][14], -100.0, 'zero kupujących to liczba')
        self.assertIsNone(s['in']['h'][15], 'mniej niż 20 godzin premii'); self.assertIsNotNone(s['in']['h'][16])
        self.assertIsNone(s['in']['s'][17], 'wiersz bez zapisanej zmiany = brak, nigdy różnica poziomów')
        self.assertIsNotNone(s['in']['s'][18])
        # dzisiejsza doba odrzucona; daty muszą rosnąć
        kd = self.kd_synth(50)
        self.assertEqual(zd._td_series_cr2(kd, 'BTC', datetime.date.fromisoformat(d(49)))['dates'][-1], d(48))
        self.assertIsNone(zd._td_series_cr2(kd, 'BTC', datetime.date.fromisoformat(d(1))), 'jedna doba — bez serii')
        self.assertIsNone(zd._td_series_cr2(kd, 'ETH', datetime.date(2026, 1, 1)), 'brak pary w pliku — bez serii')
        self.assertIsNone(zd._td_series_cr2({}, 'BTC', datetime.date(2026, 1, 1))); self.assertIsNone(zd._td_series_cr2(None, 'BTC', datetime.date(2026, 1, 1)))
        bad = copy.deepcopy(kd); bad['q']['BTC']['d'][10][0] = d(9)
        with self.assertRaises(ValueError):
            zd._td_series_cr2(bad, 'BTC', datetime.date(2026, 1, 1))
        bad = copy.deepcopy(kd); bad['q']['BTC']['d'].insert(11, list(bad['q']['BTC']['d'][10]))
        with self.assertRaises(ValueError):
            zd._td_series_cr2(bad, 'BTC', datetime.date(2026, 1, 1))
        bad = copy.deepcopy(kd); bad['q']['BTC']['d'][5] = bad['q']['BTC']['d'][5][:4]; bad['q']['BTC']['d'][6][1] = 0
        self.assertEqual(len(zd._td_series_cr2(bad, 'BTC', datetime.date(2026, 1, 1))['dates']), 50, 'wiersz 4-kolumnowy i zamknięcie 0 — doby z brakiem')
        self.assertIsNone(zd._td_series_cr2(bad, 'BTC', datetime.date(2026, 1, 1))['close'][6])
        # przeliczenie całej historii poziomów stablecoinów nie zmienia s (zmiana doby zapisana z jednej odpowiedzi)
        kd = self.kd_synth(120); s1 = zd._td_series_cr2(kd, 'BTC', datetime.date.fromisoformat(d(120)))
        for r in kd['st']['d'][:100]:
            r[1] -= 235_000_000
        self.assertEqual(zd._td_series_cr2(kd, 'BTC', datetime.date.fromisoformat(d(120)))['in']['s'], s1['in']['s'])

    def test_on_time(self):
        d = self.day
        kd = self.kd_synth(80, syms=('BTC',), pub_late=(70,))
        kd['q']['BTC']['seen'] = [d(79), d(80) + 'T05:31:00Z']; kd['hl']['BTC']['seen'] = [d(79), d(80) + 'T06:10:00Z']
        kd['st']['d'][75][3] = d(76) + 'T05:30:00Z'; kd['st']['d'][73][4] = d(74) + 'T05:30:00Z'
        kd['cm']['btc']['d'][60][4] = d(61) + 'T05:30:00Z'; kd['cm']['btc']['d'][61][4] = d(62) + 'T05:29:00Z'
        s = zd._td_series_cr2(kd, 'BTC', datetime.date.fromisoformat(d(80)))
        self.assertFalse(s['on']['e'][70], 'publikacja dostawcy ≥ 05:30'); self.assertIsNotNone(s['in']['e'][70], 'wartość po czasie zostaje w tle')
        self.assertTrue(s['on']['e'][69]); self.assertFalse(s['on']['e'][60], 'zapis ≥ 05:30'); self.assertTrue(s['on']['e'][61])
        self.assertFalse(s['on']['s'][75], 'publikacja stablecoinów ≥ 05:30'); self.assertFalse(s['on']['s'][73], 'zapis stablecoinów ≥ 05:30')
        self.assertTrue(s['on']['s'][74], 'nieznany czas publikacji = na czas (historia sprzed 28.04.2026)')
        self.assertFalse(s['on']['h'][-1]); self.assertTrue(s['late']); self.assertTrue(all(s['on']['h'][:-1]), 'historia premii — na czas')
        kd = self.kd_synth(80, syms=('BTC',)); t = datetime.date.fromisoformat(d(80))
        s = zd._td_series_cr2(kd, 'BTC', t); self.assertFalse(s['late']); self.assertTrue(s['on']['h'][-1])
        for seen in (None, [d(78), d(79) + 'T02:40:00Z'], [d(79)], 'x', [d(79), None], [d(79), '']):
            kd['q']['BTC']['seen'] = seen; kd['hl']['BTC']['seen'] = seen
            s = zd._td_series_cr2(kd, 'BTC', t)
            self.assertTrue(s['late'], f'nieznany zapis najnowszej doby albo inna doba = po czasie ({seen})'); self.assertFalse(s['on']['h'][-1], seen)
        kd['cm']['btc']['d'][79][3] = None
        self.assertFalse(zd._td_series_cr2(kd, 'BTC', t)['on']['e'][-1], 'przepływ bez czasu publikacji — nie na czas')
        # premia: noc po dobie danych — premia doby 80 zapisana 00:20 (seen), świece 80 jeszcze nie; premia doby 79 zapisana na czas (sp)
        kd = self.kd_synth(80, syms=('BTC',)); kd['hl']['BTC']['d'].append([d(80), 1.0, 24])
        kd['hl']['BTC']['seen'] = [d(80), d(81) + 'T00:20:00Z']; kd['hl']['BTC']['sp'] = [d(79), d(80) + 'T00:20:00Z']
        s = zd._td_series_cr2(kd, 'BTC', datetime.date.fromisoformat(d(81)))
        self.assertEqual(s['dates'][-1], d(79)); self.assertTrue(s['on']['h'][-1], 'premia doby 79 zapisana na czas (sp) — głos zostaje')
        for sp in (None, [d(79), d(80) + 'T05:30:00Z'], [d(78), d(79) + 'T00:20:00Z'], [d(79)], 'x'):
            kd['hl']['BTC']['sp'] = sp
            self.assertFalse(zd._td_series_cr2(kd, 'BTC', datetime.date.fromisoformat(d(81)))['on']['h'][-1], f'sp nieznane, po czasie albo innej doby ({sp})')
        kd['hl']['BTC']['sp'] = [d(79), d(80) + 'T00:20:00Z']; kd['q']['BTC']['seen'] = [d(79), d(80) + 'T05:31:00Z']
        self.assertTrue(zd._td_series_cr2(kd, 'BTC', datetime.date.fromisoformat(d(81)))['late'], 'sp dotyczy tylko premii, nie świec')
        # tło najnowszej doby (TD_LB dób przed nią) zapisane od jej granicy → wejście najnowszej doby po czasie (wartość i z zostają)
        kd = self.kd_synth(80, syms=('BTC',)); t = datetime.date.fromisoformat(d(80)); cut = d(80) + 'T05:30:00Z'
        s0 = zd._td_series_cr2(kd, 'BTC', t); self.assertTrue(s0['on']['e'][-1] and s0['on']['s'][-1])
        for i, ok in ((70, False), (19, False), (18, True)):
            k2 = json.loads(json.dumps(kd)); k2['cm']['btc']['d'][i][4] = cut; k2['st']['d'][i][4] = cut
            s = zd._td_series_cr2(k2, 'BTC', t)
            self.assertEqual((s['on']['e'][-1], s['on']['s'][-1]), (ok, ok), f'wiersz tła {i} zapisany {cut}')
            self.assertEqual((s['in']['e'][-1], s['in']['s'][-1]), (s0['in']['e'][-1], s0['in']['s'][-1]))
            self.assertEqual(s['on']['e'][:-1], s0['on']['e'][:-1][:i] + [False] + s0['on']['e'][i + 1:-1], 'historia: tylko sam wiersz')
        k2 = json.loads(json.dumps(kd)); k2['cm']['btc']['d'][70][4] = d(80) + 'T05:29:59Z'; k2['st']['d'][70][4] = d(80) + 'T05:29:59Z'
        s = zd._td_series_cr2(k2, 'BTC', t); self.assertTrue(s['on']['e'][-1] and s['on']['s'][-1], 'tło zapisane przed granicą — na czas')

    # ---------------------------------------------------------------- 5–6: głosy, okno, pary
    def test_votes(self):
        up = self.mk_s({'p': 10, 't': 10, 'e': 10, 's': 10, 'h': 10}); dn = self.mk_s({k: -10 for k in 'ptesh'})
        V, N = zd._td_votes(up, 60)
        self.assertEqual({k: V[k][2] for k in V}, {'p': 1, 't': 1, 'e': -1, 's': 1, 'h': -1}, 'kierunki z założenia'); self.assertEqual(N, 1)
        V, N = zd._td_votes(dn, 60)
        self.assertEqual({k: V[k][2] for k in V}, {'p': -1, 't': -1, 'e': 1, 's': -1, 'h': 1}); self.assertEqual(N, -1)
        self.assertEqual(list(V), ['p', 't', 'e', 's', 'h'])
        V, N = zd._td_votes(self.mk_s(), 60)
        self.assertEqual(({k: V[k][2] for k in V}, N), ({k: 0 for k in 'ptesh'}, 0), '|z| < 1 → bez głosu')
        self.assertTrue(all(abs(V[k][1]) < 1 for k in V))
        late = self.mk_s({'e': 10}, on={'e': False})
        V, N = zd._td_votes(late, 60)
        self.assertEqual(V['e'][2], 0); self.assertFalse(V['e'][3]); self.assertGreater(V['e'][1], 1, 'z zostaje do opisu'); self.assertEqual(V['e'][0], 10)
        V, N = zd._td_votes(self.mk_s({'p': None, 't': 10}, sym='SOL'), 60)
        self.assertNotIn('e', V); self.assertEqual((V['p'][1], V['p'][2]), (None, 0), 'brak liczby → bez z i bez głosu'); self.assertEqual(N, 1)

    def test_window_and_pairs(self):
        s = {'dates': [self.day(i) for i in range(7)], 'o6': [100.0, 100.0, 110.0, 110.0, 99.0, None, 120.0]}
        self.assertAlmostEqual(zd._td_win(s, 0), 10.0, msg='O6(i+2) / O6(i+1) − 1'); self.assertEqual(zd._td_win(s, 1), 0.0)
        self.assertAlmostEqual(zd._td_win(s, 2), -10.0); self.assertIsNone(zd._td_win(s, 3), 'brak otwarcia → brak'); self.assertIsNone(zd._td_win(s, 5))
        self.assertIsNone(zd._td_win(s, 6))
        V = lambda **kv: {k: (1.0, 1.5 * g if g else 0.2, g, True) for k, g in kv.items()}
        votes = [(V(p=1, t=1, h=0), 2), (V(t=1), 1), (V(p=1, h=-1), 0), (V(e=-1, s=0), -1), (V(p=0), 0), (V(p=1), 1), (V(t=1), 1)]
        pr = zd._td_pairs_cr2(s, votes=votes)
        self.assertEqual(pr, [(self.day(0), 'p', 1, 1), (self.day(0), 't', 1, 1), (self.day(0), 'n2', 1, 1), (self.day(0), 'all', 1, 1),
                              (self.day(2), 'p', 1, 0), (self.day(2), 'h', -1, 1)],
                         '|N| ≥ 2 → n2 i all; y = 0 → bez pary; sprzeczność → tylko pary wejść; brak wyniku → bez pary')
        s['o6'][5] = 90.0
        pr = zd._td_pairs_cr2(s, votes=votes)
        self.assertIn((self.day(3), 'e', -1, 1), pr); self.assertIn((self.day(3), 'all', -1, 1), pr); self.assertNotIn((self.day(3), 'n2', -1, 1), pr, 'N = −1: tylko all')
        self.assertFalse([p for p in pr if p[0] == self.day(4)], 'bez głosów — bez par')

    # ---------------------------------------------------------------- 7: linie
    def _pool(self, hits, rule='t', vote=1, ys=None, today=None, log=None):
        lines = {k: [] for k in zd.TD_RULES_CR2}
        for dd, h in hits:
            lines[('cr', rule)].append((dd, h, 'BTC', vote))
        ys = ys or {'BTC': {self.day(i): (1 if i % 2 == 0 else -1) for i in range(2000)}}
        return {b['rule']: b for b in zd._td_pool_cr2(lines, ys, log=log, today=today or datetime.date(2030, 1, 1))}

    def test_pool(self):
        H = [(self.day(i), 1 if i % 100 < 56 else 0) for i in range(400)]     # 56% w 400 dniach: 95% nad 50, 99,3% nie
        b = self._pool(H)['t']
        self.assertGreater(b['ci'][0], 50); self.assertLess(b['ca'][0], 50); self.assertEqual(b['vd'], 'none')
        self.assertEqual((b['k'], b['n'], b['days'], b['p'], b['b0'], b['m'], b['cl'], b['M'], b['cll']), (224, 400, 400, 56.0, 50.0, 1, 99.3, 7, 99.8))
        self.assertEqual(b['ca'], list(zd.wilson(224, 400, z=zd.TD_CR_ZM, n_eff=400))); self.assertEqual(b['ci'], list(zd.wilson(224, 400, n_eff=400)))
        sq = _math_v125.sqrt(0.5 * 0.5 / 400)
        self.assertEqual((b['thr'], b['mde']), (round(50 + 100 * zd.TD_CR_ZM * sq, 1), round(50 + 100 * (zd.TD_CR_ZM + zd.TD_CR_ZP) * sq, 1)))
        H = [(self.day(i), 1 if i % 100 < 64 else 0) for i in range(400)]
        b = self._pool(H)['t']; self.assertEqual(b['vd'], 'edge'); self.assertLessEqual(b['thr'], b['p']); self.assertGreater(b['mde'], b['thr'])
        self.assertEqual((b['sb']['k'], b['sb']['n'], b['ss']['n'], b['ss']['p'], b['ss']['b0']), (b['k'], b['n'], 0, None, None), 'podział stron: same kupna')
        self.assertEqual(b['sb']['k'] + b['ss']['k'], b['k'])
        b = self._pool([(self.day(i), 1 if (i < 200 and i % 10 < 8) or (i >= 200 and i % 100 < 48) else 0) for i in range(400)])['t']
        self.assertEqual((b['p'], b['h1'], b['h2']), (64.0, 80.0, 48.0)); self.assertGreater(b['ca'][0], 50); self.assertEqual(b['vd'], 'none', 'połowa pod progiem — weto')
        b = self._pool([(self.day(i), 1 if i % 100 < 36 else 0) for i in range(400)])['t']
        self.assertEqual(b['vd'], 'anti', 'odbicie lustrzane')
        b = self._pool([(self.day(i), 1 if i % 100 < 70 else 0) for i in range(90)])['t']
        self.assertEqual((b['vd'], b['need']), ('short', 10), 'mniej niż 100 dni — za krótko')
        # „zawsze kupno” przy 60% okien wzrostowych: zwykła doba ≈ 60 — bez przewagi
        import random
        rnd = random.Random(1); ys = {'TRX': {}}; lines = {k: [] for k in zd.TD_RULES_CR2}
        for i in range(1500):
            yy = 1 if rnd.random() < 0.6 else -1; ys['TRX'][self.day(i)] = yy
            lines[('cr', 'all')].append((self.day(i), 1 if yy > 0 else 0, 'TRX', 1))
        b = {x['rule']: x for x in zd._td_pool_cr2(lines, ys, today=datetime.date(2030, 1, 1))}['all']
        self.assertGreater(b['ca'][0], 50, 'dawna reguła uznałaby przewagę'); self.assertEqual(b['vd'], 'none'); self.assertGreater(b['b0'], 58)
        self.assertEqual(b['sb']['b0'], b['b0']); self.assertGreater(b['thr'], b['b0'], 'próg liczony od zwykłej doby (bm = max(50, b0))')
        # sprzedaż i kupno: podział stron = całość; ostatni rok
        H = [(self.day(i), i % 3 == 0) for i in range(0, 800)]
        lines = {k: [] for k in zd.TD_RULES_CR2}
        for i, (dd, h) in enumerate(H):
            lines[('cr', 'h')].append((dd, int(h), 'BTC', 1 if i % 2 else -1))
        ys = {'BTC': {self.day(i): (1 if i % 2 == 0 else -1) for i in range(800)}}
        b = {x['rule']: x for x in zd._td_pool_cr2(lines, ys, today=datetime.date.fromisoformat(self.day(800)))}['h']
        self.assertEqual((b['sb']['k'] + b['ss']['k'], b['sb']['n'] + b['ss']['n']), (b['k'], b['n']))
        self.assertEqual((b['sb']['b0'], b['ss']['b0'], b['b0']), (50.0, 50.0, 50.0), 'zwykła doba = udział okien wzrostowych monety w okresie linii')
        y1 = [p for p in lines[('cr', 'h')] if p[0] >= self.day(800 - 365)]
        self.assertEqual((b['y1']['n'], b['y1']['k'], b['y1']['from'], b['y1']['to'], b['y1']['days']), (len(y1), sum(p[1] for p in y1), self.day(435), self.day(799), 365))
        self.assertEqual(b['y1']['ci'], list(zd.wilson(b['y1']['k'], b['y1']['n'], n_eff=365)))
        # zawsze 7 linii; puste: brak liczb (None), za krótko; bez dziennika: licznik null, ocena „czekamy”
        bd = zd._td_pool_cr2({}, {}, today=datetime.date(2026, 9, 27))
        self.assertEqual([b['rule'] for b in bd], [k for _, k in zd.TD_RULES_CR2])
        for b in bd:
            self.assertEqual((b['fam'], b['n'], b['k'], b['days'], b['p'], b['b0'], b['thr'], b['mde'], b['vd'], b['need'], b['m']), ('cr', 0, 0, 0, None, None, None, None, 'short', 100, 0))
            self.assertEqual((b['lk'], b['ln'], b['ldays'], b['lvd'], b['lc'], b['lnx'], b['v'], b['since'], b['wh'], b['cut']), (None, None, None, 'wait', None, 100, 2, zd.TD_SINCE_CR2, 6, 330))
            self.assertEqual((b['ci'], b['ca'], b['h1'], b['h2']), ([None, None], [None, None], None, None))
            self.assertEqual((b['sb']['n'], b['ss']['n'], b['y1']['n'], b['y1']['p'], b['y1']['from']), (0, 0, 0, None, None))
        self.assertEqual(list(bd[0]), ['fam', 'rule', 'k', 'n', 'days', 'from', 'to', 'p', 'ci', 'ca', 'cl', 'M', 'b0', 'thr', 'mde', 'h1', 'h2', 'sb', 'ss', 'y1',
                                       'lk', 'ln', 'ldays', 'lvd', 'lc', 'lnx', 'cll', 'm', 'need', 'vd', 'v', 'since', 'wh', 'cut'], 'kolejność pól (SPEC §5.1)')
        self.assertTrue(all(b['lk'] == 0 and b['ln'] == 0 and b['ldays'] == 0 for b in zd._td_pool_cr2({}, {}, log={'rows': []}, today=datetime.date(2026, 9, 27))),
                        'znany pusty dziennik — licznik 0, nie null')

    # ---------------------------------------------------------------- 8: karta
    def test_row(self):
        D = '2026-09-26'; now = self.at('2026-09-27', 9); today = now.date()
        base = {('cr', k): 'none' for _, k in zd.TD_RULES_CR2}
        row = lambda s, vd=None, own=None, n=now: zd._td_row_cr2(s, {**base, **(vd or {})}, own or {}, n.date(), n)
        t_up = self.mk_s({'t': 10})
        r = row(t_up)
        self.assertEqual((r['st'], r['side'], r['vd'], r['ek'], r['rule'], r['dir'], r['N'], r['str']), ('obs', 'buy', 'none', [], 'c', 1, 1, 2), 'jeden powód, mocno (z ≥ 2)')
        self.assertEqual(row(self.mk_s({'t': 1.5}))['str'], 1, 'jeden powód, |z| < 2')
        r = row(t_up, {('cr', 't'): 'edge'})
        self.assertEqual((r['st'], r['side'], r['vd'], r['ek']), ('buy', 'buy', 'edge', ['t']), 'potwierdzona linia po stronie karty → kolor')
        r = row(self.mk_s({'t': -10}), {('cr', 't'): 'edge'}); self.assertEqual((r['st'], r['side'], r['ek']), ('sell', 'sell', ['t']))
        against = self.mk_s({'t': 10, 'p': 10, 'h': 10})                     # t +1, p +1, h −1 → N = +1
        r = row(against, {('cr', 't'): 'edge', ('cr', 'h'): 'edge'})
        self.assertEqual((r['st'], r['ek'], r['vd'], r['N']), ('obs', [], 'none', 1), 'potwierdzony powód przeciw — szara')
        r = row(t_up, {('cr', 't'): 'edge', ('cr', 'all'): 'anti'}); self.assertEqual((r['st'], r['vd']), ('obs', 'anti'), 'linia połączenia „odwrotnie” — szara')
        r = row(against, {('cr', 'all'): 'edge', ('cr', 'h'): 'edge'}); self.assertEqual((r['st'], r['vd']), ('obs', 'none'), 'linia prowadząca edge bez koloru — pokazana jako none')
        two = self.mk_s({'t': 10, 'p': 3})                                    # dwa zgodne, p mocno → siła 3
        r = row(two, {('cr', 'n2'): 'edge'})
        self.assertEqual((r['st'], r['ek'], r['N'], r['str']), ('buy', ['n2'], 2, 3), '|N| ≥ 2 i n2 potwierdzona')
        r = row(two, {('cr', 'n2'): 'anti', ('cr', 'all'): 'edge'}); self.assertEqual(r['st'], 'obs', 'przy |N| ≥ 2 prowadzi n2')
        r = row(two, {('cr', 'all'): 'edge', ('cr', 'p'): 'edge'}); self.assertEqual(r['ek'], ['p', 'all'])
        tie = self.mk_s({'t': 10, 'h': 10})
        r = row(tie, {('cr', 't'): 'edge'})
        self.assertEqual((r['st'], r['rule'], r['dir'], r['side'], r['vd'], r['ek'], r['str'], r['ik'], r['in'], r['ici']), ('x', 'cx', 0, 'none', None, [], 0, None, None, None),
                         'sprzeczna: reguła cx (kod tylko v2 — dopisek do SPEC §5.1)')
        r = row(self.mk_s()); self.assertEqual((r['st'], r['rule'], r['dir'], r['side'], r['vd']), ('quiet', 'c0', 0, 'none', None), 'spokojna: reguła c0')
        # kolejność stanów: stale przed late, late przed x/quiet, short, nodata
        self.assertEqual(row(self.mk_s({'t': 10, 'h': 10}, late=True))['st'], 'late'); self.assertEqual(row(self.mk_s(late=True))['st'], 'late')
        r = row(self.mk_s({'t': 10}, late=True), {('cr', 't'): 'edge'}); self.assertEqual((r['st'], r['side'], r['dir']), ('late', 'none', 1), 'po czasie: sam opis, bez strony')
        self.assertEqual(row(self.mk_s(late=True), n=self.at('2026-09-28', 6))['st'], 'stale')
        self.assertEqual(row(self.mk_s({'t': 10}, n=40))['st'], 'short', '39 wcześniejszych dób — za mało historii')
        self.assertEqual(row(self.mk_s({'t': 10}, n=41))['st'], 'obs')
        self.assertEqual(row(self.mk_s({k: None for k in 'ptesh'}))['st'], 'nodata')
        # aktualna do D+2 06:00 (UTC; zegar bez strefy = UTC)
        self.assertTrue(zd._td_live_cr2(D, datetime.datetime(2026, 9, 28, 5, 59, 59, tzinfo=self.UTC)))
        self.assertFalse(zd._td_live_cr2(D, datetime.datetime(2026, 9, 28, 6, 0, tzinfo=self.UTC)))
        self.assertTrue(zd._td_live_cr2(D, datetime.datetime(2026, 9, 28, 7, 59, tzinfo=datetime.timezone(datetime.timedelta(hours=2)))))
        self.assertFalse(zd._td_live_cr2(D, datetime.datetime(2026, 9, 28, 8, 0, tzinfo=datetime.timezone(datetime.timedelta(hours=2)))))
        self.assertTrue(zd._td_live_cr2(D, datetime.datetime(2026, 9, 28, 5, 0))); self.assertFalse(zd._td_live_cr2(D, datetime.datetime(2026, 9, 28, 6, 0)))
        r = row(t_up, n=self.at('2026-09-28', 5, 59)); self.assertEqual((r['live'], r['age'], r['nx'], r['date']), (True, 2, '2026-09-27', D))
        # rs: kolejność p, t, e, s, h; zaokrąglenia; t = udział kupna w obrocie; lt; własne karty monety
        s = self.mk_s({'p': 1.23456, 't': 10.04, 'e': 12345.6, 's': 157.6, 'h': -0.012345}, on={'e': False})
        r = row(s, own={'BTC': [3, 5]})
        self.assertEqual([x[0] for x in r['rs']], ['p', 't', 'e', 's', 'h'])
        self.assertEqual([x[1] for x in r['rs']], [1.23, 55.0, 12346, 158, -0.0123], 't = 50 + ι/2 (1 miejsce); e i s całkowite; h 4 miejsca')
        self.assertTrue(all(x[2] == round(x[2], 2) for x in r['rs']))
        self.assertEqual(r['rs'][2][3], 0, 'po czasie — bez głosu'); self.assertEqual(r['lt'], ['e'])
        self.assertEqual((r['ik'], r['in'], r['ici']), (3, 5, list(zd.wilson(3, 5))))
        self.assertEqual((r['r'], r['zp']), (r['rs'][0][1], r['rs'][0][2]))
        self.assertEqual([x[0] for x in row(self.mk_s({'t': 10}, sym='SOL'))['rs']], ['p', 't', 's', 'h'], 'bez przepływów dla pozostałych par')
        r = row(t_up)
        self.assertEqual((r['ik'], r['in'], r['ici']), (0, 0, None), 'karta z kierunkiem bez własnych par: 0 z 0, bez zakresu')
        keys = ['id', 'fam', 'grp', 'iss', 'pub', 'sym', 'date', 'nx', 'live', 'age', 'f', 'cur', 'fu', 'zf', 'r', 'zp', 'rule', 'dir', 'side', 'str', 'st',
                'vd', 'ik', 'in', 'ici', 'rs', 'N', 'ek', 'lt']
        self.assertEqual(list(r), keys, 'wszystkie pola wiersza v123 + rs, N, ek, lt, ici')
        self.assertEqual((r['fam'], r['grp'], r['iss'], r['pub'], r['f'], r['cur'], r['fu'], r['zf']), ('cr', None, None, 0, None, None, None, None))

    # stała strony produkcyjnej (index.html v124.3): TRD_DRL — reguły, które przyjmuje trdDRow karty przeglądarki otwartej przed wdrożeniem v125
    V1_TRD_DRL = ('f', 'p', 'fp', 'x', 'none')

    def test_row_rule_codes_v2_only(self):
        """Dopisek do SPEC §5.1 (SPEC-v125-ADDENDUM, 27.09): reguła wiersza v2 to 'c' / 'cx' / 'c0' — nigdy kod v1. Strona sprzed v125 (karta
        przeglądarki otwarta przed wdrożeniem; bez przeładowania czyta nowy plik co 20 min) odrzuca więc KAŻDY wiersz v2, w każdym stanie, i nie
        opisze karty v2 zdaniami v1. Reguła zgadza się z głosami: c ⇔ N ≠ 0, cx ⇔ N = 0 przy głosach, c0 ⇔ bez głosu; N = suma głosów w rs
        (strona v125 sprawdza to samo i dopiero wtedy mapuje cx → x, c0 → none na kopii do kontroli v1)."""
        now = self.at('2026-09-27', 9); after = self.at('2026-09-28', 6)
        base = {('cr', k): 'none' for _, k in zd.TD_RULES_CR2}
        cases = {'obs': (self.mk_s({'t': 10}), None, now), 'buy': (self.mk_s({'t': 10}), {('cr', 't'): 'edge'}, now),
                 'sell': (self.mk_s({'t': -10}), {('cr', 't'): 'edge'}, now), 'x': (self.mk_s({'t': 10, 'h': 10}), None, now),
                 'quiet': (self.mk_s(), None, now), 'late z kierunkiem': (self.mk_s({'t': 10}, late=True), None, now),
                 'late sprzeczna': (self.mk_s({'t': 10, 'h': 10}, late=True), None, now), 'late spokojna': (self.mk_s(late=True), None, now),
                 'stale sprzeczna': (self.mk_s({'t': 10, 'h': 10}), None, after), 'stale spokojna': (self.mk_s(), None, after),
                 'stale z kierunkiem': (self.mk_s({'t': 10}), None, after), 'short': (self.mk_s({'t': 10}, n=40), None, now),
                 'nodata': (self.mk_s({k: None for k in 'ptesh'}), None, now),
                 'głos po czasie (lt)': (self.mk_s({'t': 10, 'e': 10}, on={'e': False}), None, now)}
        got = {}
        for name, (s, vd, n) in cases.items():
            r = zd._td_row_cr2(s, {**base, **(vd or {})}, {}, n.date(), n)
            votes = [x[3] for x in r['rs']]
            got[name] = (r['st'], r['rule'], r['N'])
            self.assertIn(r['rule'], ('c', 'cx', 'c0'), name)
            self.assertNotIn(r['rule'], self.V1_TRD_DRL, name + ': strona sprzed v125 musi odrzucić wiersz v2')
            self.assertEqual(r['N'], sum(votes), name + ': N = suma głosów w rs')
            self.assertEqual(r['rule'], 'c' if r['N'] else ('cx' if any(votes) else 'c0'), name + ': reguła zgodna z głosami')
        self.assertEqual(got, {'obs': ('obs', 'c', 1), 'buy': ('buy', 'c', 1), 'sell': ('sell', 'c', -1), 'x': ('x', 'cx', 0), 'quiet': ('quiet', 'c0', 0),
                               'late z kierunkiem': ('late', 'c', 1), 'late sprzeczna': ('late', 'cx', 0), 'late spokojna': ('late', 'c0', 0),
                               'stale sprzeczna': ('stale', 'cx', 0), 'stale spokojna': ('stale', 'c0', 0), 'stale z kierunkiem': ('stale', 'c', 1),
                               'short': ('short', 'c0', 0), 'nodata': ('nodata', 'c0', 0), 'głos po czasie (lt)': ('obs', 'c', 1)})
        # cały przebieg (10 par, dane syntetyczne, seed 5 — są karty sprzeczne i spokojne): wiersze RÓWNE wynikom referencji sędziego
        # z dopiskiem do §5.1 (wbudowane niżej; odtwarzane skryptem ws5/fix3/regen/regen_exp_v125.py), każdy z kodem v2 zgodnym z głosami
        kd = self.kd_synth(160, syms=zd.TR_CR_SYMS, seed=5)
        with mock.patch.object(zd, '_now_utc', lambda: self.at(self.day(160), 9)), mock.patch.object(zd, 'TD_SINCE_CR2', '2026-09-28'):
            rows, _ = zd.build_daily_cr2({'krypto-dzien': kd})
        self.assertEqual(json.dumps(rows, sort_keys=True, separators=(',', ':'), ensure_ascii=False), self.EXP_V125_CX)
        self.assertEqual(sorted({(r['st'], r['rule']) for r in rows}), [('obs', 'c'), ('quiet', 'c0'), ('x', 'cx')])
        for r in rows:
            v = [x[3] for x in r['rs']]
            self.assertEqual((r['rule'], r['N']), ('c' if sum(v) else ('cx' if any(v) else 'c0'), sum(v)), r['id'])

