    def test_parse_placeholder_and_open_session(self):
        q, dates = zd.wd_parse_nq(self.nq_payload(['2026-04-17', '2026-04-20', '2026-04-21'], ph=('2026-04-20',)), self.at(2026, 4, 22, 0))
