        many = head + ''.join(f'4                FILER {i}                                                       {1732533 + i:<11d} 20260925    edgar/data/{1732533 + i}/0001104659-26-110960.txt\n' for i in range(8))
        self.assertEqual(len(zd.ins_parse_index(many)), 1)

