def _ns_obs_v139(sid, limit=None):
    """Nagranie serii → odpowiedź API: observations malejąco, najwyżej limit wierszy (jak sort_order=desc&limit=)."""
    rows = [x.split('=') for x in NS_REC_V139['fred'][sid].split(',')]
    obs = [{'realtime_start': '2026-09-27', 'realtime_end': '2026-09-27', 'date': d, 'value': v} for d, v in reversed(rows)]
    return {'observations': obs[:limit] if limit else obs}


def _ns_fu_v139(drop=()):
    """Nagranie funduszy → plik fundusze (tylko SPY i IEF; drop — fundusze pominięte)."""
    f = {}
    for t, s in NS_REC_V139['funds'].items():
        if t not in drop:
            f[t] = {'iss': 'x', 'at': NS_REC_V139['fu_at'], 'h': [[d, float(n), int(u)] for d, n, u in (x.split('=') for x in s.split(';'))]}
    return {'at': NS_REC_V139['fu_at'], 'f': f}


class NastrojV139(unittest.TestCase):
    """v139: wskaźnik własny „strach i chciwość” (GLOBAL) — parsowanie serii, średnie, percentyle 12 miesięcy bez zaglądania w przyszłość, zwrot
    akcji wobec obligacji z NAV funduszy, wynik z co najmniej 3 z 4 składników, brak nazwany z powodem (nigdy zero ani zastępstwo), historia
    45 dni, klucz tylko w adresie i maskowany, poprzedni plik przy błędzie, przebieg główny (co 6 h, ponowienie po godzinie), kontrola, strona.
    Bez sieci: get_json zaślepione nagraniem, sleep wyłączony."""

    def setUp(self):
        zd.META['errors'].clear(); zd.META['ok'].clear(); zd.META['notes'].clear()
        self.p_sleep = mock.patch.object(zd.time, 'sleep', lambda s: None); self.p_sleep.start()
        zd.SECRETS[:] = ['TAJNY-FRED-139']

    def tearDown(self):
        self.p_sleep.stop(); zd.SECRETS[:] = []

    def _get(self, fail=(), calls=None):
        def get_json(url, headers=None, timeout=30):
            if calls is not None:
                calls.append(url)
            sid = url.split('series_id=')[1].split('&')[0]
            if sid in fail:
                raise RuntimeError(f'HTTP Error 500 dla {url}')     # dostawca odbija adres z kluczem — komunikat musi być maskowany
            return _ns_obs_v139(sid, int(url.split('limit=')[1].split('&')[0]))
        return get_json

    def test_ns_rows_i_srednie(self):
        j = {'observations': [{'date': '2026-09-25', 'value': '7743.41'}, {'date': '2026-09-24', 'value': '.'}, {'date': '2026-09-23', 'value': ''},
                              {'date': '2026-09-22', 'value': '0'}, {'date': '2026-09-21', 'value': '-1'}, {'date': 'zła', 'value': '5'}, 'x',
                              {'date': '2026-02-30', 'value': '9'}, {'date': '2026-09-19', 'value': '7600.5'}]}
        self.assertEqual(zd.ns_rows(j, 'SP500'), [['2026-09-19', 7600.5], ['2026-09-25', 7743.41]], 'rosnąco; „.”, pusta, 0, ujemna i zła data pominięte (brak, nie zero)')
        with self.assertRaises(RuntimeError):
            zd.ns_rows({'observations': [{'date': '2026-09-25', 'value': '.'}]}, 'SP500')
        with self.assertRaises(RuntimeError) as cm:
            zd.ns_rows({'error_code': 400, 'error_message': 'Bad Request.'}, 'VIXCLS')
        self.assertIn('Bad Request', str(cm.exception))
        r = [['2026-09-%02d' % (i + 1), float(v)] for i, v in enumerate([10, 12, 14, 16])]
        self.assertEqual(zd.ns_ma(r, 3), [['2026-09-03', 14 / 12 - 1, 14.0, 12.0], ['2026-09-04', 16 / 14 - 1, 16.0, 14.0]], 'średnia z n ostatnich z bieżącą')
        self.assertEqual(zd.ns_ma(r, 5), [])
        self.assertEqual(zd.ns_pct([1, 2, 3, 4], 3), 62.5, '2 mniejsze + ½ równej (ona sama) z 4')
        self.assertEqual(zd.ns_pct([5, 5, 5, 5], 5), 50.0, 'same równe = środek, nie 0 ani 100')
        self.assertEqual(zd.ns_pct([1, 2, 3], 3), 100 * 2.5 / 3)

    def test_ns_sb_i_skladnik(self):
        spy = [['2026-01-%02d' % d, 100 + d, 5] for d in range(1, 26)] + [['2026-01-26', 126.0, 5], ['2026-01-26', 126.0, 5]]
        ief = [['2026-01-%02d' % d, 50 + d / 100, 3] for d in range(2, 27)]
        sb = zd.ns_sb(spy, ief, 20)
        self.assertEqual(sb[0][0], '2026-01-22', 'wspólne dni od 2.01; zwrot z 20 wspólnych sesji wstecz')
        self.assertAlmostEqual(sb[0][2], 122 / 102 - 1); self.assertAlmostEqual(sb[0][3], 50.22 / 50.02 - 1); self.assertAlmostEqual(sb[0][1], (122 / 102) - (50.22 / 50.02))
        self.assertEqual(len(zd.ns_sb(spy, [['2026-01-%02d' % d, 50.0, 3] for d in range(2, 27)], 20)), 0, 'wiersze powtórzone (ten sam NAV i jednostki — dzień wolny) liczą się raz')
        self.assertEqual(len(sb), 5)
        spy2 = [r[:] for r in spy]; spy2[-2][1] = 400.0; spy2[-1][1] = 400.0   # podział jednostek / błąd pliku — iloraz ponad 2
        self.assertNotIn('2026-01-26', [r[0] for r in zd.ns_sb(spy2, ief, 20)])
        ser = [['2025-%02d-%02d' % (1 + i // 28, 1 + i % 28), float(i), 0, 0] for i in range(300)]   # rosnąca miara
        w, c = zd.ns_comp(ser, 'spx', ser[-1][0])
        self.assertIsNone(w); self.assertEqual((c['n'], c['pct'], c['score']), (252, round(100 * 251.5 / 252, 1), round(100 * 251.5 / 252, 1)))
        w, c2 = zd.ns_comp(ser, 'vix', ser[-1][0])
        self.assertEqual(c2['score'], round(100 - 100 * 251.5 / 252, 1), 'zmienność: wysoko = strach (odwrócona)')
        self.assertEqual(zd.ns_comp(ser, 'spx', '2024-12-31'), ('nodata', None))
        self.assertEqual(zd.ns_comp(ser, 'spx', '2026-01-10'), ('stale', None), 'ostatnia obserwacja 28.11.2025 — starsza niż 5 dni')
        self.assertEqual(zd.ns_comp(ser[:200], 'spx', ser[199][0]), ('short', None), 'okno krótsze niż 240')
        w, c3 = zd.ns_comp(ser, 'spx', ser[260][0])
        self.assertEqual((c3['date'], c3['n']), (ser[260][0], 252), 'dzień z przeszłości: tylko obserwacje do niego')

    def test_nagranie_wynik_skladniki_i_historia(self):
        calls = []
        with mock.patch.object(zd, 'get_json', self._get(calls=calls)):
            out = zd.build_nastroj('TAJNY-FRED-139', {'fundusze': _ns_fu_v139()}, None)
        self.assertEqual(len(calls), 3)
        for u, sid in zip(calls, ('VIXCLS', 'BAMLH0A0HYM2', 'SP500')):
            self.assertIn(f'series_id={sid}&api_key=TAJNY-FRED-139&file_type=json&sort_order=desc&limit=460', u)
        self.assertEqual(out['now'], {'date': '2026-09-25', 'v': 62.2, 'n': 4})
        self.assertEqual(out['ok'], {'vix': True, 'hy': True, 'spx': True, 'sb': True}); self.assertEqual((out['miss'], out['why']), ([], {}))
        C = out['c']
        self.assertEqual({k: C[k]['date'] for k in C}, {'vix': '2026-09-22', 'hy': '2026-09-24', 'spx': '2026-09-25', 'sb': '2026-09-24'}, 'każdy składnik z własnym dniem')
        self.assertEqual((C['vix']['v'], C['vix']['ma'], C['vix']['score']), (14.21, 16.08, 72.4))
        self.assertEqual((C['hy']['v'], C['hy']['score']), (2.8, 55.4))
        self.assertEqual((C['spx']['v'], C['spx']['ma'], C['spx']['score']), (7743.41, 7426.0, 38.3))
        self.assertEqual((C['sb']['rs'], C['sb']['rb'], C['sb']['score']), (0.002179, -0.038946, 82.7))
        self.assertEqual(out['now']['v'], round((72.4 + 55.4 + 38.3 + 82.7) / 4, 1))
        self.assertTrue(all(c['n'] == 252 for c in C.values()), 'pełne okno 12 miesięcy')
        d = out['d']
        self.assertEqual(d[-1], ['2026-09-25', 62.2, 4]); self.assertEqual(d[0][0], '2026-08-12'); self.assertEqual(len(d), 33)
        self.assertTrue(all(zd._d(r[0]).weekday() < 5 and 0 <= r[1] <= 100 and r[2] >= zd.NS_MIN for r in d))
        self.assertEqual([r[0] for r in d], sorted(r[0] for r in d))
        # bez zaglądania w przyszłość: wynik dnia z historii = wynik liczony z serii uciętych do tego dnia
        day = '2026-09-11'; v_hist = dict((r[0], r[1]) for r in d)[day]
        cut = lambda j: {'observations': [o for o in j['observations'] if o['date'] <= day]}   # noqa: E731
        fu = _ns_fu_v139(); [f.__setitem__('h', [r for r in f['h'] if r[0] <= day]) for f in fu['f'].values()]
        with mock.patch.object(zd, 'get_json', lambda url, headers=None, timeout=30: cut(self._get()(url))):
            out2 = zd.build_nastroj('TAJNY-FRED-139', {'fundusze': fu}, None)
        self.assertEqual(out2['now']['date'], day); self.assertEqual(out2['now']['v'], v_hist)
        self.assertEqual(json.loads(json.dumps(out)), out, 'plik JSON bez NaN i obiektów')
        self.assertNotIn('TAJNY', json.dumps(out)); self.assertEqual(out['src'], zd.NS_SRC)
        for bad in ('FRED', 'St. Louis', 'Cboe', 'ICE', 'BofA', 'SPDR', 'iShares'):
            self.assertNotIn(bad, zd.NS_SRC, 'opis w pliku bez nazw dostawców')

    def test_brak_skladnika_nazwany_i_klucz_maskowany(self):
        with mock.patch.object(zd, 'get_json', self._get(fail=('VIXCLS',))):
            out = zd.build_nastroj('TAJNY-FRED-139', {'fundusze': _ns_fu_v139()}, None)
        self.assertEqual((out['now']['n'], out['miss'], out['why']), (3, ['vix'], {'vix': 'fetch'}))
        self.assertEqual(out['now']['v'], round((55.4 + 38.3 + 82.7) / 3, 1), 'średnia z trzech — bez zastępstwa brakującego')
        self.assertIs(out['ok']['vix'], False); self.assertNotIn('vix', out['c'])
        err = [e for e in zd.META['errors'] if e.startswith('Nastroje: ')]
        self.assertEqual(len(err), 1); self.assertIn('VIXCLS', err[0]); self.assertNotIn('TAJNY', err[0]); self.assertIn('***', err[0])
        zd.META['errors'].clear()
        with mock.patch.object(zd, 'get_json', self._get(fail=('VIXCLS', 'SP500'))):
            out = zd.build_nastroj('TAJNY-FRED-139', {'fundusze': _ns_fu_v139(drop=('IEF',))}, None)
        self.assertEqual((out['now'], out['d']), (None, []), 'jeden składnik — żadnego wyniku, nie „wynik” z jednej liczby')
        self.assertEqual(out['why'], {'vix': 'fetch', 'spx': 'fetch', 'sb': 'nodata'}); self.assertEqual(list(out['c']), ['hy'])
        calls = []
        with mock.patch.object(zd, 'get_json', self._get(calls=calls)):
            out = zd.build_nastroj('', {'fundusze': _ns_fu_v139()}, None)
        self.assertEqual(calls, [], 'bez klucza — bez zapytań'); self.assertEqual(out['why'], {'vix': 'nodata', 'hy': 'nodata', 'spx': 'nodata'})
        self.assertIsNone(out['now']); self.assertEqual(list(out['c']), ['sb'])
        with mock.patch.object(zd, 'get_json', self._get()):
            with self.assertRaises(RuntimeError):
                zd.build_nastroj('', {}, None)                       # nic — wyjątek (przebieg główny zostawia poprzedni plik)

    def test_blad_przy_mlodszym_lepszym_pliku_zostawia_poprzedni(self):
        prev = {'at': _iso(60), 'now': {'date': '2026-09-25', 'v': 62.2, 'n': 4}, 'd': [], 'ok': {}}
        with mock.patch.object(zd, 'get_json', self._get(fail=('SP500',))):
            with self.assertRaises(RuntimeError) as cm:
                zd.build_nastroj('TAJNY-FRED-139', {'fundusze': _ns_fu_v139()}, prev)
        self.assertIn('poprzedni plik', str(cm.exception)); self.assertNotIn('TAJNY', str(cm.exception))
        old = dict(prev, at=_iso(40 * 60))
        with mock.patch.object(zd, 'get_json', self._get(fail=('SP500',))):
            out = zd.build_nastroj('TAJNY-FRED-139', {'fundusze': _ns_fu_v139()}, old)
        self.assertEqual((out['now']['n'], out['miss']), (3, ['spx']), 'poprzedni starszy niż 36 h — nowy plik z nazwanym brakiem')

    def test_przebieg_glowny(self):
        saved = {}
        stubs = [mock.patch.object(zd, n, side_effect=RuntimeError('offline')) for n in dir(zd) if n.startswith('build_') and n != 'build_nastroj' and callable(getattr(zd, n))]
        env = {k: '' for k in ('SOSOVALUE_KEY', 'COINGECKO_KEY', 'FINNHUB_KEY', 'TWELVEDATA_KEY', 'COINMARKETCAP_KEY', 'EIA_KEY', 'BLS_KEY', 'BEA_KEY', 'SITE_URL', 'CACHE_DIR')}
        env['FRED_KEY'] = 'TAJNY-FRED-139'
        ok = {k: True for k in zd.NS_KEYS}
        young = {'at': _iso(10), 'ok': ok, 'd': []}
        mid_bad = {'at': _iso(90), 'ok': dict(ok, sb=False), 'd': []}
        mid_ok = {'at': _iso(90), 'ok': ok, 'd': []}
        old = {'at': _iso(7 * 60), 'ok': ok, 'd': []}
        built = {'at': zd.NOW, 'ok': ok, 'd': []}
        [p.start() for p in stubs]
        try:
            def run(prev, build, fu=None):
                calls = []
                def prv(name):
                    return prev if name == 'nastroj' else fu if name == 'fundusze' else None
                with mock.patch.dict(os.environ, env, clear=False), mock.patch.object(zd, 'save', lambda n, o: saved.__setitem__(n, o) or zd.SAVED.__setitem__(n, o)), \
                     mock.patch.object(zd, 'previous', prv), \
                     mock.patch.object(zd, 'build_nastroj', side_effect=(lambda k, S, p: calls.append((k, dict(S), p)) or build) if not isinstance(build, Exception) else build):
                    zd.main()
                return calls
            self.assertEqual(run(young, AssertionError('nie powinien budować')), []); self.assertIs(saved['nastroj'], young); self.assertEqual(zd.META['ok']['nastroj'], 'cached')
            self.assertEqual(run(mid_ok, AssertionError('nie powinien budować')), []); self.assertEqual(zd.META['ok']['nastroj'], 'cached', '90 min, komplet — z pamięci')
            fu = {'at': _iso(30), 'f': {}}
            c = run(mid_bad, built, fu)
            self.assertEqual(len(c), 1, 'brak składnika sprzed 90 min — ponowienie'); self.assertEqual(c[0][0], 'TAJNY-FRED-139'); self.assertIs(c[0][2], mid_bad)
            self.assertIs(c[0][1].get('fundusze'), fu, 'fundusze z tego przebiegu (zapisane wcześniej w main)'); self.assertIs(zd.META['ok']['nastroj'], True)
            self.assertEqual(len(run(old, built)), 1); self.assertIs(saved['nastroj'], built)
            run(old, dict(built, ok=dict(ok, vix=False))); self.assertIs(zd.META['ok']['nastroj'], False, 'składnik bez liczby = źródło bez pełnej odpowiedzi')
            saved.clear()
            run(old, RuntimeError('offline')); self.assertIs(saved['nastroj'], old, 'awaria — poprzedni plik'); self.assertIs(zd.META['ok']['nastroj'], False)
            self.assertIn('Nastroje: offline', zd.META['errors'])
            saved.clear()
            run(None, RuntimeError('offline')); self.assertNotIn('nastroj', saved, 'bez poprzedniego pliku i bez danych — nic')
        finally:
            [p.stop() for p in stubs]

    def test_kod_kontrola_strona_i_zaslepki(self):
        root = os.path.dirname(os.path.abspath(__file__))
        src = open(zd.__file__, encoding='utf-8').read()
        a = src.index('# ===================== v139: NASTROJE RYNKÓW'); b = src.index('\ndef parse_deriv(', a)
        blok = src[a:b]
        self.assertIn('def build_nastroj(', blok); self.assertNotIn('os.environ', blok, 'klucz tylko z przebiegu głównego')
        self.assertLess(src.index('def build_fred('), a, 'blok zaraz po FRED')
        self.assertEqual(sorted(zd.FRED_SERIES), ['DTWEXBGS', 'RRPONTSYD', 'WALCL', 'WDTGAL', 'WFASECL1', 'WMTSECL1', 'WSEFINOL', 'WSEFINTL1'], 'fred.json — same serie Fed (v293, audyt G2: TGA jako stan na środę WDTGAL)')
        self.assertEqual(zd.NS_SERIES, (('vix', 'VIXCLS'), ('hy', 'BAMLH0A0HYM2'), ('spx', 'SP500')))
        head = src[:src.index("FRED = 'https://api.stlouisfed.org")]
        self.assertIn('VIXCLS i BAMLH0A0HYM2 — wskazane wprost w zadaniu właściciela', head)
        self.assertIn('SP500 — do potwierdzenia przez właściciela', head, 'zgoda na SP500 nie jest udawana')
        self.assertNotIn('zgoda właściciela 27.09 na', src, 'bez przypisywania właścicielowi zgody, której zadanie nie zawiera')
        self.assertIn('SP500 — w zadaniu nie ma tej serii', blok); self.assertIn('DO POTWIERDZENIA', blok)
        self.assertEqual((zd.NS_WIN, zd.NS_WIN_MIN, zd.NS_MIN, zd.NS_STALE_D, zd.NS_HIST_D, zd.NS_EVERY, zd.NS_RETRY, zd.NS_KEEP_H, zd.NS_RET, zd.NS_MA),
                         (252, 240, 3, 5, 45, 360, 60, 36, 20, {'vix': 50, 'spx': 125}))
        m = src.index('def main():'); m0 = src.index("prev_ns = previous('nastroj')")
        self.assertTrue(m < src.index("if prev_fu: save('fundusze', prev_fu)") < m0 < src.index("_CR_LOG[0] = previous('krypto-dziennik')"), 'po funduszach, przed trendami')
        self.assertIn("META['errors'].append(mask(f'{NS_LABEL}: {e}')); META['ok']['nastroj'] = False", src); self.assertEqual(zd.NS_LABEL, 'Nastroje')
        me = open(__file__, encoding='utf-8').read()
        tup = zd.re.compile(r"for (?:f|fn) in\s*\(\s*('build_\w+'(?:\s*,\s*'build_\w+')*)\s*\)", zd.re.S)
        lists = [x.group(1) for x in tup.finditer(me) if "'build_wieloryby'" in x.group(1)]
        self.assertGreaterEqual(len(lists), 18); self.assertEqual([s[:60] for s in lists if "'build_nastroj'" not in s], [], 'każda krotka zaślepek zna build_nastroj')
        i = me.index('def test_meta_is_always_written'); j = me.index('\n    def ', i + 1)
        self.assertIn("'Indeksy', 'Nastroje', 'Rynki'", me[i:j], 'etykieta błędów meta')
        k = open(os.path.join(root, 'narzedzia', 'kontrola.py'), encoding='utf-8').read()
        PL = eval(zd.re.search(r'^PLIKI = (\[.*\])$', k, zd.re.M).group(1)); LM = eval(zd.re.search(r'^LIMIT_MIN = (\{[^}]*\})', k, zd.re.M).group(1))
        self.assertIn('nastroj', PL); self.assertEqual(LM['nastroj'], 12 * 60, 'plik co 6 h: dwa przebiegi bez nowego pliku = uwaga')
        h = open(os.path.join(root, 'index.html'), encoding='utf-8').read()
        self.assertEqual(h.count('<section class="panel pcard fg" id="g-fg" hidden></section>'), 1); self.assertEqual(h.count('<section class="panel fg" id="c-fg" hidden></section>'), 1)
        self.assertIn("srvJSON('nastroj')", h); self.assertIn('const EXTRA136=', h)
        wf = open(os.path.join(root, '.github', 'workflows', 'strona.yml'), encoding='utf-8').read()
        self.assertIn('FRED_KEY: ${{ secrets.FRED_KEY }}', wf, 'ten sam sekret — bez nowego')


