        self.assertIn('limit czasu', zd.META['errors'][0]); self.assertEqual(self.imgs, [], 'budżet wyczerpany — loga w następnym przebiegu')
        self.assertTrue(any('w następnym przebiegu' in x for x in zd.META['notes']), zd.META['notes'])
