        srv = _JpxSrv({}); self.assertIs(zd.build_jpx(J, {}, now=now + datetime.timedelta(minutes=20), get=srv), J); self.assertEqual(srv.calls, [])
        # zły plik z archiwum — „bad”, bez ponawiania; jego tygodnie zostają luką
