        R = self._routes(W, lm=self.LM2); R[zd.JPX_EN + 'index.html'] = self._lroute(self._listing(W), self.LM2)

        def slow(lst, rest):
            def g(url, ims=None, timeout=None):
                clock[0] += lst if url.endswith('index.html') else rest
