def _wtg161_get(calls=None, body=None, down=False):
    """Udawane API Horizon: get(url, headers, timeout) → odpowiedź /assets (body, domyślnie nagranie); down — błąd połączenia."""
    def get(url, headers=None, timeout=30):
        if calls is not None:
            calls.append((url, headers, timeout))
        if down:
            raise _socket_v150.timeout('timed out')
        return json.loads(json.dumps(_WTG161_XLM if body is None else body))
    return get


class RwaWisdomTreeV161(unittest.TestCase):
    """v161: WisdomTree w odczycie własnym — tylko WTGXX (1 USD za jednostkę), 8 sieci z dokumentu funduszu (nowe: Base, Plume, Stellar przez Horizon);
    czytnik Stellar (jednostki 10^-7, ścisły zapis), pełna konfiguracja (5 produktów), sumy bez podwójnego liczenia, nota zakresu, kontrola dzienna.
    Bez sieci (atrapy węzłów i Horizon)."""
    NOW = _RWC150_NOW

    def setUp(self):
        zd.META['errors'].clear(); zd.META['ok'].clear(); zd.META['notes'].clear()
        self.enterContext(mock.patch.object(zd, '_now_utc', lambda: self.NOW))
        self.enterContext(mock.patch.object(zd, 'post_json', side_effect=AssertionError('test nie może pytać sieci')))
        self.enterContext(mock.patch.object(zd, 'get_bytes', side_effect=AssertionError('test nie może pytać sieci')))
        self.enterContext(mock.patch.object(zd, 'get_json', side_effect=AssertionError('test nie może pytać sieci')))
        self.enterContext(mock.patch.dict(zd.RWC_PRODUKTY, {k: v for k, v in zd.RWC_PRODUKTY.items() if k not in ('pleasing-gold', 'raac')}, clear=True))   # v169: konfiguracja sprzed Pleasing Gold (v169 ma własne testy pełnej); v173: i RAAC

    def _rd(self, now=None, xlm=None, **kw):
        calls, gcalls = [], []
        post = _rwc150_post(calls=calls, sup={**_WTG161_SUP, **kw.pop('sup', {})}, dec={**_WTG161_DEC, **kw.pop('dec', {})}, **kw)
        rd = zd.rwc_odczyt(now or self.NOW, post=post, sleep=lambda s: None, get=xlm or _wtg161_get(gcalls))
        return rd, calls, gcalls

    def _oc(self, now=None, rez=None, prev=None, **kw):
        rd, calls, gcalls = self._rd(now, **kw)
        return zd.rwc_blok(rd, prev, now or self.NOW, rez=rez), calls, gcalls

    def test_konfiguracja(self):
        P = zd.RWC_PRODUKTY
        self.assertEqual(sorted(P), ['blackrock-buidl', 'circle-usyc', 'paxos-gold', 'tether-gold', 'wisdomtree'])
        w = P['wisdomtree']
        self.assertEqual((w['name'], w['seg'], w['cena'], w['zakres']), ('WisdomTree (WTGXX)', 'tb', 'nav1', 'WTGXX'))
        self.assertEqual([(t[0], t[2]) for t in w['tokeny']], [('eth', 18), ('arb', 18), ('avax', 18), ('base', 18), ('op', 18), ('plume', 18), ('sol', 9), ('xlm', 7)],
                         '8 sieci z dokumentu funduszu')
        self.assertEqual(w['tokeny'][-1][1], 'WTGX:' + _WTG161_ISS)
        self.assertTrue(all(re.fullmatch(r'0x[0-9a-f]{40}', t[1]) for t in w['tokeny'][:6]), 'adresy EVM małymi literami')
        self.assertEqual({k: zd.RWC_SIECI[k] for k in ('base', 'plume', 'xlm')},
                         {'base': ('https://base-rpc.publicnode.com', 'https://1rpc.io/base', 'evm'), 'plume': ('https://rpc.plume.org', None, 'evm'),
                          'xlm': ('https://horizon.stellar.org', None, 'xlm')})
        self.assertIn('horizon.stellar.org', zd.RWC_SRC); self.assertIn('WisdomTree WTGXX', zd.RWC_SRC)

    def test_czytnik_stellar(self):
        j = json.loads(json.dumps(_WTG161_XLM))
        self.assertEqual(zd.rwc_xlm_supply(j, 'WTGX', _WTG161_ISS), 22848388079854)
        j2 = json.loads(json.dumps(_WTG161_XLM)); r = j2['_embedded']['records'][0]
        r['balances'].update(authorized_to_maintain_liabilities='1.5000000', unauthorized='0.0000001'); r.update(claimable_balances_amount='2.0000000', contracts_amount='10.0000000')
        self.assertEqual(zd.rwc_xlm_supply(j2, 'WTGX', _WTG161_ISS), 22848388079854 + 15000000 + 1 + 20000000 + 100000000, 'wszystkie części podaży')
        for zmiana in ({'contracts_amount': None}, {'contracts_amount': '0'}, {'claimable_balances_amount': '1.5'}, {'liquidity_pools_amount': '-1.0000000'},
                       {'asset_issuer': 'GXXX'}, {'asset_code': 'WTGXX'}, {'balances': None}, {'liquidity_pools_amount': 0}):
            jj = json.loads(json.dumps(_WTG161_XLM)); jj['_embedded']['records'][0].update(zmiana)
            self.assertIsNone(zd.rwc_xlm_supply(jj, 'WTGX', _WTG161_ISS), zmiana)
        jj = json.loads(json.dumps(_WTG161_XLM)); jj['_embedded']['records'][0]['balances']['authorized'] = '1e9'
        self.assertIsNone(zd.rwc_xlm_supply(jj, 'WTGX', _WTG161_ISS), 'zapis wykładniczy — nie')
        for zle in (None, [], {}, {'_embedded': None}, {'_embedded': {'records': []}}, {'_embedded': {'records': [_WTG161_XLM['_embedded']['records'][0]] * 2}}):
            self.assertIsNone(zd.rwc_xlm_supply(zle, 'WTGX', _WTG161_ISS), zle)
        self.assertEqual([zd._rwc_xlm_int(x) for x in ('0.0000000', '12.3456789', '123456789012345.0000001', '1.234567', '01.0000000x', 1)],
                         [0, 123456789, 1234567890123450000001, None, None, None])

    def test_odczyt_pelny_piec_produktow(self):
        rd, calls, gcalls = self._rd()
        per = {}
        for sid, kind, url, body, tmo in calls:
            per[sid] = per.get(sid, 0) + 1
        self.assertEqual(per, {'eth': 1, 'arb': 1, 'op': 1, 'pol': 1, 'avax': 1, 'bsc': 1, 'tempo': 1, 'arc': 1, 'sol': 1, 'apt': 2, 'base': 1, 'plume': 1})
        self.assertEqual([(u, h, t <= zd.RWC_TIMEOUT) for u, h, t in gcalls],
                         [('https://horizon.stellar.org/assets?asset_code=WTGX&asset_issuer=' + _WTG161_ISS, {'Accept': 'application/json'}, True)])
        self.assertEqual(rd['r']['xlm']['sup'], {'WTGX:' + _WTG161_ISS: 2284838.8079854}); self.assertIsNone(rd['r']['xlm']['err'])
        eth = [b for s, k, u, b, t in calls if s == 'eth'][0]
        self.assertEqual(len(eth), 1 + 2 * 6 + 2 + 2, 'Ethereum: blok + 6 tokenów (z WTGXX) × (podaż, miejsca) + 2 wyrocznie + 2 × owner()')
        oc = zd.rwc_blok(rd, None, self.NOW, rez=zd.rwc_rezerwy(self.NOW, get=lambda u, h, t: _TETHER160))
        W = oc['p']['wisdomtree']
        self.assertEqual((W['n'], W['nr'], W['un'], W['px'], W['full'], W['zakres']), (8, 8, [], 1.0, True, 'WTGXX'))
        self.assertAlmostEqual(W['v'], _WTG161_SUMA, delta=0.01); self.assertAlmostEqual(W['v'] / 1e9, 1.2267, delta=0.0001, msg='ok. 1,23 mld USD (04.10)')
        self.assertTrue(oc['ok']); self.assertEqual(oc['notes'], [])
        U = zd.rwc_uzyj(oc, self.NOW)
        self.assertEqual(set(U), {'blackrock-buidl', 'paxos-gold', 'circle-usyc', 'tether-gold', 'wisdomtree'})
        self.assertAlmostEqual(U['wisdomtree'], _WTG161_SUMA, delta=0.01)

    def test_siec_bez_odpowiedzi_bez_wyceny(self):
        oc, _c, gcalls = self._oc(xlm=_wtg161_get(down=True))
        W = oc['p']['wisdomtree']
        self.assertEqual(len(gcalls), 0, 'atrapa bez rejestru'); self.assertEqual((W['nr'], W['n'], W['un'], W['v'], W['full']), (7, 8, ['xlm'], None, False))
        self.assertAlmostEqual(W['vp'], _WTG161_SUMA - 2284838.8079854, delta=0.01, msg='wartość częściowa opisana osobno')
        self.assertNotIn('wisdomtree', zd.rwc_uzyj(oc, self.NOW)); self.assertFalse(oc['ok'])
        self.assertTrue(any(n.startswith('sieć xlm: timeout: timed out') or n.startswith('sieć xlm: TimeoutError') for n in oc['notes']), oc['notes'])
        g = []
        oc, _c, _g = self._oc(xlm=_wtg161_get(g, body={'_embedded': {'records': []}}))
        self.assertEqual(len(g), 3, 'aktywo bez liczby = ponowienie (węzeł bez zapasu: trzy razy)'); self.assertIsNone(oc['p']['wisdomtree']['v'])
        oc, _c, _g = self._oc(down={'plume'})
        self.assertEqual(oc['p']['wisdomtree']['un'], ['plume']); self.assertIsNone(oc['p']['wisdomtree']['v'], 'brak jednej sieci = brak pełnej wartości, nigdy zero')
        oc, _c, _g = self._oc(dec={('base', '0x5096b85ed11798fddcb8b5cb27c399c04689c435'): 6})
        self.assertEqual(oc['p']['wisdomtree']['un'], ['base'], 'miejsca z łańcucha ≠ z konfiguracji — token nieodczytany')
        zly = dict(zd.RWC_PRODUKTY['wisdomtree'], tokeny=zd.RWC_PRODUKTY['wisdomtree']['tokeny'][:-1] + (('xlm', 'WTGX:' + _WTG161_ISS, 6, 'WTGX', False),))
        with mock.patch.dict(zd.RWC_PRODUKTY, {'wisdomtree': zly}):
            oc, _c, _g = self._oc()
        self.assertEqual(oc['p']['wisdomtree']['un'], ['xlm'], 'Stellar: miejsca w konfiguracji ≠ 7 — token nieodczytany (nigdy zła skala)')
        oc1, _c, _g = self._oc()
        later = self.NOW + datetime.timedelta(hours=6)
        oc2, _c, _g = self._oc(now=later, prev=oc1, xlm=_wtg161_get(down=True))
        t = [x for x in oc2['p']['wisdomtree']['t'] if x[0] == 'xlm'][0]
        self.assertEqual((t[2], t[3]), (2284838.807985, self.NOW.isoformat()), 'poprzedni odczyt Stellar z jego czasem (≤ 12 h — w sumach)')
        self.assertIn('wisdomtree', zd.rwc_uzyj(oc2, later))

    def test_sumy_zakres_i_kontrola(self):
        import importlib.util
        t = RwaLancuchV150('test_konfiguracja_produkty_adresy_ceny')
        P, H = t._t()._parsed(), t._t()._hid()
        now = datetime.datetime(2026, 10, 4, 19, 40, tzinfo=datetime.timezone.utc)
        oc, _c, _g = self._oc(now=now, rez=zd.rwc_rezerwy(now, get=lambda u, h, tm: _TETHER160))
        fz = t._frozen()
        J0, J1 = zd.rwa_build(P, H, fz, now), zd.rwa_build(P, H, fz, now, oc=oc)
        used = J1['onchain']['used']
        self.assertEqual(set(used), {'blackrock-buidl', 'paxos-gold', 'circle-usyc', 'tether-gold', 'wisdomtree'})
        self.assertAlmostEqual(J1['seg']['tb']['v'], J0['seg']['tb']['v'] + used['blackrock-buidl'] + used['circle-usyc'] + used['wisdomtree'], delta=1)
        self.assertAlmostEqual(J1['seg']['all']['v'], J0['seg']['all']['v'] + sum(used.values()), delta=1, msg='nic dwa razy')
        self.assertEqual(J1['stale']['n'], J0['stale']['n'] - 5); self.assertNotIn('wisdomtree', [r[0] for r in J1['stale']['top']])
        self.assertEqual(J1['onchain']['seg']['tb']['n'], 3); self.assertEqual(J1['onchain']['p']['wisdomtree']['zakres'], 'WTGXX')
        spec = importlib.util.spec_from_file_location('kontrola_v161', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
        K = importlib.util.module_from_spec(spec); spec.loader.exec_module(K)
        Z = K.rwc_porownanie(J1, now)
        self.assertEqual(Z['status'], '✅', Z); self.assertIn('w sumach z odczytu własnego: 5 z 5 produktów', Z['opis'])
        self.assertIn('wartość vs ostatnio znana: w paśmie', Z['opis'], 'WTGXX 1,23 vs zamrożone 1,24 mld USD')


class KontrolaDziennikowV162(unittest.TestCase):
    """v162: kontrola dzienna — ostatni dzień z wynikiem w dziennikach sygnałów TRENDÓW (treść, nie wiek pliku): krypto 4 dni kalendarzowe, świat
    48 h roboczych, przed startem „—”, najwyżej ⚠️ (nigdy ❌ ani BŁĄD); pełny przebieg kontroli z atrapą sieci — wiersze w tabeli i uwagi."""

    @classmethod
    def setUpClass(cls):
        import importlib.util
        spec = importlib.util.spec_from_file_location('kontrola_v162', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
        cls.K = importlib.util.module_from_spec(spec); spec.loader.exec_module(cls.K)

    @staticmethod
    def t(s):
        return datetime.datetime.fromisoformat(s).replace(tzinfo=datetime.timezone.utc)

    @staticmethod
    def kr(*dni, y=0.5):
        return {'v': 2, 'since': '2026-09-28', 'rows': [[d, 'BTC', 1, 'obs', 'p+', d + 'T06:10:00Z', y] for d in dni]}

    def test_krypto(self):
        K = self.K
        self.assertEqual([x[0] for x in K.DZ_SPEC], ['krypto-dziennik', 'swiat-dziennik'])
        J = self.kr('2026-09-30', '2026-10-01', '2026-10-02'); J['rows'] += [['2026-10-03', 'BTC', 1, 'obs', 'p+', 'x', None]]
        r = K.dziennik_swiezosc(J, 'krypto-dziennik', self.t('2026-10-04T12:25:00'))
        self.assertEqual(r, ('TRENDY krypto — ostatni dzień z wynikiem sygnałów', '✅', 36 * 60 + 25, '2026-10-02', ''), 'wiersz bez wyniku (czeka) się nie liczy')
        r = K.dziennik_swiezosc(self.kr('2026-09-29'), 'krypto-dziennik', self.t('2026-10-04T12:25:00'))
        self.assertEqual(r[1:4], ('⚠️', 4 * 1440 + 12 * 60 + 25, '2026-09-29')); self.assertIn('wyniki sygnałów przestały dochodzić', r[4])
        self.assertEqual(K.dziennik_swiezosc(self.kr('2026-09-30'), 'krypto-dziennik', self.t('2026-10-05T00:00:00'))[1], '✅', 'dokładnie 4 dni — w progu')
        self.assertEqual(K.dziennik_swiezosc(self.kr('2026-09-30'), 'krypto-dziennik', self.t('2026-10-05T00:01:00'))[1], '⚠️')
        for zle in (None, True, float('nan'), float('inf'), '0.5'):
            J = self.kr('2026-10-03', y=zle); J['rows'] += self.kr('2026-09-25')['rows']
            self.assertEqual(K.dziennik_swiezosc(J, 'krypto-dziennik', self.t('2026-10-04T12:25:00'))[3], '2026-09-25', zle)
        J = {'since': '2026-09-28', 'rows': [['zła', 'X', 1, 'obs', '', 'x', 1.0], ['2026-10-03', 'X', 1, 'obs'], 'x', None]}
        self.assertEqual(K.dziennik_swiezosc(J, 'krypto-dziennik', self.t('2026-10-04T12:25:00'))[1], '⚠️', 'złe wiersze pominięte — brak wyniku od startu')
        for zly in (None, [], {'at': '2026-10-04T12:00:00Z'}, {'rows': None}):
            self.assertIsNone(K.dziennik_swiezosc(zly, 'krypto-dziennik', self.t('2026-10-04T12:25:00')), zly)
        self.assertIsNone(K.dziennik_swiezosc(self.kr('2026-10-02'), 'inny', self.t('2026-10-04T12:25:00')))

    def test_swiat(self):
        K = self.K
        J = {'v': 2, 'since': '2026-10-05', 'rows': []}
        self.assertEqual(K.dziennik_swiezosc(J, 'swiat-dziennik', self.t('2026-10-04T12:25:00')),
                         ('TRENDY świat — ostatnia sesja z wynikiem sygnałów', '—', None, None, 'dziennik rusza 2026-10-05 — pierwsze wyniki po pierwszym sprawdzeniu'))
        self.assertEqual(K.dziennik_swiezosc(J, 'swiat-dziennik', self.t('2026-10-05T15:00:00'))[1], '—', 'dzień startu — wynik wieczorem')
        r = K.dziennik_swiezosc(J, 'swiat-dziennik', self.t('2026-10-06T10:00:00'))
        self.assertEqual((r[1], r[4]), ('—', 'dziennik od 2026-10-05 — czekamy na pierwsze wyniki'))
        r = K.dziennik_swiezosc(J, 'swiat-dziennik', self.t('2026-10-08T12:00:00'))
        self.assertEqual(r[1], '⚠️'); self.assertIn('brak dnia z wynikiem w dzienniku (od 2026-10-05)', r[4])
        J = {'v': 2, 'since': '2026-10-05', 'rows': [['2026-10-09', 'SPY', 1, 'obs', 'p+', 'x', 0.4], ['2026-10-12', 'SPY', -1, 'obs', 'p-', 'x', None]]}
        r = K.dziennik_swiezosc(J, 'swiat-dziennik', self.t('2026-10-12T12:00:00'))
        self.assertEqual(r[1:4], ('✅', 12 * 60, '2026-10-09'), 'piątek → poniedziałek południe: 12 h roboczych (weekend się nie liczy)')
        r = K.dziennik_swiezosc(J, 'swiat-dziennik', self.t('2026-10-14T12:00:00'))
        self.assertEqual(r[1], '⚠️', 'od piątku do środy południe: 60 h roboczych > 48 h')

    def test_przebieg_kontroli(self):
        import copy, io as _io, tempfile
        K = self.K
        NOW = self.t('2026-10-04T12:25:00')
        kr_ok = self.kr('2026-10-01', '2026-10-02')
        kr_stary = self.kr('2026-09-27')
        sw = {'v': 2, 'since': '2026-10-05', 'rows': []}

        class Resp:
            status = 200

            def __init__(self, b):
                self.b = b

            def read(self, n=-1):
                return self.b

            def __enter__(self):
                return self

            def __exit__(self, *a):
                return False

        def siec(kr):
            def urlopen(req, timeout=None, **kw):
                url = req.full_url
                J = lambda o: Resp(json.dumps(o).encode())   # noqa: E731
                if '/index.html?' in url:
                    return Resp(b'<html>const EXTRA1={};' + b' ' * 1_000_100)
                if '/data/meta.json?' in url:
                    return J({'at': (NOW - datetime.timedelta(minutes=17)).isoformat(), 'ok': {}, 'errors': [], 'notes': []})
                if '/data/krypto-dziennik.json?' in url:
                    return J(dict(copy.deepcopy(kr), at=(NOW - datetime.timedelta(minutes=17)).isoformat()))
                if '/data/swiat-dziennik.json?' in url:
                    return J(dict(sw, at=(NOW - datetime.timedelta(minutes=17)).isoformat()))
                if '/data/' in url:
                    return J({'at': (NOW - datetime.timedelta(minutes=20)).isoformat()})
                if any(f + '?' in url for f in ('robots.txt', 'sitemap.xml', 'google433f7c24524100a9.html')):
                    return Resp(b'x' * 100)
                if url.startswith('https://api.github.com/'):
                    return J({'workflow_runs': []})
                raise zd.urllib.error.HTTPError(url, 404, 'Not Found', {}, _io.BytesIO(b''))   # inne kontrole: brak odpowiedzi
            return urlopen
        for kr, st in ((kr_ok, '✅'), (kr_stary, '⚠️')):
            d = tempfile.mkdtemp(prefix='k162-')
            with mock.patch.object(K, 'NOW', NOW), mock.patch.object(K, 'OUT_DIR', d), mock.patch.object(K, 'ARCH_DIR', os.path.join(d, 'brak')), \
                    mock.patch.object(K.time, 'sleep', lambda s: None), mock.patch.object(K.urllib.request, 'urlopen', siec(kr)):
                R = K.kontrola()
                md = K.raport_md(R)
            L = md.splitlines()
            self.assertRegex(L[0], r'^# Kontrola strony — \d{2}\.\d{2}\.\d{4}, \d{2}:\d{2} \(czas polski\)$'); self.assertRegex(L[2], r'^\*\*Wynik: (OK|UWAGA|BŁĄD)\*\*$')
            row = next(s for s in R['swiezosc'] if s['zrodlo'] == 'TRENDY krypto — ostatni dzień z wynikiem sygnałów')
            self.assertEqual((row['status'], row['data']), (st, kr['rows'][-1][0]))
            row = next(s for s in R['swiezosc'] if s['zrodlo'] == 'TRENDY świat — ostatnia sesja z wynikiem sygnałów')
            self.assertEqual(row['status'], '—')
            self.assertIn('| TRENDY krypto — ostatni dzień z wynikiem sygnałów |', md)
            self.assertEqual(any(u.startswith('TRENDY krypto — ostatni dzień z wynikiem sygnałów: ostatni wynik z 2026-09-27') for u in R['uwagi']), st == '⚠️')
            self.assertFalse([b for b in R['bledy'] if 'TRENDY' in b], 'dzienniki nigdy nie są błędem kontroli')



class SzybciejV168(unittest.TestCase):
    """v168 (05.10.2026): automat co 10 minut, sieć Bitcoin i szanse Fed odświeżane w każdym przebiegu, archiwum TIC z wiersza Grand Total."""

    def test_harmonogram_co_10_min(self):
        root = os.path.dirname(os.path.abspath(__file__))
        s = open(os.path.join(root, '.github', 'workflows', 'strona.yml'), encoding='utf-8').read()
        import re
        m = re.search(r"- cron: '([0-9,]+) \* \* \* \*'", s)
        self.assertIsNotNone(m)
        minuty = [int(x) for x in m.group(1).split(',')]
        self.assertEqual(minuty, [7, 17, 27, 37, 47, 57], 'sześć przebiegów na godzinę, poza pełną godziną')
        self.assertEqual(sorted({(b - a) % 60 for a, b in zip(minuty, minuty[1:] + minuty[:1])}), [10], 'równe odstępy 10 min')
        self.assertEqual(s.count('- cron:'), 1)

    def test_pamiec_krotsza_niz_odstep(self):
        # plik młodszy niż *_EVERY = bez zapytań; przy przebiegu co 10 min pamięć < 10 min = odświeżenie w każdym przebiegu z harmonogramu
        self.assertLess(zd.LN_EVERY, 10); self.assertLess(zd.FED_EVERY, 10)
        self.assertGreaterEqual(min(zd.LN_EVERY, zd.FED_EVERY), 5, 'ręczny przebieg zaraz po zaplanowanym nie dubluje zapytań')
        # źródła z limitem darmowego planu — dalej co godzinę (pamięć liczona wiekiem pliku, nie liczbą przebiegów)
        self.assertEqual((zd.T10_EVERY, zd.LEV_EVERY, zd.DL_EVERY, zd.IX_EVERY), (55, 55, 55, 55))

    def test_archiwum_tic_grand_total(self):
        root = os.path.dirname(os.path.abspath(__file__))
        a = open(os.path.join(root, 'narzedzia', 'archiwum.py'), encoding='utf-8').read()
        self.assertIn("if r[1] == 'Grand Total':", a); self.assertNotIn("if r[1] == 'All Countries':", a)
        z = open(os.path.join(root, 'zbieraj_dane.py'), encoding='utf-8').read()
        self.assertIn("'world': region(['Grand Total'])", z, 'karta TIC na stronie — ten sam wiersz')



class SondaEmitenciV169(unittest.TestCase):
    """v169s: sonda danych emitentów RWA i JSE Top 40 — tylko liczby wyliczone z odpowiedzi (podmieniona sieć), g_nasdaq zostaje ostatnia."""

    def test_sonda_emitenci(self):
        import importlib.util
        import io as _io
        spec = importlib.util.spec_from_file_location('sondy_v169', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'sondy.py'))
        S = importlib.util.module_from_spec(spec); spec.loader.exec_module(S)
        self.assertIs(S.GROUPS[-1], S.g_nasdaq); self.assertEqual((S.GROUPS.count(S.g_rwa_emitenci), S.GROUPS.count(S.g_jse)), (1, 1))
        sec = {'data': [{'aum': '965684280.38', 'date': '1791176447000000000'}, {'aum': '14226495.41', 'date': '1791176447000000000'}]}
        R = {'EUTBL/totals': {'totalAssets': {'value': '589100000', 'currency': 'EUR'}, 'netAssetValue': {'day': '2026-10-04T00:00:00Z'}}, 'share-classes': [{}] * 14,
             'asset-stats': sec, 'hastra': {'prime_card': {'vaulted_wylds': '585610896.14'}, 'auto_card': {'vaulted_wylds': '66841503.03'}, 'timestamp': '2026-10-05T05:10:29Z'},
             'openeden': {'tvl': '294170000', 'liveVault': {'updatedAt': '2026-10-05T05:15:02Z'}}, 'matrixdock': {'data': {'token_total_supply': '16716.954084'}},
             'centrifuge': {'data': {'tokens': {'items': [{'symbol': 'JAAA', 'decimals': 6, 'totalIssuance': '557366000000000', 'tokenPrice': '1050448000000000000'},
                                                          {'symbol': 'deJAAA', 'decimals': 6, 'totalIssuance': '9600000000000', 'tokenPrice': '1000000000000000000'}]}}},
             'backed': {'data': {'tokens': {'nodes': [{}, {}], 'page': {'totalPages': 4}}}}, 'J200': [{}] * 7, 'J200.JO': {'historical': [{}] * 6}, 'JTOPI.JO': []}

        def http(url, method='GET', body=None, headers=None):
            for k, v in R.items():
                if k in url and k not in ('J200',):
                    return 200, json.dumps(v).encode(), 5, None
            if 'ondo.finance' in url:
                return 200, b'x"assetsData":{} "gmTvl":1', 7, None
            if 'eodhd.com' in url:
                return 200, json.dumps(R['J200']).encode(), 5, None
            return 404, b'', 1, None
        out = _io.StringIO()
        env = {'EODHD_KEY': 'TAJNY_EOD_123', 'FMP_KEY': 'TAJNY_FMP_456'}
        with mock.patch.object(S, 'http', http), mock.patch.object(S.time, 'sleep', lambda s: None), mock.patch('sys.stdout', out), \
                mock.patch.dict(os.environ, env, clear=False):
            S.g_rwa_emitenci(); S.g_jse()
        o = out.getvalue()
        self.assertNotIn('TAJNY', o, 'klucz nigdy w wyniku')
        self.assertIn('summary rwa-em spiko=14cl EUTBL=589.1/EUR/2026-10-04 hastra=652.5M@10-05T05:10 oe=294.2M@10-05T05:15 xaum=16717oz cfg=585.5M/2t', o)
        self.assertIn('BCAP=979.9M/2ch@10-05T05:00', o); self.assertIn('summary rwa-em3 ondo[assetsData=True gmTvl=True kB=0] backed[nodes=2 pages=4]', o)
        self.assertIn('summary jse eod_J200=rows=7 fmp_J200.JO=rows=6 fmp_JTOPI.JO=rows=0', o)


class SondaIndeksyKluczeV272p(unittest.TestCase):
    """v272p: sonda pokrycia indeksów w planach FMP i Massive — HTTP, wiersze, najnowsza data i różnica względem pliku strony; nigdy wartości,
    adresy ani klucze; przebieg tylko grup z TYLKO (bez zapytań z dobowego limitu EODHD); g_nasdaq zostaje ostatnia."""

    def _S(self):
        import importlib.util
        spec = importlib.util.spec_from_file_location('sondy_v272p', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'sondy.py'))
        S = importlib.util.module_from_spec(spec); spec.loader.exec_module(S)
        return S

    def test_grupy_i_wynik(self):
        import io as _io
        S = self._S()
        self.assertIs(S.GROUPS[-1], S.g_nasdaq); self.assertEqual((S.GROUPS.count(S.g_ix_fmp), S.GROUPS.count(S.g_ix_massive)), (1, 1))
        self.assertTrue(S.TYLKO and all(any(g.__name__ == n for g in S.GROUPS) for n in S.TYLKO), 'TYLKO = istniejące grupy (zmienia się co sondę)')
        site = {'ix': {'GSPC': {'d': [['2026-10-05', 6700.0], ['2026-10-06', 6712.5]]}, 'DJI': {'d': [['2026-10-06', 46000.0]]}}}
        fmp_gspc = [{'symbol': '^GSPC', 'date': '2026-10-06', 'price': 6712.5, 'volume': 1}, {'symbol': '^GSPC', 'date': '2026-10-05', 'price': 6706.7, 'volume': 1}]
        seen = []

        def http(url, method='GET', body=None, headers=None):
            seen.append((url, headers))
            if 'capitalflowai-app.github.io' in url:
                return 200, json.dumps(site).encode(), 3, None
            if 'index-list' in url:
                return 200, json.dumps([{'symbol': '^GSPC'}, {'symbol': '^DJI'}, {'symbol': 'XYZ'}]).encode(), 3, None
            if 'symbol=%5EGSPC' in url:
                return 200, json.dumps(fmp_gspc).encode(), 3, None
            if 'symbol=%5EDJI' in url:
                return 200, b'[]', 3, None
            if 'financialmodelingprep' in url:
                return 402, b'{"Error Message":"plan"}', 3, None
            if 'I:SPX' in url:   # 6.10 00:00 ET = 04:00 UTC
                return 200, json.dumps({'results': [{'t': 1791259200000, 'c': 6712.6}], 'resultsCount': 1}).encode(), 3, None
            return 403, b'{"status":"NOT_AUTHORIZED"}', 3, None
        out = _io.StringIO()
        env = {'FMP_KEY': 'TAJNY_FMP_456', 'MASSIVE_KEY': 'TAJNY_MAS_789'}
        with mock.patch.object(S, 'http', http), mock.patch.object(S.time, 'sleep', lambda s: None), mock.patch('sys.stdout', out), \
                mock.patch.dict(os.environ, env, clear=False):
            S.g_ix_fmp(); S.g_ix_massive()
        o = out.getvalue()
        self.assertNotIn('TAJNY', o, 'klucz nigdy w wyniku'); self.assertNotIn('http', o.replace('HTTP', ''), 'żadnego adresu')
        for v in ('6712', '6706', '46000'):
            self.assertNotIn(v, o, 'bez wartości')
        self.assertIn('summary ix-fmp-list n=3 has=GSPC,DJI site_codes=2', o)
        self.assertIn('GSPC:^GSPC=200/r2/10-06/d+0.00@10-06/m0.10', o)   # 05.10: 6706,7 vs 6700 = +0,10%
        self.assertIn('DJI:^DJI=200/r0', o); self.assertIn('WIG20:WIG20.WA=402', o); self.assertIn('WIG20:^WIG20=402', o)
        self.assertIn('summary ix-massive GSPC:I:SPX=200/r1/10-06/d+0.00@10-06/m0.00 IXIC:I:COMP=403 DJI:I:DJI=403', o)
        self.assertEqual(sum(1 for u, _ in seen if 'financialmodelingprep' in u), 1 + len(S.IXK_FMP), 'lista + 1 zapytanie na kod')
        self.assertEqual(sum(1 for u, _ in seen if 'massive' in u), 3)
        self.assertTrue(all(h == {'Authorization': 'Bearer TAJNY_MAS_789'} for u, h in seen if 'massive' in u), 'klucz Massive tylko w nagłówku')
        self.assertFalse([u for u, _ in seen if 'eodhd' in u], 'bez zapytań z dobowego limitu EODHD')

    def test_main_tylko_wybrane_grupy(self):
        import io as _io
        S = self._S()
        ran = []

        def g_ix_fmp():
            ran.append('fmp')

        def g_eodhd():
            ran.append('eodhd')
        with mock.patch.object(S, 'GROUPS', [g_eodhd, g_ix_fmp]), mock.patch.object(S, 'TYLKO', ('g_ix_fmp',)), mock.patch('sys.stdout', _io.StringIO()):
            S.main()
        self.assertEqual(ran, ['fmp'])
        ran.clear()
        with mock.patch.object(S, 'GROUPS', [g_eodhd, g_ix_fmp]), mock.patch.object(S, 'TYLKO', ()), mock.patch('sys.stdout', _io.StringIO()):
            S.main()
        self.assertEqual(sorted(ran), ['eodhd', 'fmp'], 'pusta krotka = wszystkie grupy')


