            self.assertNotIn('raac', zd.rwc_uzyj(oc, self.NOW + datetime.timedelta(hours=31)), 'cena złota starsza niż 36 h — poza sumami')
            post = _rwc150_post(sup={('eth', self.TB): 26531980000000000000000}, dec={('eth', self.TB): 6})
