# ===================== v177: KONTROLA — PRZEBIEGI „STRONA I DANE” Z CAŁEJ DOBY =====================
class KontrolaPrzebiegiV177(unittest.TestCase):
    """v177: lista przebiegów samego zadania „Strona i dane” (nie wszystkich zadań), druga strona tylko gdy pierwsza (100) nie pokrywa 24 h."""

    def _kontrola(self, strony):
        import importlib.util, tempfile
        spec = importlib.util.spec_from_file_location('kontrola_v177', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
        k = importlib.util.module_from_spec(spec); spec.loader.exec_module(k)
        NOW = datetime.datetime(2026, 10, 5, 12, 0, tzinfo=datetime.timezone.utc)
        urls = []

        class Resp:
            def __init__(self, b):
                self.b, self.status = b, 200

            def read(self):
                return self.b

            def __enter__(self):
                return self

            def __exit__(self, *a):
                return False

        def urlopen(req, timeout=None):
            url = req.full_url
            if '/index.html?' in url:
                return Resp(b'<html>const EXTRA126={};' + b' ' * 1_000_100)
            if '/data/' in url:
                return Resp(json.dumps({'at': (NOW - datetime.timedelta(minutes=8)).isoformat(), 'ok': {'etf': True}, 'errors': [], 'notes': []}).encode())
            if any(f + '?' in url for f in ('robots.txt', 'sitemap.xml', 'google433f7c24524100a9.html')):
                return Resp(b'x' * 100)
            if url.startswith('https://api.github.com/'):
                urls.append(url)
                if '/actions/workflows/strona.yml/runs' in url:
                    p = int(url.split('&page=')[1].split('&')[0]) if '&page=' in url else 1
                    return Resp(json.dumps({'workflow_runs': strony.get(p, [])}).encode())
                return Resp(b'{"workflow_runs": []}')
            raise k.urllib.error.URLError('test bez sieci')
        d = tempfile.mkdtemp(prefix='k177-')
        with mock.patch.object(k, 'NOW', NOW), mock.patch.object(k, 'OUT_DIR', d), mock.patch.object(k, 'ARCH_DIR', os.path.join(d, 'brak')), \
                mock.patch.object(k.time, 'sleep', lambda s: None), mock.patch.object(k.urllib.request, 'urlopen', urlopen), mock.patch('sys.stdout', io.StringIO()):
            R = k.kontrola()
        return R, urls, NOW

    def _runs(self, NOW, n, od_min, krok_min):
        f = lambda m: (NOW - datetime.timedelta(minutes=m)).strftime('%Y-%m-%dT%H:%M:%SZ')  # noqa: E731
        return [{'id': od_min + i * krok_min, 'name': 'Strona i dane', 'event': 'schedule', 'status': 'completed', 'conclusion': 'success',   # v181: numery unikalne jak prawdziwe (lista bez podwójnych)
                 'run_started_at': f(od_min + i * krok_min), 'created_at': f(od_min + i * krok_min)} for i in range(n)]

    def test_cala_doba_z_listy_zadania(self):
        NOW = datetime.datetime(2026, 10, 5, 12, 0, tzinfo=datetime.timezone.utc)
        R, urls, _ = self._kontrola({1: self._runs(NOW, 100, 1, 10), 2: self._runs(NOW, 100, 1001, 10)})
        runs_urls = [u for u in urls if '/runs' in u and '/jobs' not in u and 'status=completed' not in u]   # v291: bez odczytu ostrzeżeń GitHuba
        self.assertTrue(all('/actions/workflows/strona.yml/runs?per_page=100&page=' in u for u in runs_urls), runs_urls)
        self.assertEqual(len(runs_urls), 2, 'pierwsza strona (100 co 10 min = 16,7 h) nie pokrywa doby — druga strona')
        self.assertEqual(R['actions']['przebiegi_24h'], 144, '100 + 44 przebiegi z ostatnich 24 h (co 10 min)')
        R, urls, _ = self._kontrola({1: self._runs(NOW, 80, 1, 15)})
        self.assertEqual(len([u for u in urls if '/runs' in u and '/jobs' not in u and 'status=completed' not in u]), 1, 'mniej niż 100 na stronie — bez drugiej strony')
        self.assertEqual(R['actions']['przebiegi_24h'], 80)
        R, urls, _ = self._kontrola({1: self._runs(NOW, 100, 1, 20)})
        self.assertEqual(len([u for u in urls if '/runs' in u and '/jobs' not in u and 'status=completed' not in u]), 1, 'najstarszy z pierwszej strony starszy niż doba — bez drugiej strony')
        self.assertEqual(R['actions']['przebiegi_24h'], 72)


# ===================== v178: KURSY EBC — ODNIESIENIA OD DNIA OSTATNIEGO FIXINGU =====================
class RynkiFxV178(unittest.TestCase):
    """v178: kursy odniesienia (1D, 1T, 1M, 1Q, 1R) od dnia ostatniego fixingu d0, nie od dzisiejszej daty. Dawniej w poniedziałek rano
    (ostatni fixing z piątku) 1D = piątek = „now” → indeks dolara „dziś” 0,00% (05.10: powinno być +0,35%), a 1T = 4 sesje. Bez sieci:
    atrapa źródła podaje ostatni fixing nie późniejszy niż żądany dzień (jak prawdziwe — sprawdzone 05.10: 2026-10-04 → 2026-10-02)."""
    BD = ('2026-10-05', '2026-10-02', '2026-10-01', '2026-09-30', '2026-09-29', '2026-09-28', '2026-09-25', '2026-09-24', '2026-09-02',
          '2026-07-02', '2026-07-03', '2025-10-03', '2025-10-02')

    def setUp(self):
        zd.META['errors'].clear()
        self.addCleanup(zd.META['errors'].clear)

    def _gj(self, latest, calls, zly=None):
        def gj(url, headers=None, timeout=30):
            if 'bundesbank' in url:
                return RynkiV101.BUBA   # druga część pliku działa — błąd kursów nie wyłącza całego pliku
            d = url.split('/v1/')[1].split('?')[0]
            calls.append(d)
            if d == 'latest':
                x = latest
            else:
                x = max((v for v in self.BD if v <= d), default='2024-01-02')
                if zly and x == zly[0]:
                    x = zly[1]
            return {'amount': 1.0, 'base': 'USD', 'date': x, 'rates': {'EUR': 0.89 if str(x) >= '2026-10-02' else 0.88}}
        return gj

    def _build(self, latest, today, prev=None, zly=None):
        calls = []
        with mock.patch.object(zd, 'get_json', side_effect=self._gj(latest, calls, zly)), \
                mock.patch.object(zd, 'get', side_effect=RuntimeError('test: bez rentowności')):
            o = zd.build_rynki(prev, today=today)
        return o, calls

    def test_poniedzialek_rano_i_po_publikacji(self):
        o, calls = self._build('2026-10-02', datetime.date(2026, 10, 5))
        self.assertEqual(calls, ['latest', '2026-09-02', '2026-07-02', '2025-10-02', '2026-10-01', '2026-09-25'],
                         'najpierw ostatni fixing, potem odniesienia od jego dnia (02.10), nie od dziś (05.10)')
        self.assertTrue(o['ok']['fx'])
        F = o['fx']
        self.assertEqual(list(F), ['now', '1M', '1Q', '1R', '1D', '1T'])
        self.assertEqual((F['now']['date'], F['1D']['date'], F['1T']['date']), ('2026-10-02', '2026-10-01', '2026-09-25'),
                         '1D = poprzedni fixing (czwartek), nie ten sam piątek; 1T = pełny tydzień')
        o, calls = self._build('2026-10-05', datetime.date(2026, 10, 5))
        self.assertEqual(calls[-2:], ['2026-10-04', '2026-09-28'])
        self.assertEqual((o['fx']['1D']['date'], o['fx']['1T']['date']), ('2026-10-02', '2026-09-28'), 'po publikacji poniedziałkowej: 1D = piątek')
        o, calls = self._build('2026-07-03', datetime.date(2026, 7, 4))
        self.assertEqual(o['fx']['1D']['date'], '2026-07-02')

    def test_odniesienie_nie_wczesniejsze_to_blad_czesci(self):
        prev = {'at': '2026-10-05T09:00:00+00:00', 'fx': {'now': {'date': '2026-10-01', 'rates': {'EUR': 0.88}}}, 'part_at': {'fx': '2026-10-05T09:00:00+00:00'}}
        o, _ = self._build('2026-10-02', datetime.date(2026, 10, 5), prev=prev, zly=('2026-10-01', '2026-10-02'))
        self.assertFalse(o['ok']['fx']); self.assertEqual(o['fx'], prev['fx']); self.assertEqual(o['part_at']['fx'], '2026-10-05T09:00:00+00:00')
        self.assertTrue(any(e.startswith('Frankfurter: kursy 1D: data ') for e in zd.META['errors']), zd.META['errors'])
        zd.META['errors'].clear()
        for zla in ('x', None, '2026-10-06'):
            o, calls = self._build(zla, datetime.date(2026, 10, 5), prev=prev)
            self.assertFalse(o['ok']['fx'], zla); self.assertEqual(calls, ['latest'], 'bez dnia ostatniego fixingu — bez dalszych zapytań')
            self.assertTrue(any(e.startswith('Frankfurter: kursy now: zła data') for e in zd.META['errors']), zd.META['errors'])
            zd.META['errors'].clear()


# ===================== v179: INDEKSY — DNI BEZ SESJI (WYPEŁNIENIA DOSTAWCY) POZA SERIĄ =====================
class IndeksyWypelnieniaV179(unittest.TestCase):
    """v179: wiersz z zamknięciem dokładnie równym poprzedniemu = dzień bez sesji wypełniony przez dostawcę (święto, weekend) — poza serią.
    Wzory z pliku na żywo 05.10: Meksyk (sobota i niedziela po piątku, święto 16.03), Hiszpania (Wielki Piątek 03.04), Izrael (Jom Kipur 21.09)
    oraz prawdziwe sesje niedzielne (Izrael 2025, Indie 01.02.2026), które zostają. Bez sieci."""
    MON = datetime.datetime(2026, 10, 5, 12, 0, tzinfo=datetime.timezone.utc)
    MXX = [['2026-03-12', 66085.81], ['2026-03-13', 65648.91], ['2026-03-14', 65648.91], ['2026-03-15', 65648.91], ['2026-03-16', 65648.91],
           ['2026-03-17', 66196.92], ['2026-03-20', 64134.9], ['2026-03-21', 64134.9], ['2026-03-22', 64134.9], ['2026-03-23', 64370.95]]
    TA = [['2025-10-02', 3241.1], ['2025-10-05', 3270.22], ['2025-10-06', 3270.22], ['2025-10-09', 3301.5], ['2025-10-12', 3326.1799],
          ['2026-09-17', 4164.3501], ['2026-09-21', 4164.3501], ['2026-09-22', 4173.2798]]
    IN = [['2026-01-30', 81211.4], ['2026-02-01', 80722.9375], ['2026-02-02', 80901.2]]

    def setUp(self):
        zd.META['errors'].clear(); zd.META['ok'].clear(); zd.META['notes'].clear()

    def test_regula(self):
        f = zd.ix_bez_wypelnien
        self.assertEqual(f(self.MXX), [['2026-03-12', 66085.81], ['2026-03-13', 65648.91], ['2026-03-17', 66196.92], ['2026-03-20', 64134.9],
                                       ['2026-03-23', 64370.95]], 'sobota, niedziela i święto (16.03) po piątku — poza serią')
        self.assertEqual([r[0] for r in f(self.TA)], ['2025-10-02', '2025-10-05', '2025-10-09', '2025-10-12', '2026-09-17', '2026-09-22'],
                         'niedziele 2025 z własnym zamknięciem zostają; święta (06.10.2025, Jom Kipur 21.09.2026) — poza serią')
        self.assertEqual(f(self.IN), self.IN, 'niedzielna sesja budżetowa w Indiach — prawdziwa, zostaje')
        self.assertEqual(f([['2026-10-02', 7722.72], ['2026-10-05', 7722.72]]), [['2026-10-02', 7722.72]], 'wypełnienie na końcu — ostatnia sesja = piątek')
        self.assertEqual(f([]), []); self.assertEqual(f([['2026-10-02', 1.0]]), [['2026-10-02', 1.0]])
        r = [['2026-09-30', 10.0], ['2026-10-01', 10.5], ['2026-10-02', 10.0]]
        self.assertEqual(f(r), r, 'ta sama wartość, ale nie w sąsiednich wierszach — prawdziwe sesje')
        x = [['2026-10-01', 5.0], ['2026-10-02', 5.0]]; f(x)
        self.assertEqual(len(x), 2, 'lista wejściowa bez zmian w miejscu')

    def _prev(self):
        recent = '2026-10-05T11:00:00+00:00'   # po ostatnim zamknięciu każdej sesji — poza planem tego przebiegu
        ix = {s: {'cc': cc, 'at': recent, 'd': [['2026-10-01', 100.0 + i], ['2026-10-02', 101.0 + i]]} for i, (s, cc, _) in enumerate(zd.IX_SYMBOLS)}
        ix['MXX']['d'] = [list(r) for r in self.MXX]; ix['TA125']['d'] = [list(r) for r in self.TA]
        ix['GSPC'] = {'cc': 'us', 'at': '2026-10-01T23:00:00+00:00', 'd': [['2026-09-30', 7651.54], ['2026-10-01', 7666.45]]}   # do pobrania
        return {'at': recent, 'ok': {'ix': True, 'etf': True}, 'part_at': {'ix': recent, 'etf': recent}, 'ix': ix,
                'etf': {'date': '2026-10-02', 'q': {'BND': [['2026-10-01', 72.5], ['2026-10-02', 72.5]]}}}

    def test_plik_wszystkie_serie_czesci_ix(self):
        prev = self._prev(); kopia = json.loads(json.dumps(prev)); calls = []
        eod = [{'date': '2026-10-01', 'close': 7666.45}, {'date': '2026-10-02', 'close': 7722.72}, {'date': '2026-10-05', 'close': 7722.72}]
        with mock.patch.object(zd, 'get_json', side_effect=IndeksyV106._gj(self, calls, eod=eod)):
            o = zd.build_indeksy({'EODHD_KEY': 'k'}, prev, now=self.MON)
        self.assertEqual(len(calls), 1, 'w planie tylko S&P 500'); self.assertIn('GSPC.INDX', calls[0])
        self.assertEqual(o['ix']['GSPC']['d'], [['2026-09-30', 7651.54], ['2026-10-01', 7666.45], ['2026-10-02', 7722.72]],
                         'pobrany indeks: poniedziałkowy wiersz z piątkowym zamknięciem — poza serią')
        self.assertEqual([r[0] for r in o['ix']['MXX']['d']], ['2026-03-12', '2026-03-13', '2026-03-17', '2026-03-20', '2026-03-23'],
                         'niepobrany w tym przebiegu — też oczyszczony')
        self.assertEqual(len(o['ix']['TA125']['d']), 6)
        self.assertEqual(o['etf'], prev['etf'], 'fundusze ETF bez zmian (ceny bywają naprawdę równe)')
        self.assertEqual(prev, kopia, 'poprzedni plik nie jest zmieniany w miejscu')
        o2 = zd.build_indeksy({}, prev, now=self.MON)   # klucz zniknął — stare serie zostają, też bez wypełnień
        self.assertEqual(len(o2['ix']['MXX']['d']), 5); self.assertEqual(prev, kopia)


# ===================== v180: OPŁATA FUNDUSZU ETF — 0 OD ŹRÓDŁA PRZY ZNANEJ OPŁACIE Z PROSPEKTU =====================
class EtfOplataV180(unittest.TestCase):
    """v180: FBTC — źródło notowań podaje opłatę 0, prospekt 0,25% (zwolnienie skończyło się 31.07.2024); strona pokazywała „0,00%”."""

