    def test_nbp_tylko_stopa_obowiazujaca(self):
        k = self.k
        utc = datetime.timezone.utc
        F = self.F(); F['NBP_REF'] = {'2026-10-09': 3.5}   # NBP obniża stopę 08.10, obowiązuje od 09.10 — plik NBP ma już tylko nową
