# ===================== v247: KONTROLA — STRONA W PRZEGLĄDARCE BEZ OKNA =====================
class KontrolaPrzegladarkaV247(unittest.TestCase):
    """v247: Chrome bez okna otwiera stronę jak telefon; nieobsłużone błędy JavaScriptu = ⚠️; zrzut po „</html>” albo po limicie czasu,
    przeglądarka zamykana; brak przeglądarki = „nie sprawdzono”. Test z prawdziwym Chrome tylko lokalnie (na serwerze pomijany)."""

    LOG = ('[1:2:1006/154729.401951:INFO:CONSOLE:1] "BLAD-TESTOWY-1", source: https://capitalflowai-app.github.io/?nc=1 (12)\n'
           '[1:2:1006/154729.409844:INFO:CONSOLE:1] "Uncaught (in promise) Error: ODRZUCONE-2", source: https://capitalflowai-app.github.io/?nc=1 (9875)\n'
           '[1:2:1006/154729.409844:INFO:CONSOLE:1] "Uncaught TypeError: Cannot read properties of null (reading \'x\')", source: https://capitalflowai-app.github.io/index.html (4410)\n'
           '[1:2:1006/154729.5:INFO:CONSOLE:0] "Failed to load resource: the server responded with a status of 429 ()", source: https://api.coingecko.com/api/v3/global (0)\n'
           '[1:2:1006/154729.6:INFO:CONSOLE:0] "Access to fetch at \'https://api.coinpaprika.com/v1/tickers?quotes=USD&limit=800\' from origin \'https://capitalflowai-app.github.io\' has been blocked by CORS policy: No \'Access-Control-Allow-Origin\' header is present on the requested resource.", source: https://capitalflowai-app.github.io/?nc=1 (0)\n'
           '[1:2:1006/154730.1:ERROR:ui/display/mac/cv_display_link_mac.mm:188] CVDisplayLinkCreateWithCGDisplay failed. CVReturn: -6670\n')

    @classmethod
    def setUpClass(cls):
        import importlib.util, tempfile
        tmp = tempfile.mkdtemp(prefix='kontrola247-')
        with mock.patch.dict(os.environ, {'KONTROLA_DIR': os.path.join(tmp, 'k'), 'KONTROLA_ARCH': os.path.join(tmp, 'a')}):
            spec = importlib.util.spec_from_file_location('v247_k', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
            cls.k = importlib.util.module_from_spec(spec); spec.loader.exec_module(cls.k)
        cls.tmp = tmp

    def test_konsola(self):
        K = self.k.przegladarka_konsola(self.LOG)
        self.assertEqual(K['bledy'], ['Uncaught (in promise) Error: ODRZUCONE-2 (strona:9875)',
                                      "Uncaught TypeError: Cannot read properties of null (reading 'x') (index.html:4410)"])
        self.assertEqual(K['zasoby'], ['https://api.coingecko.com/api/v3/global', 'https://api.coinpaprika.com/v1/tickers?quotes=USD&limit=800'],
                         'zapytanie zablokowane (CORS) to nieudane wczytanie, nie „inny komunikat”')
        self.assertEqual(K['inne'], ['BLAD-TESTOWY-1'])
        self.assertEqual(self.k.przegladarka_konsola(''), {'bledy': [], 'zasoby': [], 'inne': [], 'nieczytelne': 0})   # v248

    def test_wiersz_i_uwagi(self):
        k = self.k
        P = {'ok': True, 'czas_s': 10.4, 'bajty': 3560630, 'svg': 170, 'wykresy': 25, 'bledy': [], 'zasoby': [], 'inne': []}
        self.assertEqual(k.przegladarka_wiersz(P), '- Strona w przeglądarce (bez okna, ekran telefonu 390 px): zrzut po 10,4 s — grafik 170, '
                                                   'wykresów liniowych 25; błędów JavaScriptu: 0 ✅.')
        self.assertEqual(k.przegladarka_uwagi(P), [])
        P2 = dict(P, **k.przegladarka_konsola(self.LOG))
        w = k.przegladarka_wiersz(P2)
        self.assertIn('błędów JavaScriptu: 2 ⚠️; nieudane wczytania: 2 (api.coingecko.com, api.coinpaprika.com) ℹ️; inne komunikaty konsoli: 1 (pierwszy: BLAD-TESTOWY-1) ℹ️.', w)
        self.assertEqual(k.przegladarka_uwagi(P2), ['strona w przeglądarce: błędów JavaScriptu 2 — pierwszy: Uncaught (in promise) Error: ODRZUCONE-2 (strona:9875)'])
        self.assertEqual(k.przegladarka_wiersz({'brak': 'brak przeglądarki na maszynie kontroli'}),
                         '- Strona w przeglądarce (bez okna, ekran telefonu): nie sprawdzono (brak przeglądarki na maszynie kontroli) ℹ️.')

    def test_program(self):
        k = self.k
        with mock.patch.dict(os.environ, {'KONTROLA_CHROME': ''}):
            self.assertEqual(k.przegladarka_program(('chromium', 'google-chrome'), szukaj=lambda n: '/usr/bin/' + n if n == 'google-chrome' else None), '/usr/bin/google-chrome')
            self.assertIsNone(k.przegladarka_program(('x-brak', '/nie/ma/chrome'), szukaj=lambda n: None))
        with mock.patch.object(k, 'przegladarka_program', lambda *a, **kw: None):
            self.assertEqual(k.strona_przegladarka('https://x'), {'stan': 'brak_programu', 'brak': 'brak przeglądarki na maszynie kontroli'})

    def _udawana(self, dom, log, spi=30):
        p = os.path.join(self.tmp, f'przegl_{abs(hash((dom, log, spi)))}.py')
        with open(p, 'w', encoding='utf-8') as f:
            f.write('#!/usr/bin/env python3\nimport sys, time\n'
                    f'sys.stdout.write({dom!r}); sys.stdout.flush()\nsys.stderr.write({log!r}); sys.stderr.flush()\ntime.sleep({spi})\n')
        os.chmod(p, 0o755)
        return p

    def test_zrzut_i_zamkniecie(self):
        import time
        k = self.k
        prog = self._udawana('<html><body><script>const EXTRA={};</script><svg></svg><svg></svg><div class="arc-gr"></div></body></html>\n', self.LOG)   # v248: znacznik strony
        t0 = time.monotonic()
        P = k.strona_przegladarka('https://x', czas_s=20, program=prog)
        self.assertLess(time.monotonic() - t0, 8, 'po „</html>” przeglądarka zamknięta od razu (nie czekamy, aż sama się zamknie)')
        self.assertEqual((P['ok'], P['svg'], P['wykresy'], len(P['bledy']), len(P['zasoby']), len(P['inne'])), (True, 2, 1, 2, 2, 1))

    def test_brak_zrzutu_w_limicie(self):
        k = self.k
        prog = self._udawana('<html><body><p>w trakcie', '')
        P = k.strona_przegladarka('https://x', czas_s=2, program=prog)
        self.assertEqual(P['brak'], 'strona nie oddała się w 2 s — zawieszona strona albo źródło, które nie odpowiada')   # v248
        self.assertIn('nie sprawdzono (strona nie oddała się w 2 s — zawieszona strona albo źródło, które nie odpowiada) ℹ️', k.przegladarka_wiersz(P))
        self.assertEqual(k.przegladarka_uwagi(P), [])

    def test_kontrola_wola(self):
        import inspect
        src = inspect.getsource(self.k.kontrola)
        self.assertIn("R['przegladarka'] = strona_przegladarka(f'{SITE}/?nc={int(time.time())}' + PRZEGL_PELNA)", src)   # v308: runda pełna z ?pelna=1
        self.assertIn("u = przegladarka_uwagi(R['przegladarka'], przegladarka_poprzedni(os.path.join(OUT_DIR, 'historia.json')))", src)   # v248
        self.assertIn("os.environ.get('KONTROLA_PRZEGLADARKA') == '1'", src, 'tylko na żądanie — testy kontrola() bez przeglądarki (ma własną sieć)')
        root = os.path.dirname(os.path.abspath(__file__))
        with open(os.path.join(root, '.github', 'workflows', 'kontrola.yml'), encoding='utf-8') as f:
            self.assertIn("KONTROLA_PRZEGLADARKA: '1'", f.read(), 'codzienna kontrola na serwerze włącza przeglądarkę')
        self.assertIn("L.append(przegladarka_wiersz(pg))", inspect.getsource(self.k.raport_md))

    def test_prawdziwy_chrome_lokalnie(self):
        k = self.k
        prog = k.przegladarka_program()
        if os.environ.get('GITHUB_ACTIONS') or not prog:
            self.skipTest('tylko lokalnie, z zainstalowanym Chrome (na serwerze sprawdza to sama kontrola)')
        p = os.path.join(self.tmp, 'strona_testowa.html')
        with open(p, 'w', encoding='utf-8') as f:
            f.write('<!doctype html><html><body><svg></svg><script>const EXTRA={};console.error("BLAD-TESTOWY-1");setTimeout(()=>{null.x},100);'
                    'Promise.reject(new Error("ODRZUCONE-2"));setInterval(()=>{},1000);</script></body></html>')
        P = k.strona_przegladarka('file://' + p, czas_s=60)
        self.assertTrue(P.get('ok'), P)
        self.assertEqual(sorted(b.rsplit(' (', 1)[0] for b in P['bledy']),
                         ['Uncaught (in promise) Error: ODRZUCONE-2', "Uncaught TypeError: Cannot read properties of null (reading 'x')"],
                         'błąd z opóźnieniem (setTimeout) też złapany — czas wirtualny strony')
        self.assertEqual(P['inne'], ['BLAD-TESTOWY-1'])


# ===================== v248: POPRAWKI PO PRZEGLĄDZIE v245–v247 =====================
class PoPrzegladzieV248(unittest.TestCase):
    """v248: wielowierszowe komunikaty konsoli; daty spoza kalendarza nie wywracają raportu; dwie fazy budżetu stóp i twardy limit zapytania;
    stany przeglądarki (awaria, zawieszona — drugi raz ⚠️, inna strona); grafiki bez tekstu skryptów, próg wykresów."""

    @classmethod
    def setUpClass(cls):
        import importlib.util, tempfile
        tmp = tempfile.mkdtemp(prefix='kontrola248-')
        with mock.patch.dict(os.environ, {'KONTROLA_DIR': os.path.join(tmp, 'k'), 'KONTROLA_ARCH': os.path.join(tmp, 'a')}):
            spec = importlib.util.spec_from_file_location('v248_k', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
            cls.k = importlib.util.module_from_spec(spec); spec.loader.exec_module(cls.k)
        cls.tmp = tmp
        cls.NOW = datetime.datetime(2026, 10, 6, 6, 20, tzinfo=datetime.timezone.utc)

    def test_konsola_wiele_linii_i_stary_zapis(self):
        k = self.k
        log = ('[1:2:1006/154729.1:INFO:CONSOLE:1] "Uncaught SyntaxError: Unexpected token \'<\', "\n<html>\n<body>"... is not valid JSON", '
               'source: https://capitalflowai-app.github.io/index.html (4410)\n'
               '[1:2:1006/154729.2:INFO:CONSOLE(77)] "Uncaught Error: a\nb", source: https://capitalflowai-app.github.io/?nc=1 (77)\n'
               '[1:2:1006/154729.3:INFO:CONSOLE:0] coś bez źródła\n'
               '[1:2:1006/154729.4:ERROR:gpu_init.cc(1)] nie konsola\n')
        K = k.przegladarka_konsola(log)
        self.assertEqual(K['bledy'], ['Uncaught SyntaxError: Unexpected token \'<\', " <html> <body>"... is not valid JSON (index.html:4410)',
                                      'Uncaught Error: a b (strona:77)'], 'wiele linii → jeden wpis; starszy zapis CONSOLE(N)')
        self.assertEqual(K['nieczytelne'], 1)
        P = dict({'ok': True, 'stan': 'ok', 'czas_s': 5.0, 'svg': 148, 'wykresy': 20}, **K)
        self.assertIn('błędów JavaScriptu: 2 ⚠️ (wpisów konsoli nieczytelnych: 1)', k.przegladarka_wiersz(P))
        P = dict(P, bledy=[])
        self.assertIn('błędów JavaScriptu: 0 ℹ️ (wpisów konsoli nieczytelnych: 1)', k.przegladarka_wiersz(P), 'nigdy cichy ✅')

    def test_prawdziwy_chrome_wiele_linii(self):
        k = self.k
        if os.environ.get('GITHUB_ACTIONS') or not k.przegladarka_program():
            self.skipTest('tylko lokalnie, z zainstalowanym Chrome')
        p = os.path.join(self.tmp, 'wiele_linii.html')
        with open(p, 'w', encoding='utf-8') as f:
            f.write('<!doctype html><html><body><script>const EXTRA={};setTimeout(()=>{throw new Error("a\\nb")},50);'
                    'setTimeout(()=>{JSON.parse("\\n<html>\\n<body>")},60);Promise.reject("x\\ny");setInterval(()=>{},1000);</script></body></html>')
        P = k.strona_przegladarka('file://' + p, czas_s=60)
        self.assertTrue(P.get('ok'), P)
        self.assertEqual(len(P['bledy']), 3, P['bledy'])

    def test_daty_spoza_kalendarza(self):
        k = self.k
        self.assertIsNone(k._dzien('2026-09-31')); self.assertEqual(k._dzien('2026-09-30'), '2026-09-30'); self.assertIsNone(k._dzien('30/09/2026'))
        bcb = k.stopy_bcb(b'[{"data":"29/09/2026","valor":"13.75"},{"data":"31/09/2026","valor":"13.50"}]')
        S = {'rows': {'BR': {'rate': 13.75, 'date': '2026-09-29'}, 'US': {'rate': 3.875, 'date': '2026-02-30'}}}
        P = k.stopy_porownanie(S, bcb, self.NOW)
        D = {o['bank']: o for o in P}
        self.assertEqual((D['Bank Brazylii']['zgodne'], D['Bank Brazylii']['zmiana']), (True, None), '31.09 pominięte — nie „zmiana”')
        self.assertIn('to nie dzień', D['Fed']['brak'], 'data strony 30.02 — nie dzień')
        k.stopy_wiersz({'wyniki': P}, self.NOW); k.stopy_uwagi(P, self.NOW)   # bez wyjątku
        import inspect
        self.assertIn('błąd kontroli stóp', inspect.getsource(k.kontrola)); self.assertIn('błąd wiersza raportu', inspect.getsource(k.raport_md))

    def test_dwie_fazy_budzetu(self):
        k = self.k
        V = KontrolaStopyV244
        t, log = [0.0], []
        odp = {'newyorkfed': None, 'data-api.ecb': None, 'bankofengland': V.BOE, 'data.snb.ch': V.SNB, 'riksbank': V.RIKS, 'norges-bank': V.NORGES,
               'nbp.pl': V.NBP, 'bankofcanada': V.BOC, 'bcb.gov.br': V.BCB, 'fred.stlouisfed': b'<html></html>'}

        def get(url, timeout=25, headers=None, limit=None):
            klucz = next(x for x in odp if x in url)
            log.append(klucz)
            if odp[klucz] is None:   # NY Fed i EBC: przekroczenie czasu po 20 s
                t[0] += 20
                raise TimeoutError('The read operation timed out')
            t[0] += 1
            return 200, odp[klucz], 5

        def spij(s):
            t[0] += s
        with mock.patch.object(k, 'get', get):
            Z, u = k.stopy_sprawdz(V.S, self.NOW, zegar=lambda: t[0], spij=spij)
        D = {o['bank']: o for o in Z['wyniki']}
        self.assertTrue(all(D[b].get('zgodne') for b in ('Bank Anglii', 'Bank Szwajcarii', 'Bank Szwecji', 'Bank Norwegii', 'NBP', 'Bank Kanady', 'Bank Brazylii')),
                        'przegląd: przy ponowieniach od razu 7 zdrowych banków było „pominięte” — teraz każde źródło raz, potem ponowienia')
        self.assertEqual([log.count(x) for x in ('newyorkfed', 'data-api.ecb', 'fred.stlouisfed')], [2, 2, 0], 'jedno ponowienie; FRED poza budżetem')
        self.assertEqual(D['Fed']['brak'], 'nie odczytano źródła — NY Fed: The read operation timed out; DFEDTARL: pominięte — limit czasu kontroli stóp; '
                                           'DFEDTARU: pominięte — limit czasu kontroli stóp')

    def test_twardy_limit_zapytania(self):
        import time
        k = self.k
        t0 = time.monotonic()
        with self.assertRaises(TimeoutError) as c:
            k._stopy_raz('https://x', 0.2, pobierz=lambda url, timeout=None, headers=None: time.sleep(3) or (200, b'x', 1), zapas=0.2)
        self.assertLess(time.monotonic() - t0, 2, 'wolne źródło nie przedłuża bloku stóp ponad limit')
        self.assertIn('brak całej odpowiedzi', str(c.exception))
        self.assertEqual(k._stopy_raz('https://x', 1, pobierz=lambda url, timeout=None, headers=None: (200, b'ok', 1)), b'ok')

    def _udawana(self, kod):
        p = os.path.join(self.tmp, f'przegl_{abs(hash(kod))}.py')
        with open(p, 'w', encoding='utf-8') as f:
            f.write('#!/usr/bin/env python3\nimport sys, time\n' + kod)
        os.chmod(p, 0o755)
        return p

    def test_stany_przegladarki(self):
        k = self.k
        awaria = self._udawana('sys.stderr.write("[0101/000000.000000:ERROR:ozone_platform_x11.cc(240)] Missing X server or $DISPLAY\\n")\nsys.exit(1)\n')
        P = k.strona_przegladarka('https://x', czas_s=20, program=awaria)
        self.assertEqual(P['stan'], 'zakonczona'); self.assertIn('kod 1: [0101/000000.000000:ERROR:ozone_platform_x11.cc(240)] Missing X server', P['brak'])
        self.assertNotIn('20 s', P['brak'], 'awaria to nie „brak strony w 20 s”')
        wisi = self._udawana('sys.stdout.write("<html><body>"); sys.stdout.flush()\nsys.stderr.write(\'[1:2:1006/1.1:INFO:CONSOLE:1] "Uncaught RangeError: x", source: https://s/ (1)\\n\'); sys.stderr.flush()\ntime.sleep(30)\n')
        P = k.strona_przegladarka('https://x', czas_s=2, program=wisi)
        self.assertEqual(P['stan'], 'zawieszona')
        self.assertEqual(k.przegladarka_uwagi(P), [], 'pierwszy raz — informacja; błędy z logu bez uwagi (przegląd: raport sam sobie przeczył)')
        self.assertIn('nie sprawdzono (strona nie oddała się w 2 s — zawieszona strona albo źródło, które nie odpowiada); w logu do przerwania '
                      'błędów JavaScriptu: 1 ℹ️.', k.przegladarka_wiersz(P))
        self.assertEqual(len(k.przegladarka_uwagi(P, 'zawieszona')), 1, 'drugi raz z rzędu — uwaga')
        self.assertTrue(k.przegladarka_wiersz(dict(P, powtorka=True)).endswith(' ⚠️.'))
        inna = self._udawana('sys.stdout.write("<html><body><h1>404</h1></body></html>\\n"); sys.stdout.flush()\ntime.sleep(30)\n')
        P = k.strona_przegladarka('https://x', czas_s=20, program=inna)
        self.assertEqual(P['stan'], 'inna_strona'); self.assertEqual(k.przegladarka_uwagi(P), [])
        pusta = self._udawana('sys.stdout.write("<html><body><script>const EXTRA={};const s=\'<svg class=\\"arc-gr\\">\';</script></body></html>\\n"); sys.stdout.flush()\ntime.sleep(30)\n')
        P = k.strona_przegladarka('https://x', czas_s=20, program=pusta)
        self.assertEqual((P['stan'], P['svg'], P['wykresy']), ('ok', 0, 0), 'tekst skryptów nie liczy się jako narysowane grafiki')
        self.assertEqual(k.przegladarka_uwagi(P), ['strona w przeglądarce: narysowanych wykresów liniowych tylko 0 (zwykle ok. 20) — dane mogły się nie wczytać'])
        self.assertIn('wykresów liniowych 0 ⚠️ (zwykle ok. 20)', k.przegladarka_wiersz(P))

    def test_poprzedni_z_historii(self):
        k = self.k
        p = os.path.join(self.tmp, 'historia.json')
        self.assertIsNone(k.przegladarka_poprzedni(p))
        with open(p, 'w', encoding='utf-8') as f:
            json.dump([{'at': '1', 'przegl': 'zawieszona'}, {'at': '2', 'przegl': 'ok'}, {'at': '3'}, {'at': '4', 'przegl': None}], f)
        self.assertEqual(k.przegladarka_poprzedni(p), 'ok', 'ostatnia kontrola, która uruchamiała przeglądarkę')
        import inspect
        src = inspect.getsource(k.kontrola)
        self.assertIn("'przegl': (R.get('przegladarka') or {}).get('stan')", src)
        self.assertIn("przegladarka_poprzedni(os.path.join(OUT_DIR, 'historia.json'))", src)


# ===================== v249: WIELORYBY — SALDA Z MIGAWEK O PÓŁNOCY UTC =====================
class KontrolaWielorybyV249(unittest.TestCase):
    """v249: para z migawek „pierwszej z doby” (pole hist pliku wielorybów, do 2 h po północy UTC, ta sama wersja listy) zastępuje parę z migawek
    archiwum robionych o różnych porach — porównanie z przelewami pełnej doby działa codziennie; bez migawek o północy — jak dotąd."""

    @classmethod
    def setUpClass(cls):
        import importlib.util, tempfile
        tmp = tempfile.mkdtemp(prefix='kontrola249-')
        with mock.patch.dict(os.environ, {'KONTROLA_DIR': os.path.join(tmp, 'k'), 'KONTROLA_ARCH': os.path.join(tmp, 'a')}):
            spec = importlib.util.spec_from_file_location('v249_k', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
            cls.k = importlib.util.module_from_spec(spec); spec.loader.exec_module(cls.k)
        cls.tmp = tmp

    def _archiwum(self):
        """Archiwum 01.10–06.10, migawki co 20 h (6000 bloków — nie doba: dotąd para pominięta); przelewy netto: Binance USDT 20 mln, Bybit USDT 5 mln."""
        p = os.path.join(self.tmp, 'wieloryby.csv')
        with open(p, 'w', encoding='utf-8') as f:
            f.write('date,exchange,asset,balance,balance_usd,inflow_24h,outflow_24h,net_24h,block\n')
            for i in range(6):
                d, b = f'2026-10-0{i + 1}', 26_000_000 + i * 6000
                f.write(f'{d},Binance,USDT,20000000000,20000000000,0,0,20000000,{b}\n{d},Bybit,USDT,1000000000,1000000000,0,0,5000000,{b}\n')
        return p

    def _hist(self, czas_ost='00:05', wer_ost='2026-09-23', bybit_ost=105_000_000):
        """Migawki o północy 30.09–06.10: Binance USDT +20 mln na dobę (= przelewy), Bybit USDT +5 mln (= przelewy), ostatnia doba Bybit + bybit_ost."""
        H = {'Binance': [], 'Bybit': []}
        for i in range(7):
            d = (datetime.date(2026, 9, 30) + datetime.timedelta(days=i)).isoformat()
            ost = i == 6
            t, w = (f'{d}T{czas_ost}:00+00:00', wer_ost) if ost else (f'{d}T00:05:00+00:00', '2026-09-23')
            H['Binance'].append([d, t, 1000.0, 20e9 + i * 20e6, 0.0, w])
            H['Bybit'].append([d, t, 10.0, 1e9 + (5 * 5e6 + bybit_ost if ost else i * 5e6), 0.0, w])
        return H

    def test_para_z_polnocy_codziennie(self):
        k = self.k
        path = self._archiwum()
        o = k.wieloryby_ocena(path)
        self.assertEqual((o['porownane'], o['odstep_h']), (0, 20.0), 'bez migawek o północy — jak dotąd: odstęp 20 h, bez porównania')
        self.assertIn('odstęp migawek 20.0 h', o['pomin'])
        o = k.wieloryby_ocena(path, hist=self._hist())
        self.assertEqual((o['porownane'], o['pominiete'], o['polnoc'], o['pomin']), (2, 0, 2, None))
        self.assertEqual([(g, a, round(x / 1e6, 1), round(y / 1e6, 1), round(z / 1e6, 1)) for g, a, x, y, z, m in o['zle']], [('Bybit', 'USDT', 105.0, 5.0, 100.0)],
                         'Binance: zmiana 20 mln = przelewy 20 mln; Bybit: 105 mln wobec przelewów 5 mln — nietypowe (zwykle 0)')
        o = k.wieloryby_ocena(path, hist=self._hist(bybit_ost=5_000_000))
        self.assertEqual((o['porownane'], o['zle']), (2, []))

    def test_migawka_pozna_albo_inna_lista(self):
        k = self.k
        path = self._archiwum()
        o = k.wieloryby_ocena(path, hist=self._hist(czas_ost='05:00'))
        self.assertEqual((o['porownane'], o['polnoc']), (0, 0), 'ostatnia migawka o 05:00 (np. po awarii) — nie o północy, para z archiwum (20 h)')
        o = k.wieloryby_ocena(path, hist=self._hist(wer_ost='2026-10-06'))
        self.assertEqual((o['porownane'], o['polnoc']), (0, 0), 'inna wersja listy portfeli — nowe portfele to skok salda bez przelewów')
        self.assertEqual(k._wh_polnoc({'Binance': [['2026-10-06', '2026-10-06T00:05:00+00:00', 1.0, float('nan'), 2.0], ['x', 'y', 1, 2, 3], 'zly']}),
                         {'2026-10-06': {('Binance', 'ETH'): (1.0, '2026-10-06T00:05:00+00:00', None), ('Binance', 'USDC'): (2.0, '2026-10-06T00:05:00+00:00', None)}},
                         'NaN i złe wiersze pominięte')

    def test_wiersz_i_wywolanie(self):
        k = self.k
        import inspect
        self.assertIn("hist=(files.get('wieloryby') or {}).get('hist')", inspect.getsource(k.kontrola))
        R = {'at': '2026-10-06T15:00:00+00:00', 'wynik': 'OK', 'uwagi': [], 'bledy': [], 'meta': {}, 'pliki': {},
             'zgodnosc': {'wieloryby': {'dzien': '2026-10-06', 'poprzedni': '2026-10-05', 'porownane': 13, 'odstep_h': 24.0, 'pomin': None,
                                        'bez_historii': 0, 'pominiete': 0, 'lista': [], 'polnoc': 13, 'rozbieznosci': []}}}
        self.assertIn('- Wieloryby 2026-10-06 vs 2026-10-05: 13 par giełda/aktywo (salda z migawek o północy UTC: 13), rozbieżności nietypowe', k.raport_md(R))


# ===================== v250: KONTROLA W PRZEGLĄDARCE — NAPISY-BŁĘDY W TEKŚCIE STRONY =====================
class KontrolaNapisyV250(unittest.TestCase):
    """v250: „NaN”, „undefined”, „[object Object]”, „Infinity”, „null” w tekście narysowanej strony = ⚠️ (tylko tekst — nie skrypty, style, atrybuty)."""

    @classmethod
    def setUpClass(cls):
        import importlib.util, tempfile
        tmp = tempfile.mkdtemp(prefix='kontrola250-')
        with mock.patch.dict(os.environ, {'KONTROLA_DIR': os.path.join(tmp, 'k'), 'KONTROLA_ARCH': os.path.join(tmp, 'a')}):
            spec = importlib.util.spec_from_file_location('v250_k', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
            cls.k = importlib.util.module_from_spec(spec); spec.loader.exec_module(cls.k)
        cls.tmp = tmp

    def test_tylko_tekst_strony(self):
        k = self.k
        self.assertEqual(k.przegladarka_artefakty('<div><p>Zmiana: 1,2%</p><style>.x{content:"NaN"}</style><p aria-label="undefined">ok</p></div>'), [],
                         'style i atrybuty się nie liczą')
        A = k.przegladarka_artefakty('<div class="k"><span>Rentowność 10L</span><b>NaN%</b></div><p>[object Object]</p><p>Nullstellensatz, nullable</p>')
        self.assertEqual(len(A), 2, A); self.assertIn('Rentowność 10L NaN%', A[0]); self.assertIn('[object Object]', A[1])

    def test_przebieg_i_uwaga(self):
        k = self.k
        p = os.path.join(self.tmp, 'przegl_napisy.py')
        with open(p, 'w', encoding='utf-8') as f:
            f.write('#!/usr/bin/env python3\nimport sys, time\nsys.stdout.write(\'<html><body><script>const EXTRA={};let a=undefined;</script>'
                    '<div class="arc-gr"></div><p>Zmiana miesiąca: NaN%</p><p>Saldo: undefined USD</p></body></html>\\n\'); sys.stdout.flush()\ntime.sleep(30)\n')
        os.chmod(p, 0o755)
        P = k.strona_przegladarka('https://x', czas_s=20, program=p)
        self.assertEqual((P['stan'], P['artefakty_n']), ('ok', 2), 'undefined w skrypcie się nie liczy')
        self.assertIn('Zmiana miesiąca: NaN%', P['artefakty'][0])
        u = k.przegladarka_uwagi(dict(P, wykresy=20))
        self.assertEqual(len(u), 1); self.assertIn('napisy-błędy w tekście strony (NaN, undefined…): 2 — pierwszy: „Zmiana miesiąca: NaN%', u[0])
        self.assertIn('; napisy-błędy w tekście (NaN, undefined…): 2 ⚠️', k.przegladarka_wiersz(dict(P, wykresy=20)))
        P0 = dict(P, artefakty=[], artefakty_n=0, wykresy=20)
        self.assertEqual(k.przegladarka_uwagi(P0), []); self.assertNotIn('napisy-błędy', k.przegladarka_wiersz(P0))


# ===================== v250b: POPRAWKI PO PRZEGLĄDZIE v248–v249 =====================
class PoPrzegladzieV250(unittest.TestCase):
    """v250b: błąd złapany przez stronę (console.error) = błąd; norma pary wielorybów z par tego samego rodzaju; podpis „d vs d − 1”;
    powód przy braku migawki o północy; „drugi raz z rzędu” tylko z ostatnich 30 h."""

    @classmethod
    def setUpClass(cls):
        import importlib.util, tempfile
        tmp = tempfile.mkdtemp(prefix='kontrola250b-')
        with mock.patch.dict(os.environ, {'KONTROLA_DIR': os.path.join(tmp, 'k'), 'KONTROLA_ARCH': os.path.join(tmp, 'a')}):
            spec = importlib.util.spec_from_file_location('v250b_k', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
            cls.k = importlib.util.module_from_spec(spec); spec.loader.exec_module(cls.k)
        cls.tmp = tmp

    def test_blad_zlapany_przez_strone(self):
        k = self.k
        log = ('[1:2:1006/1.1:INFO:CONSOLE:5] "TypeError: Cannot read properties of undefined (reading \'x\')\n    at render (https://capitalflowai-app.github.io/:3303:9)", '
               'source: https://capitalflowai-app.github.io/ (3304)\n'
               '[1:2:1006/1.2:INFO:CONSOLE:5] "Error: zła odpowiedź", source: https://capitalflowai-app.github.io/ (2426)\n'
               '[1:2:1006/1.3:INFO:CONSOLE:5] "Errors in the past", source: https://capitalflowai-app.github.io/ (1)\n'
               '[1:2:1006/1.4:INFO:CONSOLE:1] "Uncaught RangeError: x", source: https://s/ (1)\nINFO: Created TensorFlow Lite XNNPACK delegate for CPU.\n')
        K = k.przegladarka_konsola(log)
        self.assertEqual([b.split(' (')[0] for b in K['bledy']], ["TypeError: Cannot read properties of undefined", 'Error: zła odpowiedź',
                                                                  'Uncaught RangeError: x'], K)   # v252: doklejona obca linia — wpis odczytany
        self.assertEqual((K['inne'], K['nieczytelne']), (['Errors in the past'], 0), '„Errors…” to nie nazwa błędu; obca linia po „Uncaught” — błąd, nie „nieczytelny”')

    def test_prawdziwy_chrome_blad_zlapany(self):
        k = self.k
        if os.environ.get('GITHUB_ACTIONS') or not k.przegladarka_program():
            self.skipTest('tylko lokalnie, z zainstalowanym Chrome')
        p = os.path.join(self.tmp, 'zlapany.html')
        with open(p, 'w', encoding='utf-8') as f:
            f.write('<!doctype html><html><body><script>const EXTRA={};function render(){try{const o=undefined;return o.x;}catch(err){console.error(err);}}'
                    'setTimeout(render,50);setInterval(()=>{},1000);</script></body></html>')
        P = k.strona_przegladarka('file://' + p, czas_s=60)
        self.assertTrue(P.get('ok'), P)
        self.assertEqual(len(P['bledy']), 1, P); self.assertTrue(P['bledy'][0].startswith('TypeError'), P['bledy'])
        self.assertEqual(len(k.przegladarka_uwagi(dict(P, wykresy=20))), 1, 'uwaga — popsuty rysunek nie jest „0 ✅”')

    def _archiwum(self, dni, bloki, saldo, netto, nazwa='w.csv'):
        p = os.path.join(self.tmp, nazwa)
        with open(p, 'w', encoding='utf-8') as f:
            f.write('date,exchange,asset,balance,balance_usd,inflow_24h,outflow_24h,net_24h,block\n')
            for i, d in enumerate(dni):
                f.write(f'{d},Bitfinex,USDT,{saldo(i)},{saldo(i)},0,0,{netto},{bloki(i)}\n')
        return p

    def _hist(self, dni, usdt, czas=lambda d: '00:05'):
        return {'Bitfinex': [[d, f'{d}T{czas(d)}:00+00:00', 0.0, usdt(i), 0.0, '2022-11'] for i, d in enumerate(dni)]}

    def test_norma_z_par_tego_samego_rodzaju(self):
        k = self.k
        dni = [f'2026-10-0{i}' for i in range(1, 8)]
        arch = self._archiwum(dni, lambda i: 26_000_000 + i * 7200, lambda i: 1e9 + i * 20e6, 0)   # archiwum: rozbieżność 20 mln dziennie
        H = self._hist(['2026-09-30'] + dni, lambda i: 1e9 + i * 4e6, czas=lambda d: '02:30' if d == '2026-10-07' else '00:05')   # północ: 4 mln; 07.10 późno
        o = k.wieloryby_ocena(arch, hist=H)
        self.assertEqual((o['porownane'], o['polnoc'], o['zle']), (1, 0, []), 'para z archiwum (20 mln) oceniana normą par z archiwum (20 mln) — bez fałszywej ⚠️')
        H2 = self._hist(['2026-09-30'] + dni, lambda i: 1e9 + i * 4e6 + (16e6 if i == 7 else 0))
        o = k.wieloryby_ocena(arch, hist=H2)
        self.assertEqual((o['polnoc'], [(g, a, round(z / 1e6)) for g, a, x, y, z, m in o['zle']]), (1, [('Bitfinex', 'USDT', 20)]),
                         'para z północy 20 mln wobec normy par północnych 4 mln — nietypowe')

    def test_podpis_i_powod(self):
        k = self.k
        dni = ['2026-10-01', '2026-10-02', '2026-10-03', '2026-10-04', '2026-10-06']   # archiwum bez 05.10
        arch = self._archiwum(dni, lambda i: 26_000_000 + i * 6000, lambda i: 1e9, 0, nazwa='w2.csv')
        H = self._hist(['2026-10-05', '2026-10-06'], lambda i: 1e9)
        o = k.wieloryby_ocena(arch, hist=H)
        self.assertEqual((o['poprzedni'], o['poprzedni_pokaz'], o['polnoc'], o['porownane']), ('2026-10-04', '2026-10-05', 1, 1))
        R = {'at': '2026-10-06T15:00:00+00:00', 'wynik': 'OK', 'uwagi': [], 'bledy': [], 'meta': {}, 'pliki': {},
             'zgodnosc': {'wieloryby': dict(o, rozbieznosci=[])}}
        self.assertIn('- Wieloryby 2026-10-06 vs 2026-10-05: 1 par', k.raport_md(R))
        H = self._hist(['2026-10-05', '2026-10-06'], lambda i: 1e9, czas=lambda d: '03:10')
        o = k.wieloryby_ocena(arch, hist=H)
        self.assertIn('; migawki o północy brak albo później niż 2 h po północy UTC: 2026-10-05 — Bitfinex; 2026-10-06 — Bitfinex', o['pomin'])   # v253: dni i giełdy

    def test_poprzedni_tylko_z_30_h(self):
        k = self.k
        p = os.path.join(self.tmp, 'historia30.json')
        teraz = datetime.datetime(2026, 10, 6, 15, 0, tzinfo=datetime.timezone.utc)
        with open(p, 'w', encoding='utf-8') as f:
            json.dump([{'at': '2026-10-04T06:20:00+00:00', 'przegl': 'zawieszona'}], f)
        self.assertIsNone(k.przegladarka_poprzedni(p, teraz), 'sprzed 57 h — nie „z rzędu”')
        with open(p, 'w', encoding='utf-8') as f:
            json.dump([{'at': '2026-10-06T06:20:00+00:00', 'przegl': 'zawieszona'}], f)
        self.assertEqual(k.przegladarka_poprzedni(p, teraz), 'zawieszona')


# ===================== v252: POPRAWKI PO PRZEGLĄDZIE v250–v251 =====================
class PoPrzegladzieV252(unittest.TestCase):
    """v252: „[object DOMException]” i nazwy …Error/…Exception = błąd; wpis z doklejoną linią odczytany; „∞” i „Invalid Date” = napisy-błędy;
    powód braku porównania wielorybów — właściwy dzień; „błędów JavaScriptu”."""

    @classmethod
    def setUpClass(cls):
        import importlib.util, tempfile
        tmp = tempfile.mkdtemp(prefix='kontrola252-')
        with mock.patch.dict(os.environ, {'KONTROLA_DIR': os.path.join(tmp, 'k'), 'KONTROLA_ARCH': os.path.join(tmp, 'a')}):
            spec = importlib.util.spec_from_file_location('v252_k', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
            cls.k = importlib.util.module_from_spec(spec); spec.loader.exec_module(cls.k)
        cls.tmp = tmp

    def test_bledy_dom_i_doklejona_linia(self):
        k = self.k
        log = ('[1:2:1006/1.1:INFO:CONSOLE:5] "[object DOMException]", source: https://capitalflowai-app.github.io/ (3319)\n'
               '[1:2:1006/1.2:INFO:CONSOLE:5] "IndexSizeError: Failed to execute \'arc\' on \'CanvasRenderingContext2D\': The radius provided (-1) is negative.", '
               'source: https://capitalflowai-app.github.io/ (3320)\n'
               '[1:2:1006/1.3:INFO:CONSOLE:5] "TypeError: x is null", source: https://capitalflowai-app.github.io/ (3319)\nINFO: Created TensorFlow Lite XNNPACK delegate for CPU.\n')
        K = k.przegladarka_konsola(log)
        self.assertEqual([b.split(' (')[0] for b in K['bledy']], ['[object DOMException]', "IndexSizeError: Failed to execute 'arc' on 'CanvasRenderingContext2D': The radius provided",
                                                                  'TypeError: x is null'])
        self.assertEqual((K['inne'], K['nieczytelne']), ([], 0), 'doklejona obca linia — wpis odczytany')
        P = dict({'ok': True, 'stan': 'ok', 'czas_s': 5.0, 'svg': 148, 'wykresy': 20}, **K)
        w = k.przegladarka_wiersz(P)
        self.assertIn('; błędów JavaScriptu: 3 ⚠️', w); self.assertNotIn('nieobsłużonych', w)
        self.assertTrue(k.przegladarka_uwagi(P)[0].startswith('strona w przeglądarce: błędów JavaScriptu 3 — pierwszy: [object DOMException]'))

