    def test_obce_bledy_czesci_z_pamieci(self):
        prev = {'at': zd.NOW, 'ok': {'br': True}, 'br': {'at': zd.NOW, 'd': [['2026-09-25', 1.0]]}, 'errs': {'br': ['BCB: 1 serie bez odpowiedzi, np. 13970: x']}}
