# ===================== v270: POPRAWKI PO PRZEGLĄDZIE v268–v269 =====================
class PoPrzegladzieV270(unittest.TestCase):
    """v270: zapas cen kończy się na ostatniej pełnej sesji; kalendarz z pliku Świat dziennie (SPY z wierszem bez ceny); podziały jednostek;
    plik zapasu nie jest pamięcią Twelve Data; totalNodes < strona = nieużyteczne; jednostka kwoty po zaokrągleniu."""

    @classmethod
    def setUpClass(cls):
        import importlib.util, tempfile
        tmp = tempfile.mkdtemp(prefix='kontrola270-')
        with mock.patch.dict(os.environ, {'KONTROLA_DIR': os.path.join(tmp, 'k'), 'KONTROLA_ARCH': os.path.join(tmp, 'a')}):
            spec = importlib.util.spec_from_file_location('v270_k', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
            cls.k = importlib.util.module_from_spec(spec); spec.loader.exec_module(cls.k)

    def setUp(self):
        zd.META['errors'].clear(); zd.META['notes'].clear(); zd.META['ok'].clear()

    @staticmethod
    def _sd(dni=30, ost='2026-10-05'):
        d0, cal = datetime.date.fromisoformat(ost), []
        while len(cal) < dni:
            if d0.weekday() < 5:
                cal.append(d0.isoformat())
            d0 -= datetime.timedelta(days=1)
        cal = sorted(cal)
        px = {s: {'d': [[d, 99.0, 100.0 + i + j, 'x'] for j, d in enumerate(cal)]} for i, s in enumerate(zd.DAY_SYMS)}
        return {'at': '2026-10-06T23:56:47+00:00', 'px': px, 'cal': cal}

    def test_niepelna_ostatnia_sesja(self):
        sd = self._sd()
        for s in ('KSA', 'ASEA'):
            sd['px'][s]['d'] = sd['px'][s]['d'][:-1]   # brak 05.10 — dopisywane po 55 min
        c = zd.ceny_z_swiata(sd)
        self.assertEqual((c['asof'], {v['asof'] for v in c['q'].values()}, len(c['q'])), ('2026-10-02', {'2026-10-02'}, 14),
                         'przegląd: niepełny zapas (bez KSA i ASEA z 05.10) zastępował pełny plik')
        self.assertEqual(c['q']['SPY']['d'][-1][0], '2026-10-02')
        sd = self._sd(); sd['px']['ASEA']['d'] = sd['px']['ASEA']['d'][:-6]   # ASEA bez zamknięcia od 6 sesji — wypada
        c = zd.ceny_z_swiata(sd)
        self.assertEqual((c['asof'], 'ASEA' in c['q'], len(c['q'])), ('2026-10-05', False, 13))

    def test_kalendarz_z_pliku_i_spy_bez_ceny(self):
        sd = self._sd()
        d = sd['cal'][10]
        sd['px']['SPY']['d'] = [r for r in sd['px']['SPY']['d'] if r[0] != d] + [[d, None, None, 'x']]
        c = zd.ceny_z_swiata(sd)
        self.assertIn([d, None, None], c['q']['SPY']['d'], 'SPY: wiersz bez ceny — kalendarz strony pełny')
        self.assertIn(d, [r[0] for r in c['q']['EWC']['d']], 'przegląd: zamknięcia innych funduszy z tego dnia wypadały')
        self.assertEqual(len(c['q']['SPY']['d']), 30)

    def test_podzial_jednostek(self):
        sd = self._sd()
        rows = sd['px']['EWY']['d']
        for r in rows[-3:]:
            r[2] = round(r[2] / 2, 4)   # podział 2:1 trzy sesje temu, szereg niepoprawiony
        c = zd.ceny_z_swiata(sd)
        e = c['q']['EWY']['d']
        self.assertAlmostEqual(e[-3][1] / e[-4][1], (rows[-3][2] * 2) / rows[-4][2], places=6, msg='ruch dnia podziału bez skoku −50%')
        self.assertEqual(c['podzialy'], [['EWY', rows[-3][0], 0.5]])
        saved = {}
        with mock.patch.object(zd, 'previous', lambda n: None), mock.patch.object(zd, '_prev_cache', lambda n: sd if n == 'swiat-dzien' else None), \
                mock.patch.object(zd, 'save', lambda n, o: saved.__setitem__(n, o)):
            zd.ceny_zapas(None, 'Twelve Data: HTTP 401')
        self.assertTrue(any('podział jednostek uwzględniony — EWY' in n for n in zd.META['notes']), zd.META['notes'])

    def test_pelniejszy_zastepuje_i_pamiec(self):
        sd = self._sd(); sd['px']['ASEA']['d'] = sd['px']['ASEA']['d'][:-6]
        prev = zd.ceny_z_swiata(sd)   # zapas bez ASEA, sesja 05.10
        saved = {}
        with mock.patch.object(zd, 'previous', lambda n: None), mock.patch.object(zd, '_prev_cache', lambda n: self._sd() if n == 'swiat-dzien' else None), \
                mock.patch.object(zd, 'save', lambda n, o: saved.__setitem__(n, o)):
            zd.ceny_zapas(prev, 'Twelve Data: HTTP 401')
        self.assertEqual(len(saved['ceny']['q']), 14, 'ta sama sesja, więcej funduszy — zastępuje')
        import inspect
        self.assertIn("if td_key and prev_ceny and fresh(prev_ceny, 55) and not prev_ceny.get('zapas'):", inspect.getsource(zd.main))

    def test_xs_totalnodes_mniejsze_i_jednostka(self):
        N = [_rwe170_xn(f'B{i}x', 1000000, 10000, 'USD', '2026-10-06T18:00:00Z') for i in range(3)]
        for tn in (0, 2):
            j = _rwe170_xs(N); j['data']['tokens']['page']['totalNodes'] = tn
            with mock.patch.dict(zd.RWE_XS_VAR, {'pageSize': 3}):
                with self.assertRaises(ValueError) as c:
                    zd.rwe_xs_parse(j, None)
            self.assertIn('bez liczby wszystkich tokenów', str(c.exception), 'przegląd: totalNodes < strona uchodziło za pełną listę')
        k = self.k
        def opis(x):
            j = {'issuer': {'at': 'x', 'ok': True, 'used': {'xstocks': 1e9},
                            'p': {'xstocks': {'name': 'xStocks', 'v': 1e9, 'stan': 'w', 'full': True, 'ogon': {'n': 5, 'max_usd': x}}}}}
            return k.rwe_porownanie(j)['opis']
        self.assertIn('najwyżej 1.00 mln USD', opis(999960)); self.assertIn('najwyżej 1.0 tys. USD', opis(999.6))


# ===================== v271: POPRAWKI PO PRZEGLĄDZIE v270 =====================
class PoPrzegladzieV271(unittest.TestCase):
    """v271: podziały jednostek z ruchem rynku w dniu podziału (i 5:2, 4:3); zapas zastępuje tylko pełniejszy plik; Twelve Data po nieudanej
    próbie ponawiany najwcześniej po 55 min."""

    def setUp(self):
        zd.META['errors'].clear(); zd.META['notes'].clear(); zd.META['ok'].clear()

    _sd = staticmethod(PoPrzegladzieV270._sd)

    def test_podzial_z_ruchem_rynku(self):
        for wsp, ruch in ((0.5, 1.031), (1 / 3, 1.08), (0.25, 0.95), (1 / 1.5, 1.03), (2, 0.95)):   # v272: 5:2 i 4:3 usunięte; 3:1 w dniu +8%
            sd = self._sd()
            rows = sd['px']['EWY']['d']
            base = rows[-4][2]
            rows[-3][2] = round(base * wsp * ruch, 4)   # dzień podziału: współczynnik × ruch rynku
            for r in rows[-2:]:
                r[2] = round(r[2] * wsp, 4)
            c = zd.ceny_z_swiata(sd)
            self.assertEqual(c.get('podzialy'), [['EWY', rows[-3][0], round(wsp, 6)]], f'przegląd: podział ×{wsp} w dniu ruchu {ruch} umykał')
            e = c['q']['EWY']['d']
            self.assertAlmostEqual(e[-3][1] / e[-4][1], ruch, places=3, msg='po przeskalowaniu zostaje sam ruch rynku')
        sd = self._sd(); rows = sd['px']['ILF']['d']; rows[-1][2] = round(rows[-2][2] * 0.82, 4)   # −18% (największy spadek w 10 latach)
        self.assertNotIn('podzialy', zd.ceny_z_swiata(sd), 'spadek −18% to nie podział')

    @staticmethod
    def _plik(ost, pelne, niepelne=(), dzien_wczesniej='2026-10-02'):
        q = {s: {'asof': ost, 'd': [['2026-09-30', 1.0, None], [ost, 2.0, None]]} for s in pelne}
        q.update({s: {'asof': dzien_wczesniej, 'd': [['2026-09-30', 1.0, None], [dzien_wczesniej, 2.0, None]]} for s in niepelne})
        return {'at': 'x', 'q': q}

    def test_kiedy_zapas_zastepuje(self):
        S = list(zd.DAY_SYMS)
        L = zd._ceny_lepszy
        self.assertTrue(L(self._plik('2026-10-05', S), self._plik('2026-10-05', S[:-1], S[-1:])), 'przegląd (a): Twelve Data z ASEA na 02.10 — pełny zapas zastępuje')
        self.assertFalse(L(self._plik('2026-10-05', S[:-1]), self._plik('2026-10-02', S)), 'przegląd (b): zapas bez funduszu nie zastępuje pełnego o sesję starszego')
        z = self._plik('2026-10-05', S[:-1]); z['q']['SPY']['d'] = [[d, 1.0, None] for d in ('2026-09-28', '2026-09-29', '2026-09-30', '2026-10-01', '2026-10-02', '2026-10-05')]
        self.assertTrue(L(z, self._plik('2026-09-25', S)), 'poprzedni plik ≥ 5 sesji starszy — świeższy, choć niepełny')
        self.assertTrue(L(self._plik('2026-10-05', S), None)); self.assertFalse(L(self._plik('2026-10-02', S), self._plik('2026-10-05', S)))
        self.assertEqual(zd._ceny_pelne(self._plik('2026-10-05', S[:-2], S[-2:])), ('2026-10-05', 12))

    def test_ponowienie_po_godzinie(self):
        saved = {}
        prev = {'at': '2026-10-06T10:00:00+00:00', 'q': {'SPY': {'d': [['2026-10-05', 1.0, 1]]}}}
        with mock.patch.object(zd, 'previous', lambda n: None), mock.patch.object(zd, '_prev_cache', lambda n: None), \
                mock.patch.object(zd, 'save', lambda n, o: saved.__setitem__(n, o)):
            zd.ceny_zapas(prev, 'Twelve Data: HTTP 429', proba=True)
        self.assertIs(saved['ceny'], prev); self.assertEqual((prev['td_proba'], prev['td_blad']), (zd.NOW, 'Twelve Data: HTTP 429'))
        import inspect
        src = inspect.getsource(zd.main)
        self.assertIn("elif td_key and prev_ceny and isinstance(prev_ceny.get('td_proba'), str) and fresh({'at': prev_ceny['td_proba']}, 55):", src)
        self.assertIn("— ponowienie po godzinie", src)


# ===================== v272: POPRAWKI PO PRZEGLĄDZIE v271 =====================
class PoPrzegladzieV272(unittest.TestCase):
    """v272: klucz ze znakiem sterującym w środku nieużyty i nigdy w komunikacie (postaci z ucieczkami, zapytanie, straż kluczy); maskowanie
    przed cięciem; podziały jednostek w zapasie cen — para przez lukę ±2%, najbliższy współczynnik, bez 4:3 i 5:2."""

    K = 'f00dcafe12345678\tbeefbabe87654321'   # klucz wklejony z tabulatorem w środku (zmyślony)

    def setUp(self):
        zd.META['errors'].clear(); zd.META['notes'].clear(); zd.META['ok'].clear()
        self._s, self._z = list(zd.SECRETS), list(zd.SECRETS_ZLE)

    def tearDown(self):
        zd.SECRETS[:] = self._s; zd.SECRETS_ZLE[:] = self._z

    _sd = staticmethod(PoPrzegladzieV270._sd)

    def test_klucz_odrzuca_znaki_sterujace(self):
        with mock.patch.dict(os.environ, {'TWELVEDATA_KEY': self.K, 'FRED_KEY': '  dobry-klucz-123  ', 'EIA_KEY': 'ab cd'}, clear=False):
            self.assertEqual((zd.klucz('TWELVEDATA_KEY'), zd.klucz('FRED_KEY'), zd.klucz('EIA_KEY'), zd.klucz('NIE_MA_TAKIEGO')),
                             ('', 'dobry-klucz-123', '', ''))
        self.assertEqual(len(zd.META['errors']), 2); self.assertTrue(all('f00d' not in e and 'beef' not in e and 'ab cd' not in e for e in zd.META['errors']))
        self.assertIn('Klucz TWELVEDATA_KEY: spacja albo znak sterujący', zd.META['errors'][0])
        self.assertIn(self.K, zd.SECRETS_ZLE, 'odrzucona wartość nadal maskowana')
        import inspect
        src = inspect.getsource(zd.main)
        for n in ('SOSOVALUE_KEY', 'COINGECKO_KEY', 'FINNHUB_KEY', 'TWELVEDATA_KEY', 'COINMARKETCAP_KEY', 'FRED_KEY', 'COINALYZE_KEY', 'ETHERSCAN_KEY',
                  'EVDS_KEY', 'BANXICO_TOKEN'):
            self.assertIn(f"klucz('{n}')", src)
        self.assertIn("ix_keys = {k: klucz(k) for k in IX_KEYS}", src); self.assertIn("(klucz(k) for k in ('EIA_KEY', 'BLS_KEY', 'BEA_KEY'))", src)
        self.assertNotRegex(src, r"os\.environ\.get\('[A-Z_]*(KEY|TOKEN)'", 'każdy klucz przez klucz()')

    def test_maskowanie_postaci_z_ucieczkami(self):
        zd.SECRETS[:] = ['dobryklucz12345']; zd.SECRETS_ZLE[:] = [self.K]
        a, b = 'f00dcafe12345678', 'beefbabe87654321'
        for txt in (f"URL can't contain control characters. '/x?apikey={repr(self.K)[1:-1]}' (found at least '\\t')",
                    json.dumps({'e': self.K}), 'apikey=' + zd.urllib.parse.quote(self.K, safe=''), f'apikey={a}%5Ct{b}', f'{a} … {b}'):
            m = zd.mask(txt)
            self.assertNotIn(a, m, txt); self.assertNotIn(b, m, txt)
        self.assertEqual(zd.mask("x 'dobryklucz12345' y"), "x '***' y")
        self.assertEqual(zd.mask(json.dumps('dobry"klucz')), json.dumps('dobry"klucz'), 'krótkie/obce teksty bez zmian')

    def test_zapytanie_ze_zlym_kluczem_bez_tresci(self):
        for url, h in (('https://api.example.invalid/x?apikey=' + self.K, None), ('https://api.example.invalid/x', {'x-api-key': 'ab\ncd1234567890'})):
            with self.assertRaises(ValueError) as c:
                zd.get(url, h)
            self.assertEqual(str(c.exception), 'zły adres albo nagłówek zapytania (' + ('InvalidURL' if h is None else 'ValueError') + ')')
            self.assertIsNone(c.exception.__cause__); self.assertTrue(c.exception.__suppress_context__, 'bez pierwotnego wyjątku w śladzie')
        with self.assertRaises(ValueError):
            zd.get_bytes('https://api.example.invalid/x?apikey=' + self.K)

    def test_straz_kawalki(self):
        import importlib.util
        spec = importlib.util.spec_from_file_location('v272_straz', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'straz_kluczy.py'))
        s = importlib.util.module_from_spec(spec); spec.loader.exec_module(s)
        sek, _ = s.sekrety({'TWELVEDATA_KEY': self.K, 'SEC_CONTACT': 'CapitalFlowAI kontakt@example.com', 'FRED_KEY': 'zwyklyklucz123'})
        self.assertEqual(sorted(sek), ['FRED_KEY', 'SEC_CONTACT', 'TWELVEDATA_KEY', 'TWELVEDATA_KEY (kawałek 1)', 'TWELVEDATA_KEY (kawałek 2)'])
        import tempfile
        root = tempfile.mkdtemp(); os.makedirs(os.path.join(root, 'data'))
        with open(os.path.join(root, 'data', 'meta.json'), 'w', encoding='utf-8') as f:
            json.dump({'errors': ["URL can't contain control characters. '/q?apikey=" + repr(self.K)[1:-1] + "'"]}, f)
        tr, n = s.skanuj(sek, root)
        self.assertEqual(sorted(a for a, _, _ in tr), ['TWELVEDATA_KEY (kawałek 1)', 'TWELVEDATA_KEY (kawałek 2)'], 'straż widzi kawałki w postaci z ucieczkami')

    def test_maskowanie_przed_cieciem(self):
        import inspect
        src = inspect.getsource(zd.main)
        self.assertIn("ceny_zapas(prev_ceny, mask(f'Twelve Data: {e}')[:93], proba=True)", src)
        self.assertIn("err.append(f'{sid}: ' + mask(str(e))[:80])", inspect.getsource(zd.ix_wyd_part))
        zd.SECRETS[:] = ['X' * 28 + 'KLUCZ1234']
        saved = {}
        with mock.patch.object(zd, 'previous', lambda n: None), mock.patch.object(zd, '_prev_cache', lambda n: None), \
                mock.patch.object(zd, 'save', lambda n, o: saved.__setitem__(n, o)):
            zd.ceny_zapas({'at': 'x', 'q': {}}, mask_ := zd.mask('Twelve Data: ' + 'a' * 60 + ' ' + 'X' * 28 + 'KLUCZ1234')[:93], proba=True)
        self.assertNotIn('XXXXXXXX', saved['ceny']['td_blad'] + ' '.join(zd.META['notes']))

    def test_podzial_przez_luke_i_najblizszy(self):
        f = zd._ceny_podzial
        self.assertIsNone(f(0.761, False), 'TUR 9→13.08.2018 przez lukę — nie podział'); self.assertIsNone(f(0.7874, True), '4:3 usunięte')
        self.assertEqual(f(1 / 3 * 1.08), 1 / 3, 'przegląd: 3:1 w dniu +8% brany jako ×0,4'); self.assertEqual(f(0.5 * 0.9), 0.5)
        self.assertEqual(f(0.5 * 1.015, False), 0.5, 'przez lukę tylko ±2%'); self.assertIsNone(f(0.5 * 1.05, False))
        self.assertIsNone(f(0.82)); self.assertIsNone(f(1.21)); self.assertIsNone(f(1.0)); self.assertIsNone(f(0.0)); self.assertIsNone(f(float('nan')))
        self.assertEqual(f(1 / 1.5 * 1.03), 1 / 1.5); self.assertIsNone(f(1 / 1.5 * 1.06), '1,5 tylko ±5%')
        # TUR −24% przez lukę (brak wiersza w sesji pomiędzy) — zapas bez fałszywego podziału, cały rok bez przeskalowania
        sd = self._sd(); rows = sd['px']['TUR']['d']
        rows[-1][2] = round(rows[-3][2] * 0.761, 4); del rows[-2]
        c = zd.ceny_z_swiata(sd)
        self.assertNotIn('podzialy', c); e = {r[0]: r[1] for r in c['q'].get('TUR', {'d': []})['d']}
        self.assertTrue(all(abs(e[r[0]] - r[2]) < 1e-6 for r in rows if r[0] in e), 'zamknięcia TUR bez zmian')
        # prawdziwy podział 2:1 przez lukę (bez ruchu rynku) — nadal rozpoznany
        sd = self._sd(); rows = sd['px']['EWY']['d']; base = rows[-4][2]
        for r in rows[-3:]:
            r[2] = round(r[2] / 2, 4)
        rows[-3][2] = round(base / 2 * 1.01, 4); del rows[-4]
        self.assertEqual(zd.ceny_z_swiata(sd).get('podzialy'), [['EWY', rows[-3][0], 0.5]])


# ===================== v273: 5 INDEKSÓW Z FMP, EODHD JAKO ZAPAS; NAUKA PORY TAKŻE Z BRAKU SESJI =====================
class IndeksyFmpV273(unittest.TestCase):
    """v273: S&P 500, Nasdaq, Dow, Nikkei i Hang Seng z FMP (plan 250 zapytań na dobę) — EODHD ma 17 indeksów, wszystkie tego samego dnia;
    EODHD zapasem, gdy FMP zawiedzie; wspólny rdzeń (poprawki, luka, nauka); brak sesji = ponowienie (FMP) i dowód dla nauki; zmiana dostawcy
    to nie poprawka."""
    UTC = datetime.timezone.utc

    def T(self, *a):
        return datetime.datetime(*a, tzinfo=self.UTC)

    def setUp(self):
        zd.META['errors'].clear(); zd.META['notes'].clear()

    @staticmethod
    def _dni(od, do):
        d, out = od, []
        while d <= do:
            if d.weekday() < 5:
                out.append(d)
            d += datetime.timedelta(days=1)
        return out

    def _siec(self, now_ref, opoz=None, fmp_402=(), fmp_down=False):
        """Udawana sieć: każdy dostawca ma sesję dnia D od godziny h (z IX_SYMBOLS / IX_FMP) + opóźnienie opoz[kod] godzin."""
        godz = {s: h for s, _, h in zd.IX_SYMBOLS}; godz.update({s: h for s, _, h, _ in zd.IX_FMP})
        fsym = {f: s for s, _, _, f in zd.IX_FMP}
        calls = []

        def gj(url, headers=None, timeout=30):
            now = now_ref[0]
            if 'financialmodelingprep' in url:
                s = fsym[url.split('symbol=')[1].split('&')[0]]
                calls.append(('fmp', s, now))
                if fmp_down:
                    raise zd.urllib.error.URLError('timeout')
                if s in fmp_402:
                    raise zd.urllib.error.HTTPError('u', 402, 'Payment', {}, None)
            else:
                s = url.split('/eod/')[1].split('.INDX')[0]
                calls.append(('eod', s, now))
                if s == 'JTOPI':
                    return []
            frm = datetime.date.fromisoformat(url.split('from=')[1].split('&')[0])
            gotowe = now - datetime.timedelta(hours=godz[s] + (opoz or {}).get(s, 0))
            dni = self._dni(frm, gotowe.date())
            if 'financialmodelingprep' in url:
                return [{'date': d.isoformat(), 'price': 100.0 + d.toordinal() % 7} for d in dni]
            return [{'date': d.isoformat(), 'close': 100.0 + d.toordinal() % 7} for d in dni]
        return gj, calls

    def _swiezy(self, now):
        """Wszystkie indeksy pobrane w tej chwili z sesją dnia (FMP: src 'fmp') — w planie tylko to, co test zmieni."""
        d = now.date().isoformat()
        ix = {s: {'cc': c, 'at': now.isoformat(), 'd': [[d, 1.0]]} for s, c, _ in zd.IX_SYMBOLS}
        ix.update({s: {'cc': c, 'at': now.isoformat(), 'src': 'fmp', 'd': [[d, 1.0]]} for s, c, _, _ in zd.IX_FMP})
        ix['JTOPI'] = {'bad_at': now.isoformat(), 'bad_n': 3, 'bad': 'pusto'}
        return ix

    def test_tydzien_wszystkie_indeksy_tego_samego_dnia(self):
        now_ref = [self.T(2026, 10, 12, 0, 5)]
        gj, calls = self._siec(now_ref)
        dni = self._dni(datetime.date(2026, 10, 5), datetime.date(2026, 10, 9))
        rows = [[d.isoformat(), 100.0 + d.toordinal() % 7] for d in dni]
        ix = {s: {'cc': c, 'at': '2026-10-09T23:30:00+00:00', 'd': [list(r) for r in rows]} for s, c, _ in zd.IX_SYMBOLS}
        ix.update({s: {'cc': c, 'at': '2026-10-09T23:30:00+00:00', 'src': 'fmp', 'd': [list(r) for r in rows]} for s, c, _, _ in zd.IX_FMP})
        ix['JTOPI'] = {'bad_at': '2026-10-09T16:05:00+00:00', 'bad_n': 3, 'bad': 'pusto'}
        prev = {'at': '2026-10-09T23:30:00+00:00', 'ix': ix, 'ix_calls': {'d': '2026-10-09', 'n': 18}}
        with mock.patch.object(zd, 'get_json', side_effect=gj):
            for hh in range(5 * 24):   # poniedziałek 00:05 – piątek 23:05, przebieg indeksów co godzinę
                now_ref[0] = self.T(2026, 10, 12, 0, 5) + datetime.timedelta(hours=hh)
                with mock.patch.object(zd, 'NOW', now_ref[0].isoformat()):
                    prev = zd.build_indeksy({'EODHD_KEY': 'e', 'FMP_KEY': 'f'}, prev, now=now_ref[0])
                if now_ref[0].hour == 23:   # o 23:05 UTC każdy indeks ma sesję tego dnia (JTOPI — dostawca nie podaje)
                    dzien = now_ref[0].date().isoformat()
                    zal = {s: r['d'][-1][0] for s, r in prev['ix'].items() if s != 'JTOPI' and r.get('d') and r['d'][-1][0] != dzien}
                    self.assertEqual(zal, {}, f'{dzien}: indeksy bez sesji tego dnia')
        per = {}
        for src, s, t in calls:
            if src == 'eod':
                per[t.date()] = per.get(t.date(), 0) + 1
        self.assertTrue(max(per.values()) <= zd.IX_DAILY, per)
        self.assertTrue(all(n <= 18 for n in per.values()), f'EODHD: 17 indeksów (+ JTOPI w przerwie rosnącej) — {per}')
        self.assertTrue(all(t.hour >= 7 for src, _, t in calls if src == 'eod'), 'żadnego indeksu po północy — każdy w dniu swojej sesji')
        eod_kody = {s for src, s, _ in calls if src == 'eod'}
        self.assertFalse(eod_kody & {'GSPC', 'IXIC', 'DJI', 'N225', 'HSI'}, 'FMP zdrowy — EODHD nie pyta o jego indeksy')
        self.assertEqual({s for src, s, _ in calls if src == 'fmp'}, {'FTSE', 'GSPC', 'IXIC', 'DJI', 'N225', 'HSI'})
        self.assertTrue(all(prev['ix'][s].get('src') == 'fmp' for s in ('GSPC', 'IXIC', 'DJI', 'N225', 'HSI', 'FTSE')))

    def test_zapas_eodhd_gdy_fmp_zawodzi(self):
        # v284: zapas po IX_ZAPAS_PO min od chwili gotowości FMP (z nauczoną porą 23:00 → od 01:15), raz na sesję, z limitu
        now = self.T(2026, 10, 13, 22, 5)
        now_ref = [now]
        gj, calls = self._siec(now_ref, fmp_402={'GSPC'})
        prev = {'ix': self._swiezy(self.T(2026, 10, 13, 23, 5))}
        prev['ix']['GSPC'] = {'cc': 'us', 'at': '2026-10-12T22:05:00+00:00', 'src': 'fmp', 'd': [['2026-10-12', 100.0]], 'h+': 1, 'h+n': 2}
        with mock.patch.object(zd, 'get_json', side_effect=gj), mock.patch.object(zd, 'NOW', now.isoformat()):
            o = zd.build_indeksy({'EODHD_KEY': 'e', 'FMP_KEY': 'f'}, prev, now=self.T(2026, 10, 13, 23, 5))
        g = o['ix']['GSPC']
        self.assertEqual((g['fmp_bad'], g['fmp_bad_n'], g['d'][-1][0]), (402, 1, '2026-10-12'), 'przed 01:15 — jeszcze bez zapasu')
        self.assertNotIn(('eod', 'GSPC'), [(a, b) for a, b, _ in calls])
        self.assertIn('FMP HTTP 402 — GSPC (przerwa; zapas EODHD)', '; '.join(zd.META['errors']))
        calls.clear(); now_ref[0] = self.T(2026, 10, 14, 1, 20)   # nauczona pora FMP 23:00 (h+1) — zapas od 01:15
        sw = self._swiezy(self.T(2026, 10, 14, 1, 20))
        for x in sw.values():
            if isinstance(x.get('d'), list):
                x['d'] = [['2026-10-13', x['d'][0][1]]]   # sesja 13.10 już jest — zapas nie dotyczy
        o['ix'] = dict(sw, GSPC=o['ix']['GSPC'])
        with mock.patch.object(zd, 'get_json', side_effect=gj), mock.patch.object(zd, 'NOW', now_ref[0].isoformat()):
            o2 = zd.build_indeksy({'EODHD_KEY': 'e', 'FMP_KEY': 'f'}, o, now=now_ref[0])
        g2 = o2['ix']['GSPC']
        self.assertEqual([(a, b) for a, b, _ in calls if b == 'GSPC'], [('eod', 'GSPC')], 'FMP w przerwie — raz zapas EODHD')
        self.assertEqual((g2['d'][-1][0], g2['fmp_bad_n'], g2.get('src'), g2.get('h+')), ('2026-10-13', 1, None, 1),
                         'sesja z zapasu; przerwa FMP i nauczona pora FMP zostają')
        self.assertTrue(any('GSPC — FMP bez sesji 2026-10-13' in n for n in zd.META['notes']))
        # bez klucza FMP — EODHD wszystkie 22 kody jak przed v273
        with mock.patch.object(zd, 'IX_PER_RUN', 99):   # cały plan, bez limitu na przebieg
            self.assertEqual(len(zd.ix_plan({}, self.T(2026, 10, 14, 23, 0), 99)), len(zd.IX_SYMBOLS))
            self.assertEqual(set(zd.ix_plan({}, self.T(2026, 10, 14, 23, 0), 99, {'GSPC', 'N225'})), {s for s, _, _ in zd.IX_SYMBOLS} - {'GSPC', 'N225'})
    def test_brak_sesji_ponowienie_i_nauka(self):
        v13 = 100.0 + datetime.date(2026, 10, 13).toordinal() % 7   # ta sama wartość co w udawanej sieci — bez „poprawki”
        rec = {'cc': 'jp', 'at': '2026-10-13T07:05:00+00:00', 'src': 'fmp', 'd': [['2026-10-13', v13]]}
        part = {'N225': dict(rec)}
        now_ref = [self.T(2026, 10, 14, 7, 5)]
        gj, calls = self._siec(now_ref, opoz={'N225': 1})   # dostawca ma sesję dopiero od 08:00
        N1 = mock.patch.object(zd, 'IX_FMP', (('N225', 'jp', 7, '%5EN225'),))
        with mock.patch.object(zd, 'get_json', side_effect=gj), mock.patch.object(zd, 'NOW', now_ref[0].isoformat()), N1:
            self.assertEqual(zd.ix_fmp('f', part, now_ref[0], []), 1)
        n = part['N225']
        self.assertEqual(n['brak'], ['2026-10-14', 1, '2026-10-14T07:05:00+00:00']); self.assertEqual(n['d'][-1][0], '2026-10-13')
        self.assertFalse(zd.ix_do_pobrania(7, n, self.T(2026, 10, 14, 7, 45), ponow=True), 'przed IX_PONOW_MIN')   # v278: 45 min
        self.assertFalse(zd.ix_do_pobrania(7, n, self.T(2026, 10, 14, 8, 5)), 'EODHD (bez ponowień) — nie')
        self.assertTrue(zd.ix_do_pobrania(7, n, self.T(2026, 10, 14, 8, 5), ponow=True))
        now_ref[0] = self.T(2026, 10, 14, 8, 5)
        with mock.patch.object(zd, 'get_json', side_effect=gj), mock.patch.object(zd, 'NOW', now_ref[0].isoformat()),                 mock.patch.object(zd, 'IX_FMP', (('N225', 'jp', 7, '%5EN225'),)):
            self.assertEqual(zd.ix_fmp('f', part, now_ref[0], []), 1)
        n2 = part['N225']
        self.assertEqual((n2['d'][-1][0], n2.get('brak'), n2['h+'], n2['h+n'], n2['h+d']), ('2026-10-14', None, 1, 0, '2026-10-14'),
                         'sesja przyszła godzinę później — nauka: pobieranie o 08:00')
        self.assertFalse(zd.ix_do_pobrania(7, n2, self.T(2026, 10, 14, 9, 30), ponow=True))
        self.assertTrue(zd.ix_do_pobrania(7, n2, self.T(2026, 10, 15, 8, 5), ponow=True)); self.assertFalse(zd.ix_do_pobrania(7, n2, self.T(2026, 10, 15, 7, 30), ponow=True))
        # święto: sesja nie przychodzi — najwyżej IX_PONOW ponowień, potem do następnego dnia; nie dowód dla nauki
        hol = {'cc': 'jp', 'at': '2026-10-15T08:05:00+00:00', 'src': 'fmp', 'd': [['2026-10-15', 1.0]], 'brak': ['2026-10-16', 1, '2026-10-16T08:05:00+00:00']}
        for i, (hh, ok) in enumerate(((9, True), (10, True), (11, True))):
            r = dict(hol, at=f'2026-10-16T{hh - 1:02d}:05:00+00:00', brak=['2026-10-16', i + 1, '2026-10-16T08:05:00+00:00'])
            self.assertEqual(zd.ix_do_pobrania(7, r, self.T(2026, 10, 16, hh, 5), ponow=True), ok)
        self.assertFalse(zd.ix_do_pobrania(7, dict(hol, at='2026-10-16T11:05:00+00:00', brak=['2026-10-16', 4, '2026-10-16T08:05:00+00:00']),
                                           self.T(2026, 10, 16, 12, 5), ponow=True), 'po IX_PONOW ponowieniach — do następnego dnia')
        nast = zd.ix_nauka({'brak': ['2026-10-16', 4, 'x']}, [], 7, [])
        self.assertEqual(nast, (0, 0, False), 'brak bez sesji (święto) — nic do nauki')
        # sesja przyszła nazajutrz (EODHD bez ponowień) — też dowód, gdy pierwsze pobranie było w dniu sesji o nauczonej godzinie
        self.assertEqual(zd.ix_nauka({}, [], 7, [('2026-10-16', '2026-10-16T07:20:00+00:00')]), (1, 0, True))
        self.assertEqual(zd.ix_nauka({}, [], 7, [('2026-10-16', '2026-10-16T09:20:00+00:00')]), (0, 0, False), 'pobranie o innej godzinie — nie dowód')
        self.assertEqual(zd.ix_nauka({}, [], 22, [('2026-10-16', '2026-10-17T00:20:00+00:00')]), (0, 0, False), 'pobranie nazajutrz — nie dowód')

    def test_zmiana_dostawcy_to_nie_poprawka(self):
        rec = {'cc': 'jp', 'at': '2026-10-06T07:21:13+00:00', 'd': [['2026-10-05', 69000.0], ['2026-10-06', 70683.98]]}   # EODHD, wstępne +0,13%
        ans = [{'date': '2026-10-06', 'price': 70592.11}, {'date': '2026-10-07', 'price': 70900.0}]
        part = {'N225': rec}
        N1 = (('N225', 'jp', 7, '%5EN225'),)
        with mock.patch.object(zd, 'get_json', lambda url, headers=None, timeout=30: ans), mock.patch.object(zd, 'NOW', '2026-10-07T07:10:00+00:00'),                 mock.patch.object(zd, 'IX_FMP', N1):
            self.assertEqual(zd.ix_fmp('f', part, self.T(2026, 10, 7, 7, 10), []), 1)
        n = part['N225']
        self.assertEqual(n['d'], [['2026-10-05', 69000.0], ['2026-10-06', 70592.11], ['2026-10-07', 70900.0]], 'wartość końcowa wydawcy zastępuje wstępną')
        self.assertEqual(n['src'], 'fmp'); self.assertNotIn('rew', n); self.assertNotIn('h+', n, 'różnica dwóch dostawców — nie dowód dla nauki')
        # ten sam dostawca: poprawka ostatniej sesji pobranej o nauczonej godzinie = dowód (jak w EODHD)
        ans2 = [{'date': '2026-10-07', 'price': 71000.0}, {'date': '2026-10-08', 'price': 71100.0}]
        with mock.patch.object(zd, 'get_json', lambda url, headers=None, timeout=30: ans2), mock.patch.object(zd, 'NOW', '2026-10-08T07:10:00+00:00'),                 mock.patch.object(zd, 'IX_FMP', N1):
            zd.ix_fmp('f', part, self.T(2026, 10, 8, 7, 10), [])
        self.assertEqual(part['N225']['rew'][-1][:3], ['2026-10-07', 70900.0, 71000.0]); self.assertEqual(part['N225']['h+'], 1)

    def test_kontrola_pusta_seria_z_przerwa_fmp(self):
        import importlib.util
        spec = importlib.util.spec_from_file_location('v273_k', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
        kk = importlib.util.module_from_spec(spec); spec.loader.exec_module(kk)
        o = kk.indeksy_ocena({'GSPC': {'fmp_bad_at': '2026-10-13T22:05:00+00:00', 'fmp_bad': 402}, 'DJI': {'d': [['2026-10-13', 1.0]]}},
                             datetime.datetime(2026, 10, 14, 6, 0, tzinfo=self.UTC))
        self.assertEqual(o['puste'], [('GSPC', '2026-10-13')])


class PrzypietyObrazV274(unittest.TestCase):
    """v274: każdy przepływ pracy na przypiętym obrazie ubuntu-24.04 — ubuntu-latest przechodzi na Ubuntu 26 od 19.10.2026 (nowy system bez
    gotowego Pythona 3.12, inny Chrome albo Node mogłyby zatrzymać automat bez niczyjej wiedzy); zmiana obrazu tylko świadomie."""

    def test_przepływy_przypiete(self):
        import glob
        root = os.path.dirname(os.path.abspath(__file__))
        pliki = sorted(glob.glob(os.path.join(root, '.github', 'workflows', '*.yml')))
        self.assertGreaterEqual(len(pliki), 6)
        for p in pliki:
            y = open(p, encoding='utf-8').read()
            self.assertNotIn('ubuntu-latest', y, os.path.basename(p))
            self.assertEqual(y.count('runs-on:'), y.count('runs-on: ubuntu-24.04'), os.path.basename(p))


# ===================== v275: CZĘŚĆ Z BŁĘDEM ZOSTAJE Z POPRZEDNIEGO PLIKU (instytucje.json, fred.json) =====================
class CzesciZZapasemV275(unittest.TestCase):
    """v275: źródło (seria), które w tym przebiegu zawiodło, zostaje z poprzedniego pliku z własną datą danych i czasem pobrania — nie znika
    do następnej budowy; META ok False i błąd jak dotąd; wszystkie zawiodły = wyjątek mimo poprzedniego pliku; bez poprzedniego — jak dotąd."""

    def setUp(self):
        zd.META['errors'].clear(); zd.META['ok'].clear()

    def test_instytucje(self):
        prev = {'at': '2026-10-07T01:00:00+00:00', 'part_at': {'tga': '2026-10-06T23:00:00+00:00'},
                'tga': {'asof': '2026-10-05', 'd': [['2026-10-05', 984046.0]]}, 'mof': {'asof': '2026-09-26', 'd': []}}
        def get_json(url, headers=None):
            if 'fiscaldata' in url: raise RuntimeError('timeout')
            if 'reverserepo' in url: return {'repo': {'operations': [{'operationDate': '2026-10-06', 'operationType': 'Reverse Repo', 'totalAmtAccepted': 1e6}]}}
            if 'soma' in url: return {'soma': {'summary': [{'asOfDate': '2026-10-01', 'total': '6.364e12'}]}}
            if 'ecb' in url: raise RuntimeError('503')
            raise AssertionError(url)
        with mock.patch.object(zd, 'get_json', get_json), mock.patch.object(zd, 'get_bytes', side_effect=RuntimeError('cp932')), \
                mock.patch.object(zd, 'NOW', '2026-10-07T02:10:00+00:00'), mock.patch.object(zd.time, 'sleep', lambda s: None):
            out = zd.build_instytucje(prev)
        self.assertEqual(out['tga'], prev['tga'], 'TGA zawiodło — poprzednia wersja z własną datą danych (05.10)')
        self.assertEqual(out['mof'], prev['mof'])
        self.assertEqual(out['part_at'], {'tga': '2026-10-06T23:00:00+00:00', 'rrp': '2026-10-07T02:10:00+00:00', 'soma': '2026-10-07T02:10:00+00:00',
                                          'mof': '2026-10-07T01:00:00+00:00'}, 'czas pobrania części (stary plik bez part_at — czas pliku)')
        self.assertNotIn('tgb', out, 'bez poprzedniej wersji — brak, nie zero')
        self.assertIs(zd.META['ok']['tga'], False); self.assertTrue(any(e.startswith('tga:') for e in zd.META['errors']))
        with mock.patch.object(zd, 'get_json', side_effect=RuntimeError('down')), mock.patch.object(zd, 'get_bytes', side_effect=RuntimeError('down')), \
                mock.patch.object(zd.time, 'sleep', lambda s: None):
            with self.assertRaises(RuntimeError):
                zd.build_instytucje(prev)   # żadne źródło — wyjątek mimo poprzedniego pliku (main zostawia go w całości)
        import inspect
        self.assertIn("save('instytucje', build_instytucje(prev_inst))", inspect.getsource(zd.main))

    def test_fred(self):
        prev = {'at': '2026-10-07T00:57:00+00:00', 'series': {'DTWEXBGS': {'asof': '2026-10-03', 'd': [['2026-10-03', 120.5]]}}}
        def get_json(url, headers=None):
            if 'series_id=DTWEXBGS' in url:
                raise RuntimeError('HTTP 500')
            return {'observations': [{'date': '2026-10-01', 'value': '5'}]}
        with mock.patch.object(zd, 'get_json', get_json), mock.patch.object(zd.time, 'sleep', lambda s: None), mock.patch.object(zd, 'NOW', '2026-10-07T02:10:00+00:00'):
            out = zd.build_fred('k', prev)
        self.assertEqual(out['series']['DTWEXBGS'], prev['series']['DTWEXBGS']); self.assertEqual(out['part_at']['DTWEXBGS'], '2026-10-07T00:57:00+00:00')
        self.assertEqual(out['part_at']['WALCL'], '2026-10-07T02:10:00+00:00'); self.assertEqual(len(out['series']), len(zd.FRED_SERIES))
        with mock.patch.object(zd, 'get_json', side_effect=RuntimeError('down')), mock.patch.object(zd.time, 'sleep', lambda s: None):
            with self.assertRaises(RuntimeError):
                zd.build_fred('k', prev)
        import inspect
        self.assertIn("save('fred', build_fred(fred_key, prev_fred))", inspect.getsource(zd.main))


# ===================== v276: KRYPTO — CZĘŚĆ Z WŁASNĄ DATĄ ZOSTAJE PRZY BŁĘDZIE =====================
class KryptoCzesciV276(unittest.TestCase):
    """v276: fng, mk, stabh, stabc (własna data/czas danych) przy błędzie z poprzedniego pliku z czasem pobrania; deriv i defi nie (strona
    podpisuje je czasem pliku); wszystkie zawiodły = wyjątek mimo poprzedniego pliku."""

    def setUp(self):
        zd.META['errors'].clear(); zd.META['ok'].clear()

    def test_czesci(self):
        prev = {'at': '2026-10-07T01:00:00+00:00', 'part_at': {'mk': '2026-10-07T00:59:00+00:00'},
                'deriv': {'n': 3}, 'defi': {'defi_market_cap': 9.0}, 'mk': {'asof': '2026-10-07T00:58:12', 'rows': [['BTC', 1.7e12]]},
                'fng': {'asof': '2026-10-06', 'd': [['2026-10-06', 40, 'Fear']]}, 'stabc': {'asof': '2026-10-07', 'rows': []}}
        def get_json(url, headers=None):
            if 'llama' in url or 'markets' in url or 'derivatives' in url or 'alternative' in url:
                raise RuntimeError('429')
            if 'defi' in url:
                return {'data': {'defi_market_cap': '1'}}
            raise AssertionError(url)
        with mock.patch.object(zd, 'get_json', get_json), mock.patch.object(zd, 'NOW', '2026-10-07T02:10:00+00:00'):
            out = zd.build_krypto('k', prev)
        self.assertEqual((out['mk'], out['fng'], out['stabc']), (prev['mk'], prev['fng'], prev['stabc']), 'własna data/czas — poprzednia wersja')
        self.assertNotIn('deriv', out, 'otwarte pozycje podpisane czasem pliku — bez starej liczby'); self.assertEqual(out['defi']['defi_market_cap'], 1.0)
        self.assertNotIn('stabh', out, 'bez poprzedniej wersji — brak, nie zero')
        self.assertEqual(out['part_at'], {'defi': '2026-10-07T02:10:00+00:00', 'mk': '2026-10-07T00:59:00+00:00', 'fng': '2026-10-07T01:00:00+00:00',
                                          'stabc': '2026-10-07T01:00:00+00:00'})
        self.assertIs(zd.META['ok']['krypto.mk'], False)
        with mock.patch.object(zd, 'get_json', side_effect=RuntimeError('down')):
            with self.assertRaises(RuntimeError):
                zd.build_krypto('k', prev)
        import inspect
        self.assertIn("save('krypto', build_krypto(cg_key, prev_kr))", inspect.getsource(zd.main))
        self.assertEqual(zd.KR_ZAPAS_CZESCI, ('fng', 'mk', 'stabh', 'stabc'))


# ===================== v277: KONTROLA — ROZBIEŻNOŚĆ KAPITALIZACJI ROZSTRZYGANA TRZECIM ŹRÓDŁEM =====================
class KapitalizacjaTrzecieV277(unittest.TestCase):
    """v277: przy ⚠️/❌ różnicy CoinGecko–CoinPaprika kontrola patrzy na CoinMarketCap z pliku strony — gdy oba źródła strony zgodne jak
    zwykle, odstaje źródło kontrolne (ℹ️, nie uwaga i nie błąd); gdy CoinMarketCap też odstaje — status bez zmian; różnica CMC w zgodnosc.csv."""

    def setUp(self):
        import importlib.util
        spec = importlib.util.spec_from_file_location('v277_k', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
        self.k = importlib.util.module_from_spec(spec); spec.loader.exec_module(self.k)
        import tempfile
        self.tmp = tempfile.mkdtemp()

    def test_rozstrzygniecie(self):
        k = self.k
        now = datetime.datetime(2026, 10, 7, 2, 9, tzinfo=datetime.timezone.utc)
        cmc = {'at': '2026-10-07T02:07:35+00:00', 'total_mcap': 2853707426510.2}
        d = k.cmc_roznica(cmc, 2864500000000.0, now)
        self.assertAlmostEqual(d, -0.377, places=3)   # 07.10 02:09: CoinMarketCap wobec CoinGecko
        self.assertIsNone(k.cmc_roznica(dict(cmc, at='2026-10-07T01:30:00+00:00'), 2.8645e12, now), 'plik sprzed 39 min — inna chwila rynku')
        self.assertIsNone(k.cmc_roznica({'at': 'x', 'total_mcap': 1.0}, 2.8645e12, now)); self.assertIsNone(k.cmc_roznica({}, 2.8645e12, now))
        rows = {'2026-10-0%d' % i: {'cap': 4.3} for i in range(1, 7)}
        st, opis = k.kapitalizacja_trzecie(rows, '⚠️', 'odchylenie od mediany 3.30 pkt proc. (progi 2 / 5)', d, '2026-10-07')
        self.assertEqual(st, 'ℹ️'); self.assertIn('odstaje źródło kontrolne (CoinPaprika)', opis); self.assertIn('bez normy — próg ±1.5%', opis)
        self.assertEqual(k.kapitalizacja_trzecie(rows, '❌', 'x', -2.4, '2026-10-07')[0], '❌', 'CoinMarketCap też odstaje — może się mylić strona')
        self.assertEqual(k.kapitalizacja_trzecie(rows, '✅', 'x', -2.4, '2026-10-07'), ('✅', 'x')); self.assertEqual(k.kapitalizacja_trzecie(rows, '⚠️', 'x', None, '2026-10-07'), ('⚠️', 'x'))
        # z normą (≥ 7 dni): zwykle CMC −1,9% wobec CoinGecko — dziś −2,1% = w normie (rozstrzygnięte); dziś −0,4% = poza normą (bez zmian)
        hist = {'2026-09-%02d' % i: {'cap': 4.3, 'cmc': -1.9} for i in range(20, 30)}
        self.assertEqual(k.kapitalizacja_trzecie(hist, '⚠️', 'x', -2.1, '2026-10-07')[0], 'ℹ️')
        self.assertEqual(k.kapitalizacja_trzecie(hist, '⚠️', 'x', -0.4, '2026-10-07')[0], '⚠️')
        p = os.path.join(self.tmp, 'zg.csv'); k.zgodnosc_zapisz(p, {'2026-10-07': {'cap': 7.627, 'cmc': -0.377}})
        self.assertEqual(k.zgodnosc_csv(p), {'2026-10-07': {'cap': 7.627, 'cmc': -0.377}})
        src = open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'), encoding='utf-8').read()
        self.assertIn("st, opis = kapitalizacja_trzecie(rows, st, opis, d_cmc, today)", src)
        self.assertLess(src.index("st, opis = kapitalizacja_trzecie("), src.index("    if st == '❌':\n        R['bledy'].append(f'kapitalizacja krypto:"), 'rozstrzygnięcie przed uwagą/błędem')


# ===================== v278: POPRAWKI PO PRZEGLĄDZIE v272–v273 =====================
class PoPrzegladzieV278(unittest.TestCase):
    """v278: FMP bez sesji → zapas EODHD raz (licznik ciągły, nieudane ponowienia się liczą); wypełnienie w święto to nie dowód; ponowienie
    po 45 min; dni poprzedniego dostawcy ('obce') nie są poprawkami; nazwa zmiennej nie jest kawałkiem klucza; kontrola — przestój drugiego
    dostawcy = ⚠️; notka indeksów bez „co drugi dzień”."""
    UTC = datetime.timezone.utc

    def T(self, *a):
        return datetime.datetime(*a, tzinfo=self.UTC)

    def setUp(self):
        zd.META['errors'].clear(); zd.META['notes'].clear()

    def _swiezy(self, now, dzien=None):
        d = (dzien or now.date()).isoformat()
        ix = {s: {'cc': c, 'at': now.isoformat(), 'd': [[d, 1.0 + i]]} for i, (s, c, _) in enumerate(zd.IX_SYMBOLS)}
        ix.update({s: {'cc': c, 'at': now.isoformat(), 'src': 'fmp', 'd': [[d, 50.0 + i]]} for i, (s, c, _, _) in enumerate(zd.IX_FMP)})
        ix['JTOPI'] = {'bad_at': now.isoformat(), 'bad_n': 3, 'bad': 'pusto'}
        return ix

    def test_fmp_bez_sesji_zapas_eodhd(self):
        calls = []
        def gj(url, headers=None, timeout=30):
            fmp = 'financialmodelingprep' in url
            calls.append(('fmp' if fmp else 'eod', url.split('symbol=')[1].split('&')[0] if fmp else url.split('/eod/')[1].split('.INDX')[0]))
            if fmp:   # FMP stoi na 12.10 (odpowiada 200, bez nowych sesji)
                return [{'date': '2026-10-12', 'price': 6700.0}]
            return [{'date': '2026-10-12', 'close': 6700.0}, {'date': '2026-10-13', 'close': 6750.0}]
        prev = {'ix': self._swiezy(self.T(2026, 10, 12, 23, 5), datetime.date(2026, 10, 12))}
        prev['ix']['GSPC']['d'] = [['2026-10-12', 6700.0]]
        keys = {'EODHD_KEY': 'e', 'FMP_KEY': 'f'}
        only = mock.patch.object(zd, 'IX_FMP', (('GSPC', 'us', 22, '%5EGSPC'),))
        eod_only = mock.patch.object(zd, 'IX_SYMBOLS', (('GSPC', 'us', 22),))
        o = prev
        with mock.patch.object(zd, 'get_json', side_effect=gj), only, eod_only:
            for hh, mm in ((22, 5), (22, 55), (23, 45), (0, 35), (1, 25)):   # pobranie + 3 ponowienia co ≥ 45 min, potem zapas
                now = self.T(2026, 10, 13 if hh >= 22 else 14, hh, mm)
                with mock.patch.object(zd, 'NOW', now.isoformat()):
                    o = zd.build_indeksy(keys, o, now=now)
        g = o['ix']['GSPC']
        self.assertEqual([c for c in calls], [('fmp', '%5EGSPC')] * 4 + [('eod', 'GSPC')], 'FMP: 1 + 3 ponowienia, potem raz EODHD')
        self.assertEqual((g['d'][-1], g.get('src'), g.get('brak')), (['2026-10-13', 6750.0], None, None), 'sesja z zapasu')
        self.assertTrue(any('GSPC — FMP bez sesji 2026-10-13 (pobrań bez niej: 4) — pobranie z zapasu' in n for n in zd.META['notes']), zd.META['notes'])

    def test_nieudane_ponowienie_liczy_sie_i_zapas_od_razu(self):
        rec = {'cc': 'us', 'at': '2026-10-13T22:05:00+00:00', 'src': 'fmp', 'd': [['2026-10-12', 1.0]], 'brak': ['2026-10-13', 1, '2026-10-13T22:05:00+00:00']}
        part = {'GSPC': dict(rec)}
        only = mock.patch.object(zd, 'IX_FMP', (('GSPC', 'us', 22, '%5EGSPC'),))
        with mock.patch.object(zd, 'get_json', side_effect=zd.urllib.error.URLError('timed out')), only:
            zle = set()
            self.assertEqual(zd.ix_fmp('f', part, self.T(2026, 10, 13, 22, 55), [], zle), 0)
        self.assertEqual(part['GSPC']['brak'], ['2026-10-13', 2, '2026-10-13T22:05:00+00:00'], 'nieudane ponowienie liczy się do limitu')
        wl = {s: {'cc': c, 'at': '2026-10-13T23:00:00+00:00', 'd': [['2026-10-13', 1.0]]} for s, c, _ in zd.IX_SYMBOLS if s not in ('GSPC', 'IXIC', 'DJI', 'N225', 'HSI')}
        wl['JTOPI'] = {'bad_at': '2026-10-13T16:05:00+00:00', 'bad_n': 4, 'bad': 'pusto'}
        pix = _v284_fmp_swieze(dict(wl, GSPC=part['GSPC']), '2026-10-13')
        self.assertEqual(zd._ix_zapas_wybor(pix, self.T(2026, 10, 13, 23, 50), {'d': '2026-10-13', 'n': 15}, None), (set(), {}), 'v284: przed 00:15 — bez zapasu')
        w, info = zd._ix_zapas_wybor(pix, self.T(2026, 10, 14, 0, 20), {'d': '2026-10-14', 'n': 0}, None)
        self.assertEqual((w, info), ({'GSPC'}, {'GSPC': ('2026-10-13', 2)}), 'po 00:15 — raz z zapasu (licznik braku do notatki)')
        po = dict(part['GSPC'], src=None, at='2026-10-14T00:20:00+00:00')
        self.assertEqual(zd._ix_zapas_wybor(dict(pix, GSPC=po), self.T(2026, 10, 14, 1, 20), {'d': '2026-10-14', 'n': 1}, None)[0], set(), 'zapas już próbował — nie drugi raz')
        self.assertFalse(zd.ix_do_pobrania(22, dict(po, brak=['2026-10-13', 5, 'x']), self.T(2026, 10, 14, 1, 30), ponow=True), 'FMP też nie ponawia (licznik ciągły)')
    def test_ponowienie_po_45_min_i_licznik_ciagly(self):
        rec = {'cc': 'jp', 'at': '2026-10-14T07:06:00+00:00', 'src': 'fmp', 'd': [['2026-10-13', 1.0]], 'brak': ['2026-10-14', 1, '2026-10-14T07:06:00+00:00']}
        self.assertTrue(zd.ix_do_pobrania(7, rec, self.T(2026, 10, 14, 8, 0, 30), ponow=True), 'przegląd: przebieg godzinę później — ponowienie (54,5 min)')
        self.assertEqual(zd.IX_PONOW_MIN, 45)
        # zapas EODHD bez sesji (święto) — licznik ciągły: FMP nie ponawia od nowa
        eod = lambda url, headers=None, timeout=30: [{'date': '2026-10-13', 'close': 1.0}]
        r = dict(rec, brak=['2026-10-14', 4, '2026-10-14T07:06:00+00:00'], at='2026-10-14T10:06:00+00:00')
        with mock.patch.object(zd, 'get_json', eod):
            o = zd.ix_fetch('N225', 'jp', 'k', r, self.T(2026, 10, 14, 11, 0), True)   # v290 (przegląd v285): krok zapasu — z wyboru, ze znacznikiem
        self.assertEqual((o.get('src'), o['brak'][:2], o.get('zap')), (None, ['2026-10-14', 5], '2026-10-14'), 'ta sama sesja — licznik ciągły przy zmianie dostawcy')
        self.assertFalse(zd.ix_do_pobrania(7, o, self.T(2026, 10, 14, 12, 0), ponow=True), 'FMP nie ponawia — limit wyczerpany')

    def test_wypelnienie_w_swieto_to_nie_dowod(self):
        rec = {'cc': 'cn', 'at': '2026-10-01T08:05:00+00:00', 'd': [['2026-09-30', 3800.0]], 'brak': ['2026-10-01', 1, '2026-10-01T08:05:00+00:00']}
        fil = lambda url, headers=None, timeout=30: [{'date': '2026-09-30', 'close': 3800.0}, {'date': '2026-10-01', 'close': 3800.0}]   # wypełnienie
        with mock.patch.object(zd, 'get_json', fil):
            o = zd.ix_fetch('SSEC', 'cn', 'k', rec, self.T(2026, 10, 2, 8, 5))
        self.assertNotIn('h+', o, 'przegląd: wiersz-wypełnienie w święto uczył +1 h')
        real = lambda url, headers=None, timeout=30: [{'date': '2026-09-30', 'close': 3800.0}, {'date': '2026-10-01', 'close': 3812.0}]
        with mock.patch.object(zd, 'get_json', real):
            o2 = zd.ix_fetch('SSEC', 'cn', 'k', rec, self.T(2026, 10, 2, 8, 5))
        self.assertEqual(o2['h+'], 1, 'prawdziwa spóźniona sesja (inne zamknięcie) — dowód jak dotąd')

    def test_obce_dni_to_nie_poprawka(self):
        # czwartek 15.10 z zapasu EODHD (src None), FMP w piątek jeszcze tylko do środy 14.10, w sobotę podaje czwartek o 0,10% wyżej
        rec = {'cc': 'us', 'at': '2026-10-15T23:10:00+00:00', 'd': [['2026-10-14', 6700.0], ['2026-10-15', 6750.0]]}
        part = {'GSPC': rec}
        only = mock.patch.object(zd, 'IX_FMP', (('GSPC', 'us', 22, '%5EGSPC'),))
        f1 = lambda url, headers=None, timeout=30: [{'date': '2026-10-13', 'price': 6690.0}, {'date': '2026-10-14', 'price': 6700.0}]
        with mock.patch.object(zd, 'get_json', f1), only, mock.patch.object(zd, 'NOW', '2026-10-16T22:05:00+00:00'):
            zd.ix_fmp('f', part, self.T(2026, 10, 16, 22, 5), [])
        g = part['GSPC']
        self.assertEqual((g['src'], g['obce'], g['d'][-1]), ('fmp', ['2026-10-15'], ['2026-10-15', 6750.0]), 'dzień EODHD zostaje, oznaczony jako obcy')
        f2 = lambda url, headers=None, timeout=30: [{'date': '2026-10-14', 'price': 6700.0}, {'date': '2026-10-15', 'price': 6756.75}, {'date': '2026-10-16', 'price': 6770.0}]
        g['at'] = '2026-10-16T22:05:00+00:00'
        with mock.patch.object(zd, 'get_json', f2), only, mock.patch.object(zd, 'NOW', '2026-10-17T00:05:00+00:00'):
            zd.ix_fmp('f', part, self.T(2026, 10, 17, 0, 5), [])
        g2 = part['GSPC']
        self.assertNotIn('rew', g2, 'przegląd: różnica dwóch dostawców zapisywała się jako poprawka FMP'); self.assertNotIn('obce', g2)
        self.assertEqual(g2['d'][-2:], [['2026-10-15', 6756.75], ['2026-10-16', 6770.0]])
        self.assertEqual(g2['h+'], 1, 'sesja 16.10 brakowała o 22:05 i przyszła później — prawdziwy dowód spóźnienia FMP (to nie 15.10 z zapasu)')

    def test_maskowanie_nazwy_zmiennej(self):
        s0, z0 = list(zd.SECRETS), list(zd.SECRETS_ZLE)
        try:
            with mock.patch.dict(os.environ, {'FMP_KEY': 'FMP_KEY = 0123456789abcdef'}, clear=False):
                self.assertEqual(zd.klucz('FMP_KEY'), '')
            self.assertEqual(zd.mask(zd.META['errors'][-1]).split(':')[0], 'Klucz FMP_KEY', 'przegląd: nazwa sekretu maskowana — „Klucz ***”')
            self.assertEqual(zd.mask('x 0123456789abcdef y'), 'x *** y')
        finally:
            zd.SECRETS[:] = s0; zd.SECRETS_ZLE[:] = z0

    def test_kontrola_drugi_dostawca_stoi(self):
        import importlib.util
        spec = importlib.util.spec_from_file_location('v278_k', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
        kk = importlib.util.module_from_spec(spec); spec.loader.exec_module(kk)
        ix = {s: {'d': [['2026-10-26', 1.0]]} for s, _, _ in zd.IX_SYMBOLS if s not in ('GSPC', 'IXIC', 'DJI', 'N225', 'HSI', 'JTOPI')}
        ix.update({s: {'src': 'fmp', 'd': [['2026-10-08', 1.0]]} for s in ('FTSE', 'GSPC', 'IXIC', 'DJI', 'N225', 'HSI')})
        o = kk.indeksy_ocena(ix, datetime.datetime(2026, 10, 27, 6, 20, tzinfo=self.UTC))
        self.assertEqual(o['grupy_stoja'], [('fmp', '2026-10-08', 6, 12)])
        u = kk.indeksy_uwagi(o)
        self.assertTrue(any('drugi dostawca indeksów (fmp, 6 serii) — najnowsza sesja 2026-10-08' in x for x in u), u)
        self.assertIn('drugi dostawca (fmp, 6 serii) stoi', kk.indeksy_wiersz(o)); self.assertIn('⚠️', kk.indeksy_wiersz(o))
        ix2 = dict(ix, **{s: {'src': 'fmp', 'd': [['2026-10-23', 1.0]]} for s in ('FTSE', 'GSPC', 'IXIC', 'DJI', 'N225', 'HSI')})
        self.assertEqual(kk.indeksy_ocena(ix2, datetime.datetime(2026, 10, 27, 6, 20, tzinfo=self.UTC))['grupy_stoja'], [], '1 dzień roboczy — norma')

    def test_notka_indeksow(self):
        h = open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'index.html'), encoding='utf-8').read()
        import re as _re
        v = _re.findall(r'"ix\.not":"((?:[^"\\]|\\.)*)"', h)
        self.assertEqual(len(v), 10)
        for x in v:
            self.assertIsNone(_re.search('co drugi dzień|every other day|jeden zweiten Tag|cada dos días|un jour sur deux|giorni alterni|dia sim, dia não|через день|每隔一天|1日おき', x), x[:80])


# ===================== v279: SAMOUCZENIE PORY PUBLIKACJI PRZEPŁYWÓW ETF =====================
class EtfPoraPublikacjiV279(unittest.TestCase):
    """v279: oczekiwany dzień danych, okno publikacji (domyślne i z obserwacji), tryb szybki (brak dnia w oknie), zapis obserwacji 'pub',
    połączenie w main() i w build_etf."""
    UTC = datetime.timezone.utc

    def T(self, *a):
        return datetime.datetime(*a, tzinfo=self.UTC)

    def test_oczekiwany_dzien(self):
        f = zd.etf_oczekiwany
        self.assertEqual(f(self.T(2026, 10, 7, 2, 0)).isoformat(), '2026-10-06', 'środa 02:00 — wtorek')
        self.assertEqual(f(self.T(2026, 10, 6, 21, 0)).isoformat(), '2026-10-06', 'wtorek po 20:00 — wtorek')
        self.assertEqual(f(self.T(2026, 10, 6, 19, 0)).isoformat(), '2026-10-05', 'wtorek przed 20:00 — poniedziałek')
        self.assertEqual(f(self.T(2026, 10, 12, 10, 0)).isoformat(), '2026-10-09', 'poniedziałek rano — piątek')
        self.assertEqual(f(self.T(2026, 10, 11, 12, 0)).isoformat(), '2026-10-09', 'niedziela — piątek')

    def test_okno(self):
        self.assertEqual(zd.etf_okno(None), (21 * 60, 30 * 60, 0))
        pub = {'btc': [['2026-09-%02d' % d, '2026-09-%02dT01:%02d:00+00:00' % (d + 1, 10 + d)] for d in range(14, 26)]}   # 25 h 24 min – 25 h 35 min
        od, do, n = zd.etf_okno(pub)
        self.assertEqual(n, 12); self.assertEqual((od, do), (1525 - 60, 1534 + 30), '10. centyl 1525 min (25 h 25 min), 90. centyl 1534 min')
        pub['eth'] = [['2026-09-20', 'zły czas'], ['2026-09-20', '2026-09-27T00:00:00+00:00']]   # zły i ponad 3 doby — pominięte
        self.assertEqual(zd.etf_okno(pub)[2], 12)
        wcz = {'btc': [['2026-09-%02d' % d, '2026-09-%02dT19:00:00+00:00' % d] for d in range(14, 26)]}   # 19:00 tego samego dnia
        self.assertEqual(zd.etf_okno(wcz)[0], 20 * 60, 'granica okna z danych: 20:00')

    def test_tryb_szybki(self):
        prev = {'assets': {'btc': {'asof': '2026-10-05'}, 'eth': {'asof': '2026-10-05'}, 'sol': {'asof': '2026-10-06'}, 'xrp': {'asof': '2026-10-06'}}}
        self.assertTrue(zd.etf_szybko(prev, self.T(2026, 10, 7, 2, 0)), '07.10 02:00 — BTC i ETH bez 06.10, w oknie domyślnym')
        self.assertFalse(zd.etf_szybko(prev, self.T(2026, 10, 7, 7, 0)), 'po oknie (06:00)')
        pelny = {'assets': {s: {'asof': '2026-10-06'} for s in ('btc', 'eth', 'sol', 'xrp')}}
        self.assertFalse(zd.etf_szybko(pelny, self.T(2026, 10, 7, 2, 0)), 'komplet — co godzinę')
        stale = {'assets': dict(pelny['assets'], xrp={'asof': '2026-09-30', 'stale': True})}
        self.assertFalse(zd.etf_szybko(stale, self.T(2026, 10, 7, 2, 0)), 'moneta „stale” nie wymusza trybu szybkiego')
        self.assertFalse(zd.etf_szybko(None, self.T(2026, 10, 7, 2, 0))); self.assertFalse(zd.etf_szybko({'assets': 'x'}, self.T(2026, 10, 7, 2, 0)))
        self.assertFalse(zd.etf_szybko({'assets': {'btc': {'day': [[1, 1.0]]}}}, self.T(2026, 10, 7, 2, 0)), 'moneta bez daty danych — bez trybu szybkiego')

    def test_pub(self):
        pa = {'btc': {'asof': '2026-10-05'}, 'eth': {'asof': '2026-10-05'}, 'sol': {'asof': '2026-10-06'}}
        a = {'btc': {'asof': '2026-10-06'}, 'eth': {'asof': '2026-10-06'}, 'sol': {'asof': '2026-10-06'}, 'xrp': {'asof': '2026-10-06'}}
        p = zd.etf_pub({'btc': [['2026-10-02', 'x']]}, pa, a, {'eth': pa['eth']}, '2026-10-07T02:10:00+00:00')
        self.assertEqual(p, {'btc': [['2026-10-02', 'x'], ['2026-10-06', '2026-10-07T02:10:00+00:00']]},
                         'tylko nowy dzień monety pobranej teraz; przeniesiona (eth), bez zmiany (sol) i bez poprzedniego wpisu (xrp) — bez obserwacji')
        long = zd.etf_pub({'btc': [[f'd{i}', 't'] for i in range(40)]}, pa, a, {}, 'T')
        self.assertEqual(len(long['btc']), zd.ETF_PUB_KEEP); self.assertEqual(long['btc'][-1], ['2026-10-06', 'T'])

    def test_polaczenie(self):
        import inspect
        src = inspect.getsource(zd.main)
        self.assertIn("etf_szybkie = etf_brakujace(prev_etf, _now_utc()) if (soso_key and prev_etf) else set()", src)   # v282
        self.assertIn("if soso_key and prev_etf and fresh(etf_pelne, 55) and not (etf_szybkie and not fresh(prev_etf, ETF_SZYBKO_MIN)):", src)
        b = inspect.getsource(zd.build_etf)
        self.assertIn("out['pub'] = etf_pub(prev.get('pub') if isinstance(prev, dict) else None, prev_assets, out['assets'], set(stare) | pominiete, NOW)", b)   # v282
        self.assertIn("out['okno'] = {s: dict(zip(('od', 'do', 'n'), etf_okno(out['pub'], s))) for s in ETF_SYMS}", b)   # v282: okno każdej monety


class EtfKapitalizacjeV280(unittest.TestCase):
    """v280: w trybie szybkim ETF kapitalizacje z poprzedniego pliku sprzed < 55 min (bez zapytania CoinGecko); starsze albo niepełne — pobranie."""

    def setUp(self):
        zd.META['errors'].clear(); zd.META['ok'].clear()

    def test_kapitalizacje(self):
        now = datetime.datetime(2026, 10, 7, 3, 0, tzinfo=datetime.timezone.utc)
        mc = {s: 1e12 + i for i, s in enumerate(zd.ETF_SYMS)}
        prev = {'at': '2026-10-07T02:50:00+00:00', 'mcap': mc, 'mcap_at': '2026-10-07T02:20:00+00:00', 'assets': {}}
        cg = []
        def gj(url, headers=None, timeout=30):
            if 'coingecko' in url:
                cg.append(url); return {i: {'usd_market_cap': 2e12} for i in zd.CG_IDS.values()}
            raise RuntimeError('SoSoValue offline')
        with mock.patch.object(zd, 'get_json', gj), mock.patch.object(zd, '_now_utc', lambda: now), mock.patch.object(zd, 'soso', side_effect=RuntimeError('offline')), \
                mock.patch.object(zd, 'NOW', now.isoformat()):
            with self.assertRaises(RuntimeError):   # SoSoValue offline — wyjątek jak dotąd; kapitalizacje sprawdzamy przed nim
                zd.build_etf('k', 'cg', prev)
        self.assertEqual(cg, [], 'kapitalizacje sprzed 40 min — bez zapytania CoinGecko'); self.assertEqual(zd.META['ok']['coingecko'], 'cached')
        old = dict(prev, mcap_at='2026-10-07T01:59:00+00:00')
        with mock.patch.object(zd, 'get_json', gj), mock.patch.object(zd, '_now_utc', lambda: now), mock.patch.object(zd, 'soso', side_effect=RuntimeError('offline')), \
                mock.patch.object(zd, 'NOW', now.isoformat()):
            with self.assertRaises(RuntimeError):
                zd.build_etf('k', 'cg', old)
        self.assertEqual(len(cg), 1, 'kapitalizacje sprzed 61 min — pobranie'); self.assertIs(zd.META['ok']['coingecko'], True)
        niep = dict(prev, mcap={'btc': 1e12})
        with mock.patch.object(zd, 'get_json', gj), mock.patch.object(zd, '_now_utc', lambda: now), mock.patch.object(zd, 'soso', side_effect=RuntimeError('offline')), \
                mock.patch.object(zd, 'NOW', now.isoformat()):
            with self.assertRaises(RuntimeError):
                zd.build_etf('k', 'cg', niep)
        self.assertEqual(len(cg), 2, 'niepełne kapitalizacje — pobranie')


# ===================== v281: POPRAWKI PO PRZEGLĄDZIE v274–v278 =====================
class PoPrzegladzieV281(unittest.TestCase):
    """v281: straż kluczy pomija kawałki-nazwy (publikacja nie staje); części krypto najwyżej 3 h, TRENDY datują 'mk' czasem części;
    zapas EODHD za FMP z limitu, z grupą wspólnej sesji i świętem; norma CMC tylko z dni ✅/ℹ️; stablecoiny według czasu części."""
    UTC = datetime.timezone.utc

    def T(self, *a):
        return datetime.datetime(*a, tzinfo=self.UTC)

    def setUp(self):
        zd.META['errors'].clear(); zd.META['notes'].clear()

    def _mod(self, name):
        import importlib.util
        spec = importlib.util.spec_from_file_location('v281_' + name, os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', name + '.py'))
        m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
        return m

    def test_straz_nazwa_sekretu(self):
        s = self._mod('straz_kluczy')
        import tempfile
        root = tempfile.mkdtemp(); os.makedirs(os.path.join(root, 'data'))
        with open(os.path.join(root, 'data', 'meta.json'), 'w', encoding='utf-8') as f:
            json.dump({'errors': ['Klucz TWELVEDATA_KEY: spacja albo znak sterujący …', 'brak TWELVEDATA_KEY', 'brak FRED_KEY']}, f)
        sek, _ = s.sekrety({'TWELVEDATA_KEY': 'TWELVEDATA_KEY = fakefake1234abcd', 'FRED_KEY': 'FRED_KEY: abcdef0123456789'})
        self.assertEqual(sorted(sek), ['FRED_KEY', 'FRED_KEY (kawałek 1)', 'TWELVEDATA_KEY', 'TWELVEDATA_KEY (kawałek 1)'])
        self.assertEqual((sek['TWELVEDATA_KEY (kawałek 1)'], sek['FRED_KEY (kawałek 1)']), (b'fakefake1234abcd', b'abcdef0123456789'))
        tr, _ = s.skanuj(sek, root)
        self.assertEqual(tr, [], 'przegląd v278: nazwa sekretu w meta.json przerywała każdą publikację')
        with open(os.path.join(root, 'data', 'x.json'), 'w', encoding='utf-8') as f:
            f.write('{"e": "apikey=fakefake1234abcd"}')
        self.assertEqual([a for a, _, _ in s.skanuj(sek, root)[0]], ['TWELVEDATA_KEY (kawałek 1)'], 'prawdziwy kawałek klucza nadal wykrywany')
        s0, z0 = list(zd.SECRETS), list(zd.SECRETS_ZLE)
        try:
            with mock.patch.dict(os.environ, {'FRED_KEY': 'FRED_KEY: abcdef0123456789'}, clear=False):
                self.assertEqual(zd.klucz('FRED_KEY'), '')
            self.assertTrue(zd.mask(zd.META['errors'][-1]).startswith('Klucz FRED_KEY: spacja'), 'nazwa z dwukropkiem nie jest maskowana')
            os.remove(os.path.join(root, 'data', 'x.json'))
            with open(os.path.join(root, 'data', 'meta.json'), 'w', encoding='utf-8') as f:
                json.dump({'errors': [zd.mask(zd.META['errors'][-1]), 'brak FRED_KEY']}, f)
            self.assertEqual(s.skanuj(s.sekrety({'FRED_KEY': 'FRED_KEY: abcdef0123456789'})[0], root)[0], [], 'straż: „FRED_KEY:” to nazwa, nie kawałek klucza')
        finally:
            zd.SECRETS[:] = s0; zd.SECRETS_ZLE[:] = z0

    def test_krypto_najwyzej_3h_i_trendy(self):
        prev = {'at': '2026-10-10T07:05:00+00:00', 'part_at': {'mk': '2026-10-10T05:30:00+00:00', 'fng': '2026-10-10T07:05:00+00:00'},
                'mk': {'asof': '2026-10-10T05:29:00', 'cols': ['sym', 'mcap', 'p24h', 'p7d', 'p30d', 'p1y'], 'rows': [['BTC', 2e12, 1.0, 12.5, 20.0, 50.0]]},
                'fng': {'asof': '2026-10-10', 'd': [['2026-10-10', 40, 'Fear']]}}
        def gj(url, headers=None, timeout=30):
            raise RuntimeError('HTTP 401') if 'alternative' not in url else RuntimeError('HTTP 500')
        with mock.patch.object(zd, 'get_json', side_effect=gj), mock.patch.object(zd, 'NOW', '2026-10-10T08:05:00+00:00'):
            with self.assertRaises(RuntimeError):   # żadna część się nie udała — wyjątek jak dotąd
                zd.build_krypto('k', prev)
        def gj2(url, headers=None, timeout=30):
            if 'decentralized_finance' in url:
                return {'data': {'defi_market_cap': '1'}}
            raise RuntimeError('HTTP 401')
        with mock.patch.object(zd, 'get_json', side_effect=gj2), mock.patch.object(zd, 'NOW', '2026-10-10T08:05:00+00:00'):
            out = zd.build_krypto('k', prev)
        self.assertEqual((out['mk'], out['part_at']['mk']), (prev['mk'], '2026-10-10T05:30:00+00:00'), '2 h 35 min — zostaje')
        with mock.patch.object(zd, 'get_json', side_effect=gj2), mock.patch.object(zd, 'NOW', '2026-10-10T08:31:00+00:00'):
            out2 = zd.build_krypto('k', prev)
        self.assertNotIn('mk', out2, 'przegląd v276: ponad 3 h — znika („—”), nie udaje świeżej'); self.assertIn('fng', out2)
        rows, _ = zd._tr_prices({'krypto': dict(out, at='2026-10-12T08:05:00+00:00', part_at={'mk': '2026-10-10T05:30:00+00:00'})})
        self.assertEqual([r['date'] for r in rows if r.get('g') == 'cr'], ['2026-10-10'], 'TRENDY: data pobrania części, nie czas pliku')

    def test_zapas_limit_grupa_swieto(self):
        # v284: bez grup i bez zgadywania świąt — każdy indeks FMP bez sesji po 135 min raz z zapasu, z limitu, najdłużej czekający najpierw
        now = self.T(2026, 11, 27, 1, 30)
        wl = {s: {'cc': c, 'at': '2026-11-26T23:00:00+00:00', 'd': [['2026-11-26', 1.0]]} for s, c, _ in zd.IX_SYMBOLS if s not in ('GSPC', 'IXIC', 'DJI', 'N225', 'HSI')}
        wl['JTOPI'] = {'bad_at': '2026-11-25T16:05:00+00:00', 'bad_n': 4, 'bad': 'pusto'}
        def us(d, at='2026-11-26T22:05:00+00:00', src='fmp'):
            return {'cc': 'us', 'src': src, 'at': at, 'd': [[d, 1.0]]}
        pix = _v284_fmp_swieze(dict(wl, GSPC=us('2026-11-24'), IXIC=us('2026-11-25'), DJI=us('2026-11-25')), '2026-11-26')
        self.assertEqual(zd._ix_zapas_wybor(pix, now, {'d': '2026-11-27', 'n': 0}, None)[0], {'GSPC', 'IXIC'}, 'wolne 2 (v285: rezerwa 1) — najdłużej czekający i kolejność')
        self.assertEqual(zd._ix_zapas_wybor(pix, now, {'d': '2026-11-27', 'n': 1}, None)[0], {'GSPC'}, 'wolne 1 — najdłużej czekający (24.11)')
        self.assertEqual(zd._ix_zapas_wybor(pix, now, {'d': '2026-11-27', 'n': 3}, None)[0], set(), 'bez wolnego limitu — później')
        self.assertEqual(zd._ix_zapas_wybor(pix, now, {'d': '2026-11-27', 'n': 0}, '2026-11-27')[0], set(), 'blokada limitu')
        swieto = dict(pix, GSPC=us('2026-11-25', at='2026-11-27T00:20:00+00:00', src=None))   # zapas już pytał o 26.11 — bez sesji (święto)
        self.assertEqual(zd._ix_zapas_wybor(swieto, now, {'d': '2026-11-27', 'n': 0}, None)[0], {'IXIC', 'DJI'}, 'raz na sesję — GSPC już nie')
        import inspect
        self.assertIn("wymus, info = _ix_zapas_wybor(pix, now, prev.get('ix_calls'), prev.get('ix_quota'))", inspect.getsource(zd.build_indeksy))
    def test_kontrola_norma_cmc_i_stablecoiny(self):
        kk = self._mod('kontrola')
        src = open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'), encoding='utf-8').read()
        self.assertIn("if d_cmc is not None and st in ('✅', 'ℹ️'):", src)
        i, j = src.index("st, med, n, opis = kapitalizacja(rows, gap, today)"), src.index("rows[today]['cmc'] = d_cmc")
        self.assertLess(i, j, 'zapis różnicy CMC dopiero po ocenie głównej reguły')
        krypto = {'at': '2026-10-20T08:05:00+00:00', 'part_at': {'stabh': '2026-10-06T08:05:00+00:00'}, 'stabh': {'asof': '2026-10-06', 'cur': 300.0e9}}
        cmc = {'at': '2026-10-20T08:05:00+00:00', 'stable_mcap': 307.5e9}
        s = kk.stab_porownanie(krypto, cmc)
        self.assertIsNone(s['roznica_pct'], 'przegląd v276: historia sprzed 2 tygodni nie jest „z tej samej chwili”'); self.assertGreater(s['odstep_h'], 300)
        krypto2 = dict(krypto, part_at={'stabh': '2026-10-20T07:05:00+00:00'})
        self.assertIsNotNone(kk.stab_porownanie(krypto2, cmc)['roznica_pct'])


# ===================== v282: POPRAWKI PO PRZEGLĄDZIE v279–v281 =====================
class PoPrzegladzieV282(unittest.TestCase):
    """v282: tryb szybki ETF — okno każdej monety, tylko brakujące monety, niezgodna lista funduszy najwyżej co 55 min, pełna budowa od
    'pelne_at', próg 4 min; zapas EODHD dla błędów/przerw FMP przez limit; święto rozpoznane mimo wiersza-wypełnienia."""
    UTC = datetime.timezone.utc

    def T(self, *a):
        return datetime.datetime(*a, tzinfo=self.UTC)

    def setUp(self):
        zd.META['errors'].clear(); zd.META['notes'].clear(); zd.META['ok'].clear()

    def test_okno_kazdej_monety_i_brakujace(self):
        late = [['2026-09-%02d' % d, '2026-09-%02dT13:%02d:00+00:00' % (d + 1, 10 + d)] for d in range(14, 26)]   # BTC: 37 h po północy dnia danych
        early = [['2026-09-%02d' % d, '2026-09-%02dT00:%02d:00+00:00' % (d + 1, 10 + d)] for d in range(14, 26)]   # SOL: 24 h
        pub = {'btc': late, 'sol': early}
        ob, os_ = zd.etf_okno(pub, 'btc'), zd.etf_okno(pub, 'sol')
        self.assertTrue(ob[0] > 30 * 60 and os_[1] < 26 * 60, (ob, os_))
        self.assertEqual(zd.etf_okno(pub, 'xrp')[2], 24, 'moneta bez własnych obserwacji — okno ze wszystkich')
        prev = {'pub': pub, 'assets': {'btc': {'asof': '2026-10-05'}, 'eth': {'asof': '2026-10-06'}, 'sol': {'asof': '2026-10-05'}, 'xrp': {'asof': '2026-10-06'}}}
        self.assertEqual(zd.etf_brakujace(prev, self.T(2026, 10, 7, 0, 30)), {'sol'}, 'o 00:30 tylko SOL w swoim oknie — BTC poza swoim')
        self.assertEqual(zd.etf_brakujace(prev, self.T(2026, 10, 7, 13, 30)), {'btc'}, 'o 13:30 tylko BTC')
        self.assertFalse(zd.etf_szybko(prev, self.T(2026, 10, 7, 18, 0))); self.assertEqual(zd.ETF_SZYBKO_MIN, 4)
        bardzo = {'btc': [['2026-09-%02d' % d, '2026-09-%02dT17:00:00+00:00' % (d + 1)] for d in range(14, 26)]}   # 41 h — po granicy
        od, do, _ = zd.etf_okno(bardzo, 'btc')
        self.assertTrue(od > do, 'publikacje po granicy — okno puste (co godzinę), nie przyklejone do 16:00')

    def test_tylko_brakujace_monety(self):
        def pa(s, asof):
            return {'sym': s.upper(), 'asof': asof, 'day': [[1, 1.0]], 'd1': 1.0, 'cum': 5.0, 'aum': 10.0, 'funds': [], 'funds_at': '2026-10-07T02:00:00+00:00'}
        prev = {'at': '2026-10-07T02:50:00+00:00', 'pelne_at': '2026-10-07T02:30:00+00:00', 'mcap': {s: 1e12 for s in zd.ETF_SYMS}, 'mcap_at': '2026-10-07T02:30:00+00:00',
                'assets': {'btc': pa('btc', '2026-10-05'), 'eth': pa('eth', '2026-10-05'), 'sol': pa('sol', '2026-10-06'), 'xrp': pa('xrp', '2026-10-06')}, 'pub': {}}
        pytane = []
        def coin(out, s, key, prev_day=None, prev_a=None):
            pytane.append(s); a = dict(prev_a, asof='2026-10-06'); out['assets'][s] = a; out['asof'] = max(out['asof'], '2026-10-06')
        now = self.T(2026, 10, 7, 3, 0)
        with mock.patch.object(zd, '_etf_coin', coin), mock.patch.object(zd, '_now_utc', lambda: now), mock.patch.object(zd, 'NOW', now.isoformat()), \
                mock.patch.object(zd, '_etf_hk', lambda out, key, ph: ()):
            o = zd.build_etf('k', 'cg', prev, {'btc', 'eth'})
        self.assertEqual(sorted(pytane), ['btc', 'eth'], 'tryb szybki — tylko monety bez oczekiwanego dnia')
        self.assertEqual(o['assets']['sol'], prev['assets']['sol']); self.assertEqual(o['pelne_at'], '2026-10-07T02:30:00+00:00', 'szybka budowa nie jest pełną')
        self.assertEqual(sorted(o['pub']), ['btc', 'eth'], 'nowy dzień BTC i ETH zapisany; przeniesione — bez obserwacji')
        self.assertEqual(set(o['okno']), set(zd.ETF_SYMS))
        with mock.patch.object(zd, '_etf_coin', coin), mock.patch.object(zd, '_now_utc', lambda: now), mock.patch.object(zd, 'NOW', now.isoformat()), \
                mock.patch.object(zd, '_etf_hk', lambda out, key, ph: ()):
            pytane.clear(); o2 = zd.build_etf('k', 'cg', prev)
        self.assertEqual(sorted(pytane), sorted(zd.ETF_SYMS)); self.assertEqual(o2['pelne_at'], now.isoformat())
        import inspect
        src = inspect.getsource(zd.main)
        self.assertIn("etf_tylko = etf_szybkie if (prev_etf and fresh(etf_pelne, 55)) else None", src)

    def test_lista_funduszy_niezgodna_najwyzej_co_55_min(self):
        now = self.T(2026, 10, 7, 3, 19)
        rows = [{'date': '2026-10-05', 'total_net_inflow': -50.76e6, 'total_net_assets': 1e10, 'cum_net_inflow': 1e10}]
        prev_a = {'asof': '2026-10-05', 'd1': -50.76, 'cum': 1e4, 'day': [[1, 1.0]], 'funds': [{'t': 'ETHA', 'aum': 1.0, 'd1': -31.88}],
                  'funds_try': '2026-10-07T03:01:00+00:00'}
        calls = []
        def soso(path, key, _retry=True):
            calls.append(path)
            return rows if 'summary-history' in path else ([{'ticker': 'ETHA', 'name': 'x'}] if path.startswith('/etfs?') else {'net_inflow': -31.88e6, 'net_assets': 1e9})
        out = {'asof': '', 'mcap': {'eth': 1e11}, 'assets': {}}
        with mock.patch.object(zd, 'soso', soso), mock.patch.object(zd, '_now_utc', lambda: now), mock.patch.object(zd, 'NOW', now.isoformat()):
            zd._etf_coin(out, 'eth', 'k', prev_a['day'], prev_a=prev_a)
        self.assertEqual(len(calls), 1, 'przegląd: niezgodna lista pobierana w każdej budowie (12 zapytań) — teraz po 55 min')
        self.assertEqual(out['assets']['eth']['funds_try'], '2026-10-07T03:01:00+00:00'); self.assertNotIn('funds_at', out['assets']['eth'])
        later = self.T(2026, 10, 7, 4, 0)
        calls.clear(); out = {'asof': '', 'mcap': {'eth': 1e11}, 'assets': {}}
        with mock.patch.object(zd, 'soso', soso), mock.patch.object(zd, '_now_utc', lambda: later), mock.patch.object(zd, 'NOW', later.isoformat()):
            zd._etf_coin(out, 'eth', 'k', prev_a['day'], prev_a=prev_a)
        self.assertEqual(len(calls), 3, 'po 55 min — lista znowu'); self.assertEqual(out['assets']['eth']['funds_try'], later.isoformat())

    def test_zapas_dla_bledow_fmp_przez_limit(self):
        wl = {s: {'cc': c, 'at': '2026-10-12T23:00:00+00:00', 'd': [['2026-10-12', 1.0]]} for s, c, _ in zd.IX_SYMBOLS if s not in ('GSPC', 'IXIC', 'DJI', 'N225', 'HSI')}
        wl['JTOPI'] = {'bad_at': '2026-10-12T16:05:00+00:00', 'bad_n': 4, 'bad': 'pusto'}
        pix = _v284_fmp_swieze(dict(wl, N225={'cc': 'jp', 'src': 'fmp', 'at': '2026-10-12T07:05:00+00:00', 'd': [['2026-10-12', 1.0]]}), '2026-10-13')   # FMP zawodzi 13.10
        self.assertEqual(zd._ix_zapas_wybor(pix, self.T(2026, 10, 13, 7, 10), {'d': '2026-10-13', 'n': 2}, None)[0], set(), 'przed 09:15 — FMP jeszcze ma czas')
        self.assertEqual(zd._ix_zapas_wybor(pix, self.T(2026, 10, 13, 9, 20), {'d': '2026-10-13', 'n': 3}, None)[0], set(),
                         'przegląd v281: 17 własnych należnych, limit 20 − 3 — bez zapasu (własne nie po północy)')
        self.assertEqual(zd._ix_zapas_wybor(pix, self.T(2026, 10, 13, 9, 20), {'d': '2026-10-13', 'n': 1}, None)[0], {'N225'}, 'v285: rezerwa 1')
    def test_swieto_z_wypelnieniem(self):
        now = self.T(2026, 11, 27, 2, 0)
        wl = {s: {'cc': c, 'at': '2026-11-26T23:00:00+00:00', 'd': [['2026-11-26', 1.0]]} for s, c, _ in zd.IX_SYMBOLS if s not in ('GSPC', 'IXIC', 'DJI', 'N225', 'HSI')}
        wl['JTOPI'] = {'bad_at': '2026-11-25T16:05:00+00:00', 'bad_n': 4, 'bad': 'pusto'}
        wyp = {'cc': 'us', 'at': '2026-11-27T00:20:00+00:00', 'd': [['2026-11-25', 6812.0], ['2026-11-26', 6812.0]]}   # zapas oddał wypełnienie (święto)
        pix = _v284_fmp_swieze(dict(wl, GSPC=wyp, IXIC=dict(wyp), DJI=dict(wyp)), '2026-11-26')
        self.assertEqual(zd._ix_zapas_wybor(pix, now, {'d': '2026-11-27', 'n': 3}, None)[0], set(), 'v284: wypełnienie z zapasu — sesji nie ma, ale zapas już próbował: bez drugiego zapytania')


# ===================== v283: POPRAWKI PO PRZEGLĄDZIE v282 =====================
class PoPrzegladzieV283(unittest.TestCase):
    """v283: zaległy własny indeks liczy się podwójnie w limicie zapasu; brak sesji w zapasie = święto dopiero po późnym sprawdzeniu, zapas
    może ponowić; błąd jednej monety w szybkiej budowie ETF nie wywraca całego źródła."""
    UTC = datetime.timezone.utc

    def T(self, *a):
        return datetime.datetime(*a, tzinfo=self.UTC)

    def setUp(self):
        zd.META['errors'].clear(); zd.META['notes'].clear(); zd.META['ok'].clear()

    def _wl(self, at, d):
        wl = {s: {'cc': c, 'at': at, 'd': [[d, 1.0]]} for s, c, _ in zd.IX_SYMBOLS if s not in ('GSPC', 'IXIC', 'DJI', 'N225', 'HSI')}
        wl['JTOPI'] = {'bad_at': at, 'bad_n': 4, 'bad': 'pusto'}
        return wl

    def test_zalegle_wlasne_liczone_podwojnie(self):
        now = self.T(2026, 10, 8, 0, 13)
        pix = self._wl('2026-10-07T18:58:00+00:00', '2026-10-07')
        for s in ('GSPTSE', 'BVSP', 'MXX', 'WIG20'):   # sesja 07.10 jeszcze nie pobrana (jak na żywo 07.10 rano)
            pix[s] = {'cc': 'x', 'at': '2026-10-06T23:00:00+00:00', 'd': [['2026-10-06', 1.0]]}
        pix['N225'] = {'cc': 'jp', 'src': 'fmp', 'at': '2026-10-07T07:05:00+00:00', 'd': [['2026-10-06', 1.0]]}
        _v284_fmp_swieze(pix, '2026-10-07')
        self.assertEqual(zd._ix_zapas_wybor(pix, now, {'d': '2026-10-08', 'n': 0}, None), (set(), {}),
                         'przegląd v282: 17 własnych + 4 zaległe = 21 > 20 — bez zapasu (zaległe nie znów po północy)')
        jt = dict(pix, **{s: {'cc': 'x', 'at': '2026-10-07T23:00:00+00:00', 'd': [['2026-10-07', 1.0]]} for s in ('GSPTSE', 'BVSP', 'MXX', 'WIG20')})
        jt['JTOPI'] = {'bad_at': '2026-10-01T17:05:00+00:00', 'bad_n': 4, 'bad': 'pusto'}   # przerwa kończy się 08.10 17:05, nigdy nie pobrany
        self.assertEqual(zd._ix_zapas_wybor(jt, now, {'d': '2026-10-08', 'n': 0}, None)[0], {'N225'}, 'przegląd v283: JTOPI bez „at” liczony raz')
    def test_swieto_dopiero_po_poznym_sprawdzeniu(self):
        # v284: zamiast reguł świąt — pobranie z zapasu niczego nie uczy, a nauczona pora FMP zostaje (przegląd v283: pora z zapasu przechodziła na FMP)
        rec = {'cc': 'us', 'at': '2026-10-13T22:05:00+00:00', 'src': 'fmp', 'd': [['2026-10-12', 1.0]], 'h+': 1, 'h+n': 3,
               'brak': ['2026-10-13', 4, '2026-10-13T22:05:00+00:00']}
        eod = [{'date': '2026-10-12', 'close': 1.0}, {'date': '2026-10-13', 'close': 2.0}]
        with mock.patch.object(zd, 'get_json', lambda url, headers=None, timeout=30: eod):
            o = zd.ix_fetch('GSPC', 'us', 'k', rec, self.T(2026, 10, 14, 0, 20), True)   # v285: z zapasu = wybór _ix_zapas_wybor
        self.assertEqual((o.get('src'), o['d'][-1][0], o.get('h+'), o.get('h+n')), (None, '2026-10-13', 1, 3), 'zapas: bez nauki, pora FMP bez zmian')
        fmp = [{'date': '2026-10-13', 'price': 2.0}, {'date': '2026-10-14', 'price': 3.0}]
        with mock.patch.object(zd, 'get_json', lambda url, headers=None, timeout=30: fmp), \
                mock.patch.object(zd, 'IX_FMP', (('GSPC', 'us', 22, '%5EGSPC'),)), mock.patch.object(zd, 'NOW', '2026-10-14T23:05:00+00:00'):
            part = {'GSPC': o}
            zd.ix_fmp('f', part, self.T(2026, 10, 14, 23, 5), [])
        self.assertEqual((part['GSPC']['src'], part['GSPC'].get('h+')), ('fmp', 1), 'powrót do FMP — nauczona pora zostaje (bez dowodu ze zmiany dostawcy)')
    def test_etf_szybka_budowa_blad_jednej_monety(self):
        def pa(s, asof):
            return {'sym': s.upper(), 'asof': asof, 'day': [[1, 1.0]], 'd1': 1.0, 'cum': 5.0, 'aum': 10.0, 'funds': [], 'funds_at': '2026-10-07T02:00:00+00:00'}
        prev = {'at': '2026-10-07T02:50:00+00:00', 'pelne_at': '2026-10-07T02:30:00+00:00', 'mcap': {s: 1e12 for s in zd.ETF_SYMS}, 'mcap_at': '2026-10-07T02:30:00+00:00',
                'assets': {'btc': pa('btc', '2026-10-05'), 'eth': pa('eth', '2026-10-06'), 'sol': pa('sol', '2026-10-06'), 'xrp': pa('xrp', '2026-10-06')}, 'pub': {}}
