def _v284_fmp_swieze(pix, d, at='2026-10-13T23:30:00+00:00'):
    """v284 (testy): pozostałe indeksy FMP z sesją d (wybór zapasu ich nie dotyczy)."""
    for s, cc in (('GSPC', 'us'), ('IXIC', 'us'), ('DJI', 'us'), ('N225', 'jp'), ('HSI', 'hk')):
        pix.setdefault(s, {'cc': cc, 'src': 'fmp', 'at': at, 'd': [[d, 1.0]]})
    return pix


# ===================== v285: POPRAWKI PO PRZEGLĄDZIE v284 =====================
class PoPrzegladzieV285(unittest.TestCase):
    """v285: znacznik 'zap' — zapas raz na sesję mimo ponowienia FMP; rezerwa 1 zapytania limitu; bez klucza FMP pięć indeksów FMP uczy się
    pory od EODHD; notatka bez „pobrań bez niej: 0”."""
    UTC = datetime.timezone.utc

    def T(self, *a):
        return datetime.datetime(*a, tzinfo=self.UTC)

    def setUp(self):
        zd.META['errors'].clear(); zd.META['notes'].clear()

    def test_zapas_raz_na_sesje_mimo_ponowienia_fmp(self):
        rec = {'cc': 'jp', 'at': '2026-11-03T06:05:00+00:00', 'src': 'fmp', 'd': [['2026-11-02', 1.0]]}
        eod = [{'date': '2026-11-02', 'close': 1.0}]   # święto w Japonii — zapas też bez sesji 03.11
        with mock.patch.object(zd, 'get_json', lambda url, headers=None, timeout=30: eod):
            o = zd.ix_fetch('N225', 'jp', 'k', rec, self.T(2026, 11, 3, 9, 20), True)
        self.assertEqual((o['zap'], o.get('src')), ('2026-11-03', None))
        fmp = [{'date': '2026-11-02', 'price': 1.0}]
        with mock.patch.object(zd, 'get_json', lambda url, headers=None, timeout=30: fmp), mock.patch.object(zd, 'IX_FMP', (('N225', 'jp', 7, '%5EN225'),)), \
                mock.patch.object(zd, 'NOW', '2026-11-03T10:20:00+00:00'):
            part = {'N225': dict(o, brak=['2026-11-03', 2, '2026-11-03T07:05:00+00:00'], at='2026-11-03T09:20:00+00:00')}
            zd.ix_fmp('f', part, self.T(2026, 11, 3, 10, 20), [])
        p = part['N225']
        self.assertEqual((p['src'], p['zap']), ('fmp', '2026-11-03'), 'ponowienie FMP zmienia src — znacznik zostaje')
        wl = {s: {'cc': c, 'at': '2026-11-03T06:00:00+00:00', 'd': [['2026-11-02', 1.0]]} for s, c, _ in zd.IX_SYMBOLS if s not in ('GSPC', 'IXIC', 'DJI', 'N225', 'HSI')}
        wl['JTOPI'] = {'bad_at': '2026-11-02T16:05:00+00:00', 'bad_n': 4, 'bad': 'pusto'}
        pix = _v284_fmp_swieze(dict(wl, N225=p), '2026-11-03')
        self.assertEqual(zd._ix_zapas_wybor(pix, self.T(2026, 11, 3, 11, 20), {'d': '2026-11-03', 'n': 1}, None)[0], set(),
                         'przegląd v284: drugi zapas tej samej sesji (cały wolny limit dnia) — już nie')

    def test_bez_klucza_fmp_n225_uczy_sie_od_eodhd(self):
        rec = {'cc': 'jp', 'at': '2026-10-06T07:21:13+00:00', 'd': [['2026-10-05', 69946.8594], ['2026-10-06', 70777.2891]]}
        eod = [{'date': '2026-10-05', 'close': 69946.86}, {'date': '2026-10-06', 'close': 70683.98}, {'date': '2026-10-07', 'close': 71000.0}]
        with mock.patch.object(zd, 'get_json', lambda url, headers=None, timeout=30: eod):
            o = zd.ix_fetch('N225', 'jp', 'k', rec, self.T(2026, 10, 7, 7, 30))
        self.assertEqual((o['h+'], o['h+n']), (1, 0), 'przegląd v284: bez klucza FMP EODHD jest głównym — nauka pory jak przed v273')
        self.assertNotIn('zap', o)
        import inspect
        self.assertIn("ix_fetch(sym, cc, key, part.get(sym), now, sym in wymus)", inspect.getsource(zd.ix_part))
        self.assertEqual(zd.IX_ZAPAS_REZERWA, 1)

    def test_notatka_bez_zera(self):
        now = self.T(2026, 10, 14, 0, 20)
        calls = []
        def gj(url, headers=None, timeout=30):
            calls.append(url)
            if 'financialmodelingprep' in url:
                raise zd.urllib.error.HTTPError('u', 503, 'Unavailable', {}, None)
            return [{'date': '2026-10-12', 'close': 1.0}, {'date': '2026-10-13', 'close': 1.5}]   # różne zamknięcia — 1,0 dwa razy byłoby wierszem-wypełnieniem (święto)
        wl = {s: {'cc': c, 'at': '2026-10-14T00:10:00+00:00', 'd': [['2026-10-13', 1.0]]} for s, c, _ in zd.IX_SYMBOLS if s not in ('GSPC', 'IXIC', 'DJI', 'N225', 'HSI')}
        wl['JTOPI'] = {'bad_at': '2026-10-13T16:05:00+00:00', 'bad_n': 4, 'bad': 'pusto'}
        ix = _v284_fmp_swieze(dict(wl), '2026-10-13')
        ix['GSPC'] = {'cc': 'us', 'src': 'fmp', 'at': '2026-10-12T22:05:00+00:00', 'd': [['2026-10-12', 1.0]]}
        with mock.patch.object(zd, 'get_json', side_effect=gj), mock.patch.object(zd, 'NOW', now.isoformat()):
            o = zd.build_indeksy({'EODHD_KEY': 'e', 'FMP_KEY': 'f'}, {'ix': ix, 'ix_calls': {'d': '2026-10-14', 'n': 0}}, now=now)
        self.assertTrue(any('GSPC — FMP bez sesji 2026-10-13 (błąd albo przerwa FMP) — pobranie z zapasu' in n for n in zd.META['notes']), zd.META['notes'])
        self.assertEqual((o['ix']['GSPC']['d'][-1][0], o['ix']['GSPC']['zap']), ('2026-10-13', '2026-10-13'))


# ===================== v286: PRÓG KURSU BLUE Z TESTU WSTECZNEGO =====================
class ProgBlueV286(unittest.TestCase):
    """v286: próg dwóch odczytów kursu blue 1,5% (z rozkładu 2 lat), „duża różnica” od 3%; pozostałe pary bez zmian."""

    @classmethod
    def setUpClass(cls):
        import importlib.util
        spec = importlib.util.spec_from_file_location('v286_k', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
        cls.k = importlib.util.module_from_spec(spec); spec.loader.exec_module(cls.k)

    def _blue(self, a, b):
        Z = self.k.dolar_porownanie({'ar': {'q': {'blue': [round(a * 0.987, 2), a, '2026-10-06T20:56:00Z']}, 'amb': {'blue': [round(b * 0.987, 2), b, '2026-10-06T18:00:00Z']}}}, None,
                                    datetime.datetime(2026, 10, 7, 3, 0, tzinfo=datetime.timezone.utc))
        return next(P for P in Z['pary'] if P['kurs'] == 'blue'), [u for u in Z['uwagi'] if 'kurs blue' in u]

    def test_progi(self):
        self.assertEqual(dict((k, p) for k, _, p in self.k.DL_PARY), {'blue': 1.5, 'mayorista': 0.5, 'oficial': 0.5, 'bolsa': 2.0, 'contadoconliqui': 2.0})
        self.assertTrue(all(p in self.k.DL_DUZA for _, _, p in self.k.DL_PARY), 'każdy próg ma próg „dużej różnicy”')
        P, U = self._blue(1550, 1530)   # dwa kroki notowania: 1,31% — w progu
        self.assertEqual((P['status'], P['roznica_pct'], U), ('✅', 1.31, []))
        P, U = self._blue(1560, 1530)   # 1,96% — ponad próg
        self.assertEqual((P['status'], P['roznica_pct']), ('⚠️', 1.96))
        self.assertEqual(U, ['Argentyna, kurs blue: dwa odczyty różnią się o 1.96% (próg 1.5%)'])
        P, U = self._blue(1550, 1500)   # 3,33% — duża różnica
        self.assertEqual(U, ['Argentyna, kurs blue: dwa odczyty różnią się o 3.33% (próg 1.5%; ponad 3% — duża różnica)'])
        P, U = self._blue(1550, 15.5)   # błąd skali — nadal tylko ⚠️ (nigdy ❌)
        self.assertEqual(P['status'], '⚠️'); self.assertIn('duża różnica', U[0])


# ===================== v288p: SONDA — INDEKS RPA W FMP =====================
class SondaJseV288p(unittest.TestCase):
    """v288p: lista indeksów FMP — kody i nazwy z RPA (bez wartości), do 4 kodów z liczbą wierszy i najnowszą datą; bez EODHD; TYLKO = g_jse2."""

    def test_sonda(self):
        import importlib.util, io as _io
        spec = importlib.util.spec_from_file_location('sondy_v288p', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'sondy.py'))
        S = importlib.util.module_from_spec(spec); spec.loader.exec_module(S)
        self.assertTrue(S.TYLKO and all(any(g.__name__ == n for g in S.GROUPS) for n in S.TYLKO), 'TYLKO = istniejące grupy (zmienia się co sondę)')
        self.assertIs(S.GROUPS[-1], S.g_nasdaq); self.assertEqual(S.GROUPS.count(S.g_jse2), 1)
        seen = []

        def http(url, method='GET', body=None, headers=None):
            seen.append(url)
            if 'index-list' in url:
                return 200, json.dumps([{'symbol': '^GSPC', 'name': 'S&P 500', 'currency': 'USD'},
                                        {'symbol': '^J200.JO', 'name': 'FTSE/JSE Top 40', 'exchange': 'JNB', 'currency': 'ZAR'}]).encode(), 3, None
            if 'symbol=%5EJ200.JO' in url:
                return 200, json.dumps([{'symbol': '^J200.JO', 'date': '2026-10-06', 'price': 98765.4}, {'date': '2026-10-05', 'price': 98000.1}]).encode(), 3, None
            return 402, b'{"Error Message":"plan"}', 3, None
        out = _io.StringIO()
        with mock.patch.object(S, 'http', http), mock.patch.object(S.time, 'sleep', lambda s: None), mock.patch('sys.stdout', out), \
                mock.patch.dict(os.environ, {'FMP_KEY': 'TAJNY_FMP_456'}, clear=False):
            S.g_jse2()
        o = out.getvalue()
        self.assertNotIn('TAJNY', o); self.assertNotIn('http', o.replace('HTTP', '')); self.assertNotIn('98765', o); self.assertNotIn('98000', o)
        self.assertIn('summary jse2-list n=2 rpa=1 ^J200.JO|FTSE/JSE Top 40|JNB|ZAR', o)
        self.assertIn('summary jse2 ^J200.JO=200/r2/10-06 ^J203.JO=402 ^JTOPI.JO=402 ^JALSH.JO=402', o)
        self.assertEqual(len(seen), 5, 'lista + 4 kody'); self.assertFalse([u for u in seen if 'eodhd' in u], 'bez EODHD')


# ===================== v290: POPRAWKI PO PRZEGLĄDZIE v285–v287 =====================
class PoPrzegladzieV290(unittest.TestCase):
    """v290: rezerwa limitu tylko, gdy własny indeks jest jeszcze należny dziś; tekst kontroli zgodny z IX_ZAPAS_PO."""
    UTC = datetime.timezone.utc

    def T(self, *a):
        return datetime.datetime(*a, tzinfo=self.UTC)

    def _pix(self, at, d_wl, d_fmp):
        wl = {s: {'cc': c, 'at': at, 'd': [[d_wl, 1.0]]} for s, c, _ in zd.IX_SYMBOLS if s not in ('GSPC', 'IXIC', 'DJI', 'N225', 'HSI')}
        wl['JTOPI'] = {'bad_at': '2026-10-21T16:05:00+00:00', 'bad_n': 4, 'bad': 'pusto'}
        return {**wl, **{s: {'cc': c, 'src': 'fmp', 'at': '2026-10-20T23:30:00+00:00', 'd': [[d_fmp, 1.0]]}
                         for s, c in (('GSPC', 'us'), ('IXIC', 'us'), ('DJI', 'us'), ('N225', 'jp'), ('HSI', 'hk'))}}

    def test_rezerwa_tylko_gdy_wlasny_nalezny(self):
        # awaria FMP: wszystkie 5 bez sesji; własne pobrane dziś po swojej porze (22:00 — po ostatniej grupie dnia)
        now = self.T(2026, 10, 21, 23, 0)
        pix = self._pix('2026-10-21T22:40:00+00:00', '2026-10-21', '2026-10-19')
        w, info = zd._ix_zapas_wybor(pix, now, {'d': '2026-10-21', 'n': 18}, None)
        self.assertEqual(w, {'N225', 'HSI'}, 'przegląd v285: 20 − 18 = 2 wolne (v285: 1) — rezerwa wraca do zapasu, gdy żaden własny nie jest już należny')
        # rano: własne jeszcze należne dziś — rezerwa trzymana
        now2 = self.T(2026, 10, 22, 0, 30)
        pix2 = self._pix('2026-10-21T22:40:00+00:00', '2026-10-21', '2026-10-19')
        w2, _ = zd._ix_zapas_wybor(pix2, now2, {'d': '2026-10-22', 'n': 0}, None)
        wl_due = sum(1 for s, _, _ in zd.IX_SYMBOLS if s not in ('GSPC', 'IXIC', 'DJI', 'N225', 'HSI', 'JTOPI'))
        self.assertEqual(len(w2), min(5, zd.IX_DAILY - wl_due - zd.IX_ZAPAS_REZERWA), 'własne należne — rezerwa trzymana')
        import inspect
        self.assertIn('(IX_ZAPAS_REZERWA if wlasne else 0)', inspect.getsource(zd._ix_zapas_wybor))

    def test_tekst_kontroli_zgodny_z_opoznieniem_zapasu(self):
        src = open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'), encoding='utf-8').read()
        self.assertIn(f'w ciągu {zd.IX_ZAPAS_PO // 60} h {zd.IX_ZAPAS_PO % 60} min', src)


# ===================== v291: KONTROLA — OSTRZEŻENIA GITHUBA O PRZESTARZAŁYCH AKCJACH =====================
class OstrzezeniaGithubV291(unittest.TestCase):
    """v291: adnotacje „warning” o wycofaniu w ostatnim przebiegu każdego przepływu = uwaga; własne „notice” się nie liczą; raport z ✅/⚠️/?."""

    @classmethod
    def setUpClass(cls):
        import importlib.util
        spec = importlib.util.spec_from_file_location('v291_k', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
        cls.k = importlib.util.module_from_spec(spec); spec.loader.exec_module(cls.k)

    NODE = 'Node.js 20 is deprecated. The following actions target Node.js 20 but are being forced to run on Node.js 24: actions/checkout@v4.'

    def test_wybor_adnotacji(self):
        k = self.k
        ann = {'archiwum.yml': [{'annotation_level': 'warning', 'title': '', 'message': self.NODE}, {'annotation_level': 'warning', 'message': self.NODE}],
               'sondy.yml': [{'annotation_level': 'notice', 'title': 'sondy', 'message': 'summary ... deprecated?'}],
               'strona.yml': [{'annotation_level': 'warning', 'title': 'lżejsza strona', 'message': 'podział słowników nie przeszedł'}],
               'kontrola.yml': [{'annotation_level': 'notice', 'title': 'kontrola', 'message': 'UWAGA — GitHub ostrzega … deprecated'}], 'x': 'zły'}
        self.assertEqual(k.ostrzezenia_github(ann), [('archiwum.yml', self.NODE[:160])], 'tylko warning o wycofaniu, bez powtórzeń; własne notice nie')
        self.assertEqual(k.ostrzezenia_github(None), []); self.assertEqual(k.ostrzezenia_github({'a': [None, 5]}), [])

    def _R(self, go):
        return {'at': '2026-10-07T08:20:00+00:00', 'wynik': 'UWAGA', 'strona': {'ok': True, 'http': 200, 'ms': 100}, 'meta': {}, 'pliki': {},
                'actions': {'przebiegi_24h': 140, 'wg_wyniku': {'success': 140}, 'najdluzszy_min': 9.0}, 'github_ostrz': go,
                'swiezosc': [], 'zgodnosc': {}, 'uwagi': [], 'bledy': []}

    def test_raport(self):
        k = self.k
        md = k.raport_md(self._R({'sprawdzone': 5, 'znalezione': []}))
        self.assertIn('- Ostrzeżenia GitHuba o przestarzałych akcjach (ostatni przebieg każdego z 5 przepływów): brak ✅.', md)
        md = k.raport_md(self._R({'sprawdzone': 5, 'znalezione': [('archiwum.yml', self.NODE[:160])]}))
        self.assertIn('- Ostrzeżenia GitHuba o przestarzałych akcjach: archiwum.yml: Node.js 20 is deprecated.', md)
        self.assertIn('⚠️ — napisz do Claude: „zaktualizuj akcje GitHuba”.', md)
        md = k.raport_md(self._R({'blad': 'HTTP Error 403: rate limit'}))
        self.assertIn('- Ostrzeżenia GitHuba o przestarzałych akcjach: ? (odczyt przerwany: HTTP Error 403: rate limit).', md)
        self.assertNotIn('Ostrzeżenia GitHuba', k.raport_md(self._R(None)), 'stary raport bez pola — bez linii')

    def test_odczyt_w_kontroli(self):
        import inspect
        src = inspect.getsource(self.k)
        i = src.index('# 4b. v291'); j = src.index("R['github_ostrz'] = {'blad'", i)
        blok = src[i:j] + inspect.getsource(self.k.github_ostrz_odczyt)   # v292: odczyt w osobnej funkcji
        for s in ("actions/workflows/{wf}/runs?per_page=1&status=completed", "/actions/runs/{rr[0][\"id\"]}/jobs", "/check-runs/{j[\"id\"]}/annotations",
                  "GH_OSTRZ_BUDZET_S", "R['uwagi'].append('GitHub ostrzega"):
            self.assertIn(s, blok)
        self.assertNotIn("R['bledy']", blok, 'nigdy BŁĄD')
        zg = open(os.path.join(os.path.dirname(os.path.abspath(__file__)), '.github', 'workflows', 'zegar.yml'), encoding='utf-8').read()
        self.assertIn('actions/checkout@v7', zg); self.assertNotIn('actions/checkout@v4', zg)


# ===================== v292: OSTRZEŻENIA GITHUBA — KAŻDY PRZEPŁYW OSOBNO =====================
class OstrzezeniaGithubV292(unittest.TestCase):
    """v292: błąd odczytu jednego przepływu (404, 5xx) nie przerywa pozostałych; wszystkie nieudane = wyjątek („?” w raporcie)."""

    @classmethod
    def setUpClass(cls):
        import importlib.util
        spec = importlib.util.spec_from_file_location('v292_k', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
        cls.k = importlib.util.module_from_spec(spec); spec.loader.exec_module(cls.k)

    def _get(self, zly):
        k = self.k
        node = 'Node.js 20 is deprecated. The following actions target Node.js 20 but are being forced to run on Node.js 24.'

        def get(url, timeout=25, headers=None, limit=None):
            if any(f'/workflows/{w}/' in url for w in zly):
                raise k.urllib.error.HTTPError(url, 404, 'Not Found', {}, None)
            if '/workflows/' in url:
                wf = url.split('/workflows/')[1].split('/')[0]
                return 200, json.dumps({'workflow_runs': [{'id': 100 + k.GH_OSTRZ_WF.index(wf)}]}).encode(), 5
            if '/jobs' in url:
                rid = int(url.split('/runs/')[1].split('/')[0])
                return 200, json.dumps({'jobs': [{'id': rid * 10}]}).encode(), 5
            if '/annotations' in url:
                jid = int(url.split('/check-runs/')[1].split('/')[0])
                return 200, json.dumps([{'annotation_level': 'warning', 'message': node}] if jid == 1030 else []).encode(), 5   # 103 = archiwum.yml
            raise AssertionError(url)
        return get

    def test_jeden_zly_przeplyw(self):
        k = self.k
        go = k.github_ostrz_odczyt({}, self._get(('zegar.yml',)))
        self.assertEqual((go['sprawdzone'], [w for w, _ in go['znalezione']]), (4, ['archiwum.yml']), 'pozostałe ocenione mimo 404 jednego')
        self.assertEqual(len(go['bledne']), 1); self.assertTrue(go['bledne'][0].startswith('zegar.yml ('))
        md = k.raport_md({'at': '2026-10-08T06:20:00+00:00', 'wynik': 'OK', 'strona': {'ok': True, 'http': 200, 'ms': 1}, 'meta': {}, 'pliki': {},
                          'actions': {}, 'github_ostrz': {'sprawdzone': 4, 'znalezione': [], 'bledne': go['bledne']}, 'swiezosc': [], 'zgodnosc': {},
                          'uwagi': [], 'bledy': []})
        self.assertIn('brak ✅; nie odczytano: zegar.yml (', md)
        go = k.github_ostrz_odczyt({}, self._get(()))
        self.assertEqual((go['sprawdzone'], go['bledne']), (5, []))

    def test_wszystkie_zle(self):
        with self.assertRaises(RuntimeError):
            self.k.github_ostrz_odczyt({}, self._get(self.k.GH_OSTRZ_WF))


