        _, ser2, _, uw2 = zd.parse_wb(self.wb_xlsx(cocoa_unit='($/mt)'))
        self.assertNotIn('kakao', ser2, 'inna jednostka = seria pominięta (przesunięte kolumny)'); self.assertTrue(any('jednostka' in x for x in uw2))
