        self.assertIn('eia', zm3); self.assertNotIn('pre', out3['ceny']['brent']); self.assertEqual(out3['ceny']['ulsd_nyh']['d'][-1], ['2026-10-06', 4.713])
        self.assertEqual(out3['st']['eia']['asof_hh'], '2026-09-29')
