class ZlotoKryptoV295c(unittest.TestCase):
    """v295c: złoto a bitcoin (wspólne dni), korelacja krocząca 90 wspólnych dni notowań (wzorcowe dane: identyczna = 1, odwrócona = −1, za mało
    dni = None, okno kończy się na ostatnim wspólnym dniu; prawdziwy kalendarz ze świętami i punktami q bez „—”; S&P 500), tokenizowane złoto (tony =
    uncje ÷ 32 150,7466, zmiany z dziennika, odczyt starszy niż 12 h i XAUT bez potwierdzonej rezerwy poza dziennikiem, premia tylko z chwil ≤ 1 h,
    tryb szybki nie nadpisuje lepiej dopasowanej premii), wielkość rynków (szacunek złota z datą stanu), ceny tokenów z tego samego zapytania co
    kapitalizacje ETF, zapis w main i kontrola (także uwaga o starej stałej zasobów złota)."""
    NOW = datetime.datetime(2026, 10, 7, 20, 20, tzinfo=datetime.timezone.utc)

    def setUp(self):
        zd.META['errors'].clear(); zd.META['ok'].clear()

    @staticmethod
    def dni(od, n, krok=1, robocze=False):
        out, d = [], datetime.date.fromisoformat(od)
        while len(out) < n:
            if not robocze or d.weekday() < 5:
                out.append(d.isoformat())
            d += datetime.timedelta(days=krok)
        return out

    def seria(self, dni, f):
        return {d: f(i) for i, d in enumerate(dni)}

    def S(self, live_at='2026-10-07T20:00:00+00:00', tok=True, live_v=4113.0):
        F = _ZK_FX
        su = {'v': 2, 'ceny': {'gold': {'d': F['gold'][-5:], 'live': {'v': live_v, 'at': live_at, 'z': 'td'}}, 'brent': {'d': F['brent'][-5:], 'q': F['brent_q']}}}
        return {'surowce': su, 'surowce-hist': {'v': 1, 'd': {'gold': F['gold'], 'brent': F['brent']}}, 'ceny-krypto': {'q': {'BTC': {'d': F['btc']}}},
                'rwa': json.loads(json.dumps(_ZK_RWA)), 'etf': {'tok': zd.zk_cg_tok(_ZK_CG)} if tok else {}, 'cmc': dict(_ZK_CMC),
                'indeksy': {'ix': {'GSPC': {'cc': 'us', 'd': F['spx']}}}}

    @staticmethod
    def okno(pts, i, n=90, kal=140):
        """Niezależnie: ostatnie n wspólnych dni ≤ pts[i] z (pts[i] − kal dni, pts[i]]."""
        end = datetime.date.fromisoformat(pts[i][0]); lo = (end - datetime.timedelta(days=kal)).isoformat()
        return [p for p in pts[:i + 1] if p[0] > lo][-n:]

    # ---------------------------------------------------------------- korelacja na danych wzorcowych
    def test_korelacja_wzorcowa_identyczna_odwrocona_za_malo(self):
        D = self.dni('2026-05-01', 120, robocze=True)
        a = self.seria(D, lambda i: 100 * (1 + 0.01 * ((i * 7919) % 13 - 6)) + i)       # „losowe”, deterministyczne ruchy
        same = zd.zk_kor(zd.zk_wspolne(a, dict(a)))
        self.assertEqual(same['v'], 1.0, 'identyczna seria = 1')
        self.assertEqual((same['n'], zd.ZK_OKNO, zd.ZK_OKNO_KAL, zd.ZK_MIN), (90, 90, 140, 60), 'okno = ostatnie 90 wspólnych dni notowań (120 w serii)')
        skala = zd.zk_kor(zd.zk_wspolne(a, {d: 3.7 * v for d, v in a.items()}))
        self.assertEqual(skala['v'], 1.0, 'ta sama seria w innej skali = 1 (zmiany procentowe)')
        odw = zd.zk_kor(zd.zk_wspolne(a, {d: 1e6 / v for d, v in a.items()}))
        self.assertEqual(odw['v'], -1.0, 'odwrócona seria (każdy wzrost to spadek o tyle samo w log) = −1')
        self.assertTrue(-1 <= min(r[1] for r in odw['s']) and max(r[1] for r in same['s']) <= 1)
        # za mało wspólnych dni: 59 wspólnych dni w oknie = None (na stronie „—”), 60 = liczba
        m = zd.zk_wspolne(a, {d: v for d, v in a.items() if d >= D[-59]})
        r59, n59 = zd.zk_kor_okno(m, len(m) - 1)
        self.assertEqual((r59, n59), (None, 59))
        m60 = zd.zk_wspolne(a, {d: v for d, v in a.items() if d >= D[-60]})
        self.assertEqual(zd.zk_kor_okno(m60, len(m60) - 1), (1.0, 60))
        self.assertEqual(zd.zk_kor(m)['v'], None); self.assertEqual(zd.zk_kor(m)['n'], 59); self.assertEqual(zd.zk_kor(m)['s'], [])
        self.assertIsNone(zd.zk_kor([])); self.assertIsNone(zd.zk_pearson([1, 1, 1, 1], [1, 2, 3, 4]), 'stała seria — bez korelacji, nie 0')

    def test_okno_konczy_sie_na_ostatnim_wspolnym_dniu(self):
        D = self.dni('2026-05-01', 160)                      # bitcoin codziennie
        R = [d for d in D if datetime.date.fromisoformat(d).weekday() < 5][:100]   # złoto w dni robocze
        g = {d: 2000 + 10 * (i % 7) + i for i, d in enumerate(R)}
        b = {d: 50000 + 300 * (i % 5) + 7 * i for i, d in enumerate(D)}
        pts = zd.zk_wspolne(g, b)
        base = zd.zk_kor(pts)
        self.assertEqual(base['d'], R[-1], 'koniec okna = ostatni wspólny dzień, nie ostatni dzień bitcoina')
        b2 = dict(b)
        for d in D:
            if d > R[-1]:
                b2[d] = b[d] * (5 if D.index(d) % 2 else 0.2)   # dni po ostatnim wspólnym — dzikie liczby: bez wpływu (bez zaglądania w przyszłość)
        self.assertEqual(zd.zk_kor(zd.zk_wspolne(g, b2)), base)
        # okno = ostatnie 90 wspólnych dni (≤ koniec), najwyżej 140 dni kalendarzowych wstecz: dni (koniec − 140, koniec]
        W = self.okno(pts, len(pts) - 1)
        self.assertEqual((base['n'], len(W), W[-1][0]), (90, 90, R[-1]))
        # długa przerwa w danych nie wydłuża okna bez końca: 140 dni kalendarzowych wstecz, potem mniej dni (i „—” poniżej 60)
        gap = {d: v for d, v in g.items() if not ('2026-06-01' <= d < '2026-08-15')}
        W2 = self.okno(zd.zk_wspolne(gap, b), len(zd.zk_wspolne(gap, b)) - 1)
        self.assertEqual(zd.zk_kor(zd.zk_wspolne(gap, b))['n'], len(W2)); self.assertLess(len(W2), 60); self.assertIsNone(zd.zk_kor(zd.zk_wspolne(gap, b))['v'])
        # wartość zgodna z niezależnym liczeniem (statistics.correlation na zmianach logarytmicznych tych samych dni)
        xa = [_math_v125.log(W[k][1] / W[k - 1][1]) for k in range(1, len(W))]; xb = [_math_v125.log(W[k][2] / W[k - 1][2]) for k in range(1, len(W))]
        self.assertAlmostEqual(base['v'], statistics.correlation(xa, xb), places=4)
        # punkt „do sprawdzenia” (q) pominięty: dzień wypada z dni wspólnych
        q = R[-3]
        self.assertNotIn(q, [p[0] for p in zd.zk_wspolne(g, b, {q})])

    def test_tony_i_chwila_fixingu(self):
        self.assertEqual(zd.zk_tonny(32150.7466), 1.0)
        self.assertEqual(zd.zk_tonny(436648.20247), round(436648.20247 / 32150.7466, 4))
        self.assertEqual(zd.zk_tonny(436648.20247), 13.5813)
        self.assertEqual(zd.zk_tonny(-321.507466), -0.01, 'spadek podaży — tony ze znakiem')
        self.assertIsNone(zd.zk_tonny(None)); self.assertEqual(zd.ZK_OZ_T, 32150.7466)
        # fixing popołudniowy 15:00 w Londynie: latem 14:00 UTC, zimą 15:00 UTC (zmiana czasu: ostatnia niedziela marca / października)
        self.assertEqual(zd.zk_pm_chwila('2026-10-06').isoformat(), '2026-10-06T14:00:00+00:00')
        self.assertEqual(zd.zk_pm_chwila('2026-10-26').isoformat(), '2026-10-26T15:00:00+00:00')
        self.assertEqual(zd.zk_pm_chwila('2026-03-27').isoformat(), '2026-03-27T15:00:00+00:00')
        self.assertEqual(zd.zk_pm_chwila('2026-03-30').isoformat(), '2026-03-30T14:00:00+00:00')
        self.assertIsNone(zd.zk_pm_chwila('2026-02-30'))

    def test_premia_tylko_z_chwil_najwyzej_godzine_od_siebie(self):
        C = [('live', 4100.0, '2026-10-07T19:00:00+00:00'), ('wyr', 4120.0, '2026-10-07T14:01:23+00:00')]
        self.assertIsNone(zd.zk_prem(4114.84, '2026-10-07T20:00:01+00:00', C), 'chwile oddalone o ponad 1 h = brak (na stronie „—”), nie liczba')
        p = zd.zk_prem(4114.84, '2026-10-07T20:00:00+00:00', C)
        self.assertEqual((p['ref'], p['ref_px'], p['dt_min'], p['prem']), ('live', 4100.0, 60, round((4114.84 / 4100.0 - 1) * 100, 3)), 'dokładnie 1 h — jeszcze tak')
        p2 = zd.zk_prem(4114.84, '2026-10-07T14:30:00+00:00', C)
        self.assertEqual((p2['ref'], p2['dt_min']), ('wyr', 29), 'najbliższa w czasie cena złota')
        self.assertIsNone(zd.zk_prem(4114.84, None, C)); self.assertIsNone(zd.zk_prem(None, '2026-10-07T20:00:00+00:00', C))
        self.assertIsNone(zd.zk_prem(4114.84, '2026-10-07T20:00:00+00:00', [('live', 0, '2026-10-07T20:00:00+00:00')]), 'zero to nie cena')

