    def test_build_etf_tym_samym_zapytaniem(self):
        seen = []

        def gj(url, headers=None, timeout=30):
            if 'coingecko' in url:
                seen.append(url); return _ZK_CG
            raise RuntimeError('SoSoValue offline')
        with mock.patch.object(zd, 'get_json', gj), mock.patch.object(zd, 'soso', side_effect=RuntimeError('offline')), mock.patch.object(zd, 'NOW', self.NOW.isoformat()):
            out = {}
            try:
                zd.build_etf('k', 'cg', None)
            except RuntimeError:
                pass
        self.assertEqual(len(seen), 1, 'jedno zapytanie — to samo co kapitalizacje ETF')
        self.assertIn('ids=bitcoin,ethereum,solana,ripple,pax-gold,tether-gold&', seen[0]); self.assertIn('include_last_updated_at=true', seen[0])
        self.assertTrue(seen[0].startswith('https://api.coingecko.com/api/v3/simple/price?'))
        # wynik (bez SoSoValue build_etf rzuca wyjątek jak dotąd — sprawdzamy blok w pliku z udanym przebiegiem)
        rows = [{'date': '2026-10-06', 'total_net_inflow': 1.0, 'total_value_traded': 1.0, 'total_net_assets': 1.0, 'cum_net_inflow': 1.0}]
        with mock.patch.object(zd, 'get_json', gj), mock.patch.object(zd, '_etf_coin', lambda out, s, key, day, prev_a=None: out['assets'].__setitem__(s, {'asof': '2026-10-06', 'day': rows})), \
                mock.patch.object(zd, '_etf_hk', lambda out, key, ph: None), mock.patch.object(zd, 'NOW', self.NOW.isoformat()):
            out = zd.build_etf('k', 'cg', None)
        self.assertEqual(out['tok']['XAUT'], {'p': 4106.66, 'at': '2026-10-07T20:13:00+00:00', 'mcap': 3322092064})
        self.assertEqual(out['mcap']['btc'], _ZK_CG['bitcoin']['usd_market_cap'])
        # tryb szybki (kapitalizacje sprzed < 55 min) — ceny tokenów z poprzedniego pliku, bez zapytania
        prev = {'at': '2026-10-07T20:15:00+00:00', 'mcap': dict(out['mcap']), 'mcap_at': '2026-10-07T20:00:00+00:00', 'tok': out['tok'], 'assets': {}}
        seen.clear()
        with mock.patch.object(zd, 'get_json', gj), mock.patch.object(zd, '_now_utc', lambda: self.NOW), mock.patch.object(zd, '_etf_coin', lambda out, s, key, day, prev_a=None: out['assets'].__setitem__(s, {'asof': '2026-10-06', 'day': rows})), \
                mock.patch.object(zd, '_etf_hk', lambda out, key, ph: None), mock.patch.object(zd, 'NOW', self.NOW.isoformat()):
            out2 = zd.build_etf('k', 'cg', prev)
        self.assertEqual((seen, out2['tok']), ([], prev['tok']))
        # odpowiedź bez tokenów złota — kapitalizacje jak dotąd, bez bloku tok
        bez = {k: v for k, v in _ZK_CG.items() if k in zd.CG_IDS.values()}
        with mock.patch.object(zd, 'get_json', lambda url, headers=None, timeout=30: bez), mock.patch.object(zd, '_etf_coin', lambda out, s, key, day, prev_a=None: out['assets'].__setitem__(s, {'asof': '2026-10-06', 'day': rows})), \
                mock.patch.object(zd, '_etf_hk', lambda out, key, ph: None), mock.patch.object(zd, 'NOW', self.NOW.isoformat()):
            out3 = zd.build_etf('k', 'cg', None)
        self.assertNotIn('tok', out3); self.assertEqual(len(out3['mcap']), 4); self.assertIs(zd.META['ok']['coingecko'], True)

