    def test_dziennik_podazy_zmiany_7_i_30_dni(self):
        p = zd.build_zloto_krypto(self.S(), None, self.NOW)
        H = []
        for i in range(31, 0, -1):
            d = (datetime.date(2026, 10, 7) - datetime.timedelta(days=i)).isoformat()
            H.append([d, 436648.20247 - 3215.07466 * i / 10, 709323.659532 - 100.0 * i if i != 7 else None])
        p['tok']['h'] = H
        o = zd.build_zloto_krypto(self.S(), p, self.NOW)
        P, X, R = o['tok']['PAXG'], o['tok']['XAUT'], o['tok']['razem']
        self.assertEqual((P['c7']['od'], P['c7']['do'], P['c7']['t']), ('2026-09-30', '2026-10-07', 0.07), '7 dni: +0,07 t (wybite minus spalone)')
        self.assertAlmostEqual(P['c7']['usd'], 3215.07466 * 0.7 * 4100.325, delta=1, msg='USD = zmiana uncji × cena złota z wyceny tokenów')
        self.assertEqual((P['c30']['od'], P['c30']['t']), ('2026-09-07', 0.3))
        self.assertEqual((X['c7']['od'], X['c7']['oz']), ('2026-09-29', 800.0), 'brak dnia bazowego — najbliższy wcześniejszy (najwyżej 2 dni), z datą')
        self.assertEqual(R['c7']['od'], '2026-09-29', 'razem — tylko dni z obiema podażami')
        H2 = [r for r in H if r[0] not in ('2026-09-30', '2026-09-29', '2026-09-28')]
        p['tok']['h'] = H2
        self.assertIsNone(zd.build_zloto_krypto(self.S(), p, self.NOW)['tok']['PAXG']['c7'], 'brak dnia bazowego i 2 dni przed nim = None (na stronie „—”)')

