    def setUp(self):
        import shutil, tempfile
        self.tmp = tempfile.mkdtemp(prefix='v309-'); self.addCleanup(shutil.rmtree, self.tmp, True)
        for p in (mock.patch.object(zd, 'SUT_CSV', os.path.join(self.tmp, 'brak', 'surowce-dziennik.csv')),
                  mock.patch.object(zd.urllib.request, 'urlopen', side_effect=AssertionError('sieć w teście')),
                  mock.patch.object(zd.time, 'sleep', lambda s: None)):
            p.start(); self.addCleanup(p.stop)
        zd._SUT_LOG[0] = zd._SUT_LOG[1] = None
        self.addCleanup(zd._SUT_LOG.__setitem__, slice(None), [None, None])
        zd.META['notes'].clear(); zd.META['errors'].clear()
        self.addCleanup(zd.META['notes'].clear); self.addCleanup(zd.META['errors'].clear)

    # ---------------------------------------------------------------- pomocnicze: nagrania, kalendarz, pliki
    @staticmethod
    def iso(d):
        return datetime.datetime.strptime(d, '%m/%d/%Y').date().isoformat()

    def t(self, s):
        return datetime.datetime.fromisoformat(s).replace(tzinfo=self.UTC)

    def cal(self):
        """Kalendarz sesji: dni robocze 02.06.2025 – 20.03.2026 bez świąt NYSE (część umowna, sprzed nagrania) + 140 sesji z nagrania (DBC:
        23.03–09.10.2026, bez wierszy zastępczych) — 300 dni pliku wydawcy mieści się w pliku dziennym (jak w produkcji: kalendarz ok. 10 lat)."""
        sw = {'2025-06-19', '2025-07-04', '2025-09-01', '2025-11-27', '2025-12-25', '2026-01-01', '2026-01-19', '2026-02-16'}
        early = [d.isoformat() for d in (datetime.date(2025, 6, 2) + datetime.timedelta(days=i) for i in range(300))
                 if d.weekday() < 5 and d.isoformat() not in sw and d.isoformat() < '2026-03-23']
        return early + sorted(self.iso(r[0]) for r in self.NAG['nq']['DBC'])

    def nq_rows(self, t, extra=()):
        """Wiersze odpowiedzi Nasdaq (najnowsze pierwsze): nagranie funduszu + dni `extra` [(dzień, o, c)] na początku."""
        rows = [{'date': f'{d[5:7]}/{d[8:10]}/{d[:4]}', 'open': f'{o:.2f}', 'close': f'{c:.2f}', 'volume': '1,000', 'high': '0', 'low': '0'}
                for d, o, c in sorted(extra, reverse=True)]
        return rows + [{'date': r[0], 'open': r[1], 'close': r[2], 'volume': r[3], 'high': '0', 'low': '0'} for r in self.NAG['nq'][t]]

    def nq(self, extra=(), fail=(), empty=()):
        """Atrapa _wd_get_json (Nasdaq): 44 rynki — syntetycznie na kalendarzu cal() (+ dni extra), 7 funduszy surowcowych — z nagrania
        (+ dni extra); tylko wiersze z okna dat zapytania; zwraca (lista zapytań [(symbol, limit)], atrapa)."""
        calls, cal = [], self.cal()

        def gj(url, timeout):
            t = url.split('/quote/')[1].split('/')[0]; n = int(url.split('limit=')[1].split('&')[0])
            a, b = url.split('fromdate=')[1].split('&')[0], url.split('todate=')[1].split('&')[0]   # okno dat zapytania — jak giełda
            calls.append((t, n))
            if t in fail:
                raise RuntimeError('HTTP Error 503: Service Unavailable')
            if t in empty:
                return {'data': {'tradesTable': {'rows': []}}}
            ex = [(d, o * 1.01, c * 1.01) for d, o, c in extra]
            if t in zd.WD_SU_PX:
                rows = self.nq_rows(t, ex)
            else:
                rows = [{'date': f'{d[5:7]}/{d[8:10]}/{d[:4]}', 'open': '100.00', 'close': '100.50', 'volume': '1,000', 'high': '0', 'low': '0'}
                        for d in sorted(set(cal) | {d for d, *_ in extra}, reverse=True)]
            rows = [r for r in rows if a <= self.iso(r['date']) <= b]
            return {'data': {'tradesTable': {'rows': rows[:n]}}}
        return calls, gj

    def wd_prev(self):
        """Plik dzienny świata po serii wstępnej 44 rynków (bf px/fl/ob, ready), bez funduszy surowcowych — kalendarz cal()."""
        cal = self.cal()
        px = {t: {'d': [[d, 100.0, 100.5, None] for d in cal], 'miss': [], 'seed': True} for t in zd.TD_W_SYMS}
        fl = {t: {'iss': 'ssga' if t in zd.FUND_SSGA else 'ishares', 'd': [[d, 10.0, 1000 + i, None] for i, d in enumerate(cal)], 'seed': True}
              for t in zd.WD_SSGA + zd.WD_ISH}
        ob = {p: {'d': [[d, 1.0, None] for d in cal], 'empty': []} for p in ('tw', 'hk', 'in')}
        return {'at': '2026-10-10T05:00:00+00:00', 'v': 1, 'cal': cal, 'px': px, 'fl': fl, 'ob': ob, 'rv': {}, 'rvd': {},
                'bf': {'px': True, 'fl': True, 'ob': True}, 'try': None, 'nq': {'fails': 0, 'next': None, 'since': None}, 'ready': True}

    def ish_rows(self, t):
        """Wiersze pełnego pliku wydawcy z nagrania (parser produkcji na zbudowanym arkuszu Historical) — rosnąco."""
        return zd.parse_ishares_hist(self.ish_xml(t))

    def ish_xml(self, t, rows=None):
        """Plik wydawcy (Excel 2003 XML) z arkuszem Historical — kolumny i teksty jak w pliku z 10.10.2026."""
        cell = lambda v, typ: f'<ss:Cell><ss:Data ss:Type="{typ}">{v}</ss:Data></ss:Cell>'   # noqa: E731
        head = ['As Of', 'NAV per Share', 'Ex-Dividends', 'Shares Outstanding']
        body = ''.join('<ss:Row>' + cell(r[0], 'String') + cell(r[1], 'Number') + cell(r[2], 'String') + cell(r[3], 'Number') + '</ss:Row>'
                       for r in (rows if rows is not None else self.NAG['ish'][t]))
        x = ('<?xml version="1.0"?>\n<ss:Workbook xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><ss:Worksheet ss:Name="Holdings">'
             '<ss:Table><ss:Row>' + cell('Ticker', 'String') + '</ss:Row></ss:Table></ss:Worksheet><ss:Worksheet ss:Name="Historical"><ss:Table>'
             '<ss:Row>' + ''.join(cell(h, 'String') for h in head) + '</ss:Row>' + body + '</ss:Table></ss:Worksheet></ss:Workbook>')
        return x.encode('utf-8')

    def fu_su(self, upto=None, revise=None):
        """Część 'su' pliku fundusze: historia pełnego pliku wydawcy (ostatnie FUND_KEEP dni) do dnia `upto` włącznie; revise(t, wiersz) → wiersz."""
        out = {}
        for t in zd.FUND_ISH_SU:
            h = [r for r in self.ish_rows(t) if upto is None or r[0] <= upto][-zd.FUND_KEEP:]
            out[t] = {'iss': 'ishares', 'h': [revise(t, list(r)) if revise else r for r in h], 'pid': 'x', 'at': '2026-10-10T05:00:00+00:00'}
        return out

    def run_wd(self, now, prev, saved, gj, run_t0=None):
        with mock.patch.object(zd, '_now_utc', lambda: now), mock.patch.object(zd, '_wd_get_json', gj), \
                mock.patch.object(zd, '_wd_get_bytes', side_effect=AssertionError('plik wydawcy w tym teście')):
            return zd.build_swiat_dzien(prev, saved, run_t0=run_t0)

    # ---------------------------------------------------------------- 1. stałe i listy reguł głównych — bez zmian (asercje wartości)
    def test_stale_i_listy_regul_bez_zmian(self):
        import hashlib
        h = lambda x: hashlib.sha256(repr(x).encode()).hexdigest()[:16]   # noqa: E731
        self.assertEqual((h(zd.TR_FE), h(zd.TD_W_SYMS)), ('4dba46775e53461d', '72dbe975b6dc3a58'), 'TR_FE i TD_W_SYMS bajt w bajt jak w v300')
        self.assertEqual((len(zd.TD_W_SYMS), len(zd.TR_FE), sum(len(m) for _, m in zd.TR_FE)), (44, 27, 37))
        self.assertEqual(zd.FUND_ISH, ('IVV', 'EFA', 'IEFA', 'EZU', 'EWJ', 'EEM', 'IEMG', 'MCHI', 'FXI', 'INDA', 'EWZ', 'EWY', 'EWT',
                                       'TLT', 'IEF', 'SHY', 'AGG', 'LQD', 'HYG', 'EMB', 'IAU', 'SLV'), 'FUND_ISH (przepływy GLOBAL) bez zmian')
        self.assertEqual(zd.FUND_SSGA, ('SPY', 'XLK', 'XLF', 'XLE', 'XLV', 'XLI', 'XLY', 'XLP', 'XLU', 'SPDW', 'SPEM', 'BIL', 'JNK', 'GLD', 'GLDM'))
        self.assertEqual(zd.IX_ETF, ('SPY', 'EWC', 'ILF', 'VGK', 'KSA', 'TUR', 'EIS', 'EZA', 'INDA', 'MCHI', 'EWJ', 'EWY', 'ASEA', 'EWA', 'XLK',
                                     'XLF', 'XLE', 'XLV', 'XLI', 'XLY', 'XLP', 'XLU', 'SPDW', 'SPEM', 'BIL', 'JNK', 'GLD', 'GLDM', 'IVV', 'EFA', 'IEFA',
                                     'EZU', 'EEM', 'IEMG', 'FXI', 'EWZ', 'EWT', 'TLT', 'IEF', 'SHY', 'AGG', 'LQD', 'HYG', 'EMB', 'IAU', 'SLV'),
                         'IX_ETF (46 funduszy cen mapy GLOBAL i TRENDÓW) bez zmian — bez funduszy surowcowych')
        self.assertEqual((h(zd.IX_ETF), h(zd.FUND_ISH)), ('ad20440fe7558f2c', 'ba39c3c13a1e154c'))
        self.assertEqual((len(zd.WD_SSGA), len(zd.WD_ISH), zd.WD_SSGA + zd.WD_ISH), (14, 21, tuple(t for t in zd.FUND_SSGA + zd.FUND_ISH if t in zd.TD_W_SYMS)))
        self.assertEqual(zd.TD_SH_W, (('eq.pf', 'eq', ('p', 'f')), ('eq.fo', 'eq', ('f', 'o'))))
        self.assertEqual(zd.TD_SH_CR, (('pt', ('p', 't')), ('ph', ('p', 'h')), ('es', ('e', 's')), ('n3', 3)))
        self.assertAlmostEqual(zd.TD_W_ZLS, 3.1130172634086892, places=12); self.assertAlmostEqual(zd.TD_CR_ZLS, 3.1717657833516224, places=12)
        self.assertEqual([(n, f, i, d, z) for n, f, i, d, z in zd.TD_SH_SU],
                         [('cm.p', 'w', 'px', 1, 1.0), ('cm.f', 'w', 'fl', 1, 1.0), ('eq.cu', 'w', 'cuau', 1, 1.0), ('cr.au', 'cr', 'au', 1, 2.0)])
        self.assertEqual((zd.SUT_V, zd.SUT_REG, zd.SUT_SINCE, zd.SUT_M, zd.SUT_CLL), (1, '2026-10-08', '2026-10-08', 12, 99.6))
        self.assertEqual(zd.SUT_SHA, '79d4eef13ba7fc33f0630fdb323baf3979e55007a8d120ad9213f8811630fe5b', 'suma dokumentu rejestracji bez zmian')
        self.assertEqual(zd.SUT_KIND, {'px': ('close',), 'fl': ('ishares',), 'cuau': ('close', 'lbma'), 'au': ('lbma',)})
        self.assertEqual(zd.SUT_PUB['ishares'], (0, 1439, 'ny'), 'pliki wydawców dnia D — po 23:59 NY')
        self.assertEqual((zd.TD_LB, zd.TD_MIN, zd.TD_Z1, zd.TD_Z2, zd.TD_FLOOR, zd.TD_GAP, zd.TD_W_SPLIT), (60, 40, 1.0, 2.0, 0.25, 4, (1.5, 2, 3, 4, 5, 10)))
        # nowe listy: dokładnie fundusze z rejestracji, poza listami reguł głównych
        self.assertEqual(zd.FUND_ISH_SU, ('GSG', 'CMDY', 'COMT')); self.assertEqual(zd.FUND_ISH_SU, zd.SUT_CM_FL); self.assertEqual(zd.WD_SU_FL, zd.SUT_CM_FL)
        self.assertEqual(zd.WD_SU_PX, ('GSG', 'CMDY', 'COMT', 'DBC', 'USO', 'CPER', 'DBA')); self.assertEqual(zd.WD_SU_PX, zd.SUT_CM_PX)
        for L in (zd.TD_W_SYMS, zd.TD_GRP, zd.FUND_ISH, zd.FUND_SSGA, zd.IX_ETF, zd.DAY_SYMS, zd.WD_SSGA, zd.WD_ISH):
            self.assertFalse(set(zd.WD_SU_PX) & set(L), 'fundusze surowcowe poza listami reguł głównych i mapy GLOBAL')

    # ---------------------------------------------------------------- 2. zestawienie wydawcy — ta sama odpowiedź, osobna lista
    def test_zestawienie_osobna_lista(self):
        j = self.NAG['scr']
        d = zd.parse_ishares_screener(j)
        self.assertEqual(sorted(d), ['EFA', 'IVV'], 'domyślnie tylko FUND_ISH (jak dotąd)')
        s = zd.parse_ishares_screener(j, zd.FUND_ISH + zd.FUND_ISH_SU)
        self.assertEqual(sorted(s), ['CMDY', 'COMT', 'EFA', 'GSG', 'IVV'])
        self.assertEqual(s['EFA'], d['EFA']); self.assertEqual(s['IVV'], d['IVV'])
        self.assertEqual(s['GSG'], ('239757', '2026-10-09', 36.238424, 28500000), 'NAV i jednostki = aktywa ÷ NAV (zaokrąglone do tysięcy)')
        self.assertEqual((s['CMDY'][:2], s['COMT'][:2]), (('292741', '2026-10-09'), ('270319', '2026-10-09')))
        for t in zd.FUND_ISH_SU:
            r = [x for x in self.ish_rows(t) if x[0] == '2026-10-09'][0]
            self.assertEqual((s[t][2], s[t][3]), (r[1], r[2]), 'zestawienie = pełny plik wydawcy dla 09.10: ' + t)
        j2 = json.loads(json.dumps(j)); j2['239757']['totalNetAssetsFundAsOf']['r'] = 20261008
        self.assertNotIn('GSG', zd.parse_ishares_screener(j2, zd.FUND_ISH_SU), 'NAV i aktywa z różnych dni — brak, nie zgadywanie')

    # ---------------------------------------------------------------- 3. plik fundusze: część 'su' po funduszach GLOBAL, część 'f' bez zmian
    def fu_prev(self, krotkie=()):
        """Poprzedni plik fundusze: 37 funduszy (State Street świeże — bez pobierania; iShares z ~300 dniami do 08.10), zestawienie do pobrania."""
        days = [d for d in (datetime.date(2025, 6, 2) + datetime.timedelta(days=i) for i in range(600)) if d.weekday() < 5]
        days = [d.isoformat() for d in days if d.isoformat() <= '2026-10-08' and d.isoformat() not in zd.TD_NYSE_CLOSED][-300:]
        f = {}
        scr = zd.parse_ishares_screener(self.NAG['scr'])   # EFA i IVV — historia zgodna z zestawieniem (inaczej dzień 09.10 to „zły wiersz”)
        for k, t in enumerate(zd.FUND_SSGA + zd.FUND_ISH):
            if t in scr:
                h = [[d, round(scr[t][2] * (1 - 0.0002 * (len(days) - i)), 6), scr[t][3]] for i, d in enumerate(days)]
            else:
                h = [[d, round(20.0 + k + 0.01 * i, 6), 1000000 + 100 * i] for i, d in enumerate(days)]
            f[t] = {'iss': 'ssga' if t in zd.FUND_SSGA else 'ishares', 'h': h[-30:] if t in krotkie else h}
            if t in zd.FUND_SSGA:
                f[t]['at'] = '2026-10-10T05:00:00+00:00'
            else:
                f[t]['pid'] = '1'
        return {'at': '2026-10-10T05:00:00+00:00', 'scr_at': '2026-10-10T01:00:00+00:00', 'f': f}

    def run_fu(self, prev, doc=None, scr=None):
        calls = []

        def gb(url, headers=None, timeout=60):
            calls.append(url)
            if 'product-screener' in url:
                return json.dumps(scr if scr is not None else self.NAG['scr']).encode()
            if 'get-fund-document' in url:
                pid = url.split('portfolioId=')[1].split('&')[0]
                t = {'239757': 'GSG', '292741': 'CMDY', '270319': 'COMT'}.get(pid)
                if doc:
                    return doc(t, pid)
                if t:
                    return self.ish_xml(t)
                raise RuntimeError('HTTP Error 404: Not Found')
            raise AssertionError('zapytanie poza testem: ' + url[:80])
        with mock.patch.object(zd, '_now_utc', lambda: self.t('2026-10-10T05:30:00')), mock.patch.object(zd, 'get_bytes', gb), \
                mock.patch.object(zd, 'NOW', '2026-10-10T05:30:00+00:00'):
            out = zd.build_fundusze(prev)
        return out, calls

    def test_fundusze_czesc_su_i_czesc_f_bez_zmian(self):
        out, calls = self.run_fu(self.fu_prev())
        n1, e1 = list(zd.META['notes']), list(zd.META['errors'])
        self.assertEqual([c.split('?')[0].rsplit('/', 1)[-1] for c in calls], ['product-screener-v3.1.jsn'] + ['get-fund-document'] * 3,
                         'jedno zestawienie (bez nowego zapytania dla funduszy surowcowych) i 3 pełne pliki — tylko przy pierwszym pobraniu')
        self.assertEqual(sorted(out['su']), ['CMDY', 'COMT', 'GSG']); self.assertFalse(set(out['su']) & set(out['f']))
        for t in zd.FUND_ISH_SU:
            p = out['su'][t]; full = self.ish_rows(t)
            self.assertEqual(len(p['h']), zd.FUND_KEEP); self.assertEqual(p['h'], full[-zd.FUND_KEEP:], 'historia = pełny plik wydawcy (ostatnie 300 dni)')
            self.assertEqual((p['h'][-1][0], p['iss'], p['at']), ('2026-10-09', 'ishares', '2026-10-10T05:30:00+00:00'))
            self.assertEqual(p['pid'], {'GSG': '239757', 'CMDY': '292741', 'COMT': '270319'}[t])
        zd.META['notes'].clear(); zd.META['errors'].clear()
        with mock.patch.object(zd, 'FUND_ISH_SU', ()):
            ref, calls0 = self.run_fu(self.fu_prev())
        self.assertEqual(json.dumps(out['f'], sort_keys=True), json.dumps(ref['f'], sort_keys=True), 'część f bajt w bajt jak bez funduszy surowcowych')
        self.assertEqual((ref['su'], calls0), ({}, calls[:1]), 'bez listy FUND_ISH_SU — samo zestawienie, jak przed v309')
        self.assertEqual((zd.META['notes'], zd.META['errors']), (n1, e1), 'te same uwagi i błędy')
        # następny przebieg: nowy dzień z zestawienia dopisany jak w funduszach GLOBAL, bez pełnego pliku
        scr = json.loads(json.dumps(self.NAG['scr']))
        for e in scr.values():
            e['navAmountAsOf']['r'] = e['totalNetAssetsFundAsOf']['r'] = 20261012
        prev2 = json.loads(json.dumps(out)); prev2['scr_at'] = '2026-10-09T00:00:00+00:00'
        out2, calls2 = self.run_fu(prev2, scr=scr)
        self.assertEqual(len(calls2), 1, 'tylko zestawienie')
        for t in zd.FUND_ISH_SU:
            self.assertEqual(out2['su'][t]['h'][-1][0], '2026-10-12'); self.assertEqual(out2['su'][t]['h'][:-1], out['su'][t]['h'][1:])

    def test_fundusze_pierwszenstwo_globalnych_i_uwagi_osobno(self):
        # trzy fundusze GLOBAL z krótką historią zabierają limit pełnych plików (FUND_BACKFILL = 3) — surowcowe czekają na następny przebieg
        prev = self.fu_prev(krotkie=('EWZ', 'EWY', 'EWT'))
        scr = dict(self.NAG['scr'])
        for i, t in enumerate(('EWZ', 'EWY', 'EWT')):
            scr[str(900 + i)] = {'localExchangeTicker': t, 'portfolioId': 900 + i, 'navAmount': {'r': 30.0}, 'navAmountAsOf': {'r': 20261009},
                                 'totalNetAssetsFund': {'r': 3e7}, 'totalNetAssetsFundAsOf': {'r': 20261009}}
        last = prev['f']['EWZ']['h'][-1][0]
        dni = [x for x in (datetime.date(2025, 6, 2) + datetime.timedelta(days=i) for i in range(500)) if x.weekday() < 5 and x.isoformat() <= last]
        syn = [[x.strftime('%b %d, %Y'), '30.0', '--', '1000000'] for x in reversed(dni)]   # pełny plik funduszu GLOBAL (EWZ, EWY, EWT)

        def doc(t, pid):
            return self.ish_xml(None, syn) if pid in ('900', '901', '902') else self.ish_xml(t)
        self.assertEqual(zd.FUND_BACKFILL, 3)
        out, calls = self.run_fu(prev, doc=doc, scr=scr)
        docs = [c.split('portfolioId=')[1].split('&')[0] for c in calls if 'get-fund-document' in c]
        self.assertEqual(docs, ['900', '901', '902'], 'limit pełnych plików — najpierw fundusze GLOBAL')
        for t in zd.FUND_ISH_SU:
            self.assertEqual([r[0] for r in out['su'][t]['h']], ['2026-10-09'], 'na razie sam dzień z zestawienia (brak historii = brak, nie zero)')
        out2, calls2 = self.run_fu(dict(out, scr_at='2026-10-10T05:00:00+00:00'))
        self.assertEqual([c.split('portfolioId=')[1].split('&')[0] for c in calls2], ['239757', '292741', '270319'], 'następny przebieg: surowcowe')
        for t in zd.FUND_ISH_SU:
            self.assertEqual(out2['su'][t]['h'], self.ish_rows(t)[-zd.FUND_KEEP:])
        # awaria pełnego pliku funduszu surowcowego — uwaga w meta, nigdy błąd części; liczba problemów funduszy GLOBAL bez zmian
        zd.META['notes'].clear(); zd.META['errors'].clear()

        def zly(t, pid):
            raise RuntimeError('HTTP Error 500: Internal Server Error')
        out3, _ = self.run_fu(self.fu_prev(), doc=zly)
        n3, e3 = list(zd.META['notes']), list(zd.META['errors'])
        zd.META['notes'].clear(); zd.META['errors'].clear()
        with mock.patch.object(zd, 'FUND_ISH_SU', ()):
            self.run_fu(self.fu_prev(), doc=zly)
        self.assertEqual(e3, zd.META['errors'], 'błędy części fundusze — jak bez funduszy surowcowych')
        self.assertEqual([n for n in n3 if 'surowc' not in n], zd.META['notes'],
                         'uwaga „fundusze ETF” (licznik problemów GLOBAL; tu: zestawienie z nagrania ma 2 z 22 funduszy) bez zmian')
        self.assertEqual([n for n in n3 if 'surowc' in n],
                         ['fundusze surowcowe (TRENDY, reguły w cieniu): 3 problemów, np. GSG (historia): HTTP Error 500: Internal Server Error'])
        for t in zd.FUND_ISH_SU:
            self.assertEqual((len(out3['su'][t]['h']), out3['su'][t]['bf_err_at']), (1, '2026-10-10T05:30:00+00:00'), 'przerwa 6 h po błędzie')
        # zestawienie bez funduszy GLOBAL — ocena liczy tylko FUND_ISH (surowcowe jej nie zawyżają)
        zd.META['notes'].clear()
        only = {k: v for k, v in self.NAG['scr'].items() if v['localExchangeTicker'] in zd.FUND_ISH_SU}
        self.run_fu(self.fu_prev(), scr=only)
        self.assertTrue(any('zestawienie iShares: tylko 0 z 22 funduszy' in n for n in zd.META['notes'] + zd.META['errors']))

    # ---------------------------------------------------------------- 4. plik dzienny świata: seria wstępna cen 7 funduszy (krok 4b)
    def test_seria_wstepna_cen_funduszy(self):
        now = self.t('2026-10-10T05:30:00'); prev = self.wd_prev(); p0 = json.loads(json.dumps(prev))
        calls, gj = self.nq()
        wd = self.run_wd(now, prev, {'fundusze': None}, gj)
        self.assertEqual(sorted(calls), sorted((t, 9999) for t in zd.WD_SU_PX), 'tylko seria wstępna 7 funduszy (ceny dnia 44 rynków aktualne)')
        cal = set(self.cal())
        for t in zd.WD_SU_PX:
            P = wd['px'][t]
            exp = sorted([self.iso(r[0]), round(float(r[1]), 4), round(float(r[2]), 4)] for r in self.NAG['nq'][t]
                         if r[3] not in ('N/A', '') and self.iso(r[0]) in cal)
            self.assertEqual([r[:3] for r in P['d']], exp, t)
            self.assertEqual((P['seed'], P['miss'], 'se' in P), (True, [], False))
            self.assertEqual([r[0] for r in P['d'] if r[3]], ['2026-10-05', '2026-10-06', '2026-10-07', '2026-10-08', '2026-10-09'],
                             'czas zapisu tylko wierszy z ostatnich 7 dni (starsze — historia, null) — jak 44 rynki')
            self.assertTrue(all(r[3] in (None, '2026-10-10T05:30:00Z') for r in P['d']))
        self.assertEqual(len(wd['px']['GSG']['d']), 139, 'wiersz zastępczy (wolumen N/A) — brak ceny, nigdy 0')
        for t in zd.TD_W_SYMS:
            self.assertEqual(wd['px'][t], p0['px'][t], '44 rynki bez zmian: ' + t)
        self.assertEqual((wd['cal'], wd['bf'], wd['ready'], wd['bledy'], wd['fl'], wd['ob']), (p0['cal'], p0['bf'], True, {}, p0['fl'], p0['ob']))
        self.assertEqual((zd.META['errors'], [n for n in zd.META['notes'] if 'surowc' in n]), ([], []))
        self.assertEqual(wd['req'], 7)
        # drugi przebieg — nic do pobrania (seria wstępna zrobiona, ceny dnia aktualne)
        calls2, gj2 = self.nq()
        wd2 = self.run_wd(self.t('2026-10-10T05:40:00'), wd, {'fundusze': None}, gj2)
        self.assertEqual((calls2, wd2['px']['GSG'], wd2['req']), ([], wd['px']['GSG'], 0))

    def test_seria_wstepna_dopiero_po_44_rynkach_i_nie_w_spoznionym_przebiegu(self):
        now = self.t('2026-10-10T05:30:00')
        seen = []
        real = zd._wd_fetch_px

        def rec(syms, a, b, n, now_):
            seen.append(list(syms)); return real(syms, a, b, n, now_)
        for opis, zmiana, kw in (('spóźniony przebieg', {}, {'run_t0': zd.time.monotonic() - zd.WD_LATE - 5}),
                                 ('przerwa po awarii giełdy', {'nq': {'fails': 2, 'next': '2026-10-10T07:00:00Z', 'since': '2026-10-10T04:00:00Z'}}, {}),
                                 ('ceny 44 rynków bez serii wstępnej', {'bf': {'px': False, 'fl': True, 'ob': True}}, {})):
            seen.clear(); prev = self.wd_prev(); prev.update(zmiana)
            calls, gj = self.nq(fail=('SPY',))
            with mock.patch.object(zd, '_wd_fetch_px', rec):
                wd = self.run_wd(now, prev, {'fundusze': None}, gj, **kw)
            self.assertFalse(any(set(s) & set(zd.WD_SU_PX) for s in seen), opis + ': bez serii wstępnej funduszy surowcowych')
            self.assertFalse(any(t in wd['px'] for t in zd.WD_SU_PX), opis)
        # pusta odpowiedź (inny symbol) i błąd — przerwa 6 h, uwaga w meta (nie bledy), pozostałe fundusze zasiane
        zd.META['notes'].clear()
        calls, gj = self.nq(empty=('CPER',), fail=('USO',))
        wd = self.run_wd(now, self.wd_prev(), {'fundusze': None}, gj)
        self.assertEqual({t for t in zd.WD_SU_PX if (wd['px'].get(t) or {}).get('seed')}, set(zd.WD_SU_PX) - {'CPER', 'USO'})
        self.assertEqual((wd['px']['CPER']['d'], wd['px']['CPER']['se']['why'], wd['px']['USO']['se']['n']), ([], 'brak wierszy cen', 1))
        self.assertEqual(wd['bledy'], {}, 'stan pliku 44 rynków bez zmian')
        self.assertEqual(zd.META['errors'], [])
        self.assertTrue(any(n.startswith('Świat dziennie: fundusze surowcowe (TRENDY, reguły w cieniu): {\'seed_px\'') for n in zd.META['notes']), zd.META['notes'])
        calls2, gj2 = self.nq()
        wd2 = self.run_wd(self.t('2026-10-10T11:20:00'), wd, {'fundusze': None}, gj2)
        self.assertEqual(calls2, [], 'przed upływem 6 h — bez ponowienia')
        calls3, gj3 = self.nq()
        wd3 = self.run_wd(self.t('2026-10-10T11:31:00'), wd2, {'fundusze': None}, gj3)
        self.assertEqual(sorted(calls3), [('CPER', 9999), ('USO', 9999)])
        self.assertTrue(wd3['px']['CPER']['seed'] and 'se' not in wd3['px']['CPER'])

    # ---------------------------------------------------------------- 5. ceny dnia: fundusze surowcowe na końcu kolejki, błąd = uwaga
    def test_ceny_dnia_na_koncu_kolejki(self):
        wd = self.run_wd(self.t('2026-10-10T05:30:00'), self.wd_prev(), {'fundusze': None}, self.nq()[1])
        seen = []
        real = zd._wd_fetch_px

        def rec(syms, a, b, n, now_):
            seen.append(list(syms)); return real(syms, a, b, n, now_)
        now = self.t('2026-10-12T21:30:00')                          # poniedziałek 17:30 NY — po WD_POLL_M
        ex = [('2026-10-12', 50.0, 51.0)]
        calls, gj = self.nq(extra=ex, fail=('DBA', 'XLK'))
        zd.META['notes'].clear(); zd.META['errors'].clear()
        with mock.patch.object(zd, '_wd_fetch_px', rec):
            wd2 = self.run_wd(now, wd, {'fundusze': None}, gj)
        self.assertEqual(seen[0], ['SPY'])
        self.assertEqual(seen[1], [t for t in zd.TD_W_SYMS if t != 'SPY'] + list(zd.WD_SU_PX), 'najpierw 43 rynki, fundusze surowcowe na końcu')
        self.assertEqual(wd2['cal'][-1], '2026-10-12')
        for t in zd.WD_SU_PX:
            last = wd2['px'][t]['d'][-1]
            if t == 'DBA':
                self.assertEqual(last[0], '2026-10-09', 'błąd zapytania — brak dnia (ponowienie później), nie zero')
                continue
            self.assertEqual(last[:3], ['2026-10-12', 50.5, 51.51]); self.assertEqual(last[3], '2026-10-12T21:30:00Z', 'pierwsza publikacja z czasem zapisu')
            self.assertEqual(wd2['px'][t]['d'][:-1], wd['px'][t]['d'], 'wcześniejsze dni bez zmian')
        self.assertEqual(wd2['bledy'], {'px': {'HTTP Error 503: Service Unavailable': 1}}, 'bledy pliku — tylko rynek reguł głównych (XLK)')
        self.assertEqual(len([e for e in zd.META['errors'] if 'DBA' in e or 'surowc' in e]), 0)
        self.assertTrue(any("fundusze surowcowe (TRENDY, reguły w cieniu): {'px': {'HTTP Error 503: Service Unavailable': 1}}" in n
                            for n in zd.META['notes']), zd.META['notes'])
        # ponowienie brakującego dnia funduszu surowcowego (jak 44 rynki: najwyżej co 55 min), po 48 h — „miss”
        seen.clear()
        calls3, gj3 = self.nq(extra=ex)
        with mock.patch.object(zd, '_wd_fetch_px', rec):
            wd3 = self.run_wd(self.t('2026-10-12T22:20:00'), wd2, {'fundusze': None}, gj3)
        self.assertEqual((seen, calls3), ([], []), 'przed upływem 55 min — bez ponowienia')
        with mock.patch.object(zd, '_wd_fetch_px', rec):
            wd3 = self.run_wd(self.t('2026-10-12T22:31:00'), wd2, {'fundusze': None}, gj3)
        self.assertEqual(seen, [['XLK', 'DBA']], 'brakujące: rynek reguł głównych i fundusz surowcowy')
        self.assertEqual(wd3['px']['DBA']['d'][-1][0], '2026-10-12')
        calls4, gj4 = self.nq(extra=ex, fail=('DBA',))
        wd4 = self.run_wd(self.t('2026-10-15T00:30:00'), wd2, {'fundusze': None}, gj4)
        self.assertEqual(wd4['px']['DBA']['miss'], ['2026-10-12'], 'po 48 h od zamknięcia — brak na stałe (nigdy 0)')

    # ---------------------------------------------------------------- 6. NAV i jednostki z części 'su' pliku fundusze → część fl
    def test_nav_i_jednostki_z_pliku_fundusze(self):
        now = self.t('2026-10-10T05:30:00'); prev = self.wd_prev(); p0 = json.loads(json.dumps(prev))
        su = self.fu_su()
        wd = self.run_wd(now, prev, {'fundusze': {'f': {}, 'su': su}}, self.nq()[1])
        for t in zd.WD_SU_FL:
            P = wd['fl'][t]
            self.assertEqual([r[:3] for r in P['d']], su[t]['h'], 'ten sam kształt wierszy co 35 funduszy: [dzień, NAV, jednostki, czas zapisu]')
            self.assertEqual((P['iss'], P['seed']), ('ishares', 'fu'))
            self.assertEqual([r[0] for r in P['d'] if r[3]], ['2026-10-05', '2026-10-06', '2026-10-07', '2026-10-08', '2026-10-09'], 'seria wstępna')
        for t in p0['fl']:
            self.assertEqual(wd['fl'][t], p0['fl'][t], '35 funduszy reguł głównych bez zmian: ' + t)
        self.assertEqual(wd['bledy'], {})
        # następny przebieg: nowy dzień z czasem zapisu; inna wartość dnia już zapisanego — zostaje pierwsza publikacja (rv.fl raz na dzień)
        rev = lambda t, r: [r[0], round(r[1] * 1.001, 6), r[2]] if r[0] == '2026-10-09' else r   # noqa: E731
        su2 = self.fu_su(revise=rev)
        for t in zd.FUND_ISH_SU:
            su2[t]['h'] = su2[t]['h'][1:] + [['2026-10-12', 40.0, su2[t]['h'][-1][2] + 50000]]
        now2 = self.t('2026-10-13T02:10:00')
        wd2 = self.run_wd(now2, wd, {'fundusze': {'su': su2}}, self.nq()[1])
        for t in zd.WD_SU_FL:
            self.assertEqual(wd2['fl'][t]['d'][-1], ['2026-10-12', 40.0, su2[t]['h'][-1][2], '2026-10-13T02:10:00Z'])
            self.assertEqual(wd2['fl'][t]['d'][:-1], wd['fl'][t]['d'], 'dni już zapisane bez zmian (pierwsza publikacja)')
        self.assertEqual(wd2['rv']['fl'], 3); self.assertEqual(sorted(wd2['rvd']['fl']), ['CMDY', 'COMT', 'GSG'])
        wd3 = self.run_wd(self.t('2026-10-13T02:20:00'), wd2, {'fundusze': {'su': su2}}, self.nq()[1])
        self.assertEqual(wd3['rv']['fl'], 3, 'różnica liczona raz na dzień')
        # start od samego zestawienia (pełny plik jeszcze niepobrany): historia dopisana później — bez czasu zapisu (historia), nowy dzień — z czasem
        one = {t: {'iss': 'ishares', 'h': self.fu_su()[t]['h'][-1:]} for t in zd.FUND_ISH_SU}
        w1 = self.run_wd(now, self.wd_prev(), {'fundusze': {'su': one}}, self.nq()[1])
        self.assertEqual(w1['fl']['GSG']['d'], [['2026-10-09', 36.238424, 28500000, '2026-10-10T05:30:00Z']])
        full = self.fu_su()
        for t in zd.FUND_ISH_SU:
            full[t]['h'] = full[t]['h'][1:] + [['2026-10-12', 41.0, 28000000]]
        w2 = self.run_wd(now2, w1, {'fundusze': {'su': full}}, self.nq()[1])
        d = w2['fl']['GSG']['d']
        self.assertEqual(len(d), zd.FUND_KEEP)
        self.assertEqual([r[0] for r in d if r[3]], ['2026-10-06', '2026-10-07', '2026-10-08', '2026-10-09', '2026-10-12'])
        self.assertEqual((d[-2][3], d[-1][3]), ('2026-10-10T05:30:00Z', '2026-10-13T02:10:00Z'), 'wiersz zapisany wcześniej zachowuje swój czas')
        self.assertTrue(all(r[3] is None for r in d if r[0] < '2026-10-06'), 'historia dopisana wstecz — null, nie chwila dopisania')
        # nowy dzień, który doszedł z dużym opóźnieniem (np. po przerwie automatu) — czas zapisu = chwila dopisania (po czasie), nie „historia”
        pozno = self.fu_su()
        for t in zd.FUND_ISH_SU:
            pozno[t]['h'] = pozno[t]['h'][1:] + [['2026-10-12', 41.0, 28000000]]
        w5 = self.run_wd(self.t('2026-10-23T02:10:00'), wd, {'fundusze': {'su': pozno}}, self.nq()[1])
        self.assertEqual(w5['fl']['GSG']['d'][-1], ['2026-10-12', 41.0, 28000000, '2026-10-23T02:10:00Z'])
        # brak części su / zła część — brak wpisu; awaria funkcji — uwaga, nie błąd pliku (35 funduszy i zagraniczni dalej)
        for fu in (None, {}, {'su': None}, {'su': {'GSG': {'h': 'x'}, 'CMDY': None}}):
            w = self.run_wd(now, self.wd_prev(), {'fundusze': fu}, self.nq()[1])
            self.assertFalse(any(t in w['fl'] for t in zd.WD_SU_FL), repr(fu)); self.assertEqual(w['bledy'], {})
        zd.META['notes'].clear()
        with mock.patch.object(zd, '_wd_su_fl_from_saved', side_effect=ValueError('zły plik')):
            w = self.run_wd(now, self.wd_prev(), {'fundusze': {'su': su}}, self.nq()[1])
        self.assertEqual(w['bledy'], {}); self.assertEqual(zd.META['errors'], [])
        self.assertTrue(any("fundusze surowcowe (TRENDY, reguły w cieniu): {'fl': 'zły plik'}" in n for n in zd.META['notes']))

    # ---------------------------------------------------------------- 7. linie su.cm.p i su.cm.f liczą karty same (reguły bez zmian)
    def pliki(self):
        """Plik dzienny świata po serii wstępnej funduszy surowcowych (ceny z nagrania, NAV z części su) — jak po pierwszym przebiegu."""
        return self.run_wd(self.t('2026-10-10T05:30:00'), self.wd_prev(), {'fundusze': {'su': self.fu_su()}}, self.nq()[1])

    def test_karty_linii_cm_z_danych(self):
        import math
        now = self.t('2026-10-10T05:30:00')
        przed = zd._sut_log(None, {'swiat-dzien': self.wd_prev()}, now)
        self.assertEqual([r for r in przed['rows'] if r[1].startswith('cm.')], [], 'przed danymi — linie czekają')
        self.assertEqual((przed['pg']['cm.p'][4], przed['pg']['cm.f'][4]), (None, None))
        wd = self.pliki()
        W = zd._sut_wejscia({'swiat-dzien': wd})
        self.assertEqual(sorted(k for k in W if k[0].startswith('cm.')),
                         sorted([('cm.p', t) for t in zd.WD_SU_PX] + [('cm.f', t) for t in zd.WD_SU_FL]))
        log = zd._sut_log(None, {'swiat-dzien': wd}, now)
        cm = [r for r in log['rows'] if r[1].startswith('cm.')]
        self.assertEqual(len(cm), 10); self.assertTrue(all(r[0] == '2026-10-12' and r[4] == 'ok' and r[8] == '2026-10-09' for r in cm),
                                                       'karta poniedziałku z danymi piątku (sesja po publikacji), saved_at = chwila wyliczenia')
        self.assertTrue(all(r[6] == '2026-10-10T05:30:00Z' and r[7] is None for r in cm))
        R = {(r[1], r[2]): r for r in cm}
        # niezależne przeliczenie: ruch ceny CPER i przepływ GSG z nagrań (bez funkcji zbieracza)
        cl = sorted((self.iso(r[0]), float(r[2])) for r in self.NAG['nq']['CPER'] if r[3] not in ('N/A', ''))
        ch = [(b[1] / a[1] - 1) * 100 for a, b in zip(cl, cl[1:])]
        z = ch[-1] / math.sqrt(sum(x * x for x in ch[-61:-1]) / 60)            # ruch ceny: bez odejmowania średniej, 60 poprzednich
        self.assertLess(abs(R[('cm.p', 'CPER')][5] - z), 0.0051)
        self.assertEqual((R[('cm.p', 'CPER')][3], round(z, 4)), (1, 1.4965), 'CPER 09.10: +2,15% przy zwykłym ruchu ok. 1,4% — głos +1')
        h = self.fu_su()['GSG']['h']
        fl = [(b[2] - a[2]) * b[1] / 1e6 for a, b in zip(h, h[1:])]
        self.assertAlmostEqual(fl[-1], (28500000 - 28700000) * 36.238424 / 1e6, places=9)
        prev = fl[-61:-1]; m = sum(prev) / 60; sd = statistics.stdev(prev)   # przepływ: średnia i rozrzut z próby, dolna granica 0,25 × typowy dzień
        zf = (fl[-1] - m) / max(sd, 0.25 * sum(abs(x) for x in prev) / 60)
        self.assertLess(abs(R[('cm.f', 'GSG')][5] - zf), 0.0051)
        self.assertEqual((R[('cm.f', 'GSG')][3], round(zf, 4)), (-1, -1.1424), 'GSG 09.10: odpływ 7,2 mln USD — głos −1')
        for (ln, s), r in R.items():
            self.assertEqual(r[3], (1 if r[5] > 0 else -1) if abs(r[5]) >= 1.0 else 0, (ln, s, 'głos tylko przy |z| ≥ 1, kierunek +1'))
        S = zd._sut_summary(log)
        self.assertEqual((S['l']['cm.p'][4], S['l']['cm.f'][4]), ('2026-10-12', '2026-10-12'), 'strona: licznik zamiast „czeka na dane”')
        self.assertEqual((S['l']['cm.p'][:2], S['ok'], S['m']), ([0, 100], [], 12), 'bez wyników przed punktem 200')
        # wynik sesji karty: otwarcie→zamknięcie tego funduszu, gdy wiersz ceny dojdzie (raz)
        calls, gj = self.nq(extra=[('2026-10-12', 50.0, 51.0)])
        wd2 = self.run_wd(self.t('2026-10-12T21:30:00'), wd, {'fundusze': {'su': self.fu_su()}}, gj)
        log2 = zd._sut_log(log, {'swiat-dzien': wd2}, self.t('2026-10-12T21:40:00'))
        r2 = {(r[1], r[2]): r for r in log2['rows'] if r[0] == '2026-10-12'}
        self.assertEqual(r2[('cm.p', 'CPER')][7], round((51.0 * 1.01) / (50.0 * 1.01) * 100 - 100, 4))
        self.assertEqual(r2[('cm.p', 'CPER')][:7], R[('cm.p', 'CPER')][:7], 'karta zamrożona na granicy — dochodzi tylko wynik')

    # ---------------------------------------------------------------- 8. przyczynowość: pierwsza publikacja, filtry tylko wstecz (ziarna 1–30)
    def test_ziarna_1_30_pierwsza_publikacja_i_dane_pozniejsze(self):
        import copy, random
        cal = self.cal()
        base_px = {t: {self.iso(r[0]): (float(r[1]), float(r[2])) for r in self.NAG['nq'][t] if r[3] not in ('N/A', '')} for t in zd.WD_SU_PX}
        base_fl = {t: {r[0]: r for r in self.ish_rows(t)} for t in zd.FUND_ISH_SU}

        def fz(t, d, pd):
            """Podział 2:1 ceny od dnia pd (dzień podziału bez własnego ruchu — iloraz dokładnie 1/2, w paśmie TD_W_SPLIT ±2%; podział
            w dniu ruchu ponad 2% reguła — zarejestrowana, bez zmian — widzi jako ruch)."""
            if pd is None or d < pd:
                return 1.0
            if d == pd:
                p = max(x for x in base_px[t] if x < d)
                return 0.5 * base_px[t][p][1] / base_px[t][d][1]
            return 0.5

        def stan(k0, k1, rnd, pd=None, zly=None, wd=None):
            """Pliki budowane dzień po dniu (cal[k0] … cal[k1]) tymi samymi funkcjami co zbieracz: pierwszy dzień nowego pliku = seria wstępna
            (cała historia ceny, 300 dni pliku wydawcy), potem ponowny odczyt 15 ostatnich sesji ceny z poprawkami dostawcy ±0,3% i historii
            wydawcy z poprawką NAV wcześniejszych dni ±0,2%; zdarzenia po dniu D: podział jednostek 2:1 od dnia pd (cena i plik wydawcy)
            i zły wiersz NAV ×1000 w dniu zly. Chwila zapisu dnia D: D 23:50 UTC."""
            nowy = wd is None
            wd = wd or {'cal': [], 'px': {}, 'fl': {}, 'rv': {}, 'rvd': {}}
            for k in range(k0, k1 + 1):
                D = cal[k]; at = D + 'T23:50:00Z'
                wd['cal'] = cal[:k + 1]
                got = {}
                for t in zd.WD_SU_PX:
                    q = {}
                    for d in (cal[:k + 1] if nowy and k == k0 else cal[:k + 1][-15:]):
                        if d in base_px[t]:
                            o, c = base_px[t][d]
                            f = (1 + rnd.uniform(-0.003, 0.003) if d < D else 1) * fz(t, d, pd)
                            q[d] = (round(o * f, 4), round(c * f, 4))
                    got[t] = (q, set(q))
                zd._wd_merge_px(wd, got, at, stamp_all=not (nowy and k == k0))
                su = {}
                for t in zd.FUND_ISH_SU:
                    h = []
                    for d in sorted(x for x in base_fl[t] if x <= D)[-zd.FUND_KEEP:]:
                        r = list(base_fl[t][d])
                        if d < D:
                            r[1] = round(r[1] * (1 + rnd.uniform(-0.002, 0.002)), 6)
                        if d == zly:
                            r[1] = r[1] * 1000
                        elif pd and d >= pd:
                            r = [r[0], round(r[1] / 2, 6), r[2] * 2]
                        h.append(r)
                    su[t] = {'h': h}
                zd._wd_su_fl_from_saved(wd, {'su': su}, at)
            return wd
        for seed in range(1, 31):
            rnd = random.Random(seed)
            k = rnd.randrange(len(cal) - 140 + 75, len(cal) - 4)                 # dzień D w części z nagraniem (≥ 75 sesji historii cen)
            D = cal[k]
            A = stan(k - 6, k, rnd)                                              # stan plików wieczorem dnia D
            for part, syms in (('px', zd.WD_SU_PX), ('fl', zd.WD_SU_FL)):
                for t in syms:
                    P = A[part][t]['d']
                    self.assertEqual((P[-1][0], P[-1][3]), (D, D + 'T23:50:00Z'), (seed, part, t, 'dzień D z chwilą zapisu (pierwsza publikacja)'))
            for part, n in (('px', 70), ('fl', 70)):
                self.assertTrue(all(len(P['d']) > n for P in A[part].values()), (seed, part, 'historia do z (≥ 40 poprzednich wartości)'))
            B = stan(k + 1, k + rnd.randrange(2, 4), rnd, pd=cal[k + 1], zly=cal[k + 2], wd=copy.deepcopy(A))   # dni po D: podział, zły wiersz
            for part in ('px', 'fl'):
                for t, P in A[part].items():
                    self.assertEqual(B[part][t]['d'][:len(P['d'])], P['d'], (seed, D, part, t, 'dni do D bez zmian — pierwsza publikacja'))
            self.assertGreater(B['rv'].get('px', 0), 0, 'poprawki dostawcy cen wykryte, ale niezapisane')
            self.assertGreater(B['rv'].get('fl', 0), 0, 'poprawki pliku wydawcy wykryte, ale niezapisane')
            WA, WB = zd._sut_wejscia({'swiat-dzien': A}), zd._sut_wejscia({'swiat-dzien': B})
            self.assertEqual(set(WA), set(WB)); self.assertEqual(len([x for x in WA if x[0].startswith('cm.')]), 10)
            for key, (chA, dm) in WA.items():
                chB = WB[key][0]
                iA = max(i for i, x in enumerate(chA) if x[0] <= D); iB = max(i for i, x in enumerate(chB) if x[0] <= D)
                self.assertEqual(chA[:iA + 1], chB[:iB + 1], (seed, D, key, 'wejście dnia D i wcześniejszych nie zależy od dni późniejszych'))
                zA = zd._td_z([x for _, x in chA], iA, dm)
                self.assertEqual(zA, zd._td_z([x for _, x in chB], iB, dm), (seed, D, key, 'z'))
                self.assertIsNotNone(zA if chA[iA][1] is not None else 0, (seed, D, key, 'z policzalne'))
            # zdarzenia po D: podział ceny 2:1 — brak ruchu (nie −50%), zły NAV i podział jednostek — brak przepływu (nie ułamek aktywów)
            for t in zd.WD_SU_PX:
                chB = WB[('cm.p', t)][0]
                self.assertTrue(all(x is None or abs(x) < 25 for d, x in chB if d > D), (seed, t, 'podział jednostek w cenie = brak'))
            for t in zd.WD_SU_FL:
                chB = WB[('cm.f', t)][0]; P = B['fl'][t]['d']; aum = P[-1][1] * P[-1][2] / 1e6
                self.assertTrue(all(x is None or abs(x) < 0.2 * aum for d, x in chB if d > D), (seed, t, 'zły wiersz NAV i podział = brak przepływu'))

    # ---------------------------------------------------------------- 9. kontrola dzienna: świeżość nowych pozycji (próg z testu wstecznego)
    def kontrola(self):
        import importlib.util
        spec = importlib.util.spec_from_file_location('kontrola_v309', os.path.join(os.path.dirname(os.path.abspath(__file__)), 'narzedzia', 'kontrola.py'))
        K = importlib.util.module_from_spec(spec); spec.loader.exec_module(K)
        return K

    def test_kontrola_swiezosc_funduszy_surowcowych(self):
        import inspect
        K = self.kontrola()
        self.assertEqual(K.SUF_PROG, 60 * 60, 'próg 60 h roboczych (test wsteczny: fałszywych ⚠️ najwyżej 0,024% / 0,201%)')
        self.assertEqual(K.SUF_CZ[0][2], zd.WD_SU_PX); self.assertEqual(K.SUF_CZ[1][2], zd.WD_SU_FL)
        self.assertEqual(K.su_fundusze_swiezosc(None), []); self.assertEqual(K.su_fundusze_swiezosc('x'), [])
        t = self.t
        przed = K.su_fundusze_swiezosc(self.wd_prev(), t('2026-10-10T06:20:00'))
        self.assertEqual([r[1] for r in przed], ['?', '?'], 'przed pierwszym pobraniem — „?”, bez progu')
        self.assertIn('brak serii w pliku: GSG, CMDY, COMT, DBC, USO, CPER, DBA', przed[0][4])
        wd = self.pliki()
        po = K.su_fundusze_swiezosc(wd, t('2026-10-10T06:20:00'))
        self.assertEqual([(r[0], r[1], r[2], r[3], r[4]) for r in po],
                         [('TRENDY surowce — ceny 7 funduszy surowcowych (sesja w USA; reguły w cieniu)', '✅', 0, '2026-10-09', ''),
                          ('TRENDY surowce — NAV i jednostki 3 funduszy surowcowych (reguły w cieniu)', '✅', 0, '2026-10-09', '')])
        w = json.loads(json.dumps(wd))
        for p in ('px', 'fl'):
            for s in w[p]:
                w[p][s]['d'] = [r for r in w[p][s]['d'] if r[0] <= '2026-10-07']
        g = lambda iso: [r[1] for r in K.su_fundusze_swiezosc(w, t(iso))]   # noqa: E731
        self.assertEqual(g('2026-10-12T12:00:00'), ['✅', '✅'], 'równo 60 h roboczych (czw., pt., pn. do 12:00) — jeszcze ✅')
        self.assertEqual(g('2026-10-12T12:01:00'), ['⚠️', '⚠️'])
        r = K.su_fundusze_swiezosc(w, t('2026-10-12T13:00:00'))[0]
        self.assertEqual((r[2], r[3]), (61 * 60, '2026-10-07')); self.assertIn('dane przestały dochodzić: CMDY, COMT, CPER, DBA, DBC, GSG, USO (tylko uwaga)', r[4])
        # jeden zalegający fundusz — wiek najstarszego z najnowszych dni; brak serii jednego funduszu — „?” albo ⚠️ z obiema uwagami
        w2 = json.loads(json.dumps(wd)); w2['px']['USO']['d'] = [x for x in w2['px']['USO']['d'] if x[0] <= '2026-10-01']
        r = K.su_fundusze_swiezosc(w2, t('2026-10-10T06:20:00'))[0]
        self.assertEqual((r[1], r[3]), ('⚠️', '2026-10-01')); self.assertIn('dane przestały dochodzić: USO', r[4])
        w3 = json.loads(json.dumps(wd)); del w3['px']['DBA']; w3['fl']['CMDY']['d'] = [[x[0], None, x[2], x[3]] for x in w3['fl']['CMDY']['d']]
        r = K.su_fundusze_swiezosc(w3, t('2026-10-10T06:20:00'))
        self.assertEqual([(x[1], x[4]) for x in r], [('?', 'brak serii w pliku: DBA'), ('?', 'brak serii w pliku: CMDY')], 'NAV brak — wiersz bez liczby')
        w2['px'].pop('DBA')
        self.assertEqual(K.su_fundusze_swiezosc(w2, t('2026-10-10T06:20:00'))[0][4].split('; ')[1], 'brak serii w pliku: DBA')
        self.assertEqual(K.su_fundusze_swiezosc(w2, t('2026-10-10T06:20:00'))[0][1], '⚠️')
        src = inspect.getsource(K.kontrola)
        self.assertIn("su_fundusze_swiezosc(files.get('swiat-dzien'))", src)
        i, j = src.index("su_fundusze_swiezosc(files.get('swiat-dzien'))"), src.index("su_dziennik_swiezosc(files.get('surowce-dziennik'))")
        self.assertLess(j, i, 'wiersze po wierszu dziennika reguł w cieniu')
        self.assertNotIn('❌', inspect.getsource(K.su_fundusze_swiezosc).split('"""')[2], 'najwyżej ⚠️, nigdy ❌')
